// JOB_GROWTH_PROFILES: 1レベルあたりの職業固有基礎成長。5能力の成長予算は各職合計5.0。
const JOB_GROWTH_STAT_KEYS = Object.freeze(['atk','def','matk','mdef','spd']);
const JOB_GROWTH_PROFILES = Object.freeze({
  hero:      Object.freeze({hp:5,atk:1.00,def:1.00,matk:1.00,mdef:1.00,spd:1.00}),
  knight:    Object.freeze({hp:7,atk:0.75,def:1.75,matk:0.50,mdef:1.25,spd:0.75}),
  sword:     Object.freeze({hp:5,atk:1.50,def:0.75,matk:0.50,mdef:0.75,spd:1.50}),
  monk:      Object.freeze({hp:6,atk:1.75,def:1.00,matk:0.50,mdef:0.75,spd:1.00}),
  steamer:   Object.freeze({hp:6,atk:1.00,def:1.75,matk:0.50,mdef:1.00,spd:0.75}),
  mage:      Object.freeze({hp:4,atk:0.50,def:0.50,matk:1.75,mdef:1.50,spd:0.75}),
  priest:    Object.freeze({hp:5,atk:0.50,def:0.75,matk:1.25,mdef:1.75,spd:0.75}),
  alchemist: Object.freeze({hp:5,atk:0.75,def:0.75,matk:1.50,mdef:1.25,spd:0.75}),
  scout:     Object.freeze({hp:4,atk:1.25,def:0.75,matk:0.50,mdef:0.50,spd:2.00}),
  assassin:  Object.freeze({hp:4,atk:1.50,def:0.50,matk:0.50,mdef:0.50,spd:2.00}),
  clown:     Object.freeze({hp:4,atk:0.75,def:0.75,matk:1.25,mdef:0.75,spd:1.50}),
  supply:    Object.freeze({hp:6,atk:0.75,def:1.50,matk:0.50,mdef:1.50,spd:0.75})
});
function createEmptyTrainableGrowth(){return{atk:0,def:0,matk:0,mdef:0,spd:0};}
function normalizeTrainableGrowth(char){
  if(!char)return createEmptyTrainableGrowth();
  if(!char.trainableGrowth||typeof char.trainableGrowth!=='object')char.trainableGrowth=createEmptyTrainableGrowth();
  JOB_GROWTH_STAT_KEYS.forEach(key=>char.trainableGrowth[key]=Math.max(0,Math.floor(Number(char.trainableGrowth[key])||0)));
  return char.trainableGrowth;
}
function getJobGrowthProfile(jobKey){return JOB_GROWTH_PROFILES[jobKey]||JOB_GROWTH_PROFILES.hero;}
// 成長DBは不変。現行Lv範囲だけ再利用し、返却値をコピーして呼出し側の変更から守る。セーブには含めない。
const JOB_CUMULATIVE_GROWTH_CACHE=new WeakMap();
function getJobCumulativeGrowth(jobKey,level=1){
  const steps=Math.max(0,Math.floor(Number(level)||1)-1),profile=getJobGrowthProfile(jobKey);
  const cacheable=steps<MAX_CHARACTER_LEVEL&&Object.isFrozen(profile);
  let cache=cacheable?JOB_CUMULATIVE_GROWTH_CACHE.get(profile):null;
  if(cache?.has(steps))return{...cache.get(steps)};
  const out={hp:steps*Math.max(0,Number(profile.hp)||0),atk:0,def:0,matk:0,mdef:0,spd:0};
  // 毎Lvちょうど5点を配り、累積値が職業ごとの成長率へ近づくよう不足量の大きい能力から割り当てる。
  for(let step=1;step<=steps;step++){
    for(let point=0;point<5;point++){
      let best=JOB_GROWTH_STAT_KEYS[0],bestNeed=-Infinity,bestRate=-Infinity;
      JOB_GROWTH_STAT_KEYS.forEach(key=>{
        const rate=Math.max(0,Number(profile[key])||0),need=step*rate-out[key];
        if(need>bestNeed+1e-9||(Math.abs(need-bestNeed)<=1e-9&&rate>bestRate+1e-9)){
          best=key;bestNeed=need;bestRate=rate;
        }
      });
      out[best]++;
    }
  }
  if(cacheable){
    if(!cache){cache=new Map();JOB_CUMULATIVE_GROWTH_CACHE.set(profile,cache);}
    cache.set(steps,{...out});
  }
  return out;
}
function getJobLevelGrowthDelta(jobKey,fromLevel=1,toLevel=2){
  const from=getJobCumulativeGrowth(jobKey,fromLevel),to=getJobCumulativeGrowth(jobKey,toLevel),out={hp:to.hp-from.hp};
  JOB_GROWTH_STAT_KEYS.forEach(key=>out[key]=to[key]-from[key]);
  return out;
}

function getReferenceTrainableGrowth(level=1){
  const steps=Math.max(0,Math.floor(Number(level)||1)-1),out=createEmptyTrainableGrowth();
  // 高Lvで生成される冒険者向け。従来の「平均+3/Lv」から職業固定成長(+1平均)を除いた+2/Lv相当を模擬する。
  JOB_GROWTH_STAT_KEYS.forEach(key=>out[key]=steps*2);
  return out;
}
function applyReferenceTrainableGrowth(char,level=1){
  if(!char)return char;
  const earned=getReferenceTrainableGrowth(level),growth=normalizeTrainableGrowth(char);
  const keyMap={atk:'baseAtk',def:'baseDef',matk:'baseMatk',mdef:'baseMdef',spd:'baseSpd'};
  JOB_GROWTH_STAT_KEYS.forEach(key=>{
    const stat=keyMap[key],amount=Math.max(0,Math.floor(Number(earned[key])||0));
    char[stat]=clampGameInt((Number(char[stat])||1)+amount,1,GAME_LIMITS.STAT);
    growth[key]+=amount;
  });
  return char;
}


