let ENEMY_SPRITE_SHEET_IMAGE = null;
function getEnemySpriteSheetImage(){
  if(!ENEMY_SPRITE_SHEET_IMAGE){
    const img=new Image();
    img.decoding='async';
    img.src=ENEMY_SPRITE_SHEET_DATA;
    img.onload=()=>{
      try{if(gameState?.inBattle)updateDungeonView();}catch(_e){}
    };
    ENEMY_SPRITE_SHEET_IMAGE=img;
  }
  return ENEMY_SPRITE_SHEET_IMAGE;
}
const MIMIC_SPRITE_DATA='data:image/png;base64,';
let mimicSpriteImage=null;
const specialEnemySpriteCache=new Map();
function getMimicSpriteImage(){
 if(!mimicSpriteImage){
  mimicSpriteImage=new Image();
  mimicSpriteImage.onload=()=>{if(gameState?.inBattle)updateDungeonView();};
  mimicSpriteImage.src=MIMIC_SPRITE_DATA;
 }
 return mimicSpriteImage;
}
// サモナ固有ボス: 3列×2行・64pxセル。各個体を分離し外周1pxを黒で保護、透明余白2px以上。
const SUMMONA_BOSS_SPRITE_DATA='data:image/png;base64,';
const SUMMONA_BOSS_SPRITE_INDEX=Object.freeze({
  'deep_watch_return_shadow': 0,
  'full_party_probe_guardian': 1,
  'vessel_mimic_57': 2,
  'forecast_guardian_63': 3,
  'mugen_boundary_75': 4,
  'mugen_boundary_75_echo': 5,
});
const SUMMONA_BOSS_SPRITE_NAMES=Object.freeze({
  '帰路を塞ぐ黒影': 'deep_watch_return_shadow',
  '碑守の巨兵': 'full_party_probe_guardian',
  '空殻の写し身': 'vessel_mimic_57',
  '未踏記録の番人': 'forecast_guardian_63',
  '境界の観測体': 'mugen_boundary_75',
  '境界の観測体・反響': 'mugen_boundary_75_echo',
});
let summonaBossSpriteImage=null;
function getSummonaBossSpriteImage(){
 if(!summonaBossSpriteImage){
  const img=new Image();img.decoding='async';
  img.onload=()=>{try{if(gameState?.inBattle)updateDungeonView();}catch(_e){}};
  img.src=SUMMONA_BOSS_SPRITE_DATA;summonaBossSpriteImage=img;
 }
 return summonaBossSpriteImage;
}
function getSummonaBossSpriteId(enemy){
 const id=enemy?.summonaBossId||enemy?.bossDbId;
 if(Object.prototype.hasOwnProperty.call(SUMMONA_BOSS_SPRITE_INDEX,id))return id;
 const name=String(enemy?.name||'').replace(/^【固有個体】/u,'').trim();
 return SUMMONA_BOSS_SPRITE_NAMES[name]||null;
}
function getSummonaBossSprite(enemy){
 const id=getSummonaBossSpriteId(enemy);if(!id)return null;
 const key='summona:'+id;
 if(specialEnemySpriteCache.has(key))return specialEnemySpriteCache.get(key);
 const source=getSummonaBossSpriteImage();if(!source?.complete||!source.naturalWidth)return null;
 const index=SUMMONA_BOSS_SPRITE_INDEX[id];
 const cell=document.createElement('canvas');cell.width=cell.height=64;
 const ctx=cell.getContext('2d');ctx.imageSmoothingEnabled=false;
 ctx.drawImage(source,(index%3)*64,Math.floor(index/3)*64,64,64,0,0,64,64);
 specialEnemySpriteCache.set(key,cell);return cell;
}
function getSpecialEnemySprite(enemy){
 const summonaSprite=getSummonaBossSprite(enemy);if(summonaSprite)return summonaSprite;
 const name=String(enemy?.name||'');
 const key=enemy?.bossRole==='mimic'||name.includes('ミミック')?'mimic'
  :enemy?.isLivingThug||name.startsWith('ゴロツキ')?'thug':null;
 if(!key)return null;
 if(specialEnemySpriteCache.has(key))return specialEnemySpriteCache.get(key);
 const source=key==='mimic'?getMimicSpriteImage():getEnemySpriteSheetImage();
 if(!source?.complete||!source.naturalWidth)return null;
 const cell=document.createElement('canvas');cell.width=cell.height=64;
 const draw=cell.getContext('2d');draw.imageSmoothingEnabled=false;
 if(key==='mimic'){
  // 64pxへの縮小・透過背景・黒い外周1pxは埋め込みPNGに加工済み。
  draw.drawImage(source,0,0);
  specialEnemySpriteCache.set(key,cell);return cell;
 }
 // ゴロツキには既存の盗賊（DB名：山賊）を色・形とも変更せず使う。
 const index=ENEMY_SPRITE_INDEX['山賊'];
 draw.drawImage(source,(index%ENEMY_SPRITE_COLS)*ENEMY_SPRITE_CELL,
  Math.floor(index/ENEMY_SPRITE_COLS)*ENEMY_SPRITE_CELL,
  ENEMY_SPRITE_CELL,ENEMY_SPRITE_CELL,0,0,64,64);
 specialEnemySpriteCache.set(key,cell);return cell;
}
function preloadEnemyIcons(){getEnemySpriteSheetImage();getMimicSpriteImage();getSummonaBossSpriteImage();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',preloadEnemyIcons,{once:true});
else preloadEnemyIcons();

function hasMajorEnemyAura(enemy){
  return!!(enemy&&(enemy.isBoss||enemy.isStrongEnemy||enemy.isTreasureGuardian||enemy.isQuestEscapeBoss||enemy.bossRole));
}
function getEnemySpriteIndex(enemy){
  const raw=String(enemy?.name||'').trim();
  const base=raw
    .replace(/^(?:【(?:守護者|強敵|討伐対象)】)+/u,'')
    .replace(/\s*護衛\d*$/u,'')
    .replace(/\s+[A-Z]$/u,'')
    .trim();
  if(Object.prototype.hasOwnProperty.call(ENEMY_SPRITE_INDEX,base))return ENEMY_SPRITE_INDEX[base];
  return ENEMY_CATEGORY_FALLBACK_INDEX[enemy?.category] ?? 0;
}
function drawEnemyBattleIcon(ctx,enemy,cx,cy,size=64){
  const img=getEnemySpriteSheetImage();
  const special=getSpecialEnemySprite(enemy);
  const major=hasMajorEnemyAura(enemy);
  ctx.save();
  if(major){
    const pulse=.72+.18*Math.sin(Date.now()/230);
    const guardian=!!(enemy.isBoss||enemy.isTreasureGuardian||enemy.isQuestEscapeBoss||enemy.bossRole);
    const aura=ctx.createRadialGradient(cx,cy,3,cx,cy,size*.78);
    aura.addColorStop(0,guardian?`rgba(255,115,100,${.34*pulse})`:`rgba(210,135,255,${.34*pulse})`);
    aura.addColorStop(.42,guardian?`rgba(230,45,35,${.31*pulse})`:`rgba(154,63,230,${.31*pulse})`);
    aura.addColorStop(1,guardian?'rgba(155,15,10,0)':'rgba(93,20,155,0)');
    ctx.fillStyle=aura;
    ctx.beginPath();ctx.arc(cx,cy,size*.82,0,Math.PI*2);ctx.fill();
    ctx.shadowColor=guardian?'rgba(255,55,40,.98)':'rgba(189,78,255,.98)';
    ctx.shadowBlur=10;
  }
  if(special){
    const smoothing=ctx.imageSmoothingEnabled;ctx.imageSmoothingEnabled=false;
    ctx.drawImage(special,Math.round(cx-size/2),Math.round(cy-size/2),size,size);
    ctx.imageSmoothingEnabled=smoothing;
  }else if(img&&img.complete&&img.naturalWidth){
    const index=getEnemySpriteIndex(enemy);
    const sx=(index%ENEMY_SPRITE_COLS)*ENEMY_SPRITE_CELL;
    const sy=Math.floor(index/ENEMY_SPRITE_COLS)*ENEMY_SPRITE_CELL;
    const previousSmoothing=ctx.imageSmoothingEnabled;
    ctx.imageSmoothingEnabled=false;
    ctx.drawImage(
      img,
      sx,sy,ENEMY_SPRITE_CELL,ENEMY_SPRITE_CELL,
      Math.round(cx-size/2),Math.round(cy-size/2),size,size
    );
    ctx.imageSmoothingEnabled=previousSmoothing;
  }else{
    ctx.shadowBlur=major?8:0;
    ctx.font='22px serif';
    ctx.fillStyle='#e9d7b6';
    ctx.textAlign='center';ctx.textBaseline='middle';
    ctx.fillText('👾',cx,cy);
  }
  ctx.restore();
}

