let gamePreferences={...GAME_PREFERENCE_DEFAULTS};
function loadGamePreferences(){
	try{
		const saved=JSON.parse(localStorage.getItem(GAME_PREFERENCES_STORAGE_KEY)||'null');
		gamePreferences={...GAME_PREFERENCE_DEFAULTS,...(saved&&typeof saved==='object'?saved:{})};
		gamePreferences.deathMode=normalizeDeathMode(gamePreferences.deathMode);
		delete gamePreferences.debugCardCatalog;
		delete gamePreferences.debugSummonaDialogue;
		delete gamePreferences.deathModeChangedWeek;
		delete gamePreferences.equipmentConfirmScope;
	}catch(_error){gamePreferences={...GAME_PREFERENCE_DEFAULTS};}
	return gamePreferences;
}
function saveGamePreferences(){
	try{localStorage.setItem(GAME_PREFERENCES_STORAGE_KEY,JSON.stringify(gamePreferences));}catch(_error){}
}
function normalizeDeathMode(value){return ['permadeath','roguelike','safety'].includes(value)?value:'roguelike';}
function getDeathMode(d=gameState?.dungeon){
	if(!d||d.questInstance||!['normal','mugen'].includes(d.dungeonKind))return null;
	return normalizeDeathMode(gamePreferences.deathMode);
}
function isDeathModeChangeBlocked(){
	return !!(gameState?.dungeon||gameState?.inBattle||gameState?.rescueWaiting||gameState?.inheritancePending||dungeonEntryTransitionBusy);
}
function setDeathMode(value){
	const next=normalizeDeathMode(value);
	if(isDeathModeChangeBlocked()){renderGamePreferencesUI();return;}
	if(next===normalizeDeathMode(gamePreferences.deathMode)){renderGamePreferencesUI();return;}
	gamePreferences.deathMode=next;
	saveGamePreferences();
	renderGamePreferencesUI();
}
function openDeathModePicker(){
	const modal=document.getElementById('death-mode-choice-modal');if(!modal)return;
	const current=normalizeDeathMode(gamePreferences.deathMode);
	const blocked=isDeathModeChangeBlocked();
	modal.querySelectorAll('[data-death-mode-choice]').forEach(btn=>{
		const selected=btn.dataset.deathModeChoice===current;
		btn.setAttribute('aria-pressed',String(selected));
		btn.disabled=blocked&&!selected;
		btn.style.background=selected?'#493027':'#262222';
		btn.style.color=selected?'#ffdfc8':'#ddd';
	});
	const notice=document.getElementById('death-mode-choice-lock');
	if(notice)notice.textContent=blocked?'探索中・救助待ち・継承中は変更できません。町に戻ってから選んでください。':'迷宮の外ではいつでも変更できます。';
	modal.style.display='flex';
}
function closeDeathModePicker(){
	const modal=document.getElementById('death-mode-choice-modal');
	if(modal)modal.style.display='none';
}
function chooseDeathMode(value){
	if(!['permadeath','roguelike','safety'].includes(value))return;
	if(isDeathModeChangeBlocked()&&value!==gamePreferences.deathMode)return;
	setDeathMode(value);
	closeDeathModePicker();
}
function setGamePreference(key,value){
	if(!Object.prototype.hasOwnProperty.call(GAME_PREFERENCE_DEFAULTS,key))return;
	gamePreferences[key]=!!value;
	saveGamePreferences();
	renderGamePreferencesUI();
	if(key==='phantomWalls'&&gameState?.dungeon){
		updateDungeonView();
		refreshMapIfOpen();
	}
	if(key==='battleTipsVisible')updateBattleUIIfActive();
}


function normalizeAutoBattleSpeed(value){
	return ['standard','fast','fastest'].includes(value)?value:'standard';
}
function setAutoBattleSpeed(value){
	gamePreferences.autoBattleSpeed=normalizeAutoBattleSpeed(value);
	saveGamePreferences();
	renderGamePreferencesUI();
	if(battleState.autoMode&&gameState.inBattle){
		cancelPlayerAutoSequence(true);
		if(!battleVisualPlaybackActive)schedulePlayerAutoBattleTurn();
		updateBattleUI();
	}
}
function normalizeManualBattleSpeed(value){
	return ['slow','normal','fast'].includes(value)?value:'normal';
}
function setManualBattleSpeed(value){
	gamePreferences.manualBattleSpeed=normalizeManualBattleSpeed(value);
	saveGamePreferences();
	renderGamePreferencesUI();
}

function renderGamePreferencesUI(){
	const deathMode=document.getElementById('setting-death-mode');
	const stairConfirm=document.getElementById('setting-stair-arrival-confirm');
	const autoChest=document.getElementById('setting-auto-open-chests');
	const phantomWalls=document.getElementById('setting-phantom-walls');
	const formationWarning=document.getElementById('setting-formation-warning');
	const battleTipsVisible=document.getElementById('setting-battle-tips-visible');
	const autoSpeed=document.getElementById('setting-auto-battle-speed');
	const manualSpeed=document.getElementById('setting-manual-battle-speed');
	const majorManual=document.getElementById('setting-major-battle-manual-only');
	if(deathMode){
		const current=normalizeDeathMode(gamePreferences.deathMode);
		deathMode.textContent=`${current==='permadeath'?'パーマデス':current==='safety'?'セーフティ':'ローグライク'}（確認）`;
		const lockInfo=document.getElementById('setting-death-mode-lock');
		if(lockInfo)lockInfo.textContent=isDeathModeChangeBlocked()?'探索中は変更できません。':'';
	}
	if(stairConfirm)stairConfirm.checked=!!gamePreferences.stairArrivalConfirm;
	if(autoChest)autoChest.checked=!!gamePreferences.autoOpenChests;
	if(phantomWalls)phantomWalls.checked=!!gamePreferences.phantomWalls;
	if(formationWarning)formationWarning.checked=!!gamePreferences.formationWarning;
	if(battleTipsVisible)battleTipsVisible.checked=!!gamePreferences.battleTipsVisible;
	if(autoSpeed)autoSpeed.value=normalizeAutoBattleSpeed(gamePreferences.autoBattleSpeed);
	if(manualSpeed)manualSpeed.value=normalizeManualBattleSpeed(gamePreferences.manualBattleSpeed);
	if(majorManual)majorManual.checked=!!gamePreferences.majorBattleManualOnly;
}
loadGamePreferences();


function isDeckRuleExemptCard(card){
	return!!card&&(card.category==='consumable'||card.category==='reward');
}
function isWildLikeCard(card){
	return!!card&&(isDeckRuleExemptCard(card)||card.alchemistCatalyst===true||WILD_LIKE_SUITS.includes(card.suit));
}
function getDeckCoreCards(deck){
	return(deck||[]).filter(card=>card&&!isDeckRuleExemptCard(card)&&!isDepartureBlankCard(card));
}
function getDeckSuitRuleCards(deck){
  // レガシーは総枚数・3種類制限のみ。通常札のスート制限には数えない。
  return getDeckCoreCards(deck).filter(card=>card?.category!=='legacy');
}
function normalizeSpecialCardSuit(card){
	if(!card)return card;
	if(card.category==='consumable')card.suit=CONSUMABLE_SUIT;
	else if(card.category==='reward')card.suit=REWARD_SUIT;
	return card;
}
function normalizeSpecialCardSuitsInArray(cards){
	(cards||[]).forEach(normalizeSpecialCardSuit);
	return cards;
}
function createEmptySuitCounters(){
	return{"⚔️":0,"🛡️":0,"🔮":0,"✨":0,"🌟":0};
}
