const MODIFIER_FLOOR_EFFECT_BASE_WEIGHTS=Object.freeze({poison:1,blood:1,mana:1,mud:1,crumble:1});
const MODIFIER_FLOOR_EFFECT_LABELS=Object.freeze({poison:'毒沼',blood:'血溜まり',mana:'魔力溜まり',mud:'ぬかるみ',crumble:'崩れかけた床'});
function getModifierFloorEffectWordId(source){
  if(typeof source==='string')return source;
  if(source?.id)return String(source.id);
  const id=String(source?.wordIds?.[2]||'');
  if(id&&MODIFIER_FLOOR_EFFECT_WEIGHTS[id])return id;
  const name=String(source?.wordNames?.[2]||'');
  const found=(WORD_DB.modifier||[]).find(word=>word.id===id||(name&&word.name===name));
  return found?.id||id;
}
function getModifierFloorEffectWeights(source){
  const id=getModifierFloorEffectWordId(source);
  return{...MODIFIER_FLOOR_EFFECT_BASE_WEIGHTS,...(MODIFIER_FLOOR_EFFECT_WEIGHTS[id]||{})};
}
function getModifierFloorEffectTendencyText(word){
  if(getWordCategoryKey(word)!=='modifier')return'';
  const weights=getModifierFloorEffectWeights(word);
  const entries=Object.entries(weights).sort((a,b)=>b[1]-a[1]);
  const max=entries[0]?.[1]||1;
  if(max<=1.15)return'床効果の偏りは小さい';
  const favored=entries.filter(([,value])=>value>=Math.max(1.35,max*0.72)).slice(0,2).map(([key])=>MODIFIER_FLOOR_EFFECT_LABELS[key]);
  const suppressed=entries.filter(([,value])=>value<=0.6).slice(-2).map(([key])=>MODIFIER_FLOOR_EFFECT_LABELS[key]);
  let text=`${favored.join('・')}が発生しやすい`;
  if(suppressed.length)text+=`。${suppressed.join('・')}は発生しにくい`;
  return text;
}

