function clampGameInt(value,min,max){
	return Math.max(min,Math.min(max,Math.floor(Number(value)||0)));
}
function capCombatStats(entity){
	if(!entity)return entity;
	if(Number.isFinite(entity.maxHp))entity.maxHp=clampGameInt(entity.maxHp,1,GAME_LIMITS.HP);
	if(Number.isFinite(entity.hp))entity.hp=clampGameInt(entity.hp,0,Number.isFinite(entity.maxHp)?entity.maxHp:GAME_LIMITS.HP);
	['atk','def','matk','mdef','spd'].forEach(key=>{
		if(Number.isFinite(entity[key]))entity[key]=clampGameInt(entity[key],1,GAME_LIMITS.STAT);
	});
	return entity;
}
function capCharacterBases(char){
	if(!char)return char;
	if(Number.isFinite(char.baseMaxHp))char.baseMaxHp=clampGameInt(char.baseMaxHp,1,GAME_LIMITS.HP);
	['baseAtk','baseDef','baseMatk','baseMdef','baseSpd'].forEach(key=>{
		if(Number.isFinite(char[key]))char[key]=clampGameInt(char[key],1,GAME_LIMITS.STAT);
	});
	return char;
}
function addPlayerGold(amount){
	if(!gameState?.player)return 0;
	const before=clampGameInt(gameState.player.gold,0,GAME_LIMITS.GOLD);
	gameState.player.gold=clampGameInt(before+(Number(amount)||0),0,GAME_LIMITS.GOLD);
	return gameState.player.gold-before;
}
function addDiamonds(amount){
	const before=clampGameInt(gameState?.diamonds,0,GAME_LIMITS.DIAMONDS);
	gameState.diamonds=clampGameInt(before+(Number(amount)||0),0,GAME_LIMITS.DIAMONDS);
	return gameState.diamonds-before;
}
function enforceGameLimits(){
	gameState.diamonds=clampGameInt(gameState.diamonds,0,GAME_LIMITS.DIAMONDS);
	if(gameState.player)gameState.player.gold=clampGameInt(gameState.player.gold,0,GAME_LIMITS.GOLD);
	(gameState.party||[]).forEach(char=>{capCharacterBases(char);capCombatStats(char);});
	(battleState?.enemies||[]).forEach(capCombatStats);
}



function normalizeDungeonDifficultyKey(key){
	return DUNGEON_DIFFICULTIES[key]?key:'standard';
}
function getSelectedDungeonDifficultyKey(){
	return normalizeDungeonDifficultyKey(gameState?.dungeonDifficulty);
}
function isFixedDifficultySelectionContext(){
	if(isHeartDungeonInput()&&document.getElementById('screen-word')?.classList.contains('active'))return true;
	if(!customDungeonMode)return false;
	const key=(document.getElementById('custom-dungeon-input')?.value||'').trim();
	if(key==='初めての冒険')return true;
	return!!key&&typeof CUSTOM_DUNGEONS!=='undefined'&&Object.prototype.hasOwnProperty.call(CUSTOM_DUNGEONS,key);
}
function getDungeonDifficultyConfig(dungeon=null){
	const d=dungeon||gameState?.dungeon||null;
	if(d?.heartLabyrinth)return {...DUNGEON_DIFFICULTIES.standard,enemyOffense:0.75,enemyDurability:0.70,enemyDefense:0.80,enemySpeed:0.90};
	if(d?.isTutorial||d?.dungeonKind==='fixed')return DUNGEON_DIFFICULTIES.standard;
	const key=normalizeDungeonDifficultyKey(d?.difficultyKey||gameState?.dungeonDifficulty);
	return DUNGEON_DIFFICULTIES[key];
}
function getDungeonDifficultyKey(dungeon=null){
	const d=dungeon||gameState?.dungeon||null;
	if(d?.isTutorial||d?.dungeonKind==='fixed')return 'standard';
	return normalizeDungeonDifficultyKey(d?.difficultyKey||gameState?.dungeonDifficulty);
}
function getDungeonDifficultySituationText(){
	if(isHeartDungeonInput())return '現在のゲーム設定を適用（出発時に本日の入場を消費）';
	if(isFixedDifficultySelectionContext())return '救助帰還（救助費：所持金の10%）';
	const mode=normalizeDeathMode(gamePreferences.deathMode);
	if(mode==='safety')return 'セーフティ｜戦闘不能・宿屋で復帰';
	if(mode==='roguelike')return 'ローグライク｜死亡者ロスト・デッキ回収依頼';
	return 'パーマデス｜死亡者ロスト・継承者なしで記録消去';
}
function getDungeonDifficultySituationHtml(){
	return `<div style="margin-top:6px;padding-top:5px;border-top:1px solid #4d4328;color:#d8ccb0;font-size:11px;line-height:1.4;">`
		+`<b style="color:#d4af37;">死亡時：</b>${getDungeonDifficultySituationText()}</div>`;
}
