function getDifficultyLootTierBonus(dungeon=null){
	const d=dungeon||gameState?.dungeon||null;
	if(!d||d.isTutorial||d.dungeonKind==='fixed')return 0;
	return Number(getDungeonDifficultyConfig(d).lootTierBonus)||0;
}
function getGrowthDifficultyWeight(){
	const d=gameState?.dungeon||null;
	if(!d||d.isTutorial||d.dungeonKind==='fixed')return 1;
	return Math.max(0.01,Number(getDungeonDifficultyConfig(d).growthWeight)||1);
}
function getNextLevelExp(level){
	const lv=Math.max(1,Math.floor(Number(level)||1));
	if(lv>=MAX_CHARACTER_LEVEL)return 0;
	return Math.max(1,Math.round(10*lv*Math.sqrt(Math.min(lv,10))));
}


function getCharacterNextLevelExp(char){
	const base=getNextLevelExp(char?.level||1);
	if(base<=0)return 0;
	return char?.friendCharacter?Math.max(1,Math.ceil(base*FRIEND_ADVENTURER_EXP_RATE)):base;
}
function getWeekSeed(){
	return Math.floor((Date.now()-BASE_DATE)/ ONE_WEEK_MS);
}
function getDoubleSeed(extraOffset=0){
	const weekSeed=getWeekSeed();
	const partyName=(typeof gameState!=='undefined'&&gameState.partyName)||"冒険隊";
	const partySeed=stringToSeed(partyName);
	return(weekSeed^partySeed)+extraOffset;
}

// WORD_DB: 第1語は10段階の深度帯（基準Lv 5/15/.../95・主生息種・基礎危険/報酬補正）。第2〜4語はLv・深度・地形・産出傾向を小幅に調整する。unlockLevelは解読進行用。


function clampWordStat(value,min,max){
	return Math.min(max,Math.max(min,value));
}
function wordStatRound(value,digits=3){
	const p=10**digits;
	return Math.round(value*p)/ p;
}
function clampCombinedPositive(value,min=0.1,max=Infinity){
	const n=Number.isFinite(value)?value:0;
	return clampWordStat(n,min,max);
}


function getWordCategoryKey(word){
	if(['prefix','terrain','modifier','suffix'].includes(word?.customCategory))return word.customCategory;
	const id=String(word?.id||'');
	const prefixMap={p:'prefix',t:'terrain',m:'modifier',s:'suffix'};
	if(prefixMap[id.charAt(0)])return prefixMap[id.charAt(0)];
	for(const cat of['prefix','terrain','modifier','suffix']){
		if((WORD_DB[cat]||[]).some(w=>w===word||(id&&w.id===id)))return cat;
	}
	return 'unknown';
}
function getSeededWordFallback(word,path,spec){
	const cat=getWordCategoryKey(word);
	const id=String(word?.id||word?.name||'unknown');
	const rng=createRNG(stringToSeed(`WORD_FALLBACK_V7::${cat}::${id}::${path}`));
	const min=spec.min,max=spec.max;
	if(spec.integer)return min+Math.floor(rng()*(max-min+1));
	return wordStatRound(min+rng()*(max-min),spec.digits??3);
}
function getCustomPrefixBandTemplate(word){
	if(getWordCategoryKey(word)!=='prefix'||!word?.customInput)return null;
	const pool=WORD_DB.prefix||[];
	if(!pool.length)return null;
	const seed=stringToSeed(`CUSTOM_NORMAL_PREFIX_BAND_V1::${String(word.name||word.id||'')}`)>>>0;
	return pool[seed%pool.length]||pool[0];
}
function resolveWordScalar(word,key){
	if(Number.isFinite(word?.[key]))return word[key];
	const cat=getWordCategoryKey(word);
	const customPrefix=getCustomPrefixBandTemplate(word);
	if(customPrefix&&Number.isFinite(customPrefix?.[key]))return customPrefix[key];
	if(key==='level'){
		const ranges={terrain:[-2,2],modifier:[-1,1],suffix:[-1,1]};
		const[min,max]=ranges[cat]||[-1,1];
		return getSeededWordFallback(word,key,{min,max,integer:true});
	}
	if(key==='depth'&&cat!=='prefix'){
		return getSeededWordFallback(word,key,{min:-1,max:1,integer:true});
	}
	if(key==='lootTier'&&cat!=='prefix'){
		const ranges={terrain:[-0.25,0.75],modifier:[-0.4,0.4],suffix:[-0.4,1.2]};
		const[min,max]=ranges[cat]||[-0.25,0.5];
		return getSeededWordFallback(word,key,{min,max,digits:2});
	}
	if(cat==='terrain'&&key==='danger'){
		return getSeededWordFallback(word,key,{min:0.80,max:1.30,digits:2});
	}
	if(cat==='modifier'&&WORD_RATE_KEYS.includes(key)){
		return getSeededWordFallback(word,key,{min:1,max:3,integer:true});
	}
	return getSeededWordFallback(word,key,WORD_FALLBACK_SCALARS[key]);
}
function resolveWordRewardWeight(word,type){
	if(Number.isFinite(word?.rewardWeights?.[type]))return word.rewardWeights[type];
	const customPrefix=getCustomPrefixBandTemplate(word);
	if(customPrefix&&Number.isFinite(customPrefix?.rewardWeights?.[type]))return customPrefix.rewardWeights[type];
	return getSeededWordFallback(word,`rewardWeights.${type}`,WORD_FALLBACK_REWARD);
}
function getCustomPrefixEnemyStats(word){
	if(getWordCategoryKey(word)!=='prefix'||!word?.customInput)return null;
	const categories=[...ENEMY_CATEGORIES];
	const rng=createRNG(stringToSeed(`CUSTOM_NORMAL_PREFIX_ENEMY_V2::${String(word.name||word.id||'')}`));
	for(let i=categories.length-1;i>0;i--){
		const j=Math.floor(rng()*(i+1));
		[categories[i],categories[j]]=[categories[j],categories[i]];
	}
	const stats={};
	ENEMY_CATEGORIES.forEach(cat=>stats[cat]=2);
	if(categories[0])stats[categories[0]]=24;
	if(categories[1])stats[categories[1]]=16;
	if(categories[2])stats[categories[2]]=10;
	return stats;
}
function resolveWordEnemyStat(word,enemyCat){
	if(Number.isFinite(word?.enemyStats?.[enemyCat]))return word.enemyStats[enemyCat];
	const customPrefixEnemies=getCustomPrefixEnemyStats(word);
	if(customPrefixEnemies&&Number.isFinite(customPrefixEnemies?.[enemyCat]))return customPrefixEnemies[enemyCat];
	const customPrefix=getCustomPrefixBandTemplate(word);
	if(customPrefix&&Number.isFinite(customPrefix?.enemyStats?.[enemyCat]))return customPrefix.enemyStats[enemyCat];
	const spec=getWordCategoryKey(word)==='suffix'?WORD_FALLBACK_SUFFIX_ENEMY:WORD_FALLBACK_ENEMY;
	return getSeededWordFallback(word,`enemyStats.${enemyCat}`,spec);
}
function resolveModifierRateTier(word,key){
	const raw=Number(resolveWordScalar(word,key));
	return Math.round(clampWordStat(Number.isFinite(raw)?raw:2,1,3));
}
function combineDungeonWordStats(words){
	const valid=(words||[]).filter(Boolean);
	const scalarSum=key=>wordStatRound(valid.reduce((sum,w)=>sum+resolveWordScalar(w,key),0),3);
	const modifierWord=valid.find(w=>getWordCategoryKey(w)==='modifier')||null;
	const prefixWord=valid.find(w=>getWordCategoryKey(w)==='prefix')||null;
	const areaLevelBase=prefixWord?Math.round(resolveWordScalar(prefixWord,'level')):5;
	const areaLevelAdjustRaw=valid
		.filter(w=>getWordCategoryKey(w)!=='prefix')
		.reduce((sum,w)=>sum+Math.round(resolveWordScalar(w,'level')),0);
	const areaLevelAdjust=Math.round(clampWordStat(areaLevelAdjustRaw,-4,4));
	const areaLevel=Math.round(clampWordStat(areaLevelBase+areaLevelAdjust,1,100));
	const rawDanger=scalarSum('danger');
	const levelDangerBonus=((Math.min(100,areaLevel)-1)*(0.80 / 99));
	const danger=wordStatRound(clampWordStat(rawDanger+levelDangerBonus,0.80,2.00),3);
	const depthBase=prefixWord?Math.round(resolveWordScalar(prefixWord,'depth')):1;
	const depthAdjust=valid
		.filter(w=>getWordCategoryKey(w)!=='prefix')
		.reduce((sum,w)=>sum+Math.round(resolveWordScalar(w,'depth')),0);
	const depth=Math.max(2,Math.round(depthBase+depthAdjust));
	const width=Math.round(clampWordStat(scalarSum('width'),8,21));
	const height=Math.round(clampWordStat(scalarSum('height'),8,21));
	const rateTiers={};
	const rateValues={};
	WORD_RATE_KEYS.forEach(key=>{
		const tier=modifierWord?resolveModifierRateTier(modifierWord,key):2;
		rateTiers[key]=tier;
		const base=WORD_RATE_TIER_BASES[key][tier];
		const jitter=valid
			.filter(w=>getWordCategoryKey(w)!=='modifier')
			.reduce((sum,w)=>sum+resolveWordScalar(w,key),0);
		const[min,max]=WORD_RATE_LIMITS[key];
		rateValues[key]=wordStatRound(clampWordStat(base+jitter,min,max),3);
	});
	const{enemyRate,chestRate,eventRate}=rateValues;
	const lootTier=wordStatRound(clampCombinedPositive(scalarSum('lootTier'),0.1,8),2);
	const rewardWeights={weapon:0,armor:0,card:0};
	valid.forEach(word=>REWARD_CATEGORIES.forEach(type=>{
		rewardWeights[type]+=resolveWordRewardWeight(word,type);
	}));
	REWARD_CATEGORIES.forEach(type=>{
		rewardWeights[type]=wordStatRound(clampCombinedPositive(rewardWeights[type],0.1),2);
	});
	const enemyTotals={};
	ENEMY_CATEGORIES.forEach(cat=>enemyTotals[cat]=0);
	valid.forEach(word=>ENEMY_CATEGORIES.forEach(cat=>{
		enemyTotals[cat]+=resolveWordEnemyStat(word,cat);
	}));
	ENEMY_CATEGORIES.forEach(cat=>{
		enemyTotals[cat]=wordStatRound(clampCombinedPositive(enemyTotals[cat],0.1),2);
	});
	const topCategories=Object.entries(enemyTotals).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([cat])=>cat);
	return{
		areaLevel,danger,depth,width,height,
		rewardWeights,enemyTotals,topCategories,
		enemyRate,chestRate,eventRate,rateTiers,lootTier
	};
}
function ensureExplorationProgress(){
	gameState.explorationProgress||={traceAcquisitionRate:0,researchRate:0};
	const progress=gameState.explorationProgress;
	progress.traceAcquisitionRate=Math.max(0,Math.min(100,Number(progress.traceAcquisitionRate)||0));
	progress.researchRate=Math.max(0,Math.min(100,Number(progress.researchRate)||0));
	progress.letterRate=Math.max(0,Math.min(100,Number(progress.letterRate)||0));
	progress.maxNormalAreaLevelReached=Math.max(0,Math.min(100,Math.round(Number(progress.maxNormalAreaLevelReached)||0)));
	return progress;
}
function getNormalResearchReachLevel(fallback=1){
	const progress=ensureExplorationProgress();
	const reached=Math.max(0,Math.round(Number(progress.maxNormalAreaLevelReached)||0));
	return Math.max(1,reached||Math.round(Number(fallback)||1));
}
function noteNormalAreaLevelReached(areaLevel){
	const progress=ensureExplorationProgress();
	const reached=Math.max(1,Math.min(100,Math.round(Number(areaLevel)||1)));
	progress.maxNormalAreaLevelReached=Math.max(progress.maxNormalAreaLevelReached||0,reached);
	return progress.maxNormalAreaLevelReached;
}
function ensureNormalExplorationSystems(){
	gameState.normalWordUnlocks||=createInitialNormalWordUnlocks();
	ensureExplorationProgress();
	gameState.wordKnowledge||={};
	gameState.pioneerJournalSeen||=[];
	Object.keys(gameState.wordKnowledge).forEach(id=>{
		gameState.wordKnowledge[id]=Math.min(999,Math.max(0,Number(gameState.wordKnowledge[id])||0));
	});
	Object.entries(SUMMONA_BEGINNER_WORD_KNOWLEDGE).forEach(([id,bonus])=>{
		gameState.wordKnowledge[id]=Math.max(Number(gameState.wordKnowledge[id])||0,bonus);
	});
	['prefix','terrain','modifier','suffix'].forEach(cat=>{
		gameState.normalWordUnlocks[cat]||=[];
		(WORD_DB[cat]||[]).slice(0,3).forEach(word=>{
			if(word?.id&&!gameState.normalWordUnlocks[cat].includes(word.id))gameState.normalWordUnlocks[cat].push(word.id);
		});
	});
}
function getWordKnowledge(wordOrId){
	ensureNormalExplorationSystems();
	const id=typeof wordOrId==='string'?wordOrId:wordOrId?.id;
	if(!id)return 0;
	return Math.min(999,Math.max(0,Number(gameState.wordKnowledge?.[id])||0));
}
function getWordForecastKnowledge(wordOrId){
	return Math.min(10,getWordKnowledge(wordOrId));
}
function getAreaKnowledge(words){
	ensureNormalExplorationSystems();
	const valid=(words||[]).filter(Boolean);
	if(!valid.length)return 0;
	const average=valid.reduce((sum,word)=>sum+getWordForecastKnowledge(word),0)/ valid.length;
	return wordStatRound(average,1);
}
function addAreaKnowledge(d){
	if(!d||d.dungeonKind!=='normal'||!Array.isArray(d.wordIds))return;
	ensureNormalExplorationSystems();
	d.wordIds.forEach(id=>{
		if(!id)return;
		gameState.wordKnowledge[id]=Math.min(999,(Number(gameState.wordKnowledge[id])||0)+1);
	});
}


function getAreaWordNumber(cat){return AREA_WORD_CATEGORIES.indexOf(cat)+1;}
function getAreaWordPickById(id){
	for(const cat of AREA_WORD_CATEGORIES){
		const word=(WORD_DB[cat]||[]).find(w=>w?.id===id);
		if(word)return{cat,word,wordLevel:getAreaWordRewardLevel(cat,word)};
	}
	return null;
}
function getMugenWordResearchPoints(d=gameState?.dungeon){
	return Math.max(0,Math.floor(Number(d?.wordResearchPoints)||0));
}
function addMugenWordResearchPoints(d,amount,source=''){
	if(!d||d.dungeonKind!=='mugen')return 0;
	const gain=Math.max(0,Math.floor(Number(amount)||0));
	if(gain<=0)return 0;
	d.wordResearchPoints=getMugenWordResearchPoints(d)+gain;
	if(gameState.activeAdventureRecord)gameState.activeAdventureRecord.wordResearchPoints=d.wordResearchPoints;
	if(source)log(`🔎 ワード調査ポイント +${gain}（${source} / 累計${d.wordResearchPoints}）`);
	return gain;
}
function getMugenResearchThresholds(d){
	const depth=Math.max(1,Math.floor(Number(d?.maxDepth||d?.generatedFloorCount||1)||1));
	const s=Math.max(8,depth*MUGEN_RESEARCH_POINTS_PER_FLOOR_FOR_S);
	return{C:Math.ceil(s*0.25),B:Math.ceil(s*0.50),A:Math.ceil(s*0.75),S:s};
}
function getMugenResearchGrade(d,points=getMugenWordResearchPoints(d)){
	const t=getMugenResearchThresholds(d);
	return points>=t.S?'S':points>=t.A?'A':points>=t.B?'B':points>=t.C?'C':'D';
}
function getMugenResearchDepthCap(d){
	const depth=Math.max(1,Math.floor(Number(d?.maxDepth||d?.generatedFloorCount||1)||1));
	if(depth>=6)return 4;
	if(depth>=5)return 3;
	if(depth>=3)return 2;
	return 1;
}
function getMugenResearchWordCount(d,points=getMugenWordResearchPoints(d)){
	const grade=getMugenResearchGrade(d,points);
	return Math.min(MUGEN_RESEARCH_GRADE_COUNT[grade]||0,getMugenResearchDepthCap(d));
}
function getMugenModelWordPicks(d){
	return(d?.wordIds||[]).map(getAreaWordPickById).filter(Boolean);
}
function pickSeededUnique(items,count,seedText=''){
	const pool=[...(items||[])];
	const out=[];
	const rng=createRNG(stringToSeed(seedText||'MUGEN_WORD_RESEARCH'));
	while(pool.length&&out.length<count){
		const idx=Math.floor(rng()*pool.length);
		out.push(pool.splice(idx,1)[0]);
	}
	return out;
}
function acquireAreaWordSilently(pick){
	if(!pick?.cat||!pick?.word?.id)return null;
	ensureNormalExplorationSystems();
	if(gameState.normalWordUnlocks[pick.cat].includes(pick.word.id))return null;
	gameState.normalWordUnlocks[pick.cat].push(pick.word.id);
	if(gameState.wordInvestigation){
		gameState.wordInvestigation.pending=(gameState.wordInvestigation.pending||[]).filter(id=>id!==pick.word.id);
		if(gameState.wordInvestigation.fragments)delete gameState.wordInvestigation.fragments[pick.word.id];
		gameState.wordInvestigation.backlog=(gameState.wordInvestigation.backlog||[]).filter(x=>x.id!==pick.word.id);
		promoteDeferredWordInvestigations();
	}
	if(typeof refreshWordSelects==='function')refreshWordSelects();
	return pick.word.name;
}
function pickMugenRankBonusWord(d,excludedIds=[],seedText=''){
	const excluded=new Set(excludedIds||[]);
	const candidates=getResearchWordCandidates(d?.areaLevel||1)
		.filter(p=>p?.word?.id&&!excluded.has(p.word.id));
	if(!candidates.length)return null;
	const target=Math.max(1,Math.round(Number(d?.areaLevel)||1));
	const weighted=[];
	candidates.forEach(c=>{
		const distance=Math.abs(c.wordLevel-target);
		const weight=Math.max(1,7-Math.min(6,distance));
		for(let i=0;i<weight;i++)weighted.push(c);
	});
	const rng=createRNG(stringToSeed(`${seedText}::rankBonus::${target}::${weighted.length}`));
	return weighted[Math.floor(rng()*weighted.length)]||candidates[0];
}
function resolveMugenWordRewards(d,record,result='escape'){
	if(!d||d.dungeonKind!=='mugen'||d.mugenSecretArena||d.mugenWordRewardsResolved)return[];
	d.mugenWordRewardsResolved=true;
	ensureNormalExplorationSystems();
	const points=getMugenWordResearchPoints(d);
	const researchGrade=getMugenResearchGrade(d,points);
	const thresholds=getMugenResearchThresholds(d);
	const researchCount=getMugenResearchWordCount(d,points);
	const modelPicks=getMugenModelWordPicks(d);
	const lockedModels=modelPicks.filter(p=>!gameState.normalWordUnlocks[p.cat].includes(p.word.id));
	const selectedModels=pickSeededUnique(lockedModels,researchCount,`${record?.id||d.specialSeed||d.name}::models::${points}`);
	const details=[];
	selectedModels.forEach(pick=>{
		const name=acquireAreaWordSilently(pick);
		if(!name)return;
		details.push({name,source:'調査',id:pick.word.id});
		log(`🔎 調査成果：第${getAreaWordNumber(pick.cat)}ワード【${name}】を解読した。`);
	});
	if(result==='clear'&&details.length<5){
		const explorationGrade=record?.explorationGrade||legacyEvaluateCoverage(d)?.grade||'D';
		const chance=MUGEN_WORD_DECODE_RATE[explorationGrade]||0;
		const rng=createRNG(stringToSeed(`${record?.id||d.specialSeed||d.name}::rankWord::${explorationGrade}`));
		if(rng()<chance){
			const excludedIds=modelPicks.map(p=>p.word.id).concat(details.map(x=>x.id).filter(Boolean));
			const bonusPick=pickMugenRankBonusWord(d,excludedIds,record?.id||d.specialSeed||d.name);
			const bonusName=bonusPick?acquireAreaWordSilently(bonusPick):null;
			if(bonusName){
				details.push({name:bonusName,source:`探索評価${explorationGrade}`,id:bonusPick.word.id});
				log(`🏅 探索評価${explorationGrade}：追加ワード【${bonusName}】を解読した。`);
			}
		}
	}
	const capped=details.slice(0,5);
	if(record){
		record.wordResearchPoints=points;
		record.wordResearchGrade=researchGrade;
		record.wordResearchThresholds=thresholds;
		record.wordResearchDepthCap=getMugenResearchDepthCap(d);
		record.wordAwardDetails=capped;
		record.wordAwards=capped.map(x=>x.name);
	}
	return capped;
}
function getAreaWordRewardLevel(cat,word){
	// 第1語だけが迷宮の難易度帯を担う。調査条件も基準Lvそのものを使う。
	if(cat==='prefix'){
		const baseLevel=Number(word?.level);
		if(Number.isFinite(baseLevel))return Math.max(1,Math.round(baseLevel));
	}
	// 第2〜4語は横方向の探索要素。旧unlockLevelは調査条件には使わない。
	return 1;
}

 // 未解読の記録を持って痕跡を一通り調べると約1〜2周で1文字。
 // 100で確定、途中抽選は最大約2.5%。

function getTraceProgressBaseGain(d,targetPerRun=TRACE_PROGRESS_TARGET_PER_RUN,maxPerTrace=20){
	const floorCount=Math.max(1,Math.floor(Number(d?.maxDepth)||1));
	const tracesOnFloor=Math.max(1,Math.floor(Number(d?.objectCounts?.trace)||1));
	return Math.max(0.1,Math.min(maxPerTrace,targetPerRun/(floorCount*tracesOnFloor)));
}


function ensureWordInvestigationState(){
	const state=gameState.wordInvestigation&&typeof gameState.wordInvestigation==='object'?gameState.wordInvestigation:{pending:[],fragments:{},backlog:[]};
	if(!Array.isArray(state.pending))state.pending=[];
	if(!state.fragments||typeof state.fragments!=='object')state.fragments={};
	if(!Array.isArray(state.backlog))state.backlog=[];
	state.pending=[...new Set(state.pending)].filter(id=>{
		const pick=getAreaWordPickById(id);
		return!!pick&&!gameState.normalWordUnlocks?.[pick.cat]?.includes(id);
	});
	if(state.pending.length>MAX_ACTIVE_WORD_INVESTIGATIONS){
		state.pending.splice(MAX_ACTIVE_WORD_INVESTIGATIONS).forEach(id=>state.backlog.push({id,source:'保管中の記録',fragments:state.fragments[id]||[]}));
	}
	const pending=new Set(state.pending),queued=new Set();
	state.backlog=state.backlog.filter(entry=>{
		const id=entry?.id,pick=getAreaWordPickById(id);
		if(!pick||pending.has(id)||queued.has(id)||gameState.normalWordUnlocks?.[pick.cat]?.includes(id))return false;
		queued.add(id);return true;
	});
	Object.keys(state.fragments).forEach(id=>{
		if(!pending.has(id)){delete state.fragments[id];return;}
		const length=Array.from(getAreaWordPickById(id).word.name).length;
		state.fragments[id]=[...new Set(Array.isArray(state.fragments[id])?state.fragments[id]:[])].filter(i=>Number.isInteger(i)&&i>=0&&i<length);
	});
	gameState.wordInvestigation=state;return state;
}
function isWordPending(id){return ensureWordInvestigationState().pending.includes(id);}
function isWordBacklogged(id){return ensureWordInvestigationState().backlog.some(entry=>entry.id===id);}
function getWordCipherLabel(id){
	let hash=stringToSeed(`UNREAD_WORD::${id}`)>>>0;
	const length=3+(hash%4);let result='';
	for(let i=0;i<length;i++){hash=(Math.imul(hash,1664525)+1013904223)>>>0;result+=WORD_MASK_GLYPHS[hash%WORD_MASK_GLYPHS.length];}
	return result;
}
function getWordFoundLetterCount(id){return ensureWordInvestigationState().fragments[id]?.length||0;}
function getScrambledLetterHtml(id){
	const pick=getAreaWordPickById(id);if(!pick||!isWordPending(id))return '文字片なし';
	const chars=Array.from(pick.word.name),indices=ensureWordInvestigationState().fragments[id]||[];
	if(!indices.length)return '文字片なし';
	const letters=indices.map(i=>({i,char:chars[i]})).sort((a,b)=>(stringToSeed(`${id}::${a.i}::mix`)>>>0)-(stringToSeed(`${id}::${b.i}::mix`)>>>0));
	if(letters.length>1&&letters.every((entry,i)=>entry.i===indices.slice().sort((a,b)=>a-b)[i]))letters.reverse();
	return letters.map(({char})=>`「${escapeHtml(char)}」`).join(' ');
}
function stageUnresolvedWord(pick,source='調査',saveNow=true){
	if(!pick?.cat||!pick?.word?.id||isNormalWordOwned(pick.cat,pick.word.id))return false;
	const state=ensureWordInvestigationState();if(state.pending.includes(pick.word.id)||state.backlog.some(x=>x.id===pick.word.id))return false;
	if(state.pending.length>=MAX_ACTIVE_WORD_INVESTIGATIONS){
		state.backlog.push({id:pick.word.id,source});
		log(`📖 未解読の記録【${getWordCipherLabel(pick.word.id)}】を保管した。解析の枠が空いたら調べられる。`);
		if(saveNow)saveGame();return true;
	}
	state.pending.push(pick.word.id);state.fragments[pick.word.id]=[];
	if(gameState.activeAdventureRecord?.wordInvestigation)gameState.activeAdventureRecord.wordInvestigation.found.push({cipher:getWordCipherLabel(pick.word.id),source});
	log(`📖 ${source}から未解読の記録【${getWordCipherLabel(pick.word.id)}】を得た。サモナに見せられる。`);
	if(saveNow)saveGame();return true;
}
function promoteDeferredWordInvestigations(){
	const state=ensureWordInvestigationState();
	while(state.pending.length<MAX_ACTIVE_WORD_INVESTIGATIONS&&state.backlog.length){
		const entry=state.backlog.shift(),pick=getAreaWordPickById(entry.id);
		if(!pick||isNormalWordOwned(pick.cat,entry.id))continue;
		state.pending.push(entry.id);state.fragments[entry.id]=Array.isArray(entry.fragments)?entry.fragments:[];
		log(`📖 保管していた未解読の記録【${getWordCipherLabel(entry.id)}】の解析を始められる。`);
	}
}
function discoverMugenInputLetters(input){
	const state=ensureWordInvestigationState();
	if(!state.pending.length)return [];
	const gained=[];
	for(const char of Array.from(String(input||''))){
		for(const id of state.pending){
			const word=getAreaWordPickById(id)?.word;if(!word)continue;
			const found=state.fragments[id]||[],index=Array.from(word.name).findIndex((letter,i)=>letter===char&&!found.includes(i));
			if(index<0)continue;
			found.push(index);state.fragments[id]=found;
			gained.push({cipher:getWordCipherLabel(id),char});
			if(gameState.activeAdventureRecord?.wordInvestigation)gameState.activeAdventureRecord.wordInvestigation.letters.push({cipher:getWordCipherLabel(id),char});
		}
	}
	if(gained.length)log(`🔎 夢幻迷宮に入力した言葉から文字片を照合した：${gained.map(x=>`【${x.cipher}】「${escapeHtml(x.char)}」`).join(' ')}`);
	return gained;
}
function tryDiscoverWordLetter(d){
	if(d?.dungeonKind!=='normal')return false;
	const state=ensureWordInvestigationState();
	const progress=ensureExplorationProgress();
	if(!state.pending.length){progress.letterRate=0;return false;}
	progress.letterRate=Math.min(100,progress.letterRate+getTraceProgressBaseGain(d,WORD_LETTER_TARGET_PER_RUN,100));
	if(!shouldAwardFromProgress(progress.letterRate))return false;
	const possible=state.pending.flatMap(id=>{
		const word=getAreaWordPickById(id)?.word;
		if(!word)return[];
		const found=new Set(state.fragments[id]||[]);
		return Array.from(word.name).flatMap((_,i)=>found.has(i)?[]:[{id,i}]);
	});
	if(!possible.length){progress.letterRate=0;return false;}
	const item=possible[Math.floor(Math.random()*possible.length)];
	state.fragments[item.id]||=[];state.fragments[item.id].push(item.i);
	progress.letterRate=0;
	const char=Array.from(getAreaWordPickById(item.id).word.name)[item.i];
	if(gameState.activeAdventureRecord?.wordInvestigation)gameState.activeAdventureRecord.wordInvestigation.letters.push({cipher:getWordCipherLabel(item.id),char});
	log(`🔎 未解読の記録【${getWordCipherLabel(item.id)}】から文字片「${escapeHtml(char)}」を見つけた。`);
	saveGame();return true;
}
function getLockedAreaWords(){
	ensureNormalExplorationSystems();
	const result=[];
	AREA_WORD_CATEGORIES.forEach(cat=>{
		(WORD_DB[cat]||[]).forEach(word=>{
			if(gameState.normalWordUnlocks[cat].includes(word.id))return;
			result.push({cat,word,wordLevel:getAreaWordRewardLevel(cat,word)});
		});
	});
	return result;
}
function getResearchWordCandidates(areaLevel,excludePending=false){
	const target=Math.max(1,Math.round(Number(areaLevel)||1),getNormalResearchReachLevel(1));
	const locked=getLockedAreaWords().filter(p=>!excludePending||(!isWordPending(p.word.id)&&!isWordBacklogged(p.word.id)));
	if(!locked.length)return[];

	// 第1語：基準Lvまで到達済みの未解読語がある限り、他カテゴリより必ず優先する。
	// 複数取りこぼしている場合は、低い基準Lvから順番に埋める。
	const reachablePrefixes=locked.filter(c=>c.cat==='prefix'&&Math.max(1,Math.round(Number(c.word?.level)||1))<=target);
	if(reachablePrefixes.length){
		const nextLevel=Math.min(...reachablePrefixes.map(c=>Math.max(1,Math.round(Number(c.word?.level)||1))));
		return reachablePrefixes.filter(c=>Math.max(1,Math.round(Number(c.word?.level)||1))===nextLevel);
	}

	// 第2〜4語：Area Lvによる足切りは行わない。未解読なら常に調査候補。
	return locked.filter(c=>c.cat!=='prefix');
}
function pickResearchAreaWord(areaLevel,seedText='',excludePending=false){
	const candidates=getResearchWordCandidates(areaLevel,excludePending);
	if(!candidates.length)return null;
	const target=Math.max(1,Math.round(Number(areaLevel)||1),getNormalResearchReachLevel(1));
	const rng=createRNG(stringToSeed(`${seedText}::${target}::${gameState.adventureStats?.clears||0}::${candidates.length}`));

	// 第1語候補が返る時点で最優先枠。通常は次の1語だけだが、同Lvが増えても公平に抽選する。
	const prefixCandidates=candidates.filter(c=>c.cat==='prefix');
	if(prefixCandidates.length)return prefixCandidates[Math.floor(rng()*prefixCandidates.length)]||prefixCandidates[0];

	// 第2〜4語は全未解読語から均等抽選。各カテゴリは同数構成なので、
	// 解読が遅れて未解読語が多いカテゴリほど自然に少し選ばれやすくなる。
	return candidates[Math.floor(rng()*candidates.length)]||candidates[0];
}
function shouldAwardFromProgress(rate){
	const value=Math.max(0,Math.min(100,Number(rate)||0));
	if(value>=100)return true;
	return Math.random()<value*TRACE_PROGRESS_ROLL_SCALE;
}
function getCurrentAreaJournalUnseen(d){
	if(!d)return[];
	ensurePioneerJournalSeen();
	const entries=PIONEER_JOURNAL[Math.max(1,Math.round(Number(d.areaLevel)||1))];
	return Array.isArray(entries)?entries.filter(e=>!gameState.pioneerJournalSeen.includes(e.id)):[];
}
function processTraceProgress(d,seedText=''){
	if(!d||d.customDungeon||d.questInstance||gameState.tutorialState?.active)return{fragment:false,word:false,researchPoint:false};
	const progress=ensureExplorationProgress();
	const isNormal=d.dungeonKind==='normal';
	const isMugen=d.dungeonKind==='mugen';
	if(isNormal)noteNormalAreaLevelReached(d.areaLevel);

  // 夢幻迷宮の痕跡は探索内ワード調査ポイントにのみ加算する。

  if(isMugen){
		addMugenWordResearchPoints(d,1,'痕跡');
		return{fragment:false,word:false,researchPoint:true};
	}
	const baseGain=getTraceProgressBaseGain(d);
	progress.traceAcquisitionRate=Math.min(100,progress.traceAcquisitionRate+baseGain*(isNormal?2:1));
	progress.researchRate=Math.min(100,progress.researchRate+baseGain);
	if(isNormal&&progress.researchRate>=100&&!progress.researchReadyAreaLevel){
		progress.researchReadyAreaLevel=Math.max(1,Math.round(Number(d.areaLevel)||1));
		const unlocks=ensureProgressionUnlocks();
		if(!unlocks.research){
			unlocks.researchIntroPending=true;
			log('📄 痕跡から、まとまった資料を持ち帰れそうだ。');
		}else log('🔎 調査資料が揃った。町でサモナと解析しよう。');
	}
	let fragment=false;
	let word=false;
	if(isNormal&&getCurrentAreaJournalUnseen(d).length&&shouldAwardFromProgress(progress.traceAcquisitionRate)){
		const rng=createRNG(stringToSeed(`${seedText}::journal::${Math.floor(progress.traceAcquisitionRate*10)}`));
		fragment=tryDiscoverPioneerJournal(d,rng);
		if(fragment)progress.traceAcquisitionRate=0;
	}
	// 未解読の記録からのみ文字片を発見する。配列位置は画面に出さない。
	const letter=tryDiscoverWordLetter(d);
	return{fragment,word,researchPoint:false,letter};
}
function refreshWordSelects(){
	const categories=NORMAL_WORD_SLOT_DEFS;
	ensureNormalExplorationSystems();
	categories.forEach(cat=>{
		const selectEl=document.getElementById(cat.id);
		if(!selectEl)return;
		const selectedValue=selectEl.value;
		const selectedCustom=String(selectEl.dataset.customWord||'').trim();
		selectEl.innerHTML='';
		const allowed=new Set(gameState.normalWordUnlocks[cat.key]||[]);
		(WORD_DB[cat.key]||[]).filter(item=>!allowed||allowed.has(item.id)).forEach(item=>{
			const option=document.createElement('option');
			option.value=item.id;
			option.textContent=item.name;
			selectEl.appendChild(option);
		});
		if(selectedValue&&selectEl.querySelector(`option[value="${selectedValue}"]`)){
			selectEl.value=selectedValue;
		}else{
			const beginnerDefault=BEGINNER_NORMAL_DUNGEON_DEFAULTS[cat.id];
			if(beginnerDefault&&selectEl.querySelector(`option[value="${beginnerDefault}"]`))selectEl.value=beginnerDefault;
		}
		if(selectedCustom)selectEl.dataset.customWord=selectedCustom;
	});
	renderNormalWordSlots();
	if(document.getElementById('normal-word-browser-modal')?.style.display==='flex')renderNormalWordBrowser();
	if(typeof updateWordInfo==='function')updateWordInfo();
}

const NORMAL_WORD_SLOT_DEFS=Object.freeze([
	Object.freeze({id:'w1',key:'prefix',label:'第1語',kind:'深度'}),
	Object.freeze({id:'w2',key:'terrain',label:'第2語',kind:'地形'}),
	Object.freeze({id:'w3',key:'modifier',label:'第3語',kind:'性質'}),
	Object.freeze({id:'w4',key:'suffix',label:'第4語',kind:'結び'})
]);
let normalWordBrowserSlotId='w1';
const NORMAL_CUSTOM_WORD_MAX_LENGTH=5;

function getNormalWordSlotDef(slotId){
	return NORMAL_WORD_SLOT_DEFS.find(def=>def.id===slotId)||NORMAL_WORD_SLOT_DEFS[0];
}
function makeCustomNormalDungeonWord(category,name){
	const clean=Array.from(String(name||'').trim()).slice(0,NORMAL_CUSTOM_WORD_MAX_LENGTH).join('');
	if(!clean)return null;
	const seed=(stringToSeed(`CUSTOM_NORMAL_WORD_V1::${category}::${clean}`)>>>0).toString(16).padStart(8,'0');
	return{id:`custom_${category}_${seed}`,name:clean,customCategory:category,customInput:true};
}
function ensureNormalCustomWordHistory(){
	gameState.normalCustomWordHistory||={prefix:[],terrain:[],modifier:[],suffix:[]};
	for(const key of['prefix','terrain','modifier','suffix']){
		if(!Array.isArray(gameState.normalCustomWordHistory[key]))gameState.normalCustomWordHistory[key]=[];
		gameState.normalCustomWordHistory[key]=gameState.normalCustomWordHistory[key]
			.map(v=>Array.from(String(v||'').trim()).slice(0,NORMAL_CUSTOM_WORD_MAX_LENGTH).join('')).filter(Boolean).slice(0,5);
	}
	return gameState.normalCustomWordHistory;
}
function rememberNormalCustomWord(category,name){
	const history=ensureNormalCustomWordHistory();
	const clean=Array.from(String(name||'').trim()).slice(0,NORMAL_CUSTOM_WORD_MAX_LENGTH).join('');
	if(!clean)return;
	history[category]=[clean,...history[category].filter(v=>v!==clean)].slice(0,5);
}
function ensureNormalWordUsageHistory(){
	gameState.normalWordUsageHistory||={prefix:[],terrain:[],modifier:[],suffix:[]};
	for(const key of['prefix','terrain','modifier','suffix']){
		if(!Array.isArray(gameState.normalWordUsageHistory[key]))gameState.normalWordUsageHistory[key]=[];
		const normalized=[];
		for(const raw of gameState.normalWordUsageHistory[key]){
			if(!raw||typeof raw!=='object')continue;
			const custom=!!raw.custom;
			const name=Array.from(String(raw.name||'').trim()).slice(0,NORMAL_CUSTOM_WORD_MAX_LENGTH).join('');
			const id=String(raw.id||'').trim();
			if(!name||(!custom&&!id))continue;
			const rec={id:custom?(makeCustomNormalDungeonWord(key,name)?.id||id):id,name,custom};
			const recKey=`${custom?'c':'d'}:${rec.id||rec.name}`;
			if(normalized.some(v=>`${v.custom?'c':'d'}:${v.id||v.name}`===recKey))continue;
			normalized.push(rec);
			if(normalized.length>=3)break;
		}
		gameState.normalWordUsageHistory[key]=normalized;
	}
	return gameState.normalWordUsageHistory;
}
function rememberNormalWordUse(category,word){
	if(!word)return;
	const history=ensureNormalWordUsageHistory();
	const rec={id:String(word.id||''),name:String(word.name||''),custom:!!word.customInput};
	const recKey=`${rec.custom?'c':'d'}:${rec.id||rec.name}`;
	history[category]=[rec,...history[category].filter(v=>`${v.custom?'c':'d'}:${v.id||v.name}`!==recKey)].slice(0,3);
}
function resolveNormalWordUsageRecord(category,record){
	if(!record)return null;
	if(record.custom)return makeCustomNormalDungeonWord(category,record.name);
	return(WORD_DB[category]||[]).find(word=>word.id===record.id)||null;
}
function getNormalWordFromSlot(slotId){
	const def=getNormalWordSlotDef(slotId),el=document.getElementById(slotId);
	if(!el)return null;
	const custom=String(el.dataset.customWord||'').trim();
	if(custom)return makeCustomNormalDungeonWord(def.key,custom);
	return(WORD_DB[def.key]||[]).find(word=>word.id===el.value)||null;
}
function setNormalWordSlotDb(slotId,wordId){
	const def=getNormalWordSlotDef(slotId),el=document.getElementById(slotId);
	const word=(WORD_DB[def.key]||[]).find(item=>item.id===wordId)||null;
	if(!el||!word)return;
	delete el.dataset.customWord;
	el.value=wordId;
	renderNormalWordSlots();
	updateWordInfo();
	renderNormalWordBrowser();
}
function setNormalWordSlotCustom(slotId,name){
	const def=getNormalWordSlotDef(slotId),el=document.getElementById(slotId);
	const word=makeCustomNormalDungeonWord(def.key,name);
	if(!el||!word)return false;
	el.dataset.customWord=word.name;
	rememberNormalCustomWord(def.key,word.name);
	renderNormalWordSlots();
	updateWordInfo();
	renderNormalWordBrowser();
	return true;
}
function renderNormalWordSlots(){
	NORMAL_WORD_SLOT_DEFS.forEach(def=>{
		const button=document.getElementById(`normal-word-slot-${def.id}`);
		if(!button)return;
		const word=getNormalWordFromSlot(def.id),custom=!!word?.customInput;
		button.classList.toggle('is-custom',custom);
		button.innerHTML=`<span class="slot-label">${def.label}<span class="slot-kind">${custom?'自入力':def.kind}</span></span><span class="slot-word">${escapeHtml(word?.name||'未選択')}</span>`;
	});
}
function openNormalWordBrowser(slotId='w1'){
	if(customDungeonMode)return;
	normalWordBrowserSlotId=getNormalWordSlotDef(slotId).id;
	const modal=document.getElementById('normal-word-browser-modal');
	if(!modal)return;
	const panel=document.getElementById('normal-word-custom-panel');
	if(panel)panel.style.display='none';
	modal.style.display='flex';
	renderNormalWordBrowser();
}
function closeNormalWordBrowser(){
	const modal=document.getElementById('normal-word-browser-modal');
	if(modal)modal.style.display='none';
}
function switchNormalWordBrowserSlot(slotId){
	normalWordBrowserSlotId=getNormalWordSlotDef(slotId).id;
	const panel=document.getElementById('normal-word-custom-panel');
	if(panel)panel.style.display='none';
	renderNormalWordBrowser();
}
function limitNormalCustomWordLength(input){
	if(!input)return;
	const chars=Array.from(String(input.value||'').replace(/[\r\n\t]/g,' '));
	if(chars.length>NORMAL_CUSTOM_WORD_MAX_LENGTH)input.value=chars.slice(0,NORMAL_CUSTOM_WORD_MAX_LENGTH).join('');
}
function toggleNormalWordCustomInput(){
	const panel=document.getElementById('normal-word-custom-panel'),input=document.getElementById('normal-word-custom-input');
	if(!panel)return;
	const opening=panel.style.display==='none'||!panel.style.display;
	panel.style.display=opening?'grid':'none';
	if(opening&&input){
		const current=getNormalWordFromSlot(normalWordBrowserSlotId);
		input.value=current?.customInput?current.name:'';
		setTimeout(()=>input.focus(),0);
	}
}
function applyNormalWordCustomInput(){
	const input=document.getElementById('normal-word-custom-input');
	if(!input)return;
	limitNormalCustomWordLength(input);
	const clean=Array.from(String(input.value||'').trim()).slice(0,NORMAL_CUSTOM_WORD_MAX_LENGTH).join('');
	const verdict=window.MugenWordInputFilter?.validate?window.MugenWordInputFilter.validate(clean):{ok:false,reason:'filter-unavailable'};
	if(!verdict.ok){showGameNotice('反応がないようだ...',{title:'侵入ワード'});return;}
	const accepted=Array.from(String(verdict.normalized||clean).trim()).slice(0,NORMAL_CUSTOM_WORD_MAX_LENGTH).join('');
	if(setNormalWordSlotCustom(normalWordBrowserSlotId,accepted)){
		input.value=accepted;
		const panel=document.getElementById('normal-word-custom-panel');
		if(panel)panel.style.display='none';
	}
}
function getWordInfluenceArrow(value,weak=0.001,strong=0.01){
	const n=Number(value)||0;
	if(n>=strong)return '⇈';
	if(n>=weak)return '↑';
	if(n<=-strong)return '⇊';
	if(n<=-weak)return '↓';
	return '─';
}
function getWordArrowClass(arrow){
	return arrow==='⇈'||arrow==='↑'?'up':arrow==='⇊'||arrow==='↓'?'down':'flat';
}
function getNormalWordLevelArrow(word){
	return getWordInfluenceArrow(Math.round(Number(resolveWordScalar(word,'level'))||0),1,2);
}
function getNormalWordDepthArrow(word){
	return getWordInfluenceArrow(Math.round(Number(resolveWordScalar(word,'depth'))||0),1,2);
}
function getNormalWordDangerArrow(word){
	const cat=getWordCategoryKey(word);
	const raw=Number(resolveWordScalar(word,'danger'))||0;
	const delta=cat==='terrain'?raw-1:raw;
	return getWordInfluenceArrow(delta,0.04,0.14);
}
function getNormalWordScaleArrow(word){
	const cat=getWordCategoryKey(word);
	const pool=(WORD_DB[cat]||[]);
	const value=(Number(resolveWordScalar(word,'width'))||0)+(Number(resolveWordScalar(word,'height'))||0);
	if(!pool.length)return '─';
	const values=pool.map(w=>(Number(resolveWordScalar(w,'width'))||0)+(Number(resolveWordScalar(w,'height'))||0)).sort((a,b)=>a-b);
	const median=values[Math.floor(values.length/2)]||0;
	const delta=value-median;
	return getWordInfluenceArrow(delta,1.5,3.5);
}
function getNormalWordRateArrow(word,key){
	const cat=getWordCategoryKey(word);
	if(cat==='modifier'){
		const tier=resolveModifierRateTier(word,key);
		return tier>=3?'⇈':tier<=1?'⇊':'─';
	}
	return getWordInfluenceArrow(Number(resolveWordScalar(word,key))||0,0.004,0.012);
}
function getNormalWordLootArrow(word){
	const value=Number(resolveWordScalar(word,'lootTier'))||0;
	return getWordInfluenceArrow(value,0.25,1.0);
}
function getNormalWordStrongestRewardInfluence(word){
	const scored=REWARD_CATEGORIES.map(type=>{
		const value=Number(resolveWordRewardWeight(word,type))||0;
		return{type,value,delta:value-10};
	}).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta));
	const top=scored[0];
	if(!top||Math.abs(top.delta)<0.5)return null;
	return{label:rewardTypeLabel(top.type),arrow:getWordInfluenceArrow(top.delta,1.5,5)};
}
function getNormalWordStrongestEnemyInfluence(word){
	const scored=ENEMY_CATEGORIES.map(type=>({type,value:Number(resolveWordEnemyStat(word,type))||0})).sort((a,b)=>Math.abs(b.value)-Math.abs(a.value));
	const top=scored[0];
	if(!top||Math.abs(top.value)<0.5)return null;
	return{label:ENEMY_CATEGORY_LABELS[top.type]||top.type,arrow:getWordInfluenceArrow(top.value,1.5,6)};
}
function getNormalWordTopHabitatEnemies(word,count=3){
	return ENEMY_CATEGORIES
		.map(type=>({type,value:Number(resolveWordEnemyStat(word,type))||0}))
		.sort((a,b)=>b.value-a.value)
		.slice(0,Math.max(1,Math.floor(Number(count)||3)))
		.map(({type})=>ENEMY_CATEGORY_LABELS[type]||type);
}
function normalWordStatSpan(label,value,options={}){
	const publicStat=options.public===true;
	const arrow=options.arrow||'';
	const cls=publicStat?'public':getWordArrowClass(arrow);
	return `<span class="word-stat ${cls}">${escapeHtml(label)}${escapeHtml(String(value))}</span>`;
}
function getNormalWordBrowserHint(word){
	if(!word)return'';
	const cat=getWordCategoryKey(word),knowledge=getWordForecastKnowledge(word),stats=[];
	if(cat==='prefix'){
		const baseLv=Math.max(1,Math.round(resolveWordScalar(word,'level')));
		const habitats=getNormalWordTopHabitatEnemies(word,3);
		stats.push(normalWordStatSpan('Lv.',baseLv,{public:true}));
		stats.push(normalWordStatSpan('生息:',habitats.join('・'),{public:true}));
		return stats.join('');
	}else{
		const lvArrow=getNormalWordLevelArrow(word),depthArrow=getNormalWordDepthArrow(word);
		stats.push(normalWordStatSpan('Lv',lvArrow,{arrow:lvArrow}));
		stats.push(normalWordStatSpan('深度',depthArrow,{arrow:depthArrow}));
	}
	if(knowledge>=2){
		const danger=getNormalWordDangerArrow(word),scale=getNormalWordScaleArrow(word);
		stats.push(normalWordStatSpan('危',danger,{arrow:danger}));
		stats.push(normalWordStatSpan('規模',scale,{arrow:scale}));
	}
	if(knowledge>=4){
		const enemyRate=getNormalWordRateArrow(word,'enemyRate');
		const chestRate=getNormalWordRateArrow(word,'chestRate');
		const eventRate=getNormalWordRateArrow(word,'eventRate');
		stats.push(normalWordStatSpan('敵数',enemyRate,{arrow:enemyRate}));
		stats.push(normalWordStatSpan('宝箱',chestRate,{arrow:chestRate}));
		stats.push(normalWordStatSpan('出来事',eventRate,{arrow:eventRate}));
	}
	if(knowledge>=6){
		const reward=getNormalWordStrongestRewardInfluence(word);
		if(reward)stats.push(normalWordStatSpan(`報:${reward.label}`,reward.arrow,{arrow:reward.arrow}));
		const loot=getNormalWordLootArrow(word);
		if(loot!=='─')stats.push(normalWordStatSpan('質',loot,{arrow:loot}));
	}
	if(knowledge>=8){
		const enemy=getNormalWordStrongestEnemyInfluence(word);
		if(enemy)stats.push(normalWordStatSpan(`敵:${enemy.label}`,enemy.arrow,{arrow:enemy.arrow}));
	}
	return stats.join('');
}
function getNormalWordBrowserForecastText(){
	const words=getSelectedNormalDungeonWords();
	if(words.some(word=>!word))return '4語を揃えると予報が表示される。';
	const combined=combineDungeonWordStats(words);
	return `${words.map(word=>word.name).join('')}　Lv.${combined.areaLevel} / 深度${combined.depth}層`;
}
function selectNormalCustomHistory(index){
	const def=getNormalWordSlotDef(normalWordBrowserSlotId);
	const name=(ensureNormalCustomWordHistory()[def.key]||[])[Math.max(0,Math.floor(Number(index)||0))];
	if(name)setNormalWordSlotCustom(def.id,name);
}
function selectNormalWordUsageHistory(index){
	const def=getNormalWordSlotDef(normalWordBrowserSlotId);
	const record=(ensureNormalWordUsageHistory()[def.key]||[])[Math.max(0,Math.floor(Number(index)||0))];
	const word=resolveNormalWordUsageRecord(def.key,record);
	if(!word)return;
	if(word.customInput)setNormalWordSlotCustom(def.id,word.name);
	else setNormalWordSlotDb(def.id,word.id);
}
function renderNormalWordBrowser(){
	const modal=document.getElementById('normal-word-browser-modal');
	if(!modal||modal.style.display!=='flex')return;
	const def=getNormalWordSlotDef(normalWordBrowserSlotId),current=getNormalWordFromSlot(def.id);
	const title=document.getElementById('normal-word-browser-title');
	if(title)title.textContent=`${def.label}を選ぶ`;
	const forecast=document.getElementById('normal-word-browser-forecast');
	if(forecast)forecast.textContent=getNormalWordBrowserForecastText();
	document.querySelectorAll('[data-normal-word-tab]').forEach(btn=>btn.classList.toggle('active',btn.dataset.normalWordTab===def.id));
	ensureNormalExplorationSystems();
	const allowed=new Set(gameState.normalWordUnlocks[def.key]||[]);
	const dbWords=(WORD_DB[def.key]||[]).filter(word=>allowed.has(word.id));
	const storedCustomNames=(ensureNormalCustomWordHistory()[def.key]||[]).slice(0,5);
	const storedCustomWords=storedCustomNames.map(name=>makeCustomNormalDungeonWord(def.key,name)).filter(Boolean);
	const list=document.getElementById('normal-word-browser-list');
	if(list){
		const dbHtml=dbWords.map(word=>{
			const selected=!current?.customInput&&current?.id===word.id;
			const knowledge=getWordForecastKnowledge(word);
			const meta=def.key==='prefix'?'':`<span class="choice-knowledge">調査Lv.${knowledge}</span>`;
			return `<button type="button" class="normal-word-choice${selected?' selected':''}" onclick="setNormalWordSlotDb('${def.id}','${escapeHtml(word.id)}')"><span class="choice-name">${escapeHtml(word.name)}</span>${meta}<span class="choice-hint">${getNormalWordBrowserHint(word)}</span></button>`;
		}).join('');
		const customHtml=storedCustomWords.map((word,index)=>{
			const selected=!!current?.customInput&&current?.id===word.id;
			const knowledge=getWordForecastKnowledge(word);
			const meta=def.key==='prefix'?'':`<span class="choice-knowledge">自入力 / 調査Lv.${knowledge}</span>`;
			return `<button type="button" class="normal-word-choice is-custom${selected?' selected':''}" onclick="selectNormalCustomHistory(${index})"><span class="choice-name">${escapeHtml(word.name)}</span>${meta}<span class="choice-hint">${getNormalWordBrowserHint(word)}</span></button>`;
		}).join('');
		list.innerHTML=(dbHtml+customHtml)||'<div style="color:#777;padding:8px;">解読済みの語がありません。</div>';
	}
	const history=document.getElementById('normal-word-browser-history');
	const usageItems=(ensureNormalWordUsageHistory()[def.key]||[])
		.map((record,index)=>({record,index,word:resolveNormalWordUsageRecord(def.key,record)}))
		.filter(item=>item.word)
		.slice(0,3);
	if(history)history.innerHTML=usageItems.length?`<span style="flex:0 0 auto;color:#8f8468;font-size:9px;align-self:center;">使用履歴</span>${usageItems.map(({word,index})=>`<button type="button" class="normal-word-history-chip${word.customInput?' is-custom':''}" onclick="selectNormalWordUsageHistory(${index})">${escapeHtml(word.name)}</button>`).join('')}`:'';
}


// 動的札はここで生成し、CARD_MASTER由来の流通へ混入させない。

function createGeneratedCard(kind,data={},options={}){
	const serial=Math.max(0,Math.floor(Number(options.serial)||0));
	const prefix=options.instancePrefix||`generated_${kind}`;
	const card={...data};
	card.masterId||=options.masterId||`generated_${kind}`;
	card.instanceId||=`${prefix}_${Date.now()}_${serial}_${Math.random().toString(36).slice(2,8)}`;
	card.rarity||=options.rarity||'N';
	card.generatedCard=true;
	card.generatedKind=kind;
	return card;
}



function scaleEquipmentStat(baseValue,areaLevel,totalMult){
	const base=Math.max(0,Number(baseValue)||0);
	if(base<=0)return 0;
	const lv=Math.max(1,Math.floor(Number(areaLevel)||1));
	const areaMult=1+(lv-1)*EQUIPMENT_AREA_GROWTH_PER_LEVEL;
	return Math.max(1,Math.floor(base*areaMult*totalMult));
}
function isBowEquipped(char){
	return char?.equip?.weapon?.weaponType==='弓';
}
function getEquipmentMasterEntry(item){
	if(!item)return null;
	const pool=item.category==='weapon'?EQUIPMENT_MASTER.weapons
		:item.category==='armor'?EQUIPMENT_MASTER.armors:[];
	return pool.find(base=>base.type===(item.category==='weapon'?item.weaponType:item.type))||null;
}
function getEquipmentStatKeys(item){
	return item?.category==='weapon'?['atk','matk']:['def','mdef'];
}
function getDungeonEquipmentAcquisitionValue(item,baseEntry=null){
	if(!item)return EQUIPMENT_BASE_PRICE;
	const base=baseEntry||getEquipmentMasterEntry(item);
	const basePrice=Math.max(1,Math.floor(Number(base?.price)||EQUIPMENT_BASE_PRICE));
	const keys=getEquipmentStatKeys(item);
	let bonusPoints=0;
	keys.forEach(key=>{
		const masterKey=key==='atk'?'baseAtk':key==='matk'?'baseMatk':key==='def'?'baseDef':'baseMdef';
		const natural=Math.max(0,Number(base?.[masterKey])||0);
		const actual=Math.max(0,Number(item[key])||0);
		bonusPoints+=Math.max(0,actual-natural);
	});
	return Math.max(basePrice,Math.floor(basePrice*(1+bonusPoints*0.10)));
}
function ensureEquipmentEconomy(item){
	if(!item||!['weapon','armor'].includes(item.category))return item;
	ensureEquipmentOptions(item);
	const lv=Math.max(0,Math.min(10,Math.floor(Number(item.upgradeLevel)||0)));
	item.upgradeLevel=lv;
	const keys=getEquipmentStatKeys(item);
	keys.forEach(key=>{
		const storeKey='upgradeBase'+key.charAt(0).toUpperCase()+key.slice(1);
		if(!Number.isFinite(item[storeKey]))item[storeKey]=Math.max(0,Number(item[key])||0);
	});
	if(!Number.isFinite(item.baseValue)){
		const shadow={...item};
		keys.forEach(key=>{
			const storeKey='upgradeBase'+key.charAt(0).toUpperCase()+key.slice(1);
			shadow[key]=item[storeKey];
		});
		item.baseValue=getDungeonEquipmentAcquisitionValue(shadow);
	}
	if(!Number.isFinite(item.value)){
		let value=Math.max(1,Math.floor(item.baseValue));
		for(let i=0;i<lv;i++)value+=Math.max(1,Math.floor(value*EQUIPMENT_UPGRADE_VALUE_STEP));
		item.value=value;
	}
	applyEquipmentUpgradeStats(item);
	return item;
}
const EQUIPMENT_OPTION_RANK_POINTS=Object.freeze({N:1,R:2,SR:3,UR:4});
const EQUIPMENT_OPTION_DIFFICULTY_BONUS=Object.freeze({standard:0,hard:1,abyss:2,brink:3});
const EQUIPMENT_WEAPON_OPTION_DEFS=Object.freeze([
	Object.freeze({key:'atkFlat',label:'攻撃',unit:'',kind:'flat'}),
	Object.freeze({key:'matkFlat',label:'魔力',unit:'',kind:'flat'}),
	Object.freeze({key:'spdFlat',label:'速度',unit:'',kind:'spdFlat'}),
	Object.freeze({key:'physDamagePct',label:'物理与ダメージ',unit:'%',kind:'offPct'}),
	Object.freeze({key:'magicDamagePct',label:'魔法与ダメージ',unit:'%',kind:'offPct'}),
	Object.freeze({key:'shieldDamagePct',label:'シールド破壊',unit:'%',kind:'shieldBreakPct'}),
	Object.freeze({key:'highHpDamagePct',label:'高HP敵への与ダメージ',unit:'%',kind:'conditionalPct'}),
	Object.freeze({key:'executeDamagePct',label:'HP50%以下への与ダメージ',unit:'%',kind:'conditionalPct'}),
	Object.freeze({key:'frontAtkFlat',label:'前衛時の攻撃',unit:'',kind:'stanceFlat'}),
	Object.freeze({key:'backMatkFlat',label:'後衛時の魔力',unit:'',kind:'stanceFlat'}),
	Object.freeze({key:'firstStrikePct',label:'その敵への初撃ダメージ',unit:'%',kind:'conditionalPct'}),
	Object.freeze({key:'critChancePct',label:'会心率（会心1.5倍）',unit:'%',kind:'critChancePct'})
]);
const EQUIPMENT_ARMOR_OPTION_DEFS=Object.freeze([
	Object.freeze({key:'hpFlat',label:'最大HP',unit:'',kind:'hpFlat'}),
	Object.freeze({key:'defFlat',label:'防御',unit:'',kind:'flat'}),
	Object.freeze({key:'mdefFlat',label:'精神',unit:'',kind:'flat'}),
	Object.freeze({key:'spdFlat',label:'速度',unit:'',kind:'spdFlat'}),
	Object.freeze({key:'physReductionPct',label:'物理被ダメージ軽減',unit:'%',kind:'reducePct'}),
	Object.freeze({key:'magicReductionPct',label:'魔法被ダメージ軽減',unit:'%',kind:'reducePct'}),
	Object.freeze({key:'shieldGuardPct',label:'シールド被ダメージ軽減',unit:'%',kind:'shieldGuardPct'}),
	Object.freeze({key:'highHpReductionPct',label:'HP75%以上時の被ダメージ軽減',unit:'%',kind:'conditionalReducePct'}),
	Object.freeze({key:'lowHpReductionPct',label:'HP50%以下時の被ダメージ軽減',unit:'%',kind:'conditionalReducePct'}),
	Object.freeze({key:'frontDefFlat',label:'前衛時の防御',unit:'',kind:'stanceFlat'}),
	Object.freeze({key:'backMdefFlat',label:'後衛時の精神',unit:'',kind:'stanceFlat'}),
	Object.freeze({key:'firstHitReductionPct',label:'各敵からの初撃軽減',unit:'%',kind:'conditionalReducePct'}),
	Object.freeze({key:'evadeChancePct',label:'回避率',unit:'%',kind:'evadeChancePct'})
]);
function getEquipmentOptionPowerTier(areaLevel=1,danger=1,depth=1,difficultyKey='standard'){
	const areaTier=1+Math.floor((Math.max(1,Math.min(100,Math.floor(Number(areaLevel)||1)))-1)/20);
	const diffBonus=EQUIPMENT_OPTION_DIFFICULTY_BONUS[normalizeDungeonDifficultyKey(difficultyKey)]||0;
	const dangerBonus=Math.min(2,Math.max(0,Math.floor((Math.max(.8,Number(danger)||.8)-1)*2)));
	const depthBonus=Math.min(2,Math.max(0,Math.floor((Math.max(1,Math.floor(Number(depth)||1))-1)/5)));
	return Math.max(1,Math.min(10,areaTier+diffBonus+dangerBonus+depthBonus));
}
function getEquipmentOptionPointValue(def,tier){
	const t=Math.max(1,Math.min(10,Math.floor(Number(tier)||1)));
	if(def.kind==='hpFlat')return 5*t;
	if(def.kind==='flat')return t;
	if(def.kind==='spdFlat')return Math.max(1,Math.ceil(t/2));
	if(def.kind==='stanceFlat')return Math.max(1,Math.ceil(t*1.25));
	if(def.kind==='offPct')return Math.max(2,2+Math.floor(t*.8));
	if(def.kind==='shieldBreakPct')return 2+t;
	if(def.kind==='conditionalPct')return Math.max(2,2+Math.ceil(t*.7));
	if(def.kind==='critChancePct')return Math.max(1,Math.ceil(t/2));
	if(def.kind==='reducePct')return Math.max(1,Math.ceil(t*.6));
	if(def.kind==='shieldGuardPct')return Math.max(2,2+Math.ceil(t*.7));
	if(def.kind==='conditionalReducePct')return Math.max(1,1+Math.ceil(t*.7));
	if(def.kind==='evadeChancePct')return Math.max(1,Math.ceil(t/3));
	return 1;
}
function aggregateEquipmentOptions(points){
	const map=new Map();
	(points||[]).forEach(point=>{
		if(!point?.key)return;
		if(!map.has(point.key))map.set(point.key,{key:point.key,label:point.label,unit:point.unit||'',value:0});
		map.get(point.key).value+=Number(point.value)||0;
	});
	return[...map.values()];
}
function ensureEquipmentOptions(item){
	if(!item||!['weapon','armor'].includes(item.category))return item;
	if(Array.isArray(item.equipmentOptionPoints)&&!Array.isArray(item.equipmentOptions))item.equipmentOptions=aggregateEquipmentOptions(item.equipmentOptionPoints);
	if(!Array.isArray(item.equipmentOptionPoints))item.equipmentOptionPoints=[];
	if(!Array.isArray(item.equipmentOptions))item.equipmentOptions=[];
	return item;
}
function rollEquipmentOptions(item,context={}){
	if(!item||!['weapon','armor'].includes(item.category)||item.referenceEquipment||item.missionNpcEquipment)return item;
	const rarity=RARITY_CONFIG[item.dropRarity]?item.dropRarity:'N';
	const pointCount=EQUIPMENT_OPTION_RANK_POINTS[rarity]||1;
	const difficultyKey=normalizeDungeonDifficultyKey(context.difficultyKey||getDungeonDifficultyKey(gameState?.dungeon));
	const areaLevel=Math.max(1,Math.floor(Number(context.areaLevel)||1));
	const danger=Math.max(.8,Number(context.danger)||1);
	const depth=Math.max(1,Math.floor(Number(context.depth)||1));
	const tier=getEquipmentOptionPowerTier(areaLevel,danger,depth,difficultyKey);
	const pool=item.category==='weapon'?EQUIPMENT_WEAPON_OPTION_DEFS:EQUIPMENT_ARMOR_OPTION_DEFS;
	const points=[];
	for(let i=0;i<pointCount;i++){
		const def=pool[Math.floor(Math.random()*pool.length)]||pool[0];
		points.push({key:def.key,label:def.label,unit:def.unit||'',value:getEquipmentOptionPointValue(def,tier)});
	}
	item.equipmentOptionPoints=points;
	item.equipmentOptions=aggregateEquipmentOptions(points);
	item.equipmentOptionTier=tier;
	item.equipmentOptionSource={areaLevel,danger:Math.round(danger*100)/100,depth,difficultyKey};
	return item;
}
function getEquipmentOptionValue(item,key){
	ensureEquipmentOptions(item);
	return(item?.equipmentOptions||[]).reduce((sum,effect)=>effect?.key===key?sum+(Number(effect.value)||0):sum,0);
}
function getCharacterEquipmentOptionValue(char,key){
	if(!char)return 0;
	return getEquipmentOptionValue(char.equip?.weapon,key)+getEquipmentOptionValue(char.equip?.armor,key);
}
function formatEquipmentOption(effect){
	const value=Math.round((Number(effect?.value)||0)*100)/100;
	return `${effect?.label||'効果'}${value>=0?'+':''}${value}${effect?.unit||''}`;
}
function getEquipmentOptionSourceText(item){
	const src=item?.equipmentOptionSource;
	if(!src)return'';
	const diff=DUNGEON_DIFFICULTIES[normalizeDungeonDifficultyKey(src.difficultyKey)]?.name||'標準';
	return `${diff}・Area Lv.${Math.max(1,Math.floor(Number(src.areaLevel)||1))}・強度${Math.max(1,Math.floor(Number(item.equipmentOptionTier)||1))}`;
}

function equipmentOptionDetailHtml(item){
	ensureEquipmentOptions(item);
	const effects=item?.equipmentOptions||[];
	if(!effects.length)return'';
	const source=getEquipmentOptionSourceText(item);
	return `<br><span style="color:#d4af37;font-weight:bold;">付与能力${source?`（${escapeHtml(source)}）`:''}</span><br>${effects.map(effect=>`<span style="color:#bfe8ff;">◆ ${escapeHtml(formatEquipmentOption(effect))}</span>`).join('<br>')}`;
}

function getEquipmentCombatantKey(unit){
	if(!unit)return'none';
	if(typeof isPartyCombatant==='function'&&isPartyCombatant(unit))return `P:${unit.id||unit.name||gameState?.party?.indexOf(unit)||'party'}`;
	if(!unit.equipmentCombatId)unit.equipmentCombatId=`E:${Math.floor(Number(unit.formationSlot)||0)}:${unit.name||unit.category||'enemy'}:${Math.random().toString(36).slice(2,9)}`;
	return unit.equipmentCombatId;
}
function getEquipmentContactKey(attacker,target){return `${getEquipmentCombatantKey(attacker)}>${getEquipmentCombatantKey(target)}`;}
function isEquipmentFirstCombatContact(attacker,target){
	if(!attacker||!target||!battleState)return false;
	battleState.equipmentContactMemory||={};
	return!battleState.equipmentContactMemory[getEquipmentContactKey(attacker,target)];
}
function markEquipmentCombatContact(attacker,target){
	if(!attacker||!target||!battleState)return;
	battleState.equipmentContactMemory||={};
	battleState.equipmentContactMemory[getEquipmentContactKey(attacker,target)]=1;
}
function getEquipmentOutgoingDamageMultiplier(attacker,target,attackType,isFirstContact){
	if(!attacker)return 1;
	let pct=attackType==='魔法'?getCharacterEquipmentOptionValue(attacker,'magicDamagePct'):getCharacterEquipmentOptionValue(attacker,'physDamagePct');
	const maxHp=Math.max(1,Number(target?.maxHp)||Number(target?.hp)||1),ratio=Math.max(0,Number(target?.hp)||0)/maxHp;
	if(ratio>=.75)pct+=getCharacterEquipmentOptionValue(attacker,'highHpDamagePct');
	if(ratio<=.50)pct+=getCharacterEquipmentOptionValue(attacker,'executeDamagePct');
	if(isFirstContact)pct+=getCharacterEquipmentOptionValue(attacker,'firstStrikePct');
	return Math.max(.1,1+pct/100);
}
function getEquipmentIncomingDamageMultiplier(target,attackType,isFirstContact){
	if(!target)return 1;
	let pct=attackType==='魔法'?getCharacterEquipmentOptionValue(target,'magicReductionPct'):getCharacterEquipmentOptionValue(target,'physReductionPct');
	const maxHp=Math.max(1,Number(target.maxHp)||Number(target.hp)||1),ratio=Math.max(0,Number(target.hp)||0)/maxHp;
	if(ratio>=.75)pct+=getCharacterEquipmentOptionValue(target,'highHpReductionPct');
	if(ratio<=.50)pct+=getCharacterEquipmentOptionValue(target,'lowHpReductionPct');
	if(isFirstContact)pct+=getCharacterEquipmentOptionValue(target,'firstHitReductionPct');
	return Math.max(.40,1-Math.min(60,pct)/100);
}

function initializeNewEquipmentEconomy(item,baseEntry=null){
	if(!item)return item;
	ensureEquipmentOptions(item);
	item.upgradeLevel=Math.max(0,Math.floor(Number(item.upgradeLevel)||0));
	getEquipmentStatKeys(item).forEach(key=>{
		const storeKey='upgradeBase'+key.charAt(0).toUpperCase()+key.slice(1);
		item[storeKey]=Math.max(0,Number(item[key])||0);
	});
	item.baseValue=getDungeonEquipmentAcquisitionValue(item,baseEntry);
	item.value=Math.max(1,Math.floor(item.baseValue));
	return item;
}
function getEquipmentCurrentValue(item){
	ensureEquipmentEconomy(item);
	return Math.max(1,Math.floor(Number(item?.value)||EQUIPMENT_BASE_PRICE));
}
function getEquipmentNextUpgradeCost(item){
	const currentValue=getEquipmentCurrentValue(item);
	return currentValue+Math.max(1,Math.floor(currentValue*EQUIPMENT_UPGRADE_VALUE_STEP));
}
function getEquipmentUpgradeFailureLoss(currentLevel){
	const lv=Math.max(0,Math.floor(Number(currentLevel)||0));
	if(lv>=8)return 2;
	if(lv>=5)return 1;
	return 0;
}
function applyEquipmentUpgradeStats(item){
	if(!item)return;
	const lv=Math.max(0,Math.min(10,Math.floor(Number(item.upgradeLevel)||0)));
	const mult=1+EQUIPMENT_UPGRADE_STAT_STEP*lv;
	getEquipmentStatKeys(item).forEach(key=>{
		const storeKey='upgradeBase'+key.charAt(0).toUpperCase()+key.slice(1);
		if(!Number.isFinite(item[storeKey]))item[storeKey]=Math.max(0,Number(item[key])||0);
		const base=Math.max(0,Number(item[storeKey])||0);
		item[key]=base<=0?0:Math.max(0,Math.round(base*mult));
	});
}

function getEquipmentDungeonMultiplier(depth=1,danger=1){
	const floor=Math.max(1,Math.floor(Number(depth)||1));
	const risk=Math.max(0.8,Number(danger)||0.8);
	const depthBonus=(floor-1)*0.03;
	const dangerBonus=Math.max(0,risk-0.8)*0.10;
	return 1+depthBonus+dangerBonus;
}
function generateEquipmentDrop(type,danger,depth,areaLevel=1,lootTier=0,forcedRarity=null){
	const isWeapon=type?(type==='weapon'):(Math.random()<0.5);
	const dropRarity=forcedRarity&&RARITY_CONFIG[forcedRarity]?forcedRarity:rollDropRarity(lootTier);
	const rarityInfo=RARITY_CONFIG[dropRarity]||RARITY_CONFIG.N;
	const rarityMult=rarityInfo.mult;
	const dungeonMult=getEquipmentDungeonMultiplier(depth,danger);
	const totalMult=dungeonMult*rarityMult;
	if(isWeapon){
		const base=EQUIPMENT_MASTER.weapons[Math.floor(Math.random()*EQUIPMENT_MASTER.weapons.length)];
		const item={
			category:"weapon",name:base.name,weaponType:base.type,dropRarity,
			atk:scaleEquipmentStat(base.baseAtk,areaLevel,totalMult),
			matk:scaleEquipmentStat(base.baseMatk,areaLevel,totalMult)
		};
		rollEquipmentOptions(item,{areaLevel,danger,depth,difficultyKey:getDungeonDifficultyKey(gameState?.dungeon)});
		return initializeNewEquipmentEconomy(item,base);
	}else{
		const base=EQUIPMENT_MASTER.armors[Math.floor(Math.random()*EQUIPMENT_MASTER.armors.length)];
		const item={
			category:"armor",name:base.name,type:base.type,dropRarity,
			def:scaleEquipmentStat(base.baseDef,areaLevel,totalMult),
			mdef:scaleEquipmentStat(base.baseMdef,areaLevel,totalMult)
		};
		rollEquipmentOptions(item,{areaLevel,danger,depth,difficultyKey:getDungeonDifficultyKey(gameState?.dungeon)});
		return initializeNewEquipmentEconomy(item,base);
	}
}


// CARD_DEFINITIONSはN性能の基礎値。レアリティ補正は取得時に適用する。

// CARD_DEFINITION_FIELDSの列順が圧縮定義のスキーマ。


function hasCompositePrimaryAndSideEffect(card){
	if(!card)return false;
	const hasPrimary=['atk','matk','heal','def','wild_atk','wild_heal'].includes(card.type);
	const hasSide=(Number(card.sideGuard)||0)>0
		||(Number(card.sideHealScale)||0)>0
		||(Number(card.sidePhyScale)||0)>0
		||(Number(card.sideMagScale)||0)>0;
	return hasPrimary&&hasSide;
}
function compileCardDefinition(row){
	const card={...row};
  // 主効果+副効果札は基礎コスト+1。
  if(hasCompositePrimaryAndSideEffect(card)&&Number.isFinite(card.cost)&&card.cost<99){
		card.cost=Math.max(0,Number(card.cost)||0)+1;

	}
	if(card.masterId===SHOP_GEM_MASTER_ID){
		card.materialCard=true;
		card.shopGem=true;
		card.dungeonRareOnly=true;
	}
	card.rarity='N';
	card.baseRarity='N';

	return card;
}

// 常備札は50%の性能で45回。常備の集中のみNで30回。

const CARD_MASTER=CARD_DEFINITIONS.map(compileCardDefinition);
// 永続カードの流通可否はここで一元判定する。
function getCardAvailability(card){
	if(!card)return{collection:false,shopRegular:false,shopFixed:false,diamondWeekly:false,diamondPack:false,dungeonRandom:false,dungeonTreasure:false,quest:false};
	if(card.masterId===SHOP_GEM_MASTER_ID){
		return{collection:false,shopRegular:false,shopFixed:true,diamondWeekly:false,diamondPack:false,dungeonRandom:true,dungeonTreasure:true,quest:false};
	}
	const category=card.category||'battle';
	const reward=category==='reward',legacy=category==='legacy',consumable=category==='consumable';
	const revivalCharm=card.masterId==='c_revive_charm';
	return{
		collection:!reward&&!legacy&&!card.collectionUnavailable&&!revivalCharm,
		shopRegular:!reward&&!legacy&&!consumable&&!card.passive&&!card.shopUnavailable&&!card.dungeonRareOnly,
		shopFixed:consumable&&!card.shopUnavailable&&!revivalCharm,
		diamondWeekly:!reward&&!legacy&&!card.shopUnavailable&&!card.dungeonRareOnly,
		diamondPack:!reward&&!legacy&&!revivalCharm,
		dungeonRandom:!card.dungeonRareOnly,
		dungeonTreasure:!reward&&!card.dungeonRareOnly,
		quest:!reward&&!card.questUnavailable
	};
}
function getCardMastersForChannel(channel,predicate=null){
	return CARD_MASTER.filter(card=>getCardAvailability(card)[channel]&&(!predicate||predicate(card)));
}


const RARITY_TOTAL_WEIGHT=RARITY_ENTRIES.reduce((sum,[,r])=>sum+r.weight,0);


function getCardUpgradeEnergyCost(card){
	const level=getCardUpgradeLevel(card),rarity=cardEffectiveRarity(card);
	if(rarity==='UR'&&level>=CARD_UPGRADE_MAX_LEVEL)return Infinity;
	return CARD_UPGRADE_ENERGY_COSTS[rarity]?.[level-1]??CARD_UPGRADE_ENERGY_COSTS.N[0];
}
function getCardUpgradeLevel(card){return Math.max(1,Math.min(CARD_UPGRADE_MAX_LEVEL,Math.floor(Number(card?.level)||1)));}
function getCardUpgradePerformanceMult(rarity,level=1){
	const index=Math.max(0,CARD_RARITY_ORDER.indexOf(rarity));
	const current=CARD_RARITY_PERFORMANCE_MULT[CARD_RARITY_ORDER[index]];
	const next=CARD_RARITY_PERFORMANCE_MULT[CARD_RARITY_ORDER[index+1]];
	return next?current+(next-current)*CARD_UPGRADE_PRE_PROMOTION_RATE*(Math.max(1,Math.min(CARD_UPGRADE_MAX_LEVEL,level))-1)/(CARD_UPGRADE_MAX_LEVEL-1):current*(1+0.12*(Math.max(1,Math.min(CARD_UPGRADE_MAX_LEVEL,level))-1)/(CARD_UPGRADE_MAX_LEVEL-1));
}
function changeCardUpgradeRarity(card,newRarity){
	const oldRarity=cardEffectiveRarity(card);
	const oldStep=getCardRarityStep(oldRarity),newStep=getCardRarityStep(newRarity);
	if(newStep===oldStep)return;
	if(card.type==='charge'&&Number(card.manaGen)>0)card.manaGen+=newStep-oldStep;
	if(card.effect==='gain_mana'&&Number.isFinite(card.val))card.val+=newStep-oldStep;
	card.rarity=newRarity;card.dropRarity=newRarity;
}

function getCardRarityStep(rarity){
	const index=CARD_RARITY_ORDER.indexOf(rarity);
	return Math.max(0,index);
}
function applyCardRarityResourceScaling(card,rarity){
	if(!card)return card;
	const step=getCardRarityStep(rarity);
	if(card.category==='reward'||card.category==='legacy'||card.passive===true||card.effect==='return_town')return card;
	if(card.type==='charge'&&Number(card.manaGen)>0){
		card.manaGen=Math.max(0,Number(card.manaGen)||0)+step;
	}
	if(card.effect==='gain_mana'&&Number.isFinite(card.val)){
		card.val=Math.max(0,Number(card.val)||0)+step;
	}

  // レアリティはマナコストを増やさない。
	return card;
}


function isUnlimitedUseCard(card){
 return !!card&&(card.unlimitedUses===true||card.masterId==='m_meditation');
}
function isUnlimitedUseAlly(char){
 return !!char&&char.isPlayer!==true&&char!==gameState?.player&&(char.id==='tutorial_summona'
  ||(char.missionCompanion===true&&['summona_field_priest','summona_finale_priest','claude_phantom'].includes(char.npcDbId))
  ||char.friendCharacter===true);
}
function setCardUseOwner(card,char=null){
 if(!card)return;
 if(isUnlimitedUseAlly(char))card.unlimitedUses=true;
 else delete card.unlimitedUses;
}
function normalizeCharacterCardUses(char){
 if(!char)return;
 // 過去の戦闘手札には受け渡し済みの札が残るため、現在の所持札だけを更新する。
 getCharacterDeck(char).forEach(card=>setCardUseOwner(card,char));
}
function makePlayerDeckFinite(char){
 if(!char)return;
 getCharacterDeck(char).forEach(card=>setCardUseOwner(card));
}
function isDurableCard(card){return !!card&&CARD_RESOURCE_SUITS.includes(card.suit)&&card.category!=='consumable'&&card.category!=='legacy'&&!card.passive;}
function isPrimaryHealingCard(card){return card?.type==='heal'||card?.type==='wild_heal';}
function getCardBaseUseLimit(card){
 if(card?.masterId==='m_focus')return 20;
 if(card?.masterId==='m_enduring_focus')return 30;
 if(card?.suit==='🌟')return card.type==='wild_heal'?20:30;
 if(card?.masterId?.startsWith('m_enduring_')&&card.masterId!=='m_enduring_focus')return 45;
 const healing=isPrimaryHealingCard(card);
 const base=healing?20:30;
 // マナ生成は使用回数を強く減らす。消費札はチャージの手間を考慮して減少を緩める。
 const gain=Math.max(0,Number(card?.manaGen)||0),cost=Math.max(0,Number(card?.cost)||0);
 const resourcePenalty=gain>=cost?(gain-cost)*(healing?CARD_USE_HEAL_MANA_STEP:CARD_USE_MANA_STEP)
  :(cost-gain)*(healing?CARD_USE_HEAL_COST_STEP:CARD_USE_COST_STEP);
 // 副効果はマナ+2に相当する一手分の追加価値として換算する。
 const sidePenalty=hasCompositePrimaryAndSideEffect(card)?CARD_COMPOSITE_MANA_EQUIVALENT*(healing?CARD_USE_HEAL_MANA_STEP:CARD_USE_MANA_STEP):0;
 return Math.max(5,base-resourcePenalty-sidePenalty);
}

function getCardUseLimit(card){
 if(Number.isFinite(card?.inheritedFiniteUseLimit))return Math.max(1,Math.floor(card.inheritedFiniteUseLimit));
 if(!isDurableCard(card)||isUnlimitedUseCard(card))return Infinity;
 const rarity=cardEffectiveRarity(card),step=getCardRarityStep(rarity),level=getCardUpgradeLevel(card);
 const current=CARD_USE_RARITY_MULT[rarity]??1;
 const next=CARD_USE_RARITY_MULT[CARD_RARITY_ORDER[step+1]]??2;
 // 次のレアリティへの昇格時に、上限が逆戻りしないよう段階的に増やす。
 const multiplier=current+(next-current)*(level-1)/CARD_UPGRADE_MAX_LEVEL;
 const original=getCardMaster(card.masterId)||card;
 const base=card.masterId==='m_escape'?3
  :['m_focus','m_enduring_focus'].includes(card.masterId)?getCardBaseUseLimit(original)
  :Math.ceil(getCardBaseUseLimit(original)*0.5);
 return Math.max(1,Math.floor(base*multiplier+1e-9));
}
function getCardUses(card){
 const limit=getCardUseLimit(card);
 if(!Number.isFinite(limit))return Infinity;
 if(!Number.isFinite(card.usesRemaining))card.usesRemaining=limit;
 return card.usesRemaining=Math.max(0,Math.min(limit,Math.floor(card.usesRemaining)));
}
function cardUseText(card){const limit=getCardUseLimit(card);return Number.isFinite(limit)?`使用 ${getCardUses(card)}/${limit}`:card?.unlimitedUses?'使用 ∞':'';}
function spendCardUse(card){if(Number.isFinite(getCardUseLimit(card))){const before=getCardUses(card);card.usesRemaining=Math.max(0,before-1);return before>0;}return true;}
function restoreCardUses(card,ratio=1){const max=getCardUseLimit(card);if(!Number.isFinite(max))return 0;const before=getCardUses(card);card.usesRemaining=Math.min(max,before+(ratio>=1?max:Math.max(1,Math.ceil(max*ratio))));return card.usesRemaining-before;}
function forEachOwnedCard(fn,includeStorage=true){const seen=new Set();[gameState.deck,...(gameState.party||[]).map(c=>getCharacterDeck(c)),...(includeStorage?[gameState.cardStorage]:[])].forEach(deck=>{if(!Array.isArray(deck))return;deck.forEach(card=>{if(card&&!seen.has(card)){seen.add(card);fn(card);}});});}
function getHealthyHpLimit(char){return Math.max(1,(Number(char?.maxHp)||1)-Math.max(0,Math.floor(Number(char?.injury)||0)));}
function addInjury(char,actualDamage){
 if(!char||!isPartyCombatant(char)||actualDamage<=0)return;
 const accumulated=(Number(char.injuryFraction)||0)+actualDamage*0.10;
 const added=Math.floor(accumulated+1e-9);
 char.injuryFraction=accumulated-added;
 char.injury=Math.min(Math.max(0,(char.maxHp||1)-1),(char.injury||0)+added);
 char.hp=Math.min(char.hp,getHealthyHpLimit(char));
 if(added>0)scheduleCombatAdvancedTip();
}
function varyCalculatedAmount(amount){const base=Math.max(0,Math.floor(Number(amount)||0));return base>0?Math.max(1,Math.round(base*(0.88+Math.random()*0.24))):0;}
function healNormalHp(char,amount){if(!char||char.hp<=0)return 0;const before=char.hp;char.hp=Math.min(getHealthyHpLimit(char),char.hp+varyCalculatedAmount(amount));const actual=char.hp-before;if(actual>0)queueBattleVisualEffect(char,'heal');return actual;}
function treatInjury(char,amount){if(!char||char.hp<=0)return 0;const before=char.injury||0;char.injury=Math.max(0,before-varyCalculatedAmount(amount));return before-char.injury;}
function getExecutedManaCost(cards){
	const raw=(cards||[]).reduce((sum,card)=>{
		const cost=Math.max(0,Number(card?.cost)||0);
		return sum+(cost<99?cost:0);
	},0);
	return Math.max(0,Math.floor(raw+1e-9));
}
function getExecutedManaGain(rawMana){
	return Math.max(0,Math.floor((Number(rawMana)||0)+1e-9));
}
function ensureCardPerformanceDefaults(card){
	if(!card)return card;
	if((card.type==='status'||card.type==='interference')&&!Number.isFinite(card.statusPower))card.statusPower=1;
	return card;
}
function isManaOnlyValue(card){
	return!!card&&(card.effect==='gain_mana'||card.type==='gain_mana');
}
function scaleCardOverallPerformance(card,mult){
	if(!card||!Number.isFinite(mult)||mult===1)return ensureCardPerformanceDefaults(card);
	ensureCardPerformanceDefaults(card);

  // ratioは能力値×(1+ratio)。負ratioもこの基準で倍率補正する。

  if(CARD_PRIMARY_RATIO_TYPES.includes(card.type)&&Number.isFinite(card.ratio)){
		card.ratio=Number((((1+card.ratio)*mult)-1).toFixed(4));
	}
	CARD_OVERALL_RATIO_FIELDS.forEach(key=>{
		if(Number.isFinite(card[key]))card[key]=Number((card[key]*mult).toFixed(4));
	});
	CARD_OVERALL_FLAT_FIELDS.forEach(key=>{
		if(!Number.isFinite(card[key]))return;
		if(key==='val'&&isManaOnlyValue(card))return;
		card[key]=Math.max(0,Math.round(card[key]*mult));
	});
	if(Number.isFinite(card.sideGuard)){
		card.sideGuard=Number(Math.max(0,card.sideGuard*mult).toFixed(3));
	}
	if(Number.isFinite(card.effectMultiplier)){
		card.effectMultiplier=Number(Math.min(1,card.effectMultiplier*mult).toFixed(4));
	}
	if(Number.isFinite(card.statusPower)){
		card.statusPower=Number((card.statusPower*mult).toFixed(4));
	}
	return card;
}
function applyCardRarityPerformance(card,rarity){
	if(!card)return card;
	const key=RARITY_CONFIG[rarity]?rarity:'N';
	card.rarity=key;
	scaleCardOverallPerformance(card,CARD_RARITY_PERFORMANCE_MULT[key]||1);
	applyCardRarityResourceScaling(card,key);
	return card;
}
function getDungeonCardOriginMultiplier(d,depthOverride=null){
	const areaLevel=Math.max(1,Number(d?.areaLevel)||1);
	const depth=Math.max(1,Number(depthOverride??d?.currentDepth??d?.maxDepth)||1);
	const danger=Math.max(0.1,Number(d?.danger)||1);
	const areaBonus=(areaLevel-1)*0.03;
	const depthBonus=(depth-1)*0.02;
	const dangerBonus=(danger-1)*0.05;
	return Math.max(0.75,Number((1+areaBonus+depthBonus+dangerBonus).toFixed(4)));
}
function applyDungeonCardOriginScaling(card,d,depthOverride=null){
	if(!card||!d)return 1;
	if(card.category==='reward'||card.category==='legacy'||card.passive===true||card.effect==='return_town')return 1;
	const depth=Math.max(1,Number(depthOverride??d.currentDepth??d.maxDepth)||1);
	const mult=getDungeonCardOriginMultiplier(d,depth);
	scaleCardOverallPerformance(card,mult);
	card.sourceAreaLevel=Math.max(1,Number(d.areaLevel)||1);
	card.sourceDepth=depth;
	card.sourceDanger=Math.max(0.1,Number(d.danger)||1);
	card.dungeonPerformanceMult=mult;
	return mult;
}
function makeCardPerformancePreview(master,rarity=null,includeCollection=false){
	if(!master)return null;
	const card=JSON.parse(JSON.stringify(master));
	card.level=card.level||1;
	const key=RARITY_CONFIG[rarity]?rarity:'N';
	applyCardRarityPerformance(card,key);
	card.dropRarity=key;
	if(includeCollection&&typeof applyCollectionBonusToNewCard==='function')applyCollectionBonusToNewCard(card);
	return card;
}
function rollDropRarity(lootTier=0){
	const baseTier=Number.isFinite(lootTier)?lootTier:0;
	const tier=baseTier+getDifficultyLootTierBonus();
	if(tier===0){
		let rand=Math.random()*RARITY_TOTAL_WEIGHT;
		for(const[rarityKey,config]of RARITY_ENTRIES){
			if(rand<config.weight)return rarityKey;
			rand-=config.weight;
		}
		return "N";
	}
	const rarityBoost={N:0.78,R:1.05,SR:1.22,UR:1.38};
	const adjusted=RARITY_ENTRIES.map(([key,config])=>[key,config.weight*Math.pow(rarityBoost[key]||1,tier)]);
	let total=adjusted.reduce((sum,[,weight])=>sum+weight,0);
	let rand=Math.random()*total;
	for(const[key,weight]of adjusted){
		if(rand<weight)return key;
		rand-=weight;
	}
	return "N";
}


function plainNameLength(value){return Array.from(String(value||'')).length;}
function hasForbiddenNameMarkup(value){return /[<>\r\n\t]/.test(String(value??''));}
function sanitizePlainName(value,maxLength){
	const clean=String(value??'').replace(/[<>\r\n\t]/g,'').trim();
	return Array.from(clean).slice(0,maxLength).join('');
}
function clipPersonName(value){return sanitizePlainName(value,PERSON_NAME_MAX_LENGTH);}
function clipPartyName(value){return sanitizePlainName(value,PARTY_NAME_MAX_LENGTH);}

function showReservedNameEasterEgg(value){
    const name=String(value??'').trim().normalize('NFKC');
    const speaker=RESERVED_PLAYER_NAMES.get(name);
    if(!speaker)return false;
    if(speaker==='summona')openSummonaDialogue('それは私の名前','サモナ',{speaker:'summona',storySequence:false});
    else if(speaker==='claude')openSummonaDialogue('偶然か、必然か。どっちだ？','クロード',{speaker:'claude',storySequence:false});
    else openSummonaDialogue('だめ','モノリス',{speaker:'monolith',storySequence:false});
    return true;
}
function validatePlainNameInput(value,maxLength,label){
    const raw=String(value??'').trim();
    if(showReservedNameEasterEgg(raw))return false;
	if(hasForbiddenNameMarkup(raw)){showGameNotice(`${label}には < > や改行は使えません。`,{title:'入力エラー'});return false;}
	if(plainNameLength(raw)>maxLength){showGameNotice(`${label}は${maxLength}文字までです。`,{title:'入力エラー'});return false;}
	return true;
}


function getEquipmentBaseByType(category,type){
	if(!type)return null;
	const pool=category==='weapon'?EQUIPMENT_MASTER.weapons:EQUIPMENT_MASTER.armors;
	return pool.find(item=>item.type===type)||null;
}
function createReferenceEquipment(category,type,source='standard',level=1){
	const base=getEquipmentBaseByType(category,type);
	if(!base)return null;
	const item=category==='weapon'
		?{category:'weapon',name:base.name,weaponType:base.type,dropRarity:'N',atk:scaleEquipmentStat(base.baseAtk,level,1),matk:scaleEquipmentStat(base.baseMatk,level,1)}
		:{category:'armor',name:base.name,type:base.type,dropRarity:'N',def:scaleEquipmentStat(base.baseDef,level,1),mdef:scaleEquipmentStat(base.baseMdef,level,1)};
	item.referenceEquipment=true;
	item.referenceSource=source;
	return initializeNewEquipmentEconomy(item,base);
}
function equipReferenceEquipment(char,source='standard'){
	if(!char)return[];
	const ref=JOB_REFERENCE_EQUIPMENT[char.jobType]||{weapon:null,armor:null};
	const equipped=[];
	const weapon=createReferenceEquipment('weapon',ref.weapon,source);
	const armor=createReferenceEquipment('armor',ref.armor,source);
	if(weapon&&canEquip(char,weapon)){char.equip.weapon=weapon;equipped.push(weapon);}
	if(armor&&canEquip(char,armor)){char.equip.armor=armor;equipped.push(armor);}
	recalculateStats(char,true);
	return equipped;
}
// 加入時だけ職業に合う基礎装備を渡す。共有コード由来の装備は上書きしない。
function bindPersonalEquipment(char,item){
 if(!char||!item)return;
 item.personalEquipment=true;
 item.name=`${char.name}の${getEquipmentMasterEntry(item)?.name||item.name}`;
}
function equipInitialNpcEquipment(char,source='guild'){
 if(!char||char.isPlayer||char.missionCompanion)return [];
 char.equip||={weapon:null,armor:null};
 const ref=JOB_REFERENCE_EQUIPMENT[char.jobType]||{};
 const equipped=[];
 for(const [slot,type] of [['weapon',ref.weapon],['armor',ref.armor]]){
  if(!type||char.equip[slot])continue;
  const item=createReferenceEquipment(slot,type,source,char.level);
  if(item&&canEquip(char,item)){bindPersonalEquipment(char,item);char.equip[slot]=item;equipped.push(item);}
 }
 if(equipped.length)recalculateStats(char,true);
 return equipped;
}
// 戦闘職の初期デッキは主スート10枚・副スート7枚・🌟3枚。
// 補給員は非戦闘職、道化師は複数スートを扱う固有構成。
function expandJobCardGroups(groups){
 return groups.flatMap(([id,count])=>Array(count).fill(id));
}
function makeStableJobDeck(mainGroups,subGroups){
 const main=expandJobCardGroups(mainGroups),sub=expandJobCardGroups(subGroups);
 if(main.length!==10||sub.length!==7)throw new Error('初期デッキの主副枚数が不正');
 return [...main,...sub,'m_meditation','m_focus','m_focus'];
}


function getStarterJobGiftIds(jobKey=null){
	const key=jobKey||gameState?.player?.jobType||'hero';
	return[...(STARTER_JOB_CARD_GIFTS[key]||STARTER_JOB_CARD_GIFTS.hero),'m_escape'];
}
function getStarterJobGiftNames(jobKey=null){
	return getStarterJobGiftIds(jobKey).map(id=>getCardMaster(id)?.name||id);
}
function grantStarterJobCardGift(){
	if(!gameState?.player)return{granted:false,names:[],featherGranted:false};
	if(gameState.starterJobCardGiftClaimed){
		return{granted:false,already:true,names:getStarterJobGiftNames(gameState.starterJobCardGiftJob||gameState.player.jobType),featherGranted:false};
	}
	gameState.cardStorage||=[];
	if(gameState.cardStorage.length+getStarterJobGiftIds(gameState.player.jobType).length+1>CARD_STORAGE_MAX){
		return{granted:false,full:true,names:getStarterJobGiftNames(gameState.player.jobType),featherGranted:false};
	}
	const ids=getStarterJobGiftIds(gameState.player.jobType);
	const cards=ids.map(id=>createCardInstance(id,{rarity:'R',applyCollection:false})).filter(Boolean);
	const feather=createCardInstance('c_return_feather',{rarity:'N',applyCollection:false});
	if(cards.length!==ids.length||!feather)return{granted:false,names:[],featherGranted:false};
	cards.forEach(card=>gameState.cardStorage.push(card));
	gameState.cardStorage.push(feather);
	gameState.starterJobCardGiftClaimed=true;
	gameState.starterJobCardGiftJob=gameState.player.jobType||'hero';
	return{granted:true,names:cards.map(card=>card.name),featherGranted:true};
}
const CARD_MASTER_BY_ID=new Map(CARD_MASTER.map(card=>[card.masterId,card]));
const CARD_DEFAULT_NAMES=Object.freeze(Object.fromEntries(CARD_MASTER.map(card=>[card.masterId,card.name])));
function getCardMaster(masterId){return CARD_MASTER_BY_ID.get(masterId)||null;}

function isValidCardNickname(value){
 return typeof value==='string'&&!!value.trim()&&Array.from(value.trim()).length<=CARD_NICKNAME_MAX_LENGTH
  &&!/[<>&"'\`《》\x00-\x1f\x7f]/.test(value)
  &&!RESERVED_PLAYER_NAMES.has(value.trim().normalize('NFKC'));
}
function normalizeCardNameOverrides(source){
 const cleaned={};
 if(!source||typeof source!=='object'||Array.isArray(source))return cleaned;
 const used=new Set(Object.values(CARD_DEFAULT_NAMES));
 for(const [id,value] of Object.entries(source)){
  if(!Object.prototype.hasOwnProperty.call(CARD_DEFAULT_NAMES,id)||!isValidCardNickname(value))continue;
  const name=value.trim();
  if(name===CARD_DEFAULT_NAMES[id])continue;
  if(used.has(name))continue;
  cleaned[id]=name;used.add(name);
 }
 return cleaned;
}
function updateCardMasterNames(){
 const names=gameState?.cardNameOverrides||{};
 for(const card of CARD_MASTER)card.name=names[card.masterId]||CARD_DEFAULT_NAMES[card.masterId];
}


function isCollectionEligibleMaster(card){
	return!!card&&getCardAvailability(card).collection;
}
function ensureCollectionOfferings(){
	gameState.collectionOfferings||={};
	Object.keys(gameState.collectionOfferings).forEach(id=>{
		gameState.collectionOfferings[id]=Math.min(COLLECTION_OFFERING_MAX,Math.max(0,Math.floor(Number(gameState.collectionOfferings[id])||0)));
	});
}
function getCollectionOfferingCount(masterId){
	ensureCollectionOfferings();
	return Math.min(COLLECTION_OFFERING_MAX,Math.max(0,Number(gameState.collectionOfferings?.[masterId])||0));
}
function getCollectionBonusRate(masterId){
	return getCollectionOfferingCount(masterId)*COLLECTION_BONUS_PER_OFFERING;
}
function applyCollectionBonusToNewCard(card){
	if(!card?.masterId||!isCollectionEligibleMaster(getCardMaster(card.masterId)))return card;
	const rate=getCollectionBonusRate(card.masterId);
	card.collectionBonusRate=rate;
	if(rate<=0)return ensureCardPerformanceDefaults(card);
	return scaleCardOverallPerformance(card,1+rate);
}
function isAlchemistCharacter(char){return char?.jobType==='alchemist';}
function isMageCharacter(char){return char?.jobType==='mage';}
function isSteamerCharacter(char){return char?.jobType==='steamer';}


function isPrimaryPhysicalAttackCard(card){
	return!!card&&(card.type==='atk'||card.type==='wild_atk');
}
function isPrimaryMagicalAttackCard(card){
	return!!card&&card.type==='matk';
}
function getAlchemyBaseActionCard(cards){
  return(cards||[]).find(card=>card&&!isBattleMaterialCard(card)&&!isAlchemistCatalystCard(card)
		&&isPrimaryMagicalAttackCard(card))||null;
}
function getCardManaBalance(card){
	if(!card)return 0;
	return(Math.max(0,Number(card.manaGen)||0)-getExecutedManaCost([card]));
}
function getAlchemyManaBalanceInfo(card){
	const rawBalance=getCardManaBalance(card);
	const compositePenalty=hasCompositePrimaryAndSideEffect(card)?ALCHEMY_COMPOSITE_BALANCE_PENALTY:0;
	return{rawBalance,compositePenalty,effectiveBalance:rawBalance+compositePenalty};
}
function getAlchemyMaterialDamageRate(cards){
	const base=getAlchemyBaseActionCard(cards);
	if(!base)return 0;
	const{effectiveBalance}=getAlchemyManaBalanceInfo(base);
  // 錬金素材係数: 収支+2/+1/0/-1/-2以下 → 10/20/30/40/50%。複合札は判定収支+3。
  return Math.max(ALCHEMY_MATERIAL_RATE_MIN,Math.min(ALCHEMY_MATERIAL_RATE_MAX,
		ALCHEMY_MATERIAL_RATE_NEUTRAL-effectiveBalance*0.10));
}
function getAlchemyMaterialDamageBonus(cards,materialCard){
	if(materialCard?.phantomManaMaterial)return Math.max(0,Math.floor(Number(materialCard.phantomManaBonus)||0));
	return Math.max(0,Math.floor((Number(materialCard?.sellPrice)||0)*getAlchemyMaterialDamageRate(cards)));
}
function isSteamFuelCard(card){return!!card?.steamFuel;}
function isAlchemistCatalystCard(card){return!!card?.alchemistCatalyst;}
function createSteamFuelCard(serial=0){
	return createGeneratedCard('steam_fuel',{
		masterId:'battle_steam_fuel',suit:'⚙️',name:'蒸気機関',rarity:'N',cost:0,manaGen:0,
		type:'steam_fuel',effect:'steam_fuel',steamFuel:true,battleOnly:true,ephemeralOnUse:true,noGrowth:true
	},{instancePrefix:'steam_fuel',serial});
}
function createAlchemistCatalystCard(serial=0){
	return createGeneratedCard('alchemist_catalyst',{
		masterId:'battle_alchemist_catalyst',suit:'⚗️',name:'触媒',rarity:'N',cost:0,manaGen:0,
		type:'alchemist_catalyst',effect:'alchemist_catalyst',alchemistCatalyst:true,battleOnly:true,ephemeralOnUse:true,noGrowth:true
	},{instancePrefix:'alchemist_catalyst',serial});
}
function addSteamFuelToBattleDeck(char,cards){
	const deck=[...(cards||[])];
	if(!isSteamerCharacter(char))return deck;
	for(let i=0;i<STEAM_FUEL_BATTLE_COUNT;i++)deck.push(createSteamFuelCard(i));
	return deck;
}
function addAlchemistCatalystsToBattleDeck(char,cards){
	const deck=[...(cards||[])];
	if(!isAlchemistCharacter(char))return deck;
	for(let i=0;i<ALCHEMIST_CATALYST_BATTLE_COUNT;i++)deck.push(createAlchemistCatalystCard(i));
	return deck;
}
function addJobBattleExtraCards(char,cards){
	return addAlchemistCatalystsToBattleDeck(char,addSteamFuelToBattleDeck(char,cards));
}
function isJobCycleCardFor(char,card){
	return(isSteamerCharacter(char)&&isSteamFuelCard(card))||(isAlchemistCharacter(char)&&isAlchemistCatalystCard(card));
}
function createJobCycleCard(char,serial=0){
	if(isSteamerCharacter(char))return createSteamFuelCard(serial);
	if(isAlchemistCharacter(char))return createAlchemistCatalystCard(serial);
	return null;
}
function getJobCycleCardCount(char){
	if(isSteamerCharacter(char))return STEAM_FUEL_BATTLE_COUNT;
	if(isAlchemistCharacter(char))return ALCHEMIST_CATALYST_BATTLE_COUNT;
	return 0;
}
function rebuildDrawPileForNewCycle(entity,hand,discardPile){
	const base=(discardPile||[]).filter(card=>!isJobCycleCardFor(entity,card));
	const maxSpecial=getJobCycleCardCount(entity);
	const heldSpecial=(hand||[]).filter(card=>isJobCycleCardFor(entity,card)).length;
	for(let i=heldSpecial;i<maxSpecial;i++){
		const card=createJobCycleCard(entity,i);
		if(card)base.push(card);
	}
	return shuffle(base);
}
function isValidSteamerBoostCombo(cards){
	const list=(cards||[]).filter(Boolean);
	if(list.length!==3)return false;
	const engines=list.filter(isSteamFuelCard);
	const gems=list.filter(isGemCard);
	const attacks=list.filter(card=>!isSteamFuelCard(card)&&!isBattleMaterialCard(card)&&card.suit==='⚔️'&&isPrimaryPhysicalAttackCard(card));
	return engines.length===1&&gems.length===1&&attacks.length===1;
}
function isValidSteamerPartialSelection(cards){
	const list=(cards||[]).filter(Boolean);
	if(list.length===0)return true;
	if(list.length===1)return true;
	if(list.length>3)return false;
	let engineCount=0,gemCount=0,attackCount=0;
	for(const card of list){
		if(isSteamFuelCard(card))engineCount++;
		else if(isGemCard(card))gemCount++;
		else if(card?.suit==='⚔️'&&isPrimaryPhysicalAttackCard(card)&&!isBattleMaterialCard(card))attackCount++;
		else return false;
	}
	return engineCount<=1&&gemCount<=1&&attackCount<=1;
}
function isValidSteamerBattleSelection(char,cards){
	if(!isSteamerCharacter(char))return true;
	const list=(cards||[]).filter(Boolean);
	if(list.length===1)return!isSteamFuelCard(list[0])&&!isBattleMaterialCard(list[0]);
	return isValidSteamerBoostCombo(list);
}
function getSteamFuelCard(cards){
	return(cards||[]).find(isSteamFuelCard)||null;
}
function isBattleMaterialCard(card){return!!card?.materialCard;}
function isGemCard(card){return!!card&&(card.masterId===SHOP_GEM_MASTER_ID||card.shopGem===true);}
function getMageGemManaReduction(char,cards){
	if(!isMageCharacter(char))return 0;
	const gem=(cards||[]).find(isGemCard);
	if(!gem)return 0;
	return MAGE_GEM_MANA_REDUCTION[cardEffectiveRarity(gem)]||1;
}
function getBattleComboManaCost(char,cards){
	return Math.max(0,getExecutedManaCost(cards)-getMageGemManaReduction(char,cards));
}
function canUseBattleMaterial(char,card){
	if(!isBattleMaterialCard(card))return false;
	if(isAlchemistCharacter(char))return true;
	if(isMageCharacter(char)&&isGemCard(card))return true;
	return isSteamerCharacter(char)&&isGemCard(card);
}
function hasAlchemyActionCard(cards){
	return!!getAlchemyBaseActionCard(cards);
}
function isValidBattleMaterialCombo(char,cards){
	const list=(cards||[]).filter(Boolean);
	const materials=list.filter(isBattleMaterialCard);
	const catalystCount=list.filter(isAlchemistCatalystCard).length;
	if(materials.length===0&&catalystCount===0)return true;
	if(isAlchemistCharacter(char)){
		if(materials.length!==1||catalystCount!==1)return false;
		if(!hasAlchemyActionCard(list))return false;
		return comboHasAttack(list);
	}
	if(isMageCharacter(char)){
		if(catalystCount!==0||materials.length!==1||!isGemCard(materials[0]))return false;
		return list.length>=2&&list.length<=3;
	}
	if(isSteamerCharacter(char)){
		if(catalystCount!==0||materials.length!==1||!isGemCard(materials[0]))return false;
		return isValidSteamerBoostCombo(list);
	}
	return false;
}
function isBattleCardForbiddenFor(char,card){
	if(!card)return true;
	if(card.phantomManaMaterial&&char?.npcDbId!=='claude_phantom')return true;
	if(card.enemyOnly&&!isEnemyCombatant(char))return true;
	if(isEnemyCombatant(char)&&isPrimaryHealingCard(card)&&char?.strongEscortRole!=='healer')return true;
	if(isSteamFuelCard(card))return!isSteamerCharacter(char);
	if(isAlchemistCatalystCard(card))return!isAlchemistCharacter(char);
	if(card.category==='reward'&&!canUseBattleMaterial(char,card))return true;
	if(card.category==='legacy'||card.effect==='return_town'||card.effect==='heal_hp'||card.effect==='gain_mana'||card.passive===true)return true;
	return false;
}
function isSoloOnlyBattleCard(card){
	return!!card&&(isDepartureBlankCard(card)||['m_meditation','m_escape'].includes(card.masterId));
}
function isValidSoloOnlyCombo(cards){
	const list=(cards||[]).filter(Boolean);
	return list.length<=1||!list.some(isSoloOnlyBattleCard);
}
function comboHasPrimaryPhysical(cards){
	return(cards||[]).some(c=>c&&!isBattleMaterialCard(c)&&(c.type==='atk'||c.type==='wild_atk'));
}
function comboHasPrimaryMagical(cards){
	return(cards||[]).some(c=>c&&!isBattleMaterialCard(c)&&c.type==='matk');
}
function comboHasPrimaryHeal(cards){
	return(cards||[]).some(c=>c&&!isBattleMaterialCard(c)&&(c.type==='heal'||c.type==='wild_heal'));
}
// コンボ主効果は各札の(1+ratio)を加算する。

function getCardEffectProfile(card){
	const out={phyRatio:0,magRatio:0,healRatio:0,defVal:0,manaGen:0,sidePhyScale:0,sideMagScale:0,sideHealScale:0,sideGuard:0};
	if(!card)return out;
	if(card.type==='atk'||card.type==='wild_atk')out.phyRatio+=Number(card.ratio)||0;
	if(card.type==='matk')out.magRatio+=Number(card.ratio)||0;
	if(card.type==='heal'||card.type==='wild_heal')out.healRatio+=Number(card.ratio)||0;
	if(card.type==='def')out.defVal+=Number(card.val)||0;
	out.manaGen+=Number(card.manaGen)||0;
	out.sidePhyScale+=Number(card.sidePhyScale)||0;
	out.sideMagScale+=Number(card.sideMagScale)||0;
	out.sideHealScale+=Number(card.sideHealScale)||0;
	out.sideGuard+=Number(card.sideGuard)||0;
	return out;
}
function comboHasHeal(cards){
	return(cards||[]).some(c=>{
		const p=getCardEffectProfile(c);
		return c?.type==='heal'||c?.type==='wild_heal'||p.sideHealScale>0||(c.category==='consumable'&&c.effect==='heal_hp');
	});
}
// 《愚者》は異なる通常スート3種で成立。


function getFoolArcanaBonuses(user,cards){
	if(!isJesterCharacter(user))return new Set();
  // 《愚者》では🌟も1スート。🧪/📦だけ種類判定から除外する。

  const suits=new Set((cards||[])
		.filter(card=>card&&!isDeckRuleExemptCard(card)&&CARD_RESOURCE_SUITS.includes(card.suit))
		.map(card=>card.suit));
	if(suits.size<3)return new Set();
	return suits;
}
function hasFoolArcanaBonus(user,cards,suit){
	return getFoolArcanaBonuses(user,cards).has(suit);
}
function removeOneShotCardInstance(user,card,preserveOwned=false){
	if(!user||!card?.instanceId)return;
	const deck=user.isPlayer?gameState.deck:user.deck;
	if(!preserveOwned&&Array.isArray(deck)){
		const idx=deck.findIndex(c=>c?.instanceId===card.instanceId);
		if(idx!==-1)deck.splice(idx,1);
	}
	if(user.isPlayer){
		battleState.hand=(battleState.hand||[]).filter(c=>c?.instanceId!==card.instanceId);
		battleState.drawPile=(battleState.drawPile||[]).filter(c=>c?.instanceId!==card.instanceId);
		battleState.discardPile=(battleState.discardPile||[]).filter(c=>c?.instanceId!==card.instanceId);
	}else{
		user.hand=(user.hand||[]).filter(c=>c?.instanceId!==card.instanceId);
		user.drawPile=(user.drawPile||[]).filter(c=>c?.instanceId!==card.instanceId);
		user.discardPile=(user.discardPile||[]).filter(c=>c?.instanceId!==card.instanceId);
	}
}


// 雑魚・強敵専用。各種族につき20枚のうち1枚だけ、攻撃と組み合わせる固有札を持つ。
// 守護者は専用札と専用デッキを使用する。

function createEnemySpeciesSkillCard(category){
	const spec=ENEMY_SPECIES_SKILL_SPECS[category];if(!spec)return null;
	return createGeneratedCard('enemy_species_skill',{
		masterId:`enemy_species_${category}`,suit:'🌟',name:spec.name,rarity:'ENEMY',cost:0,manaGen:0,type:'modifier',
		enemySpeciesSkill:category,enemyOnly:true,tacticText:spec.text,noGrowth:true,
		...(category==='humanoid'?{targetMode:'lowest_hp'}:{})
	},{instancePrefix:`enemy_species_${category}`});
}

// 強敵/守護者専用札は戦利品・ショップ・プレイヤーデッキへ流入させない。

function createEnemyTacticCard(kind,serial=0){
	const spec=ENEMY_TACTIC_CARD_SPECS[kind];
	if(!spec)return null;
	return createGeneratedCard('enemy_tactic',{
		masterId:`enemy_tactic_${kind}`,suit:'🌟',name:spec.name,rarity:'ENEMY',cost:0,manaGen:0,type:'modifier',
		enemyTactic:kind,enemyOnly:true,tacticText:spec.text,noGrowth:true
	},{instancePrefix:`enemy_tactic_${kind}`,serial});
}
function addEnemyTacticCards(deck,copies=1){
	if(!Array.isArray(deck))return 0;
	let added=0;
	const count=Math.max(1,Math.floor(Number(copies)||1));
	for(let copy=0;copy<count;copy++){
		['extra_attack','acceleration','assault'].forEach((kind,index)=>{
			const card=createEnemyTacticCard(kind,copy*3+index);
			if(card){deck.push(card);added++;}
		});
	}
	return added;
}
function hasEnemyTactic(cards,kind){
	return(cards||[]).some(card=>card?.enemyTactic===kind);
}
function isEnemyTacticComboCompatible(cards){
	const tactics=(cards||[]).filter(card=>card?.enemyTactic);
	if(!tactics.length)return true;
	if((cards||[]).some(card=>card?.targetMode==='all'||card?.masterId==='m_all_target'))return false;
	if((hasEnemyTactic(cards,'extra_attack')||hasEnemyTactic(cards,'assault'))&&!comboHasAttack(cards))return false;
	if(hasEnemyTactic(cards,'extra_attack')&&hasEnemyTactic(cards,'assault'))return false;
	return true;
}


let pendingMugenFloorChoice=null;
function ensureMugenAdaptiveState(d){
	if(!d||d.dungeonKind!=='mugen')return null;
	if(!d.mugenEffects||typeof d.mugenEffects!=='object')d.mugenEffects={};
	const e=d.mugenEffects;
	for(const key of['enemyOffense','enemyDurability','enemyDefense','enemySpeed','stepHealRatio','startBarrierRatio']){
		if(!Number.isFinite(Number(e[key])))e[key]=0;
	}
	if(!Number.isFinite(Number(d.mugenTrapWeight)))d.mugenTrapWeight=1;
	if(!Number.isFinite(Number(d.mugenRewardBias)))d.mugenRewardBias=0;
	d.mugenRewardBias=Math.max(-3,Math.min(3,Math.round(Number(d.mugenRewardBias)||0)));
	if(!d.mugenAdaptation||typeof d.mugenAdaptation!=='object')d.mugenAdaptation={rating:'steady',last:null};
	if(!['easy','steady','struggle'].includes(d.mugenAdaptation.rating))d.mugenAdaptation.rating='steady';
	if(!Array.isArray(d.mugenChosenCards))d.mugenChosenCards=[];
	if(!d.mugenChoiceResolvedFloors||typeof d.mugenChoiceResolvedFloors!=='object'||Array.isArray(d.mugenChoiceResolvedFloors))d.mugenChoiceResolvedFloors={};
	// 未公開版のため旧セーブの移行は行わない。現行の選択状態だけを扱う。
	// 選択記録がある階は解決済みとして扱い、階段往復で再選択させない。
	d.mugenChosenCards.forEach(choice=>{const floor=Math.max(1,Math.floor(Number(choice?.floor)||1));d.mugenChoiceResolvedFloors[String(floor)]=true;});
	if(!d.mugenMinorFloors||typeof d.mugenMinorFloors!=='object'||Array.isArray(d.mugenMinorFloors))d.mugenMinorFloors={};
	return e;
}
function isMugenFloorChoiceResolved(d,floor=d?.currentDepth){
	if(!d||d.dungeonKind!=='mugen')return false;
	ensureMugenAdaptiveState(d);
	return!!d.mugenChoiceResolvedFloors?.[String(Math.max(1,Math.floor(Number(floor)||1)))];
}
function markMugenFloorChoiceResolved(d,floor=d?.currentDepth){
	if(!d||d.dungeonKind!=='mugen')return;
	ensureMugenAdaptiveState(d);
	d.mugenChoiceResolvedFloors[String(Math.max(1,Math.floor(Number(floor)||1)))]=true;
}
function getMugenMinorMutationDefinition(id){
	return MUGEN_MINOR_MUTATIONS.find(m=>m.id===id)||null;
}
function getMugenMinorMutationsForFloor(d,depth=d?.currentDepth){
	if(!d||d.dungeonKind!=='mugen'||d.mugenSecretArena)return[];
	ensureMugenAdaptiveState(d);
	const key=String(Math.max(1,Math.floor(Number(depth)||1)));
	const ids=Array.isArray(d.mugenMinorFloors?.[key])?d.mugenMinorFloors[key]:[];
	return ids.map(getMugenMinorMutationDefinition).filter(Boolean);
}
function rollMugenMinorMutations(d,depth){
	if(!d||d.dungeonKind!=='mugen'||d.mugenSecretArena)return[];
	const floor=Math.max(1,Math.floor(Number(depth)||1));
	const seedText=`${d.specialSeed||d.name||'mugen'}::MINOR::${floor}F`;
	const rng=createRNG(stringToSeed(seedText));
	const pool=[...MUGEN_MINOR_MUTATIONS];
	for(let i=pool.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]];}
	const count=rng()<0.5?2:3;
	const picked=[],groups=new Set();
	for(const mutation of pool){
		if(groups.has(mutation.group))continue;
		picked.push(mutation);groups.add(mutation.group);
		if(picked.length>=count)break;
	}
	return picked;
}
function ensureMugenMinorMutationsForFloor(d,depth=d?.currentDepth){
	if(!d||d.dungeonKind!=='mugen'||d.mugenSecretArena)return[];
	ensureMugenAdaptiveState(d);
	const key=String(Math.max(1,Math.floor(Number(depth)||1)));
	if(!Array.isArray(d.mugenMinorFloors[key])){
		const picked=rollMugenMinorMutations(d,Number(key));
		d.mugenMinorFloors[key]=picked.map(m=>m.id);
	}
	return getMugenMinorMutationsForFloor(d,Number(key));
}
function getMugenActiveMinorMutations(d){
	if(!d||d.dungeonKind!=='mugen'||d.mugenSecretArena)return[];
	ensureMugenAdaptiveState(d);
	return Object.keys(d.mugenMinorFloors||{})
		.map(key=>Math.max(1,Math.floor(Number(key)||1)))
		.sort((a,b)=>a-b)
		.flatMap(floor=>getMugenMinorMutationsForFloor(d,floor).map(m=>({...m,sourceFloor:floor})));
}
function getMugenMinorFloorEffects(d){
	const total={enemyOffense:0,enemyDurability:0,enemyDefense:0,enemySpeed:0,stepHealRatio:0,startBarrierRatio:0,trapWeightMult:1,hordeRateDelta:0,objectDelta:{chest:0,trap:0,enemy:0,trace:0}};
	getMugenActiveMinorMutations(d).forEach(m=>{
		const e=m.effects||{};
		for(const key of['enemyOffense','enemyDurability','enemyDefense','enemySpeed','stepHealRatio','startBarrierRatio','hordeRateDelta'])total[key]+=Number(e[key])||0;
		if(Number.isFinite(Number(e.trapWeightMult)))total.trapWeightMult*=Number(e.trapWeightMult);
		for(const type of['chest','trap','enemy','trace'])total.objectDelta[type]+=Math.trunc(Number(e.objectDelta?.[type])||0);
	});
	return total;
}
function applyMugenMinorGenerationProfile(d,depth,profile){
	if(!d||d.dungeonKind!=='mugen'||d.mugenSecretArena)return profile;
	ensureMugenMinorMutationsForFloor(d,depth);
	const minor=getMugenMinorFloorEffects(d);
	const out={...(profile||d)};
	out.mugenTrapWeight=Math.max(0.20,Math.min(3.00,(Number(out.mugenTrapWeight)||1)*minor.trapWeightMult));
	out.mugenObjectCountDelta={...minor.objectDelta};
	return out;
}
function logMugenMinorMutationsForFloor(d,depth=d?.currentDepth){
	const mutations=getMugenMinorMutationsForFloor(d,depth);
	if(!mutations.length)return;
	log(`🔹 小変異：${mutations.map(m=>`【${m.name}】`).join(' ')}`);
}
function getMugenRewardBias(d){
	if(d?.dungeonKind!=='mugen')return 0;
	ensureMugenAdaptiveState(d);
	return Math.max(-3,Math.min(3,Number(d.mugenRewardBias)||0));
}
function getMugenRewardTierAdjustment(d){
	return getMugenRewardBias(d)*0.5+(d?.heartLabyrinth?2:0);
}
function getMugenRewardValueMultiplier(d){
	return Math.max(0.70,Math.min(1.30,1+getMugenRewardBias(d)*0.10))*(d?.heartLabyrinth?1.5:1);
}
function getMugenRewardTrendText(d){
	const bias=getMugenRewardBias(d);
	if(bias>0)return '危険を受け入れたことで、迷宮の報酬も濃くなった。';
	if(bias<0)return '援護を受け入れたことで、迷宮の報酬は薄くなった。';
	return '危険と援護が釣り合い、報酬の気配は変わらない。';
}
function getMugenEnemyEffectMult(d,key){
	if(d?.dungeonKind!=='mugen')return 1;
	const e=ensureMugenAdaptiveState(d)||{};
	const minor=getMugenMinorFloorEffects(d);
	const base={offense:1.08,durability:1.12,defense:1.06,speed:1.03}[key]||1;
	const persistent=key==='offense'?e.enemyOffense:key==='durability'?e.enemyDurability:key==='defense'?e.enemyDefense:key==='speed'?e.enemySpeed:0;
	const local=key==='offense'?minor.enemyOffense:key==='durability'?minor.enemyDurability:key==='defense'?minor.enemyDefense:key==='speed'?minor.enemySpeed:0;
	return Math.max(0.1,base*(1+Math.max(-0.8,(Number(persistent)||0)+(Number(local)||0))));
}
function shuffleMugenCards(list){
	const a=[...list];
	for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}
	return a;
}
function buildMugenFloorChoices(d){
	ensureMugenAdaptiveState(d);
	const rating=d.mugenAdaptation?.rating||'steady';
	let riskCount=rating==='easy'?2:rating==='struggle'?1:(Math.random()<0.5?1:2);
	let aidCount=3-riskCount;
	const risks=shuffleMugenCards(MUGEN_FLOOR_RISK_CARDS).slice(0,riskCount);
	const aids=shuffleMugenCards(MUGEN_FLOOR_AID_CARDS).slice(0,aidCount);
	return shuffleMugenCards([...risks,...aids]);
}
function getMugenAdaptationLabel(rating){
	if(rating==='easy')return '迷宮は余裕を感じ取り、危険な変異を寄せている。';
	if(rating==='struggle')return '迷宮は消耗を感じ取り、援護の変異を寄せている。';
	return '迷宮は様子を見ている。';
}
function renderMugenFloorChoiceModal(d,choices){
	const modal=document.getElementById('mugen-floor-choice-modal');
	const status=document.getElementById('mugen-floor-choice-status');
	const list=document.getElementById('mugen-floor-choice-list');
	if(!modal||!status||!list)return false;
	const pending=pendingMugenFloorChoice;
	const revealed=!!pending?.revealed;
	status.textContent=revealed
		?`${d.currentDepth}F突破。選ばなかった変異も明らかになった。${getMugenRewardTrendText(d)}`
		:`${d.currentDepth}F突破。${getMugenAdaptationLabel(d.mugenAdaptation?.rating)} 3枚の内容はまだ見えない。`;
	list.replaceChildren();
	choices.forEach((card,index)=>{
		const btn=document.createElement('button');
		btn.type='button';
		const selected=revealed&&pending?.selectedIndex===index;
		btn.style.cssText=`text-align:left;padding:10px;background:${selected?'#2b2818':'#182019'};border:${selected?'2px solid #d4af37':'1px solid #52644d'};color:#ddd;min-height:64px;`;
		btn.disabled=revealed;
		const title=document.createElement('div');
		title.style.cssText=`font-weight:bold;margin-bottom:4px;color:${revealed?(card.kind==='risk'?'#e7b0a5':'#b8dfb3'):'#d8d2bf'};`;
		const desc=document.createElement('div');
		desc.style.cssText='font-size:11px;color:#bbb;line-height:1.45;';
		if(revealed){
			title.textContent=`${selected?'▶ ':''}${card.kind==='risk'?'⚠️':'✨'} ${card.name}`;
			desc.textContent=`${card.desc} ${card.kind==='risk'?'報酬の質も上がる。':'報酬の質も下がる。'}`;
		}else{
			title.textContent='❓ 封じられた変異';
			desc.textContent='選ぶまで内容は分からない。';
			btn.addEventListener('click',()=>selectMugenFloorChoice(index));
		}
		btn.append(title,desc);
		list.appendChild(btn);
	});
	if(revealed){
		const next=document.createElement('button');
		next.type='button';
		next.textContent='次の階へ進む';
		next.style.cssText='margin-top:4px;padding:10px;background:#355338;border:1px solid #7fa77a;color:#fff;font-weight:bold;';
		next.addEventListener('click',continueMugenFloorChoice);
		list.appendChild(next);
	}
	modal.style.display='flex';
	return true;
}
function applyMugenFloorCard(d,card){
	const e=ensureMugenAdaptiveState(d);if(!e||!card)return;
	if(card.id==='enemy_fury')e.enemyOffense+=0.10;
	else if(card.id==='enemy_vigor')e.enemyDurability+=0.15;
	else if(card.id==='enemy_shell')e.enemyDefense+=0.12;
	else if(card.id==='enemy_haste')e.enemySpeed+=0.08;
	else if(card.id==='trap_bloom')d.mugenTrapWeight=Math.min(3.0,Math.max(0.2,Number(d.mugenTrapWeight)||1)*1.40);
	else if(card.id==='healing_steps')e.stepHealRatio+=0.005;
	else if(card.id==='start_barrier')e.startBarrierRatio+=0.06;
	else if(card.id==='trap_calm')d.mugenTrapWeight=Math.max(0.20,(Number(d.mugenTrapWeight)||1)*0.65);
	const rewardDelta=card.kind==='risk'?1:-1;
	d.mugenRewardBias=Math.max(-3,Math.min(3,(Number(d.mugenRewardBias)||0)+rewardDelta));
	const floor=Math.max(1,Number(d.currentDepth)||1);
	d.mugenChosenCards.push({id:card.id,name:card.name,floor,rewardDelta});
	markMugenFloorChoiceResolved(d,floor);
}
function offerMugenFloorChoice(d,partyName){
	if(isMugenFloorChoiceResolved(d,d?.currentDepth)){completeDownStairTransition(d,partyName);return;}
	if(pendingMugenFloorChoice?.dungeon===d)return;
	const choices=buildMugenFloorChoices(d);
	pendingMugenFloorChoice={dungeon:d,partyName,choices,revealed:false,selectedIndex:-1};
	const present=()=>{if(!pendingMugenFloorChoice||pendingMugenFloorChoice.dungeon!==d)return;
	if(!renderMugenFloorChoiceModal(d,choices)){
		applyMugenFloorCard(d,choices[0]);
		pendingMugenFloorChoice=null;
		completeDownStairTransition(d,partyName);
	}};
	if(!ensureFeatureTipsSeen().mugenFloorChoice)showFeatureTipOnce('mugenFloorChoice',MUGEN_FLOOR_CHOICE_TIP_TEXT,{title:'Tips：夢幻の階層効果'}).then(present);
	else present();
}
function selectMugenFloorChoice(index){
	const pending=pendingMugenFloorChoice;if(!pending||pending.revealed)return;
	const card=pending.choices?.[index];if(!card)return;
	const d=pending.dungeon;
	applyMugenFloorCard(d,card);
	pending.revealed=true;
	pending.selectedIndex=index;
	log(`🌀 夢幻の変異【${card.name}】を受け入れた。`);
	renderMugenFloorChoiceModal(d,pending.choices);
}
function continueMugenFloorChoice(){
	const pending=pendingMugenFloorChoice;if(!pending?.revealed)return;
	const d=pending.dungeon,partyName=pending.partyName;
	const modal=document.getElementById('mugen-floor-choice-modal');if(modal)modal.style.display='none';
	pendingMugenFloorChoice=null;
	completeDownStairTransition(d,partyName);
}
function beginMugenStrongBattleMeasure(d){
	if(d?.dungeonKind!=='mugen')return;
	const alive=(gameState.party||[]).filter(c=>c&&c.hp>0);
	d.mugenStrongBattleMeasure={
		hpBefore:alive.reduce((s,c)=>s+Math.max(0,Number(c.hp)||0),0),
		hpMax:alive.reduce((s,c)=>s+Math.max(1,Number(c.maxHp)||1),0)
	};
}
function recordMugenStrongBattlePerformance(d){
	if(d?.dungeonKind!=='mugen')return;
	ensureMugenAdaptiveState(d);
	const alive=(gameState.party||[]).filter(c=>c&&c.hp>0);
	const hpMax=Math.max(1,alive.reduce((s,c)=>s+Math.max(1,Number(c.maxHp)||1),0));
	const hpNow=alive.reduce((s,c)=>s+Math.max(0,Number(c.hp)||0),0);
	const ratio=hpNow/hpMax;
	const turns=Math.max(1,Number(gameState.turn)||1);
	let rating='steady';
	if(turns<=2&&ratio>=0.80)rating='easy';
	else if(turns>=5||ratio<0.55)rating='struggle';
	d.mugenAdaptation={rating,last:{turns,hpRatio:Number(ratio.toFixed(3)),floor:d.currentDepth}};
	delete d.mugenStrongBattleMeasure;
}
function applyMugenStepRecovery(d){
	const legacyRatio=Math.min(0.005,getLegacyPower('stepHeal')/100);
	const e=d?.dungeonKind==='mugen'?ensureMugenAdaptiveState(d):null;
	const minor=d?.dungeonKind==='mugen'?getMugenMinorFloorEffects(d):{stepHealRatio:0};
	const ratio=Math.max(0,(Number(e?.stepHealRatio)||0)+(Number(minor.stepHealRatio)||0)+legacyRatio);if(!ratio)return;
	let changed=false;
	(gameState.party||[]).forEach(c=>{
		if(!c||c.hp<=0||c.hp>=c.maxHp)return;
		const heal=varyCalculatedAmount(Math.max(1,Math.floor((Number(c.maxHp)||1)*ratio)));
		const next=Math.min(c.maxHp,c.hp+heal);if(next!==c.hp){c.hp=next;changed=true;}
	});
	if(changed)updatePartyUI();
}
function applyMugenBattleStartSupport(d){
	const legacyRatio=Math.min(0.20,getLegacyPower('startBarrier')/100);
	const e=d?.dungeonKind==='mugen'?ensureMugenAdaptiveState(d):null;
	const minor=d?.dungeonKind==='mugen'?getMugenMinorFloorEffects(d):{startBarrierRatio:0};
	const ratio=Math.max(0,(Number(e?.startBarrierRatio)||0)+(Number(minor.startBarrierRatio)||0)+legacyRatio);if(!ratio)return;
	(gameState.party||[]).forEach(c=>{if(c&&c.hp>0)c.guard=Math.max(0,Number(c.guard)||0)+Math.max(1,Math.floor((Number(c.maxHp)||1)*ratio));});
}

// 敵成長は耐久/防御/火力を別曲線にし、単発即死を避ける。


 // 50枚を5スート均等使用した期待成長。


function getTutorialCombatParty(){
	const party=(gameState?.party||[]).filter(c=>c&&c.hp>0);
	const hero=party.find(c=>c.isPlayer)||gameState?.player||party[0]||null;
	const summona=party.find(c=>c.id==='tutorial_summona')||null;
	return[hero,summona].filter(Boolean);
}
function getTutorialPartyExpectedStandardHit(enemyDef=0,enemyMdef=0){
	const members=getTutorialCombatParty();
	if(!members.length)return 1;
	return Math.max(1,members.reduce((sum,member)=>{
		const physical=Math.max(0,Number(member?.atk)||Number(member?.baseAtk)||0)
			*(100 /(100+Math.max(0,Number(enemyDef)||0)));
		const magical=Math.max(0,Number(member?.matk)||Number(member?.baseMatk)||0)
			*(100 /(100+Math.max(0,Number(enemyMdef)||0)));
		return sum+((physical+magical)/ 2);
	},0));
}
function getTutorialEnemyTargetHp(kind,mult,enemyDef,enemyMdef,randomize=false){
	const partyHit=getTutorialPartyExpectedStandardHit(enemyDef,enemyMdef);
	const turns=kind==='guardian'
		?TUTORIAL_COMBAT_BALANCE.guardianPartyTurns
		:TUTORIAL_COMBAT_BALANCE.normalPartyTurns;
	const speciesHp=Math.pow(Math.max(0.25,Number(mult?.hp)||1),TUTORIAL_COMBAT_BALANCE.speciesHpExponent);
	const variance=randomize
		?1+((Math.random()*2-1)*TUTORIAL_COMBAT_BALANCE.normalVariance)
		:1;
	return Math.max(1,Math.round(partyHit*turns*speciesHp*variance));
}
function getTutorialEnemyTargetOffenseStat(kind,mult,attackKind='physical'){
	const hero=getTutorialCombatParty().find(c=>c?.isPlayer)||gameState?.player;
	if(!hero)return 1;
	const ratio=kind==='guardian'
		?TUTORIAL_COMBAT_BALANCE.guardianCardHeroHpRatio
		:TUTORIAL_COMBAT_BALANCE.normalCardHeroHpRatio;
	const defense=attackKind==='magical'
		?Math.max(0,Number(hero?.mdef)||Number(hero?.baseMdef)||0)
		:Math.max(0,Number(hero?.def)||Number(hero?.baseDef)||0);
	const desiredPostMitigation=Math.max(1,(Number(hero?.maxHp)||Number(hero?.hp)||1)*ratio);
	const preMitigation=desiredPostMitigation*((100+defense)/ 100);
	const rawSpecies=attackKind==='magical'?(Number(mult?.matk)||1):(Number(mult?.atk)||1);
	const speciesFactor=Math.pow(Math.max(0.25,rawSpecies),TUTORIAL_COMBAT_BALANCE.speciesOffenseExponent);
	return Math.max(1,Math.round(preMitigation*speciesFactor));
}
function getTutorialBossLessonShield(hero,bossMdef=0){
	const actor=hero||gameState?.player;
	if(!actor)return 1;
	const ids=['m_spark','m_magic_shot','m_spark'];
	const power=ids.reduce((sum,id)=>{
		const card=getCardMaster(id);
		return sum+Math.max(0.10,1+(Number(card?.ratio)||0));
	},0);  
  const initial=Math.max(1,(Number(actor?.matk)||Number(actor?.baseMatk)||1)*power);
	const postMitigation=Math.max(1,Math.floor(initial*(100 /(100+Math.max(0,Number(bossMdef)||0)))));
	return Math.max(1,Math.floor(postMitigation*TUTORIAL_COMBAT_BALANCE.shieldLessonSafety));
}
function getBalancedReferencePlayerStats(level=1){
	const lv=Math.max(1,Math.floor(Number(level)||1));
	const keys=Object.keys(JOB_TEMPLATES||{}).filter(key=>key!=='supply');
	const templates=keys.map(key=>JOB_TEMPLATES[key]).filter(Boolean);
	const count=Math.max(1,templates.length);
	const avg=key=>templates.reduce((sum,job)=>sum+(Number(job?.[key])||0),0)/ count;
	const steps=lv-1;
	return{
		level:lv,
		hp:avg('hp')+BALANCED_REFERENCE_HP_GROWTH_PER_LEVEL*steps,
		atk:avg('atk')+BALANCED_REFERENCE_STAT_GROWTH_PER_LEVEL*steps,
		def:avg('def')+BALANCED_REFERENCE_STAT_GROWTH_PER_LEVEL*steps,
		matk:avg('matk')+BALANCED_REFERENCE_STAT_GROWTH_PER_LEVEL*steps,
		mdef:avg('mdef')+BALANCED_REFERENCE_STAT_GROWTH_PER_LEVEL*steps,
		spd:avg('spd')+BALANCED_REFERENCE_STAT_GROWTH_PER_LEVEL*steps
	};
}
function getExpectedBalancedStandardHit(level,enemyDef=0,enemyMdef=0){
	const ref=getBalancedReferencePlayerStats(level);
	const physical=ref.atk*(100 /(100+Math.max(0,Number(enemyDef)||0)));
	const magical=ref.matk*(100 /(100+Math.max(0,Number(enemyMdef)||0)));
	return Math.max(1,(physical+magical)/ 2);
}
function getEnemySpeciesTtkHpFactor(mult=null){
	const hpMult=Math.max(0.25,Number(mult?.hp)||1);
	return Math.pow(hpMult,ENEMY_TTK_TARGETS.speciesHpExponent);
}
function resolveEnemyCombatDepth(d,depthOverride=null){
	const nominal=Math.max(1,Math.floor(Number(depthOverride??d?.currentDepth)||1));
	if(d?.questInstance&&isQuestRetreatPhase(d)){
		const maxDepth=Math.max(1,Math.floor(Number(d.maxDepth)||1));
		if(nominal<=maxDepth)return Math.max(nominal,maxDepth+(maxDepth-nominal));
	}
	return nominal;
}
function getEnemyFloorPressure(kind,d,depthOverride=null){
	const depth=resolveEnemyCombatDepth(d,depthOverride);
	const rawSteps=depth-1;
	const steps=Math.min(rawSteps,4)+Math.sqrt(Math.max(0,rawSteps-4));
	const hpStep=kind==='strong'?0.12:kind==='guardian'?0.04:0.08;
	const offenseStep=kind==='strong'?0.08:kind==='guardian'?0.04:0.05;
	return{
		depth,
		durability:1+hpStep*steps,
		offense:1+offenseStep*steps
	};
}
function getEnemyTargetOffenseStat(kind,d,mult,attackKind='physical',depthOverride=null){
	const level=Math.max(1,Math.round(Number(d?.areaLevel)||1));
	const ref=getBalancedReferencePlayerStats(level);
	const ratio=kind==='guardian'?ENEMY_OFFENSE_TARGETS.guardianCardHpRatio
		:kind==='strong'?ENEMY_OFFENSE_TARGETS.strongCardHpRatio
		:ENEMY_OFFENSE_TARGETS.normalCardHpRatio;
	const gradeMult=kind==='guardian'?ENEMY_CARD_GRADE_MULT.SR
		:kind==='strong'?ENEMY_CARD_GRADE_MULT.R
		:ENEMY_CARD_GRADE_MULT.N;
	const defense=attackKind==='magical'?ref.mdef:ref.def;
	const desiredPostMitigation=Math.max(1,ref.hp*ratio);
	const preMitigation=desiredPostMitigation*((100+Math.max(0,defense))/ 100)/ Math.max(0.01,gradeMult);
	const rawSpecies=attackKind==='magical'?(Number(mult?.matk)||1):(Number(mult?.atk)||1);
	const speciesFactor=Math.pow(Math.max(0.25,rawSpecies),ENEMY_OFFENSE_TARGETS.speciesStatExponent);
	const difficulty=getDungeonDifficultyConfig(d);
	const danger=Math.max(0.1,Number(d?.danger)||1);
	const dangerOffense=0.85+(0.15*danger);
	const floorPressure=getEnemyFloorPressure(kind,d,depthOverride);
	return Math.max(1,Math.round(preMitigation*speciesFactor*dangerOffense*floorPressure.offense*(Number(difficulty?.enemyOffense)||1)*getMugenEnemyEffectMult(d,'offense')));
}
function getSummonaMissionEnemyDurabilityScale(d=gameState?.dungeon,kind='normal'){
	if(!d?.questInstance||!d?.summonaMissionId)return 1;
	if(typeof getSummonaMissionDefinition==='function'&&!getSummonaMissionDefinition(d.summonaMissionId))return 1;
	if(typeof updatePartyPositions==='function')updatePartyPositions();
	const participants=(gameState.party||[]).filter(c=>c&&(c.position==='front'||c.position==='back')).length;
	const ratio=Math.max(1/6,Math.min(1,Math.max(1,participants)/6));
	// 少人数でもボスのHPを極端に削らない。6人編成を基準とする。
	if(kind==='guardian')return Math.max(0.70,Math.pow(ratio,0.32));
	if(kind==='strong')return Math.max(0.65,Math.pow(ratio,0.40));
	return Math.max(0.60,Math.pow(ratio,0.45));
}


function getSummonaMissionShieldReferenceHp(d,hp,kind='guardian',unique=false){
	if(!d?.summonaMissionId)return hp;
	const prior=unique?1:1.20;
	const current=unique?SUMMONA_MISSION_UNIQUE_BOSS_HP_MULT:SUMMONA_MISSION_HP_MULT[kind];
	return Math.max(1,Math.round(hp*prior/current));
}
function getEnemyTtkTargetHp(kind,d,mult,enemyDef,enemyMdef,randomize=false,depthOverride=null){
	const level=Math.max(1,Math.round(Number(d?.areaLevel)||1));
	const hit=getExpectedBalancedStandardHit(level,enemyDef,enemyMdef);
	const hits=kind==='guardian'?ENEMY_TTK_TARGETS.guardianHits
		:kind==='strong'?ENEMY_TTK_TARGETS.strongHits
		:ENEMY_TTK_TARGETS.normalHits;
	const difficulty=getDungeonDifficultyConfig(d);
	const danger=Math.max(0.1,Number(d?.danger)||1);
	const dangerDurability=0.80+(0.20*danger);
	const speciesFactor=getEnemySpeciesTtkHpFactor(mult);
	const floorPressure=getEnemyFloorPressure(kind,d,depthOverride);
	const variance=randomize
		?1+((Math.random()*2-1)*ENEMY_TTK_TARGETS.normalVariance)
		:1;
	// 共同調査は均等振りを基準に、盾弱体化をHPの厚さで補う。種別ごとに局所調整する。
	const missionPressure=d?.summonaMissionId?(SUMMONA_MISSION_HP_MULT[kind]||1):1;
	return Math.max(1,Math.round(hit*hits*speciesFactor*dangerDurability*floorPressure.durability*(Number(difficulty?.enemyDurability)||1)*getMugenEnemyEffectMult(d,'durability')*getSummonaMissionEnemyDurabilityScale(d,kind)*missionPressure*variance));
}
function getEnemyDifficultyScales(d,depthOverride=null){
	const areaLevel=Math.max(1,Number(d?.areaLevel)||1);
	const depth=resolveEnemyCombatDepth(d,depthOverride);
	const danger=Math.max(0.1,Number(d?.danger)||0.1);
	const dangerDurability=0.80+(0.20*danger);
	const dangerOffense=0.85+(0.15*danger);
	const dangerSpeed=0.90+(0.10*danger);
	const areaRoot=Math.sqrt(Math.max(0,areaLevel-1));
	const areaDurability=1+11.50*areaRoot;
	const areaDefense=1+6.32*areaRoot;
	const areaOffense=1+3.67*areaRoot;
	const areaSpeed=1+2.31*areaRoot;
	const floorDurability=1+ENEMY_BALANCE.floorDurabilityStep*(depth-1);
	const floorDefense=1+ENEMY_BALANCE.floorDefenseStep*(depth-1);
	const floorOffense=1+ENEMY_BALANCE.floorOffenseStep*(depth-1);
	const floorSpeed=1+ENEMY_BALANCE.floorSpeedStep*(depth-1);
	const difficulty=getDungeonDifficultyConfig(d);
	const durability=areaDurability*dangerDurability*floorDurability*difficulty.enemyDurability;
	const defense=areaDefense*dangerDurability*floorDefense*difficulty.enemyDefense*getMugenEnemyEffectMult(d,'defense');
	const offense=areaOffense*dangerOffense*floorOffense*difficulty.enemyOffense*getMugenEnemyEffectMult(d,'offense');
	const speed=areaSpeed*dangerSpeed*floorSpeed*difficulty.enemySpeed*getMugenEnemyEffectMult(d,'speed');
	return{
		areaLevel,depth,danger,
		durability:Math.max(1,durability),
		defense:Math.max(1,defense),
		offense:Math.max(1,offense),
		speed:Math.max(1,speed)
	};
}

function createBossTrumpCard(category,serial=0){
	const spec=BOSS_TRUMP_CARDS[category]||BOSS_TRUMP_CARDS.dragon;
	return createGeneratedCard('boss_trump',{
		masterId:`boss_trump_${category}`,suit:'🌟',name:spec.name,rarity:'BOSS',cost:0,manaGen:0,
		type:spec.type,ratio:spec.ratio,bossOnly:true,enemyOnly:true,noGrowth:true
	},{instancePrefix:`boss_trump_${category}`,serial});
}

function getMajorEnemyScalingDungeon(d,role){
	if(!d||d.isTutorial)return d;
	const byKind=MAJOR_ENEMY_AREA_LEVEL_BONUS[d.dungeonKind];
	if(!byKind)return d;
	const bonus=Math.max(0,Number(byKind[role])||0);
	if(!bonus)return d;
	return{...d,areaLevel:Math.max(1,(Number(d.areaLevel)||1)+bonus)};
}
function getStrongTrumpCount(danger){
	return Math.max(1,Math.floor(Math.max(0,Number(danger)||0)));
}
function getGuardianTrumpCount(danger){
	return Math.max(2,Math.floor(Math.max(0,Number(danger)||0))*2);
}
function addTrumpCards(deck,category,count,prefix='boss'){
	const n=Math.max(0,Math.floor(Number(count)||0));
	for(let i=0;i<n;i++){
		const card=createBossTrumpCard(category,i);
		card.instanceId=`${prefix}_${card.instanceId}`;
		deck.push(card);
	}
	return n;
}

// 敵札にはプレイヤー用の高レア追加コスト/マナ増加を適用しない。


function getEnemyDangerCardPerformanceMult(d){
	if(!d||d.isTutorial)return 1;
	const danger=Math.max(0.1,Number(d.danger)||1);
	return Math.max(ENEMY_DANGER_CARD_POWER.min,Math.min(ENEMY_DANGER_CARD_POWER.max,
		1+(danger-1)*ENEMY_DANGER_CARD_POWER.slope));
}
function applyEnemyCardGrade(card,grade='N'){
	if(!card)return card;
	const key=ENEMY_CARD_GRADE_MULT[grade]?grade:'N';
	card.enemyGrade=key;
	card.rarity=key;
	scaleCardOverallPerformance(card,ENEMY_CARD_GRADE_MULT[key]);
	return card;
}
function applyEnemyDangerCardPerformance(card,mult=1){
	if(!card)return card;
	const safe=Math.max(0.01,Number(mult)||1);
	card.enemyDangerPerformanceMult=Number(safe.toFixed(4));
	if(Math.abs(safe-1)>0.0001)scaleCardOverallPerformance(card,safe);
	return card;
}
function createEnemyCardInstance(masterId,category,grade='N',dangerPerformanceMult=1){
	const card=createCardInstance(masterId,{rarity:'N',applyRarity:false,applyCollection:false});
	if(!card)return null;
	applyEnemyCardGrade(card,grade);
	applyEnemyDangerCardPerformance(card,dangerPerformanceMult);
	const flavorName=ENEMY_CARD_NAMES[category]?.[masterId];
	card.name=flavorName||CARD_DEFAULT_NAMES[masterId]||card.name;
	delete card.cardNicknameLast;
	card.enemyOriginalMasterId=masterId;
	card.enemySpecies=category;
	return card;
}
function buildEnemyDeckFromCardIds(cardIds,category,grade='N',dangerPerformanceMult=1){
	if(!Array.isArray(cardIds)||cardIds.length===0)return[];
	let expanded=[];
	while(expanded.length<20)expanded=expanded.concat(cardIds);
	for(let i=expanded.length-1;i>0;i--){
		const j=Math.floor(Math.random()*(i+1));
		[expanded[i],expanded[j]]=[expanded[j],expanded[i]];
	}
	return expanded.slice(0,20).map(id=>createEnemyCardInstance(id,category,grade,dangerPerformanceMult)).filter(Boolean);
}
function createEnemySpeciesDeck(category,fallbackCardIds=null,grade='N',dangerPerformanceMult=1){
	const source=ENEMY_SPECIES_DECKS[category]||fallbackCardIds||['m_quick_slash','m_slash','m_guard'];
	const deck=buildEnemyDeckFromCardIds(source,category,grade,dangerPerformanceMult);
	const skill=createEnemySpeciesSkillCard(category);
	if(skill&&deck.length){
		applyEnemyCardGrade(skill,grade);
		applyEnemyDangerCardPerformance(skill,dangerPerformanceMult);
		const replaceIndex=deck.findIndex(card=>card.masterId==='m_focus');
		deck[replaceIndex>=0?replaceIndex:deck.length-1]=skill;
	}
	return deck;
}
function isGuardianForbiddenCard(card){
	if(!card)return true;
	if(card.suit==='🛡️')return true;
	if(['def','heal','wild_heal'].includes(card.type))return true;
	if((card.category==='consumable'||card.type==='use_item')&&card.effect==='heal_hp')return true;
	return false;
}
function createGuardianSpeciesDeck(category,fallbackCardIds=null,options={}){
	const preferProvided=!!options.preferProvided;
	const allowRestrictedCards=!!options.allowRestrictedCards;
	const addAllTarget=options.addAllTarget!==false;
	const raw=(preferProvided&&Array.isArray(fallbackCardIds)&&fallbackCardIds.length)
		?fallbackCardIds
		:(ENEMY_SPECIES_DECKS[category]||fallbackCardIds||['m_quick_slash','m_slash','m_focus']);
	let source=raw.filter(id=>{
		const master=getCardMaster(id);
		return master&&(allowRestrictedCards||!isGuardianForbiddenCard(master));
	});
	if(!source.length)source=['m_quick_slash','m_slash','m_focus'].filter(id=>getCardMaster(id));
	if(addAllTarget&&getCardMaster('m_all_target')&&!source.includes('m_all_target'))source.push('m_all_target');
	return buildEnemyDeckFromCardIds(source,category,options.grade||'SR',options.dangerPerformanceMult||1);
}


// 戦闘AIは「記憶=事実」「思考=現在解釈」を分離する。


function createCombatMind(){
	return{
		memory:{
			lastAttackerId:null,lastAttackerName:'',lastDamage:0,lastDamageTurn:0,lastDamageType:'',
			lastHealerId:null,lastHealerName:'',lastHeal:0,lastHealedTurn:0,
			lastTargetId:null,lastTargetName:'',lastAttackTurn:0,
			lastGuardianSpecialTurn:0,lastGuardianSpecialWasArea:false,
			events:[]
		},
		thought:{state:'calm',reason:'',turn:0}
	};
}
function ensureCombatMind(unit,reset=false){
	if(!unit)return null;
	if(reset||!unit.combatMind||typeof unit.combatMind!=='object')unit.combatMind=createCombatMind();
	unit.combatMind.memory||=createCombatMind().memory;
	unit.combatMind.memory.events||=[];
	unit.combatMind.thought||={state:'calm',reason:'',turn:0};
	return unit.combatMind;
}
// 共有予測は個人記憶と分離し、次に起こる戦場情報だけを持つ。
function createBattleForecastLayer(){
	return{guardianSpecial:null};
}
function ensureBattleForecastLayer(reset=false){
	if(!battleState)return createBattleForecastLayer();
	if(reset||!battleState.forecast||typeof battleState.forecast!=='object')battleState.forecast=createBattleForecastLayer();
	if(!Object.prototype.hasOwnProperty.call(battleState.forecast,'guardianSpecial'))battleState.forecast.guardianSpecial=null;
	return battleState.forecast;
}
function setGuardianSpecialForecast(guardian,type='single',targetId=null,resolveTurn=null){
	const currentTurn=Math.max(1,Number(gameState?.turn)||1);
	const layer=ensureBattleForecastLayer();
	layer.guardianSpecial={
		sourceId:guardian?.id||null,
		sourceName:guardian?.name||'',
		type:type||'single',
		targetId:targetId||null,
		announcedTurn:currentTurn,
		resolveTurn:Math.max(currentTurn+1,Number(resolveTurn)||(currentTurn+1))
	};
	return layer.guardianSpecial;
}
function clearGuardianSpecialForecast(guardian=null){
	const layer=ensureBattleForecastLayer();
	const current=layer.guardianSpecial;
	if(!current)return;
	if(guardian?.id&&current.sourceId&&current.sourceId!==guardian.id)return;
	layer.guardianSpecial=null;
}
function getActiveGuardianSpecialForecast(){
	const layer=ensureBattleForecastLayer();
	const forecast=layer.guardianSpecial;
	if(!forecast)return null;
	const guardian=(battleState?.enemies||[]).find(e=>e?.id===forecast.sourceId&&e.hp>0);
	if(!guardian||!guardian.guardianSpecialTelegraphed){
		layer.guardianSpecial=null;
		return null;
	}
	return forecast;
}
function rememberCombatEvent(unit,type,data={}){
	const mind=ensureCombatMind(unit);
	if(!mind)return;
	const event={type,turn:Math.max(1,Number(gameState?.turn)||1),...data};
	mind.memory.events.push(event);
	if(mind.memory.events.length>COMBAT_MEMORY_EVENT_LIMIT)mind.memory.events.splice(0,mind.memory.events.length-COMBAT_MEMORY_EVENT_LIMIT);
}
function rememberCombatDamage(attacker,target,amount,damageType=''){
	const dmg=Math.max(0,Math.floor(Number(amount)||0));
	if(!target||dmg<=0)return;
	const turn=Math.max(1,Number(gameState?.turn)||1);
	const targetMind=ensureCombatMind(target);
	targetMind.memory.lastAttackerId=attacker?.id||null;
	targetMind.memory.lastAttackerName=attacker?.name||'';
	targetMind.memory.lastDamage=dmg;
	targetMind.memory.lastDamageTurn=turn;
	targetMind.memory.lastDamageType=damageType||'';
	rememberCombatEvent(target,'damaged',{sourceId:attacker?.id||null,sourceName:attacker?.name||'',amount:dmg,damageType});
	if(attacker){
		const attackerMind=ensureCombatMind(attacker);
		attackerMind.memory.lastTargetId=target?.id||null;
		attackerMind.memory.lastTargetName=target?.name||'';
		attackerMind.memory.lastAttackTurn=turn;
		rememberCombatEvent(attacker,'attacked',{targetId:target?.id||null,targetName:target?.name||'',amount:dmg,damageType});
	}
}
function rememberCombatAttackContact(attacker,target,damageType=''){
	if(!target||!attacker)return;
	const turn=Math.max(1,Number(gameState?.turn)||1);
	const targetMind=ensureCombatMind(target);
	targetMind.memory.lastAttackerId=attacker?.id||null;
	targetMind.memory.lastAttackerName=attacker?.name||'';
	targetMind.memory.lastDamageTurn=turn;
	targetMind.memory.lastDamageType=damageType||'';
	rememberCombatEvent(target,'attacked_or_blocked',{sourceId:attacker?.id||null,sourceName:attacker?.name||'',damageType});
	const attackerMind=ensureCombatMind(attacker);
	attackerMind.memory.lastTargetId=target?.id||null;
	attackerMind.memory.lastTargetName=target?.name||'';
	attackerMind.memory.lastAttackTurn=turn;
}
function rememberCombatHeal(healer,target,amount){
	const heal=Math.max(0,Math.floor(Number(amount)||0));
	if(!target||heal<=0)return;
	const turn=Math.max(1,Number(gameState?.turn)||1);
	const targetMind=ensureCombatMind(target);
	targetMind.memory.lastHealerId=healer?.id||null;
	targetMind.memory.lastHealerName=healer?.name||'';
	targetMind.memory.lastHeal=heal;
	targetMind.memory.lastHealedTurn=turn;
	rememberCombatEvent(target,'healed',{sourceId:healer?.id||null,sourceName:healer?.name||'',amount:heal});
	if(healer)rememberCombatEvent(healer,'healed_ally',{targetId:target?.id||null,targetName:target?.name||'',amount:heal});
}
function broadcastGuardianTelegraph(guardian,type,targetId=null,resolveTurn=null){
	const forecast=setGuardianSpecialForecast(guardian,type,targetId,resolveTurn);
  // 個人記憶には予兆を複製せず、発生済みイベントだけ残す。
  (gameState?.party||[]).filter(u=>u&&u.hp>0).forEach(unit=>{
		rememberCombatEvent(unit,'guardian_telegraph_observed',{
			sourceId:guardian?.id||null,telegraphType:type||'single',targetId:targetId||null,resolveTurn:forecast?.resolveTurn||null
		});
	});
}
function broadcastGuardianSpecialResolved(guardian,wasArea=false){
	const turn=Math.max(1,Number(gameState?.turn)||1);
	clearGuardianSpecialForecast(guardian);
	(gameState?.party||[]).filter(u=>u&&u.hp>0).forEach(unit=>{
		const mind=ensureCombatMind(unit);
		mind.memory.lastGuardianSpecialTurn=turn;
		mind.memory.lastGuardianSpecialWasArea=!!wasArea;
		rememberCombatEvent(unit,'guardian_special_resolved',{sourceId:guardian?.id||null,wasArea:!!wasArea});
	});
}
function getCombatTeamSnapshot(unit){
	const allies=getLivingAlliesOf(unit);
	const ratios=allies.map(a=>Math.max(0,a.hp||0)/ Math.max(1,a.maxHp||1));
	const avgHpRatio=ratios.length?ratios.reduce((a,b)=>a+b,0)/ ratios.length:1;
	const woundedCount=ratios.filter(r=>r<0.80).length;
	const severeCount=ratios.filter(r=>r<0.50).length;
	const totalMissingHp=allies.reduce((sum,a)=>sum+Math.max(0,(a.maxHp||0)-(a.hp||0)),0);
	return{allies,avgHpRatio,woundedCount,severeCount,totalMissingHp};
}
function updateCombatThought(unit){
	const mind=ensureCombatMind(unit);
	if(!mind)return{state:'calm',reason:'',turn:0};
	const turn=Math.max(1,Number(gameState?.turn)||1);
	const hpRatio=Math.max(0,unit.hp||0)/ Math.max(1,unit.maxHp||1);
	let state='calm',reason='';
	if(isPartyCombatant(unit)){
		const forecast=getActiveGuardianSpecialForecast();
		if(forecast&&forecast.resolveTurn>=turn){
			if(forecast.type==='area'){
				state='alert_aoe';reason=`守護者の全体攻撃予兆（T${forecast.resolveTurn}）`;
			}else if(forecast.targetId&&forecast.targetId===unit.id){
				state='targeted';reason=`守護者の大技に狙われている（T${forecast.resolveTurn}）`;
			}else{
				state='alert';reason=`守護者の大技予兆（T${forecast.resolveTurn}）`;
			}
		}else if(mind.memory.lastGuardianSpecialWasArea&&mind.memory.lastGuardianSpecialTurn>=turn-1){
			const team=getCombatTeamSnapshot(unit);
			if(team.woundedCount>=2||team.avgHpRatio<0.82){
				state='recovery';reason='直前の全体攻撃から立て直す';
			}
		}
	}
	if(state==='calm'&&hpRatio<=0.40){state='recovery';reason='自身のHPが低い';}
	else if(state==='calm'&&mind.memory.lastDamageTurn>=turn-1&&mind.memory.lastDamage>=Math.max(1,(unit.maxHp||1)*0.22)){
		state='pressured';reason='直前に大きなダメージを受けた';
	}else if(state==='calm'&&mind.memory.lastHealedTurn>=turn-1){
		state='supported';reason='直前に味方から回復を受けた';
	}
	mind.thought={state,reason,turn};
	return mind.thought;
}
function findRememberedAttacker(unit,opponents){
	const id=ensureCombatMind(unit)?.memory?.lastAttackerId;
	if(!id)return null;
	return(opponents||[]).find(o=>o?.id===id&&o.hp>0)||null;
}


function getStandardShieldCap(unit){
	return Math.max(0,Math.floor(Math.max(1,Number(unit?.maxHp)||1)*STANDARD_SHIELD_CAP_RATIO));
}
function getGuardianSpecialShieldCap(unit){
	if(!unit?.isTreasureGuardian)return 0;
	const active=Number(unit.guardianShieldActiveCap);
	if(Number.isFinite(active))return Math.max(0,Math.floor(active));
	return Math.max(0,Math.floor(Number(unit.guardianShieldAmount)||Number(unit.initialGuard)||0));
}
function getShieldCap(unit){
	const standard=getStandardShieldCap(unit);
	if(!unit?.isTreasureGuardian)return standard;
	return Math.max(standard,getGuardianSpecialShieldCap(unit));
}
function addShieldWithCap(unit,amount){
	if(!unit||unit.hp<=0)return 0;
	const gain=Math.max(0,Math.floor(Number(amount)||0));
	if(gain<=0)return 0;
	const before=Math.max(0,Math.floor(Number(unit.guard)||0));
	const cap=getShieldCap(unit);
	const after=Math.min(cap,before+gain);
	unit.guard=after;
	const actual=Math.max(0,after-before);
	if(actual>0)queueBattleVisualEffect(unit,'shield');
	return actual;
}
function recoverGuardianSpecialShield(guardian,ratio,reason=''){
	if(!guardian?.isTreasureGuardian||guardian.hp<=0)return 0;
	if((guardian.guardianBreakStunRemaining||0)>0||(guardian.guardianShieldReformTurn||0)>0)return 0;
	const cap=getGuardianSpecialShieldCap(guardian);
	if(cap<=0||(guardian.guard||0)<=0||guardian.guard>=cap)return 0;
	const requested=Math.max(1,Math.floor(cap*Math.max(0,Number(ratio)||0)));
	const before=guardian.guard||0;
	guardian.guard=Math.min(cap,before+requested);
	const gained=Math.max(0,guardian.guard-before);
	if(gained>0)queueBattleVisualEffect(guardian,'shield');
	if(gained>0&&reason)log(`🛡️ 【${guardian.name}】${reason}、特殊シールド +${gained}P。`);
	return gained;
}
function isPartyCombatant(unit){
	if(!unit)return false;
	if(unit===gameState?.player||unit.isPlayer===true)return true;
	if((gameState?.party||[]).includes(unit))return true;
	const id=unit.id;
	return!!id&&(gameState?.party||[]).some(member=>member&&member.id===id);
}
function isEnemyCombatant(unit){return!!unit&&!isPartyCombatant(unit);}
let enemyActionSafetyContext=null;
function beginEnemyActionSafety(attacker){
	if(!attacker||isPartyCombatant(attacker)){enemyActionSafetyContext=null;return;}
	const starts=new Map();
	(gameState.party||[]).forEach(c=>{
		if(c)starts.set(c,{hp:Math.max(0,c.hp||0),maxHp:Math.max(1,c.maxHp||1)});
	});
	enemyActionSafetyContext={attacker,starts};
}
function endEnemyActionSafety(attacker){
	if(!enemyActionSafetyContext||enemyActionSafetyContext.attacker===attacker)enemyActionSafetyContext=null;
}
function isHeroCharacter(char){return char?.jobType==='hero';}
function capDamageForHeroLastStand(target,damage){
	let dmg=Math.max(0,Math.floor(Number(damage)||0));
	if(!target||!isHeroCharacter(target)||target.hp<=0||target.heroLastStandUsed)return dmg;
	if(dmg<target.hp)return dmg;
	target.heroLastStandUsed=true;
	const capped=Math.max(0,target.hp-1);
	log(`🛡️ ${escapeHtml(target.name)}はHP1で踏みとどまった！`);
	return capped;
}
function capEnemyActionDamageForPermadeath(target,damage){
	let dmg=Math.max(0,Math.floor(Number(damage)||0));
	const ctx=enemyActionSafetyContext;
	if(!ctx||!target||!isPartyCombatant(target))return dmg;
	const start=ctx.starts.get(target);
	if(!start)return dmg;
	if(start.hp>=Math.ceil(start.maxHp*PERMADEATH_SAFETY.healthyStartRatio)){
		dmg=Math.min(dmg,Math.max(0,(target.hp||0)-1));
	}
	return dmg;
}
// 安全弁: HP30%以上から敵1体の1行動だけでは死亡させない。
const fatalDamageCauses=new WeakMap();
function rememberFatalDamage(target,source,damage){
	if(!target||target.hp>0||!isPartyCombatant(target))return;
	fatalDamageCauses.set(target,{source:String(source||'原因不明の損傷'),damage:Math.max(0,Math.floor(Number(damage)||0))});
}
function fatalCauseLogLines(members){
	return(members||[]).filter(member=>member?.hp<=0).map(member=>{
		const cause=fatalDamageCauses.get(member);
		return cause
			?`💥 【${escapeHtml(member.name)}】の致命傷：${escapeHtml(cause.source)}で ${combatLogValue(cause.damage,'damage')}ダメージ。`
			:`💥 【${escapeHtml(member.name)}】の致命傷：直前の損傷（詳細は記録されていない）。`;
	});
}
function logFatalCauses(members){fatalCauseLogLines(members).forEach(log);}
function getFatalCauseSnapshot(member){
	const cause=fatalDamageCauses.get(member);
	return{
		source:String(cause?.source||'直前の損傷'),
		damage:Math.max(0,Math.floor(Number(cause?.damage)||0))
	};
}
function getBattleFatalMemberKey(member){
	return `${String(member?.id||'')}:${String(member?.name||'')}`;
}
function ensureBattleFatalRecord(member){
	if(!member)return null;
	battleState.fatalHistory||=[];
	const key=getBattleFatalMemberKey(member);
	let record=battleState.fatalHistory.find(item=>item?.key===key);
	if(!record){
		const cause=getFatalCauseSnapshot(member);
		record={
			key,
			memberId:String(member?.id||''),
			name:String(member?.name||'名もなき仲間'),
			isPlayer:!!member?.isPlayer,
			causeSource:cause.source,
			damage:cause.damage,
			inheritedCards:[]
		};
		battleState.fatalHistory.push(record);
	}
	return record;
}
function getBattleFatalInjurySentence(member){
	const cause=getFatalCauseSnapshot(member);
	const source=cause.source||'直前の損傷';
	return `${source}によって、${String(member?.name||'仲間')}は瀕死となった。`;
}
function pauseAutoBattleForFatalNotice(){
	const wasAuto=!!battleState.autoMode;
	battleState.deathModalPaused=true;
	if(wasAuto){
		battleState.autoMode=false;
		cancelPlayerAutoSequence(false);
		battleState.autoSelecting=false;
	}
	updateBattleUI();
	return wasAuto;
}
function restoreAutoBattleAfterFatalNotice(wasAuto){
	battleState.deathModalPaused=false;
	if(!wasAuto||!gameState?.inBattle||isMajorBattleManualOnly()||isSummonaFinalBossBattle())return;
	battleState.autoMode=true;
	battleState.autoSelecting=false;
	updateBattleUI();
}
async function handleBattleDeathInterruption(){
	if(!gameState?.inBattle||!(gameState.party||[]).some(c=>c?.hp<=0))return false;
	if(gameState.tutorialState?.active)return checkPartyDeaths();
	const d=gameState.dungeon;
	const mode=getDeathMode(d);
	if(mode==='safety'||!mode)return checkPartyDeaths();
	// お守りで戻れる場合は「死亡」として扱わない。
	const revivedByCharm=activateRevivalCharmsForDeadMembers();
	if(revivedByCharm>0){
		updatePartyUI();
		saveGame();
	}
	const deadMembers=(gameState.party||[]).filter(c=>c?.hp<=0);
	if(!deadMembers.length)return false;
	deadMembers.forEach(ensureBattleFatalRecord);
	const resumeAuto=pauseAutoBattleForFatalNotice();
	await showGameNotice(
		deadMembers.map(getBattleFatalInjurySentence).join('\n'),
		{title:'致命傷',confirmText:'続ける'}
	);
	const ended=checkPartyDeaths();
	if(!ended)restoreAutoBattleAfterFatalNotice(resumeAuto);
	else battleState.deathModalPaused=false;
	return ended;
}
function battleFatalResultCardHtml(info){
	const rarity=String(info?.rarity||'N');
	const color=typeof getRarityColor==='function'?getRarityColor(rarity):'#d8efff';
	return `<div class="battle-inherit-card"><div class="name" style="color:${color};">${escapeHtml(info?.name||'継承カード')}</div><div class="meta">${escapeHtml(rarity)}${info?.usesText?`　${escapeHtml(info.usesText)}`:''}</div>${info?.effect?`<div style="margin-top:4px;color:#c7d6df;">${escapeHtml(info.effect)}</div>`:''}</div>`;
}
function showBattleFatalResultModalIfNeeded(){
	const records=(battleState.fatalHistory||[]).filter(item=>item&&!item.isPlayer);
	if(!records.length||battleState.fatalResultShown)return false;
	const modal=document.getElementById('battle-fatal-result-modal');
	const body=document.getElementById('battle-fatal-result-body');
	if(!modal||!body)return false;
	body.innerHTML=records.map(record=>{
		const cards=(record.inheritedCards||[]);
		const inheritance=cards.length
			?cards.map(info=>info.stored
				?`<div class="battle-inherit-label">🎴 「${escapeHtml(info.name||'継承カード')}」を継承した</div>${battleFatalResultCardHtml(info)}`
				:`<div class="battle-inherit-failed">カード鞄が満杯のため、${escapeHtml(info.name||'継承カード')}は継承できなかった。</div>`
			).join('')
			:'';
		return `<div class="battle-fatal-entry"><div class="battle-fatal-line">💀 この戦いで${escapeHtml(record.name)}は命を落とした…</div>${inheritance}</div>`;
	}).join('');
	battleState.fatalResultShown=true;
	modal.style.display='flex';
	modal.setAttribute('aria-hidden','false');
	return true;
}
function closeBattleFatalResultModal(){
	const modal=document.getElementById('battle-fatal-result-modal');
	if(modal){modal.style.display='none';modal.setAttribute('aria-hidden','true');}
}
function applyDirectDamageWithSafety(target,damage,label='ダメージ',attacker=null){
	if(!target||target.hp<=0)return 0;
	let finalDmg=capEnemyActionDamageForPermadeath(target,varyCalculatedAmount(damage));
	finalDmg=capDamageForHeroLastStand(target,finalDmg);
	finalDmg=capSummonaFinalSceneDamage(target,finalDmg);
	if(finalDmg<=0)return 0;
	target.hp=Math.max(0,target.hp-finalDmg);
	addInjury(target,finalDmg);
	queueBattleVisualEffect(target,'damage');
	rememberFatalDamage(target,`${attacker?.name?`【${attacker.name}】の`:''}${attacker?.guardianSpecialActiveName||label}`,finalDmg);
	log(`  └ ${label} ${escapeHtml(target.name)}に ${combatLogValue(finalDmg,'damage')}ダメージ！`);
	rememberCombatDamage(attacker,target,finalDmg,'直接');
	return finalDmg;
}
function addSimpleStatus(target,status,amount=1){
	if(!target||target.hp<=0)return false;
	if(isPartyCombatant(target)){
		const amulet=getOwnedAmulet(target);
		if(amulet){
			log(`  └ 🧿 【${target.name}】の［${amulet.name||'護符'}］が異常を無効化した！`);
			consumeAmuletOnBlock(target,amulet);
			return false;
		}
	}
	target.statuses||={poison:0,stun:0,dazzle:0};
	target.statuses[status]=Math.max(target.statuses[status]||0,amount);
	return true;
}
function getGuardianMarkedTarget(guardian,targets){
	const id=guardian?.guardianMarkedTargetId;
	return(targets||[]).find(t=>t?.id===id&&t.hp>0)||null;
}
function telegraphGuardianSpecial(guardian){
	if(!guardian||guardian.hp<=0)return;
	const targets=getLivingOpponentsOf(guardian);
	if(!targets.length)return;
	recoverGuardianSpecialShield(guardian,GUARDIAN_CHARGE_SHIELD_RECOVERY_RATIO,'が種族技をチャージし');
	const category=guardian.category||'dragon';
	const spec=GUARDIAN_SPECIAL_ACTIONS[category]||GUARDIAN_SPECIAL_ACTIONS.dragon;
	guardian.guardianMarkedTargetId=null;
	const currentTurn=Math.max(1,Number(gameState?.turn)||1);
	guardian.guardianSpecialTelegraphed=true;
	guardian.guardianSpecialTelegraphTurn=currentTurn;
	guardian.guardianSpecialReadyTurn=currentTurn+1;
	guardian.guardianSpecialQueuedTurn=0;
	guardian.guardianSpecialIsArea=GUARDIAN_AREA_SPECIAL_CATEGORIES.has(category);
	if(category==='humanoid'){
		const marked=[...targets].sort((a,b)=>(a.hp/Math.max(1,a.maxHp))-(b.hp/Math.max(1,b.maxHp)))[0];
		guardian.guardianMarkedTargetId=marked?.id||null;
		log(`⚠️ 【${guardian.name}】が【${marked?.name||'味方'}】へ［処刑宣告］！ 次のラウンドに［${spec.name}］を狙う。回復・かばう・シールドブレイクで凌げる！`);
	}else if(category==='construct'||category==='dragon'){
		const marked=[...targets].sort((a,b)=>b.hp-a.hp)[0];
		guardian.guardianMarkedTargetId=marked?.id||null;
		log(`⚠️ 【${guardian.name}】が【${marked?.name||'味方'}】へ［${spec.name}］の狙いを定めた！ 次のラウンドに発動する。`);
	}else{
		log(`⚠️ 【${guardian.name}】が［${spec.name}］の予兆を見せた！ 次のラウンドに特殊行動が来る。`);
	}
	broadcastGuardianTelegraph(guardian,guardian.guardianSpecialIsArea?'area':'single',guardian.guardianMarkedTargetId||null,guardian.guardianSpecialReadyTurn);
}
function executeGuardianSpecialAction(guardian){
	if(!guardian||guardian.hp<=0)return;
	const targets=getLivingOpponentsOf(guardian);
	if(!targets.length)return;
	const category=guardian.category||'dragon';
	const spec=GUARDIAN_SPECIAL_ACTIONS[category]||GUARDIAN_SPECIAL_ACTIONS.dragon;
	const lowestHp=[...targets].sort((a,b)=>(a.hp/Math.max(1,a.maxHp))-(b.hp/Math.max(1,b.maxHp)))[0];
	const highestHp=[...targets].sort((a,b)=>b.hp-a.hp)[0];
	const marked=getGuardianMarkedTarget(guardian,targets);
	guardian.guardianMarkedTargetId=null;
	log(`👑 【${guardian.name}】の種族特殊行動［${spec.name}］！`);
	beginEnemyActionSafety(guardian);
	guardian.guardianSpecialActiveName=`［${spec.name}］`;
	try{
		switch(category){
			case 'beast':
				targets.forEach(t=>applyDamageWithPassives(guardian,t,Math.max(1,Math.floor(guardian.atk*0.55)),'物理'));break;
			case 'undead':
				targets.forEach(t=>{const dmg=Math.max(1,Math.floor(t.maxHp*0.05));applyDirectDamageWithSafety(t,dmg,'☠️ 生命侵食：',guardian);});break;
			case 'demon':
				targets.forEach(t=>applyDamageWithPassives(guardian,t,Math.max(1,Math.floor(guardian.matk*0.60)),'魔法'));break;
			case 'dragon':{
				let t=marked||highestHp;
				t=getCoveredTarget(t,gameState.party);
				applyDamageWithPassives(guardian,t,Math.max(1,Math.floor(guardian.atk*0.85)),'物理');
				if(t.hp>0)applyDamageWithPassives(guardian,t,Math.max(1,Math.floor(guardian.matk*0.45)),'魔法');break;
			}
			case 'construct':{
				let t=getCoveredTarget(marked||highestHp,gameState.party);
				const capped=Math.min(Math.floor(guardian.atk*1.25),Math.floor(t.maxHp*0.55));
				applyDamageWithPassives(guardian,t,Math.max(1,capped),'物理');break;
			}
			case 'insect':{
				const picks=[...targets].sort(()=>Math.random()-0.5).slice(0,Math.min(2,targets.length));
				picks.forEach(t=>{applyDamageWithPassives(guardian,t,Math.max(1,Math.floor(guardian.atk*0.65)),'物理');addSimpleStatus(t,'dazzle',1);log(`  └ 🌀 ${t.name} は鱗粉で眩暈状態になった！`);});break;
			}
			case 'spirit':
				targets.forEach(t=>{const drained=Math.min(1,Math.max(0,t.mana||0));t.mana=Math.max(0,(t.mana||0)-drained);applyDamageWithPassives(guardian,t,Math.max(1,Math.floor(guardian.matk*0.35)),'魔法');if(drained>0)log(`  └ 🔮 ${t.name} のマナを ${drained} 奪った！`);});break;
			case 'aquatic':
				targets.forEach(t=>{applyDamageWithPassives(guardian,t,Math.max(1,Math.floor(guardian.matk*0.40)),'魔法');addSimpleStatus(t,'dazzle',1);});log('  └ 🌊 奔流で味方全体の視界が乱された！');break;
			case 'humanoid':{
				let t=getCoveredTarget(marked||lowestHp,gameState.party);
				const capped=Math.min(Math.floor(guardian.atk*1.10),Math.floor(t.maxHp*0.45));
				applyDamageWithPassives(guardian,t,Math.max(1,capped),'物理');break;
			}
			case 'plant':
				targets.forEach(t=>{applyDamageWithPassives(guardian,t,Math.max(1,Math.floor(guardian.matk*0.38)),'魔法');t.mana=Math.max(0,(t.mana||0)-Math.min(1,Math.max(0,t.mana||0)));});break;
		}
		guardian.guardianSpecialTelegraphed=false;
		guardian.guardianSpecialTelegraphTurn=0;
		guardian.guardianSpecialReadyTurn=0;
		guardian.guardianSpecialQueuedTurn=0;
		guardian.guardianActionCounter=0;
		broadcastGuardianSpecialResolved(guardian,GUARDIAN_AREA_SPECIAL_CATEGORIES.has(category));
	}finally{
		delete guardian.guardianSpecialActiveName;
		endEnemyActionSafety(guardian);
	}
}
function triggerGuardianShieldBreak(target){
	if(!target?.isTreasureGuardian||target.hp<=0)return;
	const currentTurn=Math.max(1,Number(gameState?.turn)||1);
	target.guardianBreakStunRemaining=GUARDIAN_BREAK_SKIP_ROUNDS;
	target.guardianBreakTriggeredTurn=currentTurn;
	target.guardianBreakSkipTurn=currentTurn+1;
	target.guardianShieldReformTurn=currentTurn+GUARDIAN_SHIELD_REFORM_DELAY;
	target.guardianBreakProcessedTurn=null;
	target.guardianActionCounter=0;
	target.guardianMarkedTargetId=null;
	target.guardianSpecialTelegraphed=false;
	target.guardianSpecialTelegraphTurn=0;
	target.guardianSpecialReadyTurn=0;
	target.guardianSpecialQueuedTurn=0;
	clearGuardianSpecialForecast(target);
	const statMult=ENEMY_BALANCE.boss.breakStatMult||1.05;
	['atk','def','matk','mdef','spd'].forEach(key=>{
		target[key]=Math.max(1,Number(((Number(target[key])||1)*statMult).toFixed(2)));
	});
	target.guardianBreakCount=(target.guardianBreakCount||0)+1;
	if(target.statuses)target.statuses.stun=0;
	log(`⚡ 【${target.name}】はシールドブレイク！ 次の1ラウンドは行動不能。シールドは${GUARDIAN_SHIELD_REFORM_DELAY}ラウンド後に再展開する。HP以外の能力が5%上昇した。`);
}
function reformGuardianShield(guardian){
	if(!guardian?.isTreasureGuardian||guardian.hp<=0)return;
	guardian.guardianShieldReformCount=(guardian.guardianShieldReformCount||0)+1;
	const baseAmount=Math.max(1,Number(guardian.guardianShieldAmount)||Number(guardian.initialGuard)||1);
	const remainingRate=Math.max(0,1-(guardian.guardianShieldReformCount*0.10));
	const amount=Math.max(0,Math.floor(baseAmount*remainingRate));
	guardian.guardianShieldActiveCap=amount;
	guardian.guard=amount;
	if(amount>0)queueBattleVisualEffect(guardian,'shield');
	guardian.guardianBreakStunRemaining=0;
	guardian.guardianBreakSkipTurn=0;
	guardian.guardianShieldReformTurn=0;
	if(amount>0){
		log(`🛡️ 【${guardian.name}】がシールドを ${amount}P 再展開した。`);
	}else{
		log(`⚡ 【${guardian.name}】はもうシールドを張り直せない！`);
	}
}
function processGuardianRoundTimers(){
	const currentTurn=Math.max(1,Number(gameState?.turn)||1);
	getActiveGuardianSpecialForecast();  
  (battleState?.enemies||[]).forEach(guardian=>{
		if(!guardian?.isTreasureGuardian||guardian.hp<=0)return;
		if((guardian.guardianShieldReformTurn||0)>0&&currentTurn>=guardian.guardianShieldReformTurn&&(guardian.guard||0)<=0){
			reformGuardianShield(guardian);
		}
	});
}


function isAmulet(card){return!!card&&card.masterId===AMULET_MASTER_ID;}
function getOwnedAmulet(char){
	return getCharacterDeck(char).find(isAmulet)||null;
}
function consumeAmuletOnBlock(char,amulet){
	if(!char||!amulet)return false;
	if(Math.random()>=AMULET_BREAK_RATE)return false;
	const deck=getCharacterDeck(char);
	const idx=deck.findIndex(card=>card?.instanceId===amulet.instanceId);
	if(idx!==-1)deck.splice(idx,1);
	log(`  └ 💥 【${char.name}】の［${amulet.name||'護符'}］が破損した。`);
	return true;
}

function isRevivalCharm(card){
	return!!card&&card.masterId===REVIVAL_CHARM_MASTER_ID;
}
function createRevivalCharmInstance(displayName=null){
	const card=createCardInstance(REVIVAL_CHARM_MASTER_ID,{rarity:'UR'});
	if(!card)return null;
	card.rarity='UR';
	card.dropRarity='UR';
	if(displayName)card.name=displayName;
	return card;
}
function pickRandomDungeonCardMaster(){
	const pool=getCardMastersForChannel('dungeonRandom');
	return pool[Math.floor(Math.random()*pool.length)]||null;
}
function canTreasureChestDropRevivalCharm(d){
	return!!d&&d.isTreasureRoom===true&&(d.dungeonKind==='normal'||d.dungeonKind==='mugen');
}
function giveTreasureRevivalCharm(){
	const card=createRevivalCharmInstance();
	if(!card)return false;
	const routed=addDungeonCardToPlayerOrStorage(card);
	if(routed.location==='deck'){
		log(`🎴 宝物部屋の宝箱から<span style="color:${RARITY_CONFIG.UR.color};font-weight:bold;">［${card.name}］</span>を獲得し、【${routed.ownerName}】が所持した！`);
		return true;
	}

  // お守りは希少品のため、同行者が受け取れない場合も消失させずカード鞄へ強制収納する。
  gameState.cardStorage||=[];
	delete card.dungeonAcquired;
	delete card.dungeonAcquiredAt;
	delete card.dungeonAcquiredName;
	delete card.questLootToken;
	gameState.cardStorage.push(card);
	const overflow=gameState.cardStorage.length>CARD_STORAGE_MAX;
	log(`🎴 宝物部屋の宝箱から<span style="color:${RARITY_CONFIG.UR.color};font-weight:bold;">［${card.name}］</span>を獲得した。${routed.reason} カード鞄に収めた${overflow?'（所持枠を超えて保管中）':''}。`);
	return true;
}


function isSupplyCharacter(char){return char?.jobType==='supply';}
function isJesterCharacter(char){return char?.jobType==='clown';}
function getCharacterDeck(char){
	if(!char)return[];
	if(char.isPlayer){
		gameState.deck||=[];
		return gameState.deck;
	}
	char.deck||=[];
	return char.deck;
}
function getDeployConsumableCount(deck){
	return(deck||[]).filter(card=>card?.category==='consumable'&&!isRevivalCharm(card)).length;
}
function markDungeonAcquiredCard(card){
	if(!card||!gameState?.dungeon)return card;
	card.dungeonAcquired=true;
	card.dungeonAcquiredAt=Date.now();
	card.dungeonAcquiredName=gameState.dungeon?.name||'';
	if(gameState.dungeon?.questInstance&&gameState.dungeon.questRunToken)card.questLootToken=gameState.dungeon.questRunToken;
	return card;
}
function moveDungeonAcquiredCardsToStorage(){
	if(!gameState||!gameState.player)return{moved:0,remaining:0};
	gameState.cardStorage||=[];
	const members=[...(gameState.party||[])];
	if(gameState.player&&!members.includes(gameState.player))members.unshift(gameState.player);
	const seenDecks=new Set();
	let moved=0;
	let remaining=0;
	members.forEach(char=>{
		if(!char)return;
		const deck=getCharacterDeck(char);
		if(!Array.isArray(deck)||seenDecks.has(deck))return;
		seenDecks.add(deck);
		for(let i=deck.length-1;i>=0;i--){
			const card=deck[i];
			if(!card?.dungeonAcquired)continue;
			if(gameState.cardStorage.length>=CARD_STORAGE_MAX){
				remaining++;
				continue;
			}
			deck.splice(i,1);
			delete card.dungeonAcquired;
			delete card.dungeonAcquiredAt;
			delete card.dungeonAcquiredName;
			delete card.questLootToken;
			setCardUseOwner(card);
			gameState.cardStorage.push(card);
			moved++;
		}
	});
	return{moved,remaining};
}
function getLegacyTypeKey(card){
	return String(card?.masterId||card?.name||card?.legacyKind||card?.instanceId||'legacy');
}

function isDepartureBlankCard(card){
	return!!card?.departureBlank;
}
function createDepartureBlankCard(serial=0){
	return createGeneratedCard('departure_blank',{
		masterId:'temporary_departure_blank',suit:'',name:'ブランク',rarity:'N',cost:0,manaGen:0,
		type:'atk',ratio:-0.8,departureBlank:true,temporaryDepartureCard:true,noGrowth:true,
		noUpgrade:true,noTrade:true,noSell:true
	},{instancePrefix:'departure_blank',serial});
}
function getDepartureBlankPlan(){
	updatePartyPositions();
	return(gameState.party||[])
		.filter(char=>char&&char.hp>0&&(char.position==='front'||char.position==='back')&&!char.missionCompanion&&!isSupplyCharacter(char))
		.map(char=>{
			const deck=getCharacterDeck(char);
			const missing=Math.max(0,STANDARD_DECK_MIN-deck.length);
			return{char,deck,missing};
		})
		.filter(entry=>entry.missing>0);
}
function removeDepartureBlankCardsFromParty(){
	let removed=0;const seen=new Set();
	const members=[...(gameState.party||[])];
	if(gameState.player&&!members.includes(gameState.player))members.unshift(gameState.player);
	for(const char of members){
		if(!char)continue;
		const deck=getCharacterDeck(char);if(!Array.isArray(deck)||seen.has(deck))continue;seen.add(deck);
		for(let i=deck.length-1;i>=0;i--){
			if(!isDepartureBlankCard(deck[i]))continue;
			deck.splice(i,1);removed++;
		}
	}
	return removed;
}
async function confirmAndFillDepartureBlanks(){
	// 町で残っていた旧ブランクは再利用せず、その出撃の不足数から作り直す。
	if(!gameState?.dungeon)removeDepartureBlankCardsFromParty();
	const plan=getDepartureBlankPlan();
	if(!plan.length)return true;
	const lines=plan.map(({char,deck,missing})=>`【${char.name||'冒険者'}】 ${deck.length}/${STANDARD_DECK_MIN}枚 → 《ブランク》+${missing}枚`);
	const ok=await showGameConfirm(
		`出撃デッキが${STANDARD_DECK_MIN}枚に足りません。\n\n${lines.join('\n')}\n\n不足分を《ブランク》で補って出撃しますか？\n\n《ブランク》：マナ0 / コンボ不可 / 物理攻撃20% / ジョブ特殊効果の対象外。迷宮内でカードを得ると1枚ずつ入れ替わり、町へ戻ると残りは消滅します。`,
		{title:'《ブランク》で補充',confirmText:'補って出撃する',cancelText:'準備に戻る'}
	);
	if(!ok)return false;
	let serial=0,total=0;
	for(const {char,deck,missing} of plan){
		for(let i=0;i<missing;i++){deck.push(createDepartureBlankCard(serial++));total++;}
		log(`⬜ 【${escapeHtml(char.name||'冒険者')}】の不足 ${missing}枚を《ブランク》で補った。`);
	}
	if(total)updatePartyUI();
	return true;
}
function replaceDepartureBlankWithDungeonCard(card){
	if(!card||isDepartureBlankCard(card)||!gameState?.dungeon)return null;
	const recipients=getDungeonCardRecipients();
	for(let i=0;i<recipients.length;i++){
		const char=recipients[i],deck=getCharacterDeck(char);
		const blankIndex=deck.findIndex(isDepartureBlankCard);
		if(blankIndex<0)continue;
		setCardUseOwner(card,char);
		deck[blankIndex]=card;
		if(card.category==='legacy'&&typeof recalculateStats==='function')recalculateStats(char);
		return{location:'deck',ownerName:char.name||'仲間',ownerId:char.id||'',transferred:i>0,replacedBlank:true,reason:'《ブランク》と入れ替えて獲得した。'};
	}
	return null;
}
function validateDeckAddition(char,card,deckOverride=null){
	if(!char||!card)return{ok:false,reason:'カード情報が不正です。'};
	normalizeSpecialCardSuit(card);
	const deck=deckOverride||getCharacterDeck(char);
	if(isRevivalCharm(card)&&deck.some(isRevivalCharm)){
		return{ok:false,reason:'お守りは1人のデッキに1枚までです。'};
	}
	const deckMax=isSupplyCharacter(char)?SUPPLY_DECK_MAX:STANDARD_DECK_MAX;
	if(deck.length>=deckMax){
		return{ok:false,reason:`デッキ上限は${deckMax}枚です。素材・消耗品・報酬も枠を使います。`};
	}
	if(isSupplyCharacter(char)){
		if(!isDeckRuleExemptCard(card))return{ok:false,reason:'補給員は消耗品・報酬カードのみ所持できます。'};
		return{ok:true};
	}

  // 🧪/📦は総枚数に含むが、通常札のスート/同名制限から除外する。
  if(isDeckRuleExemptCard(card)){
		if(card.category==='consumable'&&!isRevivalCharm(card)
			&&!gameState?.dungeon
			&&getDeployConsumableCount(deck)>=STANDARD_DEPLOY_CONSUMABLE_MAX){
			return{ok:false,reason:`補給員以外が町から持ち出せる消耗品は最大${STANDARD_DEPLOY_CONSUMABLE_MAX}枚です。`};
		}
		return{ok:true};
	}
	const coreDeck=getDeckCoreCards(deck);
	if(!gameState?.dungeon&&card.category!=='legacy'&&card.suit
		&&getDeckSuitRuleCards(deck).filter(c=>c?.suit===card.suit).length>=STANDARD_SUIT_CARD_MAX){
		return{ok:false,reason:`同じスート【${card.suit}】は最大${STANDARD_SUIT_CARD_MAX}枚までです。`};
	}
	if(!isJesterCharacter(char)&&card.category!=='legacy'&&card.suit){
		const suits=new Set(getDeckSuitRuleCards(deck).map(c=>c?.suit).filter(Boolean));
		if(!suits.has(card.suit)&&suits.size>=STANDARD_SUIT_TYPE_MAX){
			return{ok:false,reason:`通常札に使えるスートは最大${STANDARD_SUIT_TYPE_MAX}種類です。`};
		}
	}
	if(card.name&&coreDeck.filter(c=>c?.name===card.name).length>=STANDARD_NAME_MAX){
		return{ok:false,reason:`同名カード【${card.name}】は最大${STANDARD_NAME_MAX}枚までです。`};
	}
	if(card.category==='legacy'){
		const equippedTypes=new Set(coreDeck.filter(c=>c?.category==='legacy').map(getLegacyTypeKey));
		const incomingType=getLegacyTypeKey(card);
		if(!equippedTypes.has(incomingType)&&equippedTypes.size>=STANDARD_LEGACY_TYPE_MAX){
			return{ok:false,reason:`レガシーは${STANDARD_LEGACY_TYPE_MAX}種類まで装備できます。`};
		}
	}
	return{ok:true};
}
function getDeckMinimum(char){return isSupplyCharacter(char)?SUPPLY_DECK_MIN:STANDARD_DECK_MIN;}
function getDeckMaximum(char){return isSupplyCharacter(char)?SUPPLY_DECK_MAX:STANDARD_DECK_MAX;}
function validateCurrentDeck(char,options={}){
	if(!char)return{ok:false,reason:'キャラクター情報が不正です。'};
	const deck=getCharacterDeck(char);
	normalizeSpecialCardSuitsInArray(deck);
	const count=deck.length;
	const min=getDeckMinimum(char),max=getDeckMaximum(char);
	if(count<min&&!options.allowBelowMinimum)return{ok:false,reason:`デッキは最低${min}枚必要です（現在${count}枚）。`};
	if(count>max)return{ok:false,reason:`デッキは最大${max}枚です（現在${count}枚）。素材・消耗品・報酬も枠を使います。`};
	if(deck.filter(isRevivalCharm).length>1)return{ok:false,reason:'お守りは1人のデッキに1枚までです。'};
	if(isSupplyCharacter(char)){
		if(deck.some(c=>!isDeckRuleExemptCard(c)))return{ok:false,reason:'補給員は消耗品・報酬カードのみ所持できます。'};
		return{ok:true};
	}
	const consumableCount=getDeployConsumableCount(deck);
	if(consumableCount>STANDARD_DEPLOY_CONSUMABLE_MAX){
		return{ok:false,reason:`補給員以外が持ち出せる消耗品は最大${STANDARD_DEPLOY_CONSUMABLE_MAX}枚です（現在${consumableCount}枚）。`};
	}
	const coreDeck=getDeckCoreCards(deck);
	const suitCounts=new Map();
	for(const card of getDeckSuitRuleCards(deck)){
		if(!card?.suit)continue;
		const n=(suitCounts.get(card.suit)||0)+1;suitCounts.set(card.suit,n);
		if(n>STANDARD_SUIT_CARD_MAX)return{ok:false,reason:`同じスート【${card.suit}】は最大${STANDARD_SUIT_CARD_MAX}枚までです（現在${n}枚以上）。`};
	}
	const suitTypes=new Set(getDeckSuitRuleCards(deck).map(card=>card?.suit).filter(Boolean));
	const nameCounts=new Map(),legacyTypes=new Set();
	for(const card of coreDeck){
		if(!card)continue;
		if(card.name){
			const n=(nameCounts.get(card.name)||0)+1;nameCounts.set(card.name,n);
			if(n>STANDARD_NAME_MAX)return{ok:false,reason:`同名カード【${card.name}】は最大${STANDARD_NAME_MAX}枚までです。`};
		}
		if(card.category==='legacy')legacyTypes.add(getLegacyTypeKey(card));
	}
	if(!isJesterCharacter(char)&&suitTypes.size>STANDARD_SUIT_TYPE_MAX){
		return{ok:false,reason:`通常札に使えるスートは最大${STANDARD_SUIT_TYPE_MAX}種類です（現在${suitTypes.size}種類）。`};
	}
	if(legacyTypes.size>STANDARD_LEGACY_TYPE_MAX)return{ok:false,reason:`レガシーは${STANDARD_LEGACY_TYPE_MAX}種類まで装備できます。`};
	return{ok:true};
}
function validatePartyDecksForDungeonEntry(){
	updatePartyPositions();
	const entrants=(gameState.party||[]).filter(c=>c&&c.hp>0&&(c.position==='front'||c.position==='back'));
	for(const char of entrants){
		// DBで完成済みのミッション同行NPCは、プレイヤー用の編成制限（3スート等）の対象外。
		if(char.missionCompanion)continue;
		const result=validateCurrentDeck(char,{allowBelowMinimum:true});
		if(!result.ok){
			showGameNotice(`【${char.name}】のデッキを確認してください。\n${result.reason}\n拠点でデッキを整えてから迷宮へ向かいましょう。`,{title:'探索に出られません'});
			return false;
		}
	}
	return true;
}
function putCardInStorage(card,options={}){
	if(!card)return false;
	gameState.cardStorage||=[];
	if(gameState.cardStorage.length>=CARD_STORAGE_MAX){
		if(!options.silent)log(`⚠️ カード鞄が満杯（${CARD_STORAGE_MAX}枚）のため、【${card.name||'カード'}】を収納できません。`);
		return false;
	}
	setCardUseOwner(card);
	gameState.cardStorage.push(card);
	return true;
}
function getDungeonCardRecipients(){
	if(typeof updatePartyPositions==='function')updatePartyPositions();
	const party=(gameState.party||[]).filter(c=>c&&c.hp>0&&(c.position==='front'||c.position==='back'));
	const hero=gameState.player||party.find(c=>c?.isPlayer);
	return[hero,...party.filter(c=>c!==hero)].filter((c,i,a)=>c&&a.indexOf(c)===i);
}
function addDungeonCardToPlayerOrStorage(card){
	if(!card)return{location:'lost',reason:'カード情報が不正です。'};
	markDungeonAcquiredCard(card);
	const blankReplacement=replaceDepartureBlankWithDungeonCard(card);
	if(blankReplacement)return blankReplacement;
	const recipients=getDungeonCardRecipients();
	if(!recipients.length)return{location:'lost',reason:'受け取れる同行者がいません。'};
	let firstReason='';
	for(let i=0;i<recipients.length;i++){
		const char=recipients[i];
		const deck=getCharacterDeck(char);
		const check=validateDungeonCardAddition(char,card,deck);
		if(!check.ok){
			if(!firstReason)firstReason=check.reason;
			continue;
		}
		setCardUseOwner(card,char);
		deck.push(card);
		if(card.category==='legacy'&&typeof recalculateStats==='function')recalculateStats(char);
		return{
			location:'deck',
			ownerName:char.name||'仲間',
			ownerId:char.id||'',
			transferred:i>0,
			reason:i>0?`${firstReason||getPlayerDisplayName()+'のデッキに入らない'}ため、同行者へ受け渡した。`:''
		};
	}
	return{
		location:'lost',
		reason:`${firstReason||'デッキ制限'} 同行者全員のデッキにも受け入れ余地がありません。`
	};
}
function getActiveExplorationPartyMembers(){
	return(gameState.party||[]).filter(c=>c&&(c.position==='front'||c.position==='back'));
}
function getCurrentPartyAverageLevel(){
	const active=getActiveExplorationPartyMembers();
	const pool=active.length?active:(gameState.party||[]).filter(Boolean);
	if(!pool.length)return 1;
	return Math.max(1,pool.reduce((sum,c)=>sum+Math.max(1,Number(c.level)||1),0)/ pool.length);
}
function getMaterialBundlerRole(char){
	if(!char||char.hp<=0)return null;
	if(isSupplyCharacter(char))return 'supply';
	if(isAlchemistCharacter(char))return 'alchemist';
	return 'basic';
}
function getActiveMaterialBundlers(){
	return getActiveExplorationPartyMembers().filter(c=>c&&c.hp>0);
}
function getMaterialBundlerForSelectedDeck(){
	const active=getActiveMaterialBundlers();
	if(!active.length)return null;
	const selected=gameState.party?.[selectedDungeonDeckCharIdx]||null;
	return active.find(isSupplyCharacter)
		||active.find(isAlchemistCharacter)
		||(selected&&active.includes(selected)?selected:active[0]);
}
function getMaterialBundleProfile(role){
	if(role==='supply')return{coeff:50,name:'圧縮素材',kind:'supply_material_bundle',masterId:'material_supply_bundle',prefix:'supply_material'};
	if(role==='alchemist')return{coeff:20,name:'錬金素材',kind:'alchemical_material_bundle',masterId:'material_alchemical_bundle',prefix:'alchemical_material'};
	return{coeff:10,name:'束ねた素材',kind:'material_bundle',masterId:'material_bundle',prefix:'material_bundle'};
}
function getMaterialBundleValueCapFor(char){
	const role=getMaterialBundlerRole(char);
	if(!role)return 0;
	const profile=getMaterialBundleProfile(role);
	return Math.max(1,Math.floor(getCurrentPartyAverageLevel()*profile.coeff));
}
function createBundledMaterialCard(value,sourceCount,bundleRole='basic'){
	const sellPrice=Math.max(1,Math.floor(Number(value)||0));
	const profile=getMaterialBundleProfile(bundleRole);
	return createGeneratedCard(profile.kind,{
		masterId:profile.masterId,
		suit:REWARD_SUIT,
		name:profile.name,
		rarity:'N',dropRarity:'N',cost:0,
		category:'reward',type:'material_boost',materialCard:true,
		bundledMaterial:true,
		basicBundle:bundleRole==='basic',
		alchemicalBundle:bundleRole==='alchemist',
		supplyBundle:bundleRole==='supply',
		sourceMaterialCount:Math.max(2,Math.floor(Number(sourceCount)||2)),
		sellPrice
	},{instancePrefix:profile.prefix});
}
function getPartyMaterialEntriesForBundling(){
	const active=getActiveExplorationPartyMembers();
	const members=active.length?active:(gameState.party||[]).filter(Boolean);
	const entries=[];
	members.forEach(owner=>{
		const deck=getCharacterDeck(owner);
		deck.forEach((card,index)=>{
			if(isBattleMaterialCard(card)&&!isGemCard(card)&&!card.tutorialPracticeCargo&&Math.max(0,Number(card.sellPrice)||0)>0){
				entries.push({owner,deck,card,index,value:Math.max(1,Math.floor(Number(card.sellPrice)||0))});
			}
		});
	});
	return entries;
}
function getBundledSourceCount(entries){
	return(entries||[]).reduce((sum,e)=>sum+Math.max(1,Math.floor(Number(e?.card?.sourceMaterialCount)||1)),0);
}
function inheritDungeonAcquiredMarker(targetCard,sourceEntries){
	if(!targetCard)return targetCard;
	const cards=(sourceEntries||[]).map(e=>e?.card);
	const token=cards.find(card=>card?.questLootToken)?.questLootToken;
	if(token)targetCard.questLootToken=token;
	const source=cards.find(card=>card?.dungeonAcquired);
	if(!source)return targetCard;
	targetCard.dungeonAcquired=true;
	targetCard.dungeonAcquiredAt=Number(source.dungeonAcquiredAt)||Date.now();
	targetCard.dungeonAcquiredName=source.dungeonAcquiredName||gameState.dungeon?.name||'';
	return targetCard;
}
function hasMergeableMaterialPair(entries,cap){
	const values=(entries||[]).map(e=>Number(e?.value)||0).filter(v=>v>0&&v<=cap).sort((a,b)=>a-b);
	if(values.length<2)return false;
	return values[0]+values[1]<=cap;
}
function findMaterialMergeCandidate(entries,char,cap){
	const destDeck=getCharacterDeck(char);
	const max=getDeckMaximum(char);
	const eligible=(entries||[]).filter(e=>e.value>0&&e.value<=cap);
	if(eligible.length<2)return null;
	const questToken=gameState?.dungeon?.questInstance?gameState.dungeon.questRunToken:null;
	let best=null;
	eligible.forEach(seed=>{
		const seedTemporary=!!(questToken&&seed.card?.questLootToken===questToken);
		const others=eligible.filter(e=>e!==seed&&(!questToken||!!(e.card?.questLootToken===questToken)===seedTemporary)).sort((a,b)=>{
			const aOwn=a.owner===char?1:0;
			const bOwn=b.owner===char?1:0;
			if(aOwn!==bOwn)return bOwn-aOwn;
			return a.value-b.value;
		});
		const group=[seed];
		let total=seed.value;
		for(const entry of others){
			if(total+entry.value>cap)continue;
			group.push(entry);
			total+=entry.value;
		}
		if(group.length<2)return;
		const ownCount=group.filter(e=>e.owner===char).length;
		const projectedLength=destDeck.length-ownCount+1;
		if(projectedLength>max)return;
		const score=(group.length*1000000)+(ownCount*10000)+total;
		if(!best||score>best.score)best={group,total,ownCount,projectedLength,score};
	});
	return best;
}
function applyMaterialMergeCandidate(char,candidate,role){
	if(!char||!candidate?.group?.length)return null;
	const byOwner=new Map();
	candidate.group.forEach(entry=>{
		if(!byOwner.has(entry.owner))byOwner.set(entry.owner,new Set());
		byOwner.get(entry.owner).add(entry.card);
	});
	byOwner.forEach((cards,owner)=>{
		const deck=getCharacterDeck(owner);
		const kept=deck.filter(card=>!cards.has(card));
		if(owner.isPlayer)gameState.deck=kept;
		else owner.deck=kept;
	});
	const bundle=createBundledMaterialCard(candidate.total,getBundledSourceCount(candidate.group),role);
	inheritDungeonAcquiredMarker(bundle,candidate.group);
	getCharacterDeck(char).push(bundle);
	return bundle;
}
function compactPartyMaterialsWith(char){
	const role=getMaterialBundlerRole(char);
	const cap=getMaterialBundleValueCapFor(char);
	if(!role||!cap)return{changed:false,reason:'職業',before:0,after:0,cap:0,value:0};
	const initialEntries=getPartyMaterialEntriesForBundling();
	const before=initialEntries.length;
	const totalValue=initialEntries.reduce((sum,e)=>sum+e.value,0);
	if(before<2)return{changed:false,reason:'不足',before,after:before,cap,value:totalValue,role};
	let merged=0;
	let bundles=0;
	let guard=0;
	while(guard++<500){
		const entries=getPartyMaterialEntriesForBundling();
		const candidate=findMaterialMergeCandidate(entries,char,cap);
		if(!candidate)break;
		const bundle=applyMaterialMergeCandidate(char,candidate,role);
		if(!bundle)break;
		merged+=candidate.group.length-1;
		bundles++;
	}
	const remainingEntries=getPartyMaterialEntriesForBundling();
	const after=remainingEntries.length;
	const max=getDeckMaximum(char);
	const current=getCharacterDeck(char).length;
	const blockedByCapacity=hasMergeableMaterialPair(remainingEntries,cap)
		&&!findMaterialMergeCandidate(remainingEntries,char,cap);
	const reason=merged>0?(blockedByCapacity?'容量':'')
		:(blockedByCapacity?'容量':'上限');
	return{
		changed:merged>0,reason,before,after,merged,bundles,value:totalValue,cap,role,
		current,max,blockedByCapacity,remaining:remainingEntries.length
	};
}
function compactDungeonMaterialsWithSpecialist(index){
	if(!gameState.dungeon||gameState.inBattle){
		log('⚠️ 「素材を整頓」は探索中・非戦闘時に使用できます。');
		return;
	}
	const char=gameState.party?.[index];
	const role=getMaterialBundlerRole(char);
	if(!char||!getActiveExplorationPartyMembers().includes(char)||!['alchemist','supply'].includes(role))return;
	const result=compactPartyMaterialsWith(char);
	const profile=getMaterialBundleProfile(role);
	if(!result.changed){
		if(result.reason==='容量')log(`⚠️ 【${char.name}】の所持枠が上限${result.max}枚のため、これ以上まとめられない。`);
		else log(`🧱 PT全体の素材はこれ以上まとめられない。（${profile.name} ×${profile.coeff}）`);
	}else{
		log(`🧱 【${char.name}】が素材を整理した。${result.before}枚 → ${result.after}枚（${profile.name} ×${profile.coeff}）。`);
		if(result.blockedByCapacity)log(`📦 【${char.name}】は${result.current}/${result.max}枚。所持上限の手前で整理を止めた。`);
		saveGame();
	}
	updatePartyUI();
}
function createEnemyMaterialCard(enemy){
	if(!enemy)return null;
	const rawName=String(enemy.name||'魔物')
		.replace(/^【[^】]+】/,'')
		.replace(/\s+[A-D]$/,'')
		.trim();
	const hp=Math.max(1,Number(enemy.maxHp||enemy.hp)||1);
	const sellPrice=Math.max(1,Math.floor(hp*0.10));
	return createGeneratedCard('enemy_material',{
		masterId:`material_${enemy.category||'unknown'}`,suit:REWARD_SUIT,name:`${rawName}の素材`,rarity:'N',dropRarity:'N',cost:0,
		category:'reward',type:'material_boost',materialCard:true,sourceEnemyCategory:enemy.category||'unknown',sellPrice
	},{instancePrefix:'material'});
}
function bundleEnemyMaterialDrops(cards){
	const bundler=getMaterialBundlerForSelectedDeck();
	const role=getMaterialBundlerRole(bundler);
	const cap=getMaterialBundleValueCapFor(bundler);
	if(!role||!cap)return cards;
	const pending=[...cards];
	while(true){
		const eligible=pending.filter(card=>Number(card.sellPrice)>0&&Number(card.sellPrice)<=cap).sort((a,b)=>a.sellPrice-b.sellPrice);
		if(eligible.length<2||eligible[0].sellPrice+eligible[1].sellPrice>cap)break;
		const group=[eligible[0]];
		let value=Number(eligible[0].sellPrice);
		for(const card of eligible.slice(1)){
			if(value+Number(card.sellPrice)>cap)continue;
			group.push(card);
			value+=Number(card.sellPrice);
		}
		if(group.length<2)break;
		group.forEach(card=>pending.splice(pending.indexOf(card),1));
		pending.push(createBundledMaterialCard(value,group.reduce((sum,card)=>sum+Math.max(1,Number(card.sourceMaterialCount)||1),0),role));
	}
	return pending;
}
function mergeIncomingMaterialWithParty(card,bundler){
	if(!bundler||!isBattleMaterialCard(card)||isGemCard(card))return null;
	const cap=getMaterialBundleValueCapFor(bundler);
	const value=Number(card.sellPrice)||0;
	if(value<=0||value>=cap)return null;
	const token=gameState.dungeon?.questInstance?gameState.dungeon.questRunToken:null;
	const isTemporary=!!(token&&card.questLootToken===token);
	const entries=getPartyMaterialEntriesForBundling().filter(e=>e.value+value<=cap&&(!token||!!(e.card.questLootToken===token)===isTemporary));
	entries.sort((a,b)=>Number(b.owner===bundler)-Number(a.owner===bundler)||a.value-b.value);
	const group=[];
	let total=value;
	for(const entry of entries){
		if(total+entry.value>cap)continue;
		group.push(entry);
		total+=entry.value;
	}
	if(!group.length)return null;
	const ownCount=group.filter(e=>e.owner===bundler).length;
	if(getCharacterDeck(bundler).length-ownCount+1>getDeckMaximum(bundler))return null;
	const incoming={owner:bundler,card,value};
	return applyMaterialMergeCandidate(bundler,{group:[...group,incoming],total},getMaterialBundlerRole(bundler));
}
function grantEnemyMaterialDrops(enemies){
	const cards=(enemies||[]).map(createEnemyMaterialCard).filter(Boolean);
	const results=[];
	const bundler=getMaterialBundlerForSelectedDeck();
	if(bundler)compactPartyMaterialsWith(bundler);
	bundleEnemyMaterialDrops(cards).forEach(card=>{
		let routed=addDungeonCardToPlayerOrStorage(card);
		if(routed.location!=='deck'&&bundler){
			compactPartyMaterialsWith(bundler);
			routed=addDungeonCardToPlayerOrStorage(card);
			if(routed.location!=='deck'){
				const bundle=mergeIncomingMaterialWithParty(card,bundler);
				if(bundle)routed={location:'deck',ownerName:bundler.name||'仲間',transferred:true};
			}
		}
		results.push({card,routed});
	});
	if(bundler)compactPartyMaterialsWith(bundler);
	return results;
}
function createCardInstance(masterId,options={}){
	const master=getCardMaster(masterId);
	if(!master)return null;
	const instance=JSON.parse(JSON.stringify(master));
	if(gameState?.cardNameOverrides?.[masterId])instance.cardNicknameLast=gameState.cardNameOverrides[masterId];
	instance.instanceId="card_"+Date.now()+"_"+Math.random().toString(36).substr(2,9);
	instance.level=instance.level||1;
	ensureCardPerformanceDefaults(instance);
	const requestedRarity=RARITY_CONFIG[options.rarity]?options.rarity:'N';
	if(options.applyRarity===false)instance.rarity=requestedRarity;
	else applyCardRarityPerformance(instance,requestedRarity);
	if(options.applyCollection!==false)applyCollectionBonusToNewCard(instance);
	if(Number.isFinite(getCardUseLimit(instance)))instance.usesRemaining=getCardUseLimit(instance);
	return instance;
}
function buildDeckFromMasterIds(ids){
	return ids.map(id=>createCardInstance(id,{rarity:'N',applyCollection:false})).filter(c=>c!==null);
}
