function openSettingsModal(options={}){
	const heartKeyInput=document.getElementById('heart-link-key-setting');if(heartKeyInput)heartKeyInput.value=getHeartLinkKey();
	const forceCreation=options.forceCreation===true;
	if(!forceCreation&&blockGuidedTutorialAction())return;
	creationSettingsActive=forceCreation;
	renderCreationSettingsScope();
	renderGamePreferencesUI();
    renderSaveBackupCooldownUI();
	
	refreshPlayerNamedUi();
	const modal=document.getElementById('settings-modal');
	if(!modal)return;
	const btn=document.getElementById('emergency-escape-btn');
	const desc=document.getElementById('emergency-escape-description');
	const available=!forceCreation&&canUseEmergencyEscape();
	if(btn){
		btn.disabled=!available;
		btn.textContent=available?'⚠️ 緊急脱出を実行':'緊急脱出（迷宮外では使用不可）';
	}
	if(desc)desc.style.opacity=available?'1':'.55';
	modal.style.display='flex';
}
let gameDialogState=null;
const gameDialogQueue=[];
function pumpGameDialogQueue(){
	if(gameDialogState||!gameDialogQueue.length)return;
	const modal=document.getElementById('game-dialog-modal');
	const title=document.getElementById('game-dialog-title');
	const message=document.getElementById('game-dialog-message');
	const input=document.getElementById('game-dialog-input');
	const cancel=document.getElementById('game-dialog-cancel');
	const confirmButton=document.getElementById('game-dialog-confirm');
	const queued=gameDialogQueue.shift();
	const options=queued?.options||{};
	const mode=options.mode||'notice';
	if(!modal||!title||!message||!input||!cancel||!confirmButton){
		queued?.resolve(mode==='confirm'?false:null);
		pumpGameDialogQueue();
		return;
	}
	gameDialogState={resolve:queued.resolve,mode};
	title.textContent=resolvePlayerReferenceText(options.title||({confirm:'確認',prompt:'入力',notice:'お知らせ'}[mode]||'確認'));
	if(options.inscriptionHtml)message.innerHTML=String(options.message||'');
    else if(/^Tips[：:]/.test(options.title||''))renderReadableTip(message,resolvePlayerReferenceText(options.message||''));
    else message.textContent=resolvePlayerReferenceText(options.message||'');
    message.scrollTop=0;
	input.style.display=mode==='prompt'?'block':'none';
	input.readOnly=!!options.readOnly;
	input.maxLength=Number.isFinite(Number(options.maxLength))?Math.max(1,Math.floor(Number(options.maxLength))):524288;
	input.value=mode==='prompt'?String(options.defaultValue??''):'';
	cancel.style.display=mode==='notice'||options.hideCancel?'none':'';
	cancel.textContent=options.cancelText||'キャンセル';
	confirmButton.textContent=options.confirmText||(mode==='notice'?'閉じる':'決定');
	modal.style.display='flex';modal.setAttribute('aria-hidden','false');
	setTimeout(()=>{if(gameDialogState){(mode==='prompt'?input:confirmButton).focus();if(mode==='prompt'&&!input.readOnly)input.select();}},0);
}
function openGameDialog(options={}){
	return new Promise(resolve=>{
		gameDialogQueue.push({options,resolve});
		pumpGameDialogQueue();
	});
}
function resolveGameDialog(confirmed){
	const state=gameDialogState;if(!state)return;
	const modal=document.getElementById('game-dialog-modal');
	const input=document.getElementById('game-dialog-input');
	if(modal){modal.style.display='none';modal.setAttribute('aria-hidden','true');}
	gameDialogState=null;
	if(state.mode==='confirm')state.resolve(!!confirmed);
	else if(state.mode==='prompt')state.resolve(confirmed?String(input?.value??''):null);
	else state.resolve(true);
	pumpGameDialogQueue();
}
function showGameConfirm(message,options={}){return openGameDialog({...options,mode:'confirm',message});}
function showGamePrompt(message,defaultValue='',options={}){return openGameDialog({...options,mode:'prompt',message,defaultValue});}
function renderReadableTip(container,text){
 container.replaceChildren();
 for(const block of String(text).split(/\n\s*\n/)){
  const section=document.createElement('section');section.className='readable-tip';
  const lines=block.split('\n');
  if(/^【.+】$/.test(lines[0])){const heading=document.createElement('strong');heading.textContent=lines.shift().slice(1,-1);section.append(heading);}
  const body=document.createElement('div');body.textContent=lines.join('\n');section.append(body);container.append(section);
 }
}
function showGameNotice(message,options={}){return openGameDialog({...options,mode:'notice',message});}

function showTownGuideChoice(){
	if(gameState.onboardingStage!=='tutorialRest')return;
	if(gameState.onboardingGuidePreference){showSummonaGuide('restAfterTutorial');return;}
	const result=document.getElementById('adventure-result-modal');
	if(result?.style.display==='flex'){setTimeout(showTownGuideChoice,180);return;}
	openSummonaDialogue('……やっと外の空気が吸えたね。おかえり。ここなら、ひとまず肩の力を抜いていい。<br><br>一緒に歩いてくれる仲間には声をかけてある。旅の支度も少し用意したよ。<br><br>初めてなら、宿屋から順に案内しようか。休んで、ギルドで仲間と会って、店と拠点で旅の支度を整えよう。<br><br>自分で見て回りたいなら、それでも大丈夫。分からない時に声をかけて。','サモナ',{storySequence:false});
	const choices=document.getElementById('summona-town-guide-choices');
	const next=document.getElementById('summona-dialog-next-btn');
	if(choices)choices.style.display='flex';
	if(next)next.style.display='none';
}
async function chooseTownGuide(preference){
	if(gameState.onboardingStage!=='tutorialRest'||!['all','context','skip'].includes(preference))return;
	const choices=document.getElementById('summona-town-guide-choices');
	const next=document.getElementById('summona-dialog-next-btn');
	if(choices)choices.style.display='none';
	if(next)next.style.display='';
	hideModalById('summona-dialog-modal');
	gameState.onboardingGuidePreference=preference;
	saveGame();
	if(preference==='all'){
		showSummonaGuide('restAfterTutorial');
	}else{
		completeTownGuidePreparation();
	}
}

function completeTownGuidePreparation(){
	const hero=gameState.player;
	if(!hero)return;
	if(gameState.firstDungeonLessonSeen&&gameState.starterJobCardGiftClaimed)return;
	const members=Array.isArray(gameState.pendingStarterMembers)&&gameState.pendingStarterMembers.length===5?gameState.pendingStarterMembers:buildStarterGuildMembers();
	setStarterPartyFormation([hero,...members]);
	delete gameState.pendingStarterMembers;
	gameState.guildIntroPending=false;
	gameState.onboardingStage=null;
	if(gameState.onboardingGuidePreference==='skip')gameState.firstAdventureGuidesSeen={quest:true,normal:true,mugen:true};
	const defer=gameState.onboardingGuidePreference==='context';
	gameState.contextFacilityGuidesSeen={shop:!defer,storage:!defer};
	gameState.townNotices={rest:false,storage:false};
	if(hero.hp>0){hero.injury=0;hero.hp=hero.maxHp;}
	processLevelUp(hero);
	const potionMaster=getCardMaster('c_potion');
	if(potionMaster){
		const potion=createCardInstance('c_potion',{rarity:'N'});
		if(potion)putCardInStorage(potion,{silent:true});
	}
	gameState.firstDungeonLessonSeen=true;
	grantTownTutorialRewards();
	updatePartyPositions();updatePartyUI();refreshWordSelects();updateGuidedTutorialLocks();updateTownNotices();
	clearLog();log('🤝 仲間と合流し、サモナから旅の支給品を受け取った。');
	log('🎁 ポーション、職業に応じたカード、帰還の羽、支援カード、《サモナ》のお守りを受け取った。');
	log('🧭 町と迷宮を自由に選べます。案内は「サモナに聞く」から確認できます。');
	saveGame();
}

