function saveCardNickname(){
 const id=document.getElementById('card-naming-select')?.value;
 if(!Object.prototype.hasOwnProperty.call(CARD_DEFAULT_NAMES,id))return;
 const raw=String(document.getElementById('card-naming-input')?.value||'').trim();
 if(!raw){applyCardNicknameChange(id,'');return;}
 if(RESERVED_PLAYER_NAMES.has(raw.normalize('NFKC'))){
  closeSettingsModal();
  showReservedNameEasterEgg(raw);
  return;
 }
 if(!isValidCardNickname(raw)){
  showGameNotice('カード名は16文字までです。改行、HTML記号、引用符、《》は使えません。',{title:'入力エラー'});
  return;
 }
 if(Object.entries(CARD_DEFAULT_NAMES).some(([otherId,base])=>otherId!==id&&base===raw)
  ||CARD_MASTER.some(card=>card.masterId!==id&&card.name===raw)){
  showGameNotice('別の種類のカードと同じ名前は登録できません。',{title:'入力エラー'});
  return;
 }
 applyCardNicknameChange(id,raw===CARD_DEFAULT_NAMES[id]?'':raw);
}
