async function emergencyEscapeToTown(){
	if(!canUseEmergencyEscape())return;
	const name=getPlayerDisplayName();const warning=`緊急脱出を実行しますか？\n\n${name}以外の仲間は全員失われます。\n仲間のカード・装備も回収されません。\n${name}はHP1で町へ帰還します。\n\nこの操作は元に戻せません。`;
	if(!await showGameConfirm(warning,{title:'緊急脱出',confirmText:'脱出する'}))return;
	if(typeof cancelPlayerAutoSequence==='function')cancelPlayerAutoSequence(true);
	const escapedDungeon=gameState.dungeon;
	if(escapedDungeon?.externalRescue){const rq=findQuestById(escapedDungeon.questId);if(rq)markExternalRescueFailed(rq,'emergency-escape');}
	const hero=gameState.player||(gameState.party||[]).find(c=>c?.isPlayer);
	if(!hero)return;
	const rp=ensureResearchProgram();
	const currentLost=(gameState.party||[]).filter(c=>c&&c!==hero&&!c.isPlayer);
	const researchLost=(rp.partyBackup||[]).filter(c=>c&&!c.isPlayer);
	const missionLost=(gameState.missionCompanionContext?.partyBackup||[]).filter(c=>c&&!c.isPlayer);
	const tutorialLost=(gameState.tutorialState?.reserveParty||[]).filter(c=>c&&!c.isPlayer);
	const allLost=[...currentLost,...researchLost,...missionLost,...tutorialLost];
	const seenLost=new Set();
	const lostNames=allLost.filter(c=>{
		const key=c.id||`${c.name}:${c.job}`;
		if(seenLost.has(key))return false;
		seenLost.add(key);
		return true;
	}).map(c=>c.name||'仲間');
	rp.partyBackup=[];
	rp.inResearchDungeon=false;
	gameState.missionCompanionContext={active:false,partyBackup:[],questId:'',npcId:'',selectedAllyIds:[]};
	if(gameState.tutorialState){
		gameState.tutorialState.reserveParty=[];
		gameState.tutorialState.active=false;
		gameState.tutorialState.completed=true;
		gameState.tutorialState.replay=false;
	}
	gameState.party=[hero];
	gameState.player=hero;
	hero.isPlayer=true;
	hero.id='hero';
	hero.hp=1;
	hero.statuses=createInitialStatuses();
	hero.guard=0;
	hero.mana=0;
	hero.deck=gameState.deck;
	if(gameState.activeAdventureRecord)finalizeAdventureRecord(escapedDungeon,'emergency-escape');
	gameState.dungeon=null;
	gameState.inBattle=false;
	gameState.turn=1;
	gameState.rescueWaiting=null;
	gameState.inheritancePending=false;
	gameState.onboardingStage=null;
	battleState=createBattleState();
	closeAllOverlaysForEmergencyEscape();
	updatePartyPositions();
	showScreen('screen-town');
	updatePartyUI();
	updateTownNotices();
	clearLog();
	log(`🚨 緊急脱出を実行した。【${escapeHtml(getPlayerDisplayName())}】だけが瀕死の状態で町へ帰還した。`);
	if(lostNames.length)log(`💀 帰還できなかった仲間：${lostNames.join('、')}`);
	else log('💀 同行者はいなかった。');
	saveGame();
}
// 保存契約: キー・構造・値の意味は applyLoadedSaveData() と対応させて維持する。
