async function resumeRescueOrInheritance(){
	if(gameState.rescueWaiting){
		if(Date.now()-gameState.rescueWaiting.deathTime>RESCUE_LIMIT_MS){
			showScreen('screen-town');
			await showGameNotice('救助の有効期限が切れました。後継者選択に進みます。',{title:'救助期限'});
			saveGame();
			showScreen('screen-town');
			openInheritanceModal();
			return true;
		}
		showScreen(gameState.dungeon?'screen-dungeon':'screen-town');
		if(gameState.dungeon){updateDungeonView();updateStairActionButton();}
		const outputElem=document.getElementById('rescue-code-output');
		if(outputElem)outputElem.value=gameState.rescueWaiting.code;
		updateDeathRescueGuide(normalizeDeathMode(gameState.rescueWaiting.deathMode));
		const modalElem=document.getElementById('death-rescue-modal');
		if(modalElem)modalElem.style.display='flex';
		log("⚠️ 救助を待っている状態から再開した。");
		return true;
	}
	if(!gameState.inheritancePending)return false;
	showScreen('screen-town');
	const candidates=gameState.party.filter(c=>c&&!c.isPlayer&&c.hp>0&&c.jobType!=='supply');
	if(candidates.length>0){
		showHeroSelectModal(candidates);
		log("👑 継承者選択を再開しました。");
		updatePartyUI();
		return true;
	}
	resolveNoHeirDeath();
	return true;
}
function resumeOnboardingStage(){
	if(gameState.tutorialState?.active){
		restoreTutorialFromSave();
		return true;
	}
		switch(gameState.onboardingStage){
		case 'tutorialRest':
			showScreen('screen-town');updatePartyUI();updateTownNotices();
			setTimeout(showTownGuideChoice,100);
			return true;
		case 'guild':
			showScreen('screen-town');updatePartyUI();updateTownNotices();
			setTimeout(()=>showSummonaGuide('guildMeet'),100);
			return true;
		case 'formationTutorial':
			showScreen('screen-guild');updatePartyUI();updateGuildUI();
			scheduleFormationTutorialGuide(100);
			return true;
		case 'partyName':
			showScreen('screen-guild');updatePartyUI();
			setTimeout(openStarterPartyNameModal,100);
			return true;
		case 'shopPotion':
		case 'shopPotionBought':{
			const expectedStage=gameState.onboardingStage;
			openShopScreen();updatePartyUI();
			scheduleSummonaGuide(expectedStage==='shopPotion'?'shopPotion':'potionUse',100,expectedStage,'screen-shop');
			return true;
		}
		case 'potionStorage':
			openStorageScreen();updatePartyUI();
			scheduleSummonaGuide('potionStorage',100,'potionStorage','screen-storage');
			return true;
		case 'dungeonLessonPending':
			showScreen('screen-town');updatePartyUI();updateTownNotices();
			return true;
		case 'dungeonLesson':
			showScreen('screen-town');updatePartyUI();updateTownNotices();
			scheduleSummonaGuide('dungeonKinds',100,'dungeonLesson','screen-town');
			return true;
		default:
			return false;
	}
}
function resumeDungeonFromSave(){
	const d=gameState.dungeon;
	if(!d)return false;
	updatePartyPositions();
	updatePartyUI();

  // ロード時は戦闘チェックポイント復元を最優先する。
  if(gameState.inBattle&&Array.isArray(battleState.enemies)&&battleState.enemies.length>0){
		battleState.selectedIndices=[];
		battleState.autoMode=false;
		battleState.autoSelecting=false;
		showScreen('screen-battle');
		clearLog();
		log('⚔️ 戦闘開始時点から再開した。敵が目前にいる。');
		updateBattleUI();
		return true;
	}

  // 非戦闘チュートリアルは専用復元処理へ渡す。
  if(gameState.tutorialState?.active){
		restoreTutorialFromSave();
		return true;
	}
	gameState.inBattle=false;
	revealAround(d.x,d.y);
	showScreen('screen-dungeon');
	updateDungeonView();
	updateStairActionButton();
	refreshMapIfOpen();
	clearLog();
	log(`🧭 迷宮【${d.name||'名称不明'}】の最後に到達した階段から再開した。`);
	return true;
}
async function resumeLoadedGame(){
 if(returnFromExpiredQuest())return;
 if(gameState.equipmentOverflow?.length)setTimeout(()=>{if(gameState.equipmentOverflow?.length)openEquipmentWarehouse(gameState.equipmentOverflow[0].category);},300);
	evaluateMilestoneEvents('load');
	if(await resumeRescueOrInheritance())return;
	if(resumeDungeonFromSave()){
		if(gameState.storyDialogueResume)setTimeout(resumePendingSummonaDialogue,80);
		else if(gameState.dungeon?.summonaMissionState?.monolithObjectiveResolved&&['inspection','clearVoice','afterClear'].includes(gameState.dungeon.summonaMissionState.monolithFlowStage)){const d=gameState.dungeon;setTimeout(()=>resumeSummonaMissionMonolithFlow(d),80);}
		else if(gameState.dungeon?.summonaMissionState?.secondPhaseSceneActive)setTimeout(()=>showSummonaMissionSecondPhaseScene(gameState.dungeon),80);
		return;
	}
	if(resumeOnboardingStage())return;
	showScreen('screen-town');
	syncProgressionUnlockUI();
	scheduleProgressionUnlockNotice(420);
	log("📖 冒険の続きから再開した。");
	updatePartyPositions();
	updatePartyUI();
	refreshWordSelects();
	// クリア直後に再読込されても、未表示の町エピローグを失わない。
	setTimeout(()=>{
		if(resumePendingSummonaDialogue())return;
		if(typeof maybeStartPendingSummonaTownEpilogue==='function'&&maybeStartPendingSummonaTownEpilogue())return;
  if(maybeShowSummonaArchiveGift())return;
  if(maybeShowSummonaChapterResearchResult())return;
  if(maybeStartPendingSummonaChapterEndCard())return;
		maybeStartNextMilestoneEvent();
	},120);
}
function initializeStartupUI(){
	setupTownModalScreens();
	try{
		refreshWordSelects();
		setupJobSelects();
	}catch(wordDbError){
		console.error("WORD_DB の初期化中にエラーが発生しました:",wordDbError);
	}
}
const LOAD_RECOVERY_SKIP_ONCE_KEY='mugen-no-meikyu:skip-failed-save-once';
function getLoadErrorInfo(error){
	const stage=String(error?.loadStage||loadRecoveryContext?.stage||'unknown');
	const message=String(error?.message||'');
	const name=String(error?.name||'Error');
	let code='LOAD-UNKNOWN-01',summary='原因を特定できない読み込みエラーが発生しました。';
	if(message==='WEB_CRYPTO_UNAVAILABLE'){code='LOAD-CRYPTO-01';summary='暗号化された記録を読み込む機能を利用できません。';}
	else if(message==='CRYPTO_DB_OPEN_ERROR'){code='LOAD-KEYDB-01';summary='暗号鍵の保管領域を開けませんでした。';}
	else if(message==='SAVE_ENCRYPTION_FORMAT_ERROR'){code='LOAD-ENC-FORMAT-01';summary='暗号化された記録の形式を確認できませんでした。';}
	else if(message==='SAVE_FORMAT_ERROR'){code='LOAD-FORMAT-01';summary='記録のデータ形式を確認できませんでした。';}
	else if(message==='SAVE_PLAYER_MISSING'){code='LOAD-PLAYER-01';summary='探索者データを復元できませんでした。';}
	else if(stage==='storage'){code='LOAD-STORAGE-01';summary='端末の保存領域から記録を取得できませんでした。';}
	else if(stage==='decrypt'){code='LOAD-DECRYPT-01';summary='暗号化された記録の復号に失敗しました。';}
	else if(stage==='parse'){code='LOAD-JSON-01';summary='記録データの解析に失敗しました。';}
	else if(stage==='validate'){code='LOAD-FORMAT-01';summary='記録のデータ形式を確認できませんでした。';}
	else if(stage==='apply'){code='LOAD-APPLY-01';summary='記録は読み取れましたが、ゲーム状態の復元に失敗しました。';}
	return{code,summary,stage,technical:`${name}${message?`: ${message}`:''}`};
}
function showLoadRecoveryModal(info){
	const modal=document.getElementById('load-recovery-modal');if(!modal)return;
	const summary=document.getElementById('load-recovery-message');
	const code=document.getElementById('load-recovery-code');
	const detail=document.getElementById('load-recovery-detail');
	const status=document.getElementById('load-recovery-status');
	if(summary)summary.textContent=`冒険の記録を読み込めませんでした。記録は削除されていません。\n\n${info?.summary||'読み込み処理でエラーが発生しました。'}\n再試行、復旧用バックアップ、記録を残したまま新規開始、または記録の削除を選べます。`;
	if(code)code.textContent=info?.code||'LOAD-UNKNOWN-01';
	if(detail)detail.textContent=`段階: ${info?.stage||'unknown'} / 技術情報: ${info?.technical||'不明'}`;
	if(status)status.textContent='';
	modal.style.display='flex';modal.setAttribute('aria-hidden','false');
}
function hideLoadRecoveryModal(){const modal=document.getElementById('load-recovery-modal');if(modal){modal.style.display='none';modal.setAttribute('aria-hidden','true');}}
function retryFailedSaveLoad(){location.reload();}
function startFreshAfterLoadFailure(){
	try{sessionStorage.setItem(LOAD_RECOVERY_SKIP_ONCE_KEY,'1');location.reload();}
	catch(error){const status=document.getElementById('load-recovery-status');if(status)status.textContent='新規開始への切り替えに失敗しました。再試行またはバックアップを利用してください。';console.error('ロード失敗後の新規開始切替エラー:',error);}
}
function clearAdventureSaveOnly(){saveWriteEpoch++;localStorage.removeItem(SAVE_STORAGE_KEY);observedSaveText=null;saveConflict=false;}
async function deleteFailedSaveAndRestart(){
	hideLoadRecoveryModal();
	const ok=await showGameConfirm('読み込めなかった冒険の記録を削除しますか？\nゲーム設定やバックアップ制限の記録は残ります。\nこの操作は元に戻せません。',{title:'冒険の記録を削除',confirmText:'削除する'});
	if(!ok){showLoadRecoveryModal(openingStartup?.errorInfo);return;}
	try{clearAdventureSaveOnly();location.reload();}
	catch(error){console.error('読み込み失敗セーブの削除エラー:',error);showLoadRecoveryModal(openingStartup?.errorInfo);const status=document.getElementById('load-recovery-status');if(status)status.textContent='記録を削除できませんでした。復旧用バックアップを保存してから再試行してください。';}
}
function exportFailedLoadRecoveryBackup(){
	const status=document.getElementById('load-recovery-status');
	try{
		let stored=loadRecoveryContext?.storedText;
		if(stored==null){try{stored=localStorage.getItem(SAVE_STORAGE_KEY);}catch(_){stored=null;}}
		const info=openingStartup?.errorInfo||getLoadErrorInfo(openingStartup?.error);
		const packageData={
			type:'mugen-no-meikyu-load-recovery',version:1,createdAt:new Date().toISOString(),
			error:{code:info.code,summary:info.summary,stage:info.stage,technical:info.technical},
			environment:{protocol:location.protocol,userAgent:navigator.userAgent},
			save:{storageKey:SAVE_STORAGE_KEY,storedText:stored,decryptedText:loadRecoveryContext?.decryptedText??null}
		};
		const blob=new Blob([JSON.stringify(packageData,null,2)],{type:'application/json'});
		const url=URL.createObjectURL(blob),a=document.createElement('a');
		const stamp=new Date().toISOString().replace(/[:.]/g,'-');
		a.href=url;a.download=`mugen-load-recovery-${info.code}-${stamp}.mugen-recovery.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
		if(status)status.textContent='復旧用バックアップを保存しました。問い合わせ時はエラーコードと一緒に保管してください。';
	}catch(error){console.error('復旧用バックアップ保存エラー:',error);if(status)status.textContent='復旧用バックアップを保存できませんでした。エラーコードを控えてください。';}
}
async function copyLoadRecoveryErrorCode(){
	const code=document.getElementById('load-recovery-code')?.textContent?.trim()||'LOAD-UNKNOWN-01';
	const status=document.getElementById('load-recovery-status');
	try{await navigator.clipboard.writeText(code);if(status)status.textContent=`エラーコード ${code} をコピーしました。`;}
	catch(_){if(status)status.textContent=`エラーコード：${code}`;}
}

let openingSoundEnabled=true;
window.__mugenOpeningSoundConfirmed=false;
function getStoredOpeningSoundEnabled(){
	try{
		const raw=localStorage.getItem('mugen.bgm.enabled');
		return raw===null?true:raw!=='0';
	}catch(_){return true;}
}
function renderOpeningSoundChoice(){
	const on=document.getElementById('opening-sound-on'),off=document.getElementById('opening-sound-off');
	if(on){on.classList.toggle('selected',openingSoundEnabled);on.setAttribute('aria-pressed',String(openingSoundEnabled));}
	if(off){off.classList.toggle('selected',!openingSoundEnabled);off.setAttribute('aria-pressed',String(!openingSoundEnabled));}
}
function showOpeningSoundNotice(){
	if(openingDismissed)return;
	openingSoundEnabled=window.MugenBGM?.enabled ?? getStoredOpeningSoundEnabled();
	renderOpeningSoundChoice();
	const notice=document.getElementById('opening-sound-notice');
	if(notice)notice.classList.add('visible');
}
function setOpeningSoundChoice(value){
	openingSoundEnabled=!!value;
	renderOpeningSoundChoice();
}
function confirmOpeningSoundNotice(){
	window.__mugenOpeningSoundConfirmed=true;
	const notice=document.getElementById('opening-sound-notice');
	if(notice)notice.classList.remove('visible');
	if(window.MugenBGM){
		window.MugenBGM.setEnabled(openingSoundEnabled);
		window.MugenSE?.setEnabled(openingSoundEnabled);
		if(openingSoundEnabled)window.MugenBGM.sync();
	}else{
		try{localStorage.setItem('mugen.bgm.enabled',openingSoundEnabled?'1':'0');}catch(_){}
	}
	enterFromOpeningScreen();
}

let openingStartup=null;
let openingRequested=false;
let openingDismissed=false;
async function enterFromOpeningScreen(){
	if(openingDismissed)return;
	openingRequested=true;
	const prompt=document.getElementById('opening-prompt');
	if(!openingStartup){if(prompt)prompt.textContent='記録を読み込み中…';return;}
	openingDismissed=true;
	const opening=document.getElementById('opening-screen');
	if(opening)opening.classList.add('opening-exit');
	await new Promise(resolve=>setTimeout(resolve,520));
	if(openingStartup.error){
		ensureMetaSystems();
		showScreen('screen-make');
	}else if(openingStartup.loaded){
		const restoration=resumeLoadedGame().catch(error=>console.error('冒険の再開中にエラーが発生しました:',error));
		// ダイアログで待機する復帰経路でも、暗幕は開けて操作可能にする。
		await Promise.race([restoration,new Promise(resolve=>setTimeout(resolve,450))]);
	}else{
		showScreen('screen-make');
	}
	await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
	if(opening)opening.classList.add('opening-reveal');
	await new Promise(resolve=>setTimeout(resolve,680));
	if(opening){opening.hidden=true;opening.setAttribute('aria-hidden','true');}
	if(openingStartup.error)showLoadRecoveryModal(openingStartup.errorInfo);
}
async function init(){
	initializeStartupUI();
	let skipFailedSaveOnce=false;
	try{skipFailedSaveOnce=sessionStorage.getItem(LOAD_RECOVERY_SKIP_ONCE_KEY)==='1';if(skipFailedSaveOnce)sessionStorage.removeItem(LOAD_RECOVERY_SKIP_ONCE_KEY);}catch(_){skipFailedSaveOnce=false;}
	if(skipFailedSaveOnce){
  observedSaveText=localStorage.getItem(SAVE_STORAGE_KEY);
		ensureMetaSystems();
		openingStartup={loaded:false,recoveryBypass:true};
		if(openingRequested)enterFromOpeningScreen();
		return;
	}
	try{
		const saveData=await readSaveData();
		if(saveData){
			loadRecoveryContext.stage='apply';
			try{applyLoadedSaveData(saveData);}catch(error){error.loadStage='apply';throw error;}
			loadRecoveryContext.stage='done';
			clearLog();
			openingStartup={loaded:true};
		}else{
			ensureMetaSystems();
			openingStartup={loaded:false};
		}
	}catch(error){
		console.error('ロード時にエラーが発生しました:',error);
		openingStartup={error,errorInfo:getLoadErrorInfo(error)};
	}
	if(openingRequested)enterFromOpeningScreen();
}
