 first:{label:'初めて',jobs:['hero','knight','sword'],level:0,preferences:{deathMode:'safety',autoOpenChests:true,phantomWalls:false,formationWarning:true,battleTipsVisible:true,manualBattleSpeed:'slow',autoBattleSpeed:'standard',equipmentConfirmScope:'player',majorBattleManualOnly:true}},
 little:{label:'少しだけ',jobs:['hero','knight','sword','priest','scout','mage','monk','assassin'],level:1,preferences:{deathMode:'safety',autoOpenChests:false,phantomWalls:false,formationWarning:true,battleTipsVisible:true,manualBattleSpeed:'normal',autoBattleSpeed:'standard',equipmentConfirmScope:'player',majorBattleManualOnly:true}},
 used:{label:'慣れてる',jobs:PLAYER_JOB_KEYS.filter(key=>key!=='clown'),level:2,preferences:{deathMode:'roguelike',autoOpenChests:false,phantomWalls:true,formationWarning:true,battleTipsVisible:true,manualBattleSpeed:'normal',autoBattleSpeed:'fast',equipmentConfirmScope:'player',majorBattleManualOnly:true}},
