function updateCreationBackgroundPreview(){
	const preview=document.getElementById('creation-background-preview');if(!preview)return;
	const groups=[['origin','make-origin','生まれ'],['upbringing','make-upbringing','育ち'],['motive','make-motive','理由']];
	preview.innerHTML=groups.map(([g,id,label])=>{
		const e=getBackgroundEntry(g,document.getElementById(id)?.value);
		return `<div style="margin-bottom:3px;"><b style="color:#d4af37;">${label}：</b>${e?.text||''}</div>`;
	}).join('');
	if(typeof updateCreationJobPreview==='function')updateCreationJobPreview();
}
function resolveCreationBackground(group,elementId){
	const val=document.getElementById(elementId)?.value;
	return getBackgroundEntry(group,val)?.id||CHARACTER_BACKGROUNDS[group]?.[0]?.id||null;
}


function getJobBattleTipText(job){return JOB_BATTLE_TIPS[job]||JOB_CREATION_GUIDE[job]?.trait||'得意な札と装備を確認しましょう。';}

function getCreationPreviewHistory(){
	const selections=[['origin','make-origin'],['upbringing','make-upbringing'],['motive','make-motive']]
		.map(([group,id])=>[group,document.getElementById(id)?.value]);
	const mult={hp:1,atk:1,def:1,matk:1,mdef:1,spd:1};
	selections.forEach(([group,value])=>{
		const entry=getBackgroundEntry(group,value);
		Object.entries(entry?.mult||{}).forEach(([key,factor])=>{if(mult[key]!==undefined)mult[key]*=factor;});
	});
	return{mult};
}
function getCreationPreviewStats(jobKey){
	const job=JOB_TEMPLATES[jobKey]||JOB_TEMPLATES.hero;
	const ref=JOB_REFERENCE_EQUIPMENT[jobKey]||JOB_REFERENCE_EQUIPMENT.hero;
	const weapon=getEquipmentBaseByType('weapon',ref.weapon);
	const armor=getEquipmentBaseByType('armor',ref.armor);
	const{mult}=getCreationPreviewHistory();
	return{
		hp:Math.max(1,Math.round(job.hp*mult.hp)),
		atk:Math.max(1,Math.round(job.atk*mult.atk)+(weapon?.baseAtk||0)),
		def:Math.max(1,Math.round(job.def*mult.def)+(armor?.baseDef||0)),
		matk:Math.max(1,Math.round(job.matk*mult.matk)+(weapon?.baseMatk||0)),
		mdef:Math.max(1,Math.round(job.mdef*mult.mdef)+(armor?.baseMdef||0)),
		spd:Math.max(1,Math.round(job.spd*mult.spd))
	};
}
