function clearLog(){
	const logEl=document.getElementById('log');
	if(logEl)logEl.innerHTML='';
}
function escapeHtml(value){
	return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
function sanitizeGameHtml(value){
	const template=document.createElement('template');
	template.innerHTML=String(value??'');
	const allowedTags=new Set(['B','BR','SPAN','DIV','I','EM','STRONG']);
	const walk=node=>{
		[...node.childNodes].forEach(child=>{
			if(child.nodeType!==Node.ELEMENT_NODE)return;
			if(!allowedTags.has(child.tagName)){
				child.replaceWith(document.createTextNode(child.textContent||''));
				return;
			}
			[...child.attributes].forEach(attr=>{
				if(attr.name!=='style')child.removeAttribute(attr.name);
			});
			if(child.hasAttribute('style')){
				const safe=[];
				const color=child.style.color;
				const weight=child.style.fontWeight;
				const fontStyle=child.style.fontStyle;
				if(color)safe.push(`color:${color}`);
				if(weight)safe.push(`font-weight:${weight}`);
				if(fontStyle)safe.push(`font-style:${fontStyle}`);
				if(safe.length)child.setAttribute('style',safe.join(';'));
				else child.removeAttribute('style');
			}
			walk(child);
		});
	};
	walk(template.content);
	return template.innerHTML;
}
let battleVisualCapture=null;
let battleVisualPlaybackActive=false;
function appendGameLog(text){
	const logEl=document.getElementById('log');
	if(!logEl)return;
	logEl.insertAdjacentHTML('beforeend',`<div>${sanitizeGameHtml(resolvePlayerReferenceHtml(text))}</div>`);
	logEl.scrollTop=logEl.scrollHeight;
}
function log(text,type='log'){
	if(battleVisualCapture){battleVisualCapture.push({type,text:String(text??'')});return;}
	appendGameLog(text);
}
function logCombatDamage(target,amount,kind){
	const text=`  └ ${kind==='magicDamage'?'🔮':'⚔️'} ${escapeHtml(target.name)}に ${combatLogValue(amount,kind)}ダメージ！`;
	if(battleVisualCapture)battleVisualCapture.push({type:'damageLog',text,amount,kind});
	else appendGameLog(text);
}
function logCombatHeal(target,amount){
	const text=`  └ ✨ ${escapeHtml(target.name)}のHPが ${combatLogValue(amount,'heal')}回復！`;
	if(battleVisualCapture)battleVisualCapture.push({type:'healLog',text,target,amount});
	else appendGameLog(text);
}
function getCombatVisualKey(unit){
	if(!unit)return'';
	const partyIndex=(gameState?.party||[]).indexOf(unit);
	if(partyIndex>=0)return`party:${unit.id||partyIndex}`;
	const enemyIndex=(battleState?.enemies||[]).indexOf(unit);
	if(enemyIndex>=0)return`enemy:${unit.id||enemyIndex}`;
	return`${isPartyCombatant(unit)?'party':'enemy'}:${unit.id||unit.name||'unit'}`;
}
function queueBattleVisualEffect(unit,kind){
	if(!unit||!battleVisualCapture)return;
	battleVisualCapture.push({type:'visual',unit,kind});
}
function findCombatVisualElement(unit){
	const key=getCombatVisualKey(unit);
	if(!key)return null;
	return[...document.querySelectorAll('#party-area .char-card,#battle-enemy-names .enemy-status-gauge')].find(el=>el.dataset.combatKey===key)||null;
}
function battleVisualTiming(){
	if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)return{actor:0,effect:0,resultHold:0,actionGap:0};
	if(battleState?.isHordeEncounter)return{actor:30,effect:100,resultHold:30,actionGap:15};
	if(!battleState?.autoMode){
		const manual=normalizeManualBattleSpeed(gamePreferences.manualBattleSpeed);
		if(manual==='slow')return{actor:145,effect:300,resultHold:280,actionGap:80};
		if(manual==='fast')return{actor:55,effect:155,resultHold:70,actionGap:30};
		return{actor:85,effect:210,resultHold:120,actionGap:45};
	}
	const speed=normalizeAutoBattleSpeed(gamePreferences.autoBattleSpeed);
	if(speed==='fastest')return{actor:30,effect:100,resultHold:30,actionGap:15};
	if(speed==='fast')return{actor:60,effect:155,resultHold:70,actionGap:30};
	return{actor:85,effect:200,resultHold:110,actionGap:35};
}
function waitBattleVisual(ms){return new Promise(resolve=>setTimeout(resolve,Math.max(0,ms||0)));}
function getBattleVisualEffectDuration(kind,baseDuration){
	const base=Math.max(20,Number(baseDuration)||20);
	if(kind==='shield')return Math.round(base*1.28);
	if(kind==='heal'||kind==='shieldBreak')return Math.round(base*1.10);
	return base;
}
async function playBattleVisualEffect(unit,kind,duration){
	const actualDuration=getBattleVisualEffectDuration(kind,duration);
	const el=findCombatVisualElement(unit);
	if(!el)return;
	const classMap={actor:'bfx-actor',damage:'bfx-damage',magicDamage:'bfx-magic',heal:'bfx-heal',shield:'bfx-shield',shieldHit:'bfx-shield-hit',shieldBreak:'bfx-shield-break',poison:'bfx-poison'};
	const cls=classMap[kind]||'bfx-actor';
	el.classList.remove(cls);
	el.style.setProperty('--bfx-duration',`${actualDuration}ms`);
	void el.offsetWidth;
	el.classList.add(cls);
	await waitBattleVisual(actualDuration);
	el.classList.remove(cls);
	el.style.removeProperty('--bfx-duration');
}
async function playCapturedBattleAction(actor,events,{pulseActor=true,clearPrevious=true}={}){
	const timing=battleVisualTiming();
	if(clearPrevious)clearLog();
	if(pulseActor&&actor?.hp>0)await playBattleVisualEffect(actor,'actor',timing.actor);
	const damage=(events||[]).filter(event=>event.type==='damageLog');
	const heals=(events||[]).filter(event=>event.type==='healLog');
	const healByTarget=new Map();
	for(const heal of heals)healByTarget.set(heal.target,(healByTarget.get(heal.target)||0)+heal.amount);
	const coverEvents=(events||[]).filter(event=>event.type==='coverLog');
	let damageShown=false;
	let healShown=false,coverShown=false;
	const effects=new Map();
	for(const event of events||[]){
		if(event.type==='actionHeader'){
			appendGameLog(event.text);
			for(const cover of coverEvents)appendGameLog(cover.text);
			coverShown=true;
		}else if(event.type==='coverLog')continue;
		else if(event.type==='healLog'){
			if(healShown)continue;
			if(healByTarget.size>1){
				const total=[...healByTarget.values()].reduce((sum,amount)=>sum+amount,0);
				const average=Math.round(total/healByTarget.size*10)/10;
				appendGameLog(`  └ ✨ ${healByTarget.size}人のHPを平均 ${combatLogValue(average,'heal')}回復した！`);
			}else{
				const [target,total]=healByTarget.entries().next().value;
				appendGameLog(`  └ ✨ ${escapeHtml(target.name)}のHPが ${combatLogValue(total,'heal')}回復！`);
			}
			healShown=true;
		}else if(event.type==='damageLog'){
			if(damage.length>1){
				if(damageShown)continue;
				const total=damage.reduce((sum,hit)=>sum+hit.amount,0);
				const average=Math.round(total/damage.length*10)/10;
				appendGameLog(`  └ ⚔️🔮 ${damage.length}回命中・平均 ${combatLogValue(average,'damage')}ダメージ`);
				damageShown=true;
			}else appendGameLog(event.text);
		}else if(event.type==='log')appendGameLog(event.text);
		else if(event.type==='visual')effects.set(getCombatVisualKey(event.unit),event);
	}
	if(!coverShown)for(const cover of coverEvents)appendGameLog(cover.text);
	await Promise.all([...effects.values()].map(event=>playBattleVisualEffect(event.unit,event.kind,timing.effect)));
	await waitBattleVisual(timing.resultHold+timing.actionGap);
}
function setBattleVisualPlaybackActive(active){
	battleVisualPlaybackActive=!!active;
	document.body.classList.toggle('battle-action-playing',battleVisualPlaybackActive);
	if(gameState?.inBattle)updateBattleUI();
}
function updatePartyPositions(){
	// セーフティ帰還後も、宿屋で復帰するまでは戦闘不能者の隊列とカードを保持する。
	if(getDeathMode()==='safety'||(!gameState.dungeon&&normalizeDeathMode(gamePreferences.deathMode)==='safety')){
		const activeCount=Math.min(6,Math.max(1,Math.floor(Number(gameState.formationActiveCount)||6)));
		const frontCount=Math.min(5,Math.max(1,Math.floor(Number(gameState.formationFrontCount)||3)));
		gameState.party.forEach((char,index)=>{char.position=index<frontCount?'front':index<activeCount?'back':'reserve';});
		return;
	}
	let aliveCount=0;
	const configuredFront=Math.min(5,Math.max(1,Math.floor(Number(gameState.formationFrontCount)||3)));
	const activeCount=Math.min(6,Math.max(configuredFront,Math.floor(Number(gameState.formationActiveCount)||6)));
	const livingCount=gameState.party.filter(char=>char?.hp>0).length;
	const frontCount=Math.min(5,Math.max(configuredFront,Math.ceil(Math.min(livingCount,activeCount)/2)));
	gameState.formationFrontCount=frontCount;
	gameState.party.forEach((char)=>{
		if(char.hp>0){
			aliveCount++;
			if(aliveCount<=frontCount){
				char.position="front";
			}else if(aliveCount<=activeCount){
				char.position="back";
			}else{
				char.position="reserve";
			}
		}else{
			char.position="dead";
		}
	});
}

function getFirstAdventureGuideHtml(mode){
	const guide=FIRST_ADVENTURE_GUIDES[mode];
	return guide?escapeHtml(guide.text).replace(/\n/g,'<br>'):'';
}
let firstAdventureGuideOpening=false;
async function maybeShowFirstAdventureGuide(mode){
	const guide=FIRST_ADVENTURE_GUIDES[mode];
	if(!guide||gameState.firstAdventureGuidesSeen?.[mode])return true;
	if(firstAdventureGuideOpening)return false;
	firstAdventureGuideOpening=true;
	try{
		await showGameNotice(guide.text,{title:guide.title,confirmText:'出発する'});
		gameState.firstAdventureGuidesSeen??={quest:false,normal:false,mugen:false};
		gameState.firstAdventureGuidesSeen[mode]=true;
		saveGame();
		return true;
	}finally{firstAdventureGuideOpening=false;}
}

function showSummonaResearchList(){
 const detail=document.getElementById('summona-help-detail');if(!detail)return;
 toggleSummonaHelpBrowse(false);
 const state=ensureWordInvestigationState(),progress=ensureExplorationProgress();
 const rate=Math.round(progress.researchRate*10)/10,ready=rate>=100;
 detail.replaceChildren();
 const add=(tag,text,className='')=>{const el=document.createElement(tag);el.textContent=text;if(className)el.className=className;detail.append(el);return el;};
 add('h3','🔎 ワード調査');
 add('p','集めた資料から未知の言葉を探そう。解読したワードは、通常迷宮の組み合わせに使えるよ。');
 add('p',`次の記録を見つける資料：${rate}%`,'research-status');
 const meter=add('progress','');meter.max=100;meter.value=rate;meter.setAttribute('aria-label','未解読記録の発見進捗');meter.style.width='100%';
 const full=state.pending.length>=MAX_ACTIVE_WORD_INVESTIGATIONS;
 const action=add('button',full?'解読して調査枠を空けよう':ready?'資料を解析して、未解読の記録を得る':'資料を集めると解析できる（100％で解禁）');
 action.type='button';action.disabled=!ready||full;action.className='research-action';action.addEventListener('click',startSummonaResearchAnalysis);
 add('p',full?'調査枠がいっぱいだね。一件解読すると次へ進める。集まった資料は残るよ。':ready?'資料が揃ったね。上のボタンで新しい記録を取り出そう。':'通常迷宮で痕跡を調べよう。条件を満たして帰還すると、調査報告でも進捗が増えるよ。');
 add('h4',`解読中の記録 ${state.pending.length} / ${MAX_ACTIVE_WORD_INVESTIGATIONS}件`);
 for(const id of state.pending){
  const total=Array.from(getAreaWordPickById(id)?.word?.name||'').length,found=getWordFoundLetterCount(id);
  const button=add('button',`記録【${getWordCipherLabel(id)}】\n文字片 ${found} / ${total}文字${found>=total?' ・文字片が揃っています':' ・手掛かりを確認'}`,'research-action');
  button.type='button';button.addEventListener('click',()=>showSummonaWordPuzzle(id));
 }
 if(!state.pending.length)add('p','まだ解読中の記録はないね。まずは資料を100％まで集めて解析しよう。');
 if(state.backlog.length)add('p',`保管中の記録：${state.backlog.length}件。調査枠が空くと、順に解読中の一覧へ移るよ。`);
 const guide=add('details','');guide.className='tips-entry';guide.open=state.pending.length===0;
 const summary=document.createElement('summary');summary.textContent='調査の仕組み・進め方';guide.append(summary);
 const mugenGuide=hasProgressionUnlock('mugenDungeon')?'\n\n【夢幻迷宮での補助】\n夢幻迷宮へ入力した言葉に、未解読記録と一致する文字が含まれる場合も文字片を得られます。夢幻迷宮で集める調査ポイントと、帰還時に得るワード報酬は、この画面の未解読記録とは別の仕組みです。':'';
 const body=document.createElement('div');renderReadableTip(body,
  '【① 資料を集める】\n通常迷宮の痕跡を調べると、未解読記録の発見進捗が増えます。100％になったら、この画面で資料を解析しましょう。解析すると進捗を消費し、未解読の記録を1件得ます。\n\n【② 文字片を集める】\n解読中の記録がある状態で通常迷宮の痕跡を調べると、文字片を発見することがあります。\n\n【③ 元の言葉を解読する】\n記録を開き、順不同の文字片を手掛かりに元の言葉を入力します。文字片が全部揃う前でも、答えが分かれば照合できます。表記が完全に一致すれば、通常迷宮のワードとして解禁されます。\n\n【調査枠と次の記録】\n同時に解読できるのは5件。解読すると枠が空き、保管中の記録があれば順に取り出されます。新たな未解読記録が見つかることもあります。'+mugenGuide);
 guide.append(body);detail.scrollTop=0;
}
function startSummonaResearchAnalysis(){
	const progress=ensureExplorationProgress();
	if(progress.researchRate<100)return showSummonaResearchList();
	if(ensureWordInvestigationState().pending.length>=MAX_ACTIVE_WORD_INVESTIGATIONS)return showSummonaResearchList();
	const areaLevel=Math.max(1,Math.round(Number(progress.researchReadyAreaLevel)||Number(gameState.player?.level)||1));
	const seed=`SUMMONA_ANALYSIS::${areaLevel}::${gameState.adventureStats?.clears||0}`;
	const pick=pickResearchAreaWord(areaLevel,seed,true);
	const detail=document.getElementById('summona-help-detail');if(!detail)return;
	if(!pick){detail.innerHTML='<b style="color:#bfe8ff;">調査</b><div style="margin:9px 0;">今の到達範囲では、新しい記録が見つからなかった。資料の進捗は消費していないよ。未到達の第1語が残っているなら、その基準Lvの迷宮へ到達すると新しい調査対象になる。</div><button onclick="showSummonaResearchList()">調査記録に戻る</button>';return;}
	if(!stageUnresolvedWord(pick,'サモナとの解析',false))return showSummonaResearchList();
	progress.researchRate=0;delete progress.researchReadyAreaLevel;
	saveGame();
	detail.innerHTML=`<b style="color:#bfe8ff;">解析した記録</b><div style="line-height:1.8;margin:9px 0;">資料から未解読の記録【${getWordCipherLabel(pick.word.id)}】を見つけたよ。<br><br>次は通常迷宮の痕跡を調べて文字片を集めよう。記録を開けば、集まった文字を確認して解読できる。</div><button onclick="showSummonaResearchList()" style="width:100%;min-height:38px;">調査記録を見る</button>`;
}
function showSummonaWordPuzzle(id,message=''){
	if(!isWordPending(id))return showSummonaResearchList();
	const detail=document.getElementById('summona-help-detail');if(!detail)return;
	detail.innerHTML=`<b style="color:#bfe8ff;">記録【${getWordCipherLabel(id)}】の解析</b><div style="color:#d9c18b;margin:8px 0;line-height:1.8;">集めた文字片：${getScrambledLetterHtml(id)}</div><div style="font-size:11px;color:#aebec6;">文字片は順不同だよ。元の言葉を推理して入力しよう。文字片が揃う前でも照合できる。<br>ひらがな・カタカナ・漢字を含め、表記が完全に一致すると解読成功。間違えても資料や文字片は減らないよ。</div><input id="summona-word-answer" type="text" maxlength="20" autocomplete="off" aria-label="解読した言葉" placeholder="元の言葉を入力" style="box-sizing:border-box;width:100%;font-size:16px;margin:9px 0;padding:10px;background:#111;border:1px solid #638ca3;color:#fff;"><button onclick="submitSummonaWordPuzzle('${id}')" style="width:100%;min-height:38px;">照合する</button><div id="summona-word-feedback" style="margin-top:7px;color:#e8b99b;">${message}</div><button onclick="showSummonaResearchList()" style="margin-top:8px;">別の記録を見る</button>`;
	detail.scrollTop=0;
	const answer=document.getElementById('summona-word-answer');
	answer?.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.isComposing){event.preventDefault();submitSummonaWordPuzzle(id);}});
}
function submitSummonaWordPuzzle(id){
	const input=document.getElementById('summona-word-answer');
	const pick=getAreaWordPickById(id);
	if(!input||!pick||!isWordPending(id))return showSummonaResearchList();
	// 表記揺れを許さず、表示名との完全一致だけを解読成功とする。
	if(input.value!==pick.word.name){
		const feedback=document.getElementById('summona-word-feedback');if(feedback)feedback.textContent='まだ記録と一致しないね。文字の順番と表記を確かめよう。資料や文字片は減っていないよ。';return;
	}
	const name=acquireAreaWordSilently(pick);
	if(!name)return showSummonaResearchList();
	const next=pickResearchAreaWord(getNormalResearchReachLevel(1),`SUMMONA_DECODE::${id}::${(gameState.adventureStats?.clears||0)}`,true);
	if(next)stageUnresolvedWord(next,'解読の連鎖');
	saveGame();
	const detail=document.getElementById('summona-help-detail');
	if(detail)detail.innerHTML=`<b style="color:#bfe8ff;">解読成功</b><div style="line-height:1.7;margin:9px 0;">${escapeHtml(name)}。確かにこの言葉だ。通常迷宮のワードとして記録したよ。出発画面で組み合わせに選べる。${next?'<br>新たな未解読の記録も見つかった。':''}</div><button onclick="showSummonaResearchList()" style="width:100%;min-height:38px;">調査記録に戻る</button>`;
}
function summonaHelpButton(label,key){
	return `<button id="summona-help-item-${key}" onclick="showSummonaTopic('${key}')" aria-pressed="false" style="display:block;width:100%;min-height:37px;padding:5px 6px;margin:3px 0;text-align:left;font-size:11px;font-weight:normal;line-height:1.35;background:#23323a;border-color:#506c79;color:#e1edf2;">${label}</button>`;
}
function getReplayableTips(){
 const entries=[];
 const add=(title,text,group='探索')=>{entries.push({title,text,group});};
 add('Tips：町の施設',TOWN_FACILITIES_TIP_TEXT,'町とギルド');
 add(DUNGEON_SELECT_FIRST_GUIDE.title,DUNGEON_SELECT_FIRST_GUIDE.text);
 add('Tips：隊列と射程',FORMATION_RANGE_TIP_TEXT,'仲間');
 add('Tips：レガシー',LEGACY_TIP_TEXT,'探索');
 add('Tips：探索の基本',EXPLORATION_BASICS_TIP_TEXT);
 add('Tips：地形効果',TERRAIN_EFFECTS_TIP_TEXT);
 add('Tips：宝物部屋',TREASURE_ROOM_TIP_TEXT);
 if(hasProgressionUnlock('mugenDungeon'))add('Tips：夢幻の階層効果',MUGEN_FLOOR_CHOICE_TIP_TEXT);
 add('Tips：素材とジェム精製',MATERIAL_BUNDLE_TIP_TEXT);
 {
  for(const job of Object.keys(JOB_BATTLE_TIPS)){
   const guide=JOB_CREATION_GUIDE[job];
   entries.push({title:`Tips：【職業】 ${JOB_TEMPLATES[job]?.name||guide?.role||job}`,text:getJobBattleTipText(job),group:'戦闘'});
  }
 }
 entries.push({...COMBAT_TIPS[0],group:'戦闘'});
 add(COMBAT_TIPS[1].title,COMBAT_TIPS[1].text,'戦闘');
 add('Tips：依頼','依頼の「詳細」で目標・失敗条件・挑戦回数を確認できます。受注後、「出発」から依頼迷宮へ向かい、目標を達成して町まで戻りましょう。\n\n通常の報酬がある依頼は達成して帰還後に受け取れます。失敗・中断しても拾った品や素材は持ち帰れます。装備やデッキを整えて再挑戦しましょう。依頼の期限を過ぎると探索は中断され、町へ戻ります。記録からの再調査は戦利品を持ち帰れません。ローグライクの「回収依頼」は最深部で先代のデッキを見つけ、持ち帰った時にカード鞄へ戻ります。回収期限はなく、成功するまで再挑戦できます。保持されるのは最新の1件で、次のデッキロスト時に上書きされます。','町とギルド');
 add('Tips：仲間募集','応募者の職業・特徴・契約金を比べて仲間を選べます。条件を変えて再募集した場合、新しい応募者は次の探索から帰還したあとに届きます。','町とギルド');
 add('Tips：フレンドコード','フレンドコードを交換すると、ほかのプレイヤーの探索者を仲間として受け入れられます。自分のコードを共有することもできます。\n\n通常のフレンドコードの受け入れには💎10を消費します。\n\nギルドで共有用デッキを20枚ちょうどに設定してください。全キャラクターのデッキとカード鞄から、通常5スートの札を選べます。通常は3スートまで（道化師は5スート）、同スート12枚・同名4枚まで。選んだ札は移動・消費されません。','町とギルド');
 add('Tips：救助','操作中の探索者が倒れた場合、24時間有効な救難刻印が発行されます。\n\n救難刻印をほかのプレイヤーに共有してください。相手が救助依頼を達成して得た「救助成立の証印」を入力すると、探索者を救出できます。','町とギルド');
 for(const tip of Object.values(SHOP_FEATURE_TIPS))add(tip.title,tip.text,'店とデッキ');
 add('Tips：デッキの編集','【札を移す】\n仲間を選び、デッキ欄・カード鞄の札をタップ。「選択カードを移動」で出し入れします。長押しで効果を確認できます。\n\n【編成のルール】\n通常の冒険者は20～30枚。通常札は3スートまで、同じスート12枚まで、同名4枚までです。道化師はスートの種類数に制限がありません。レガシーは3種類、お守りは1人1枚。補給員は消耗品・報酬のみ0～60枚です。\nスート別枚数は拠点の上部で確認できます。レガシーも表示し、お守り・消耗品・荷物はこの枚数表示から除外します。\n\n【持ち込む札を決める】\n⚡は必要なマナ。マナを補う札と、マナを使う札を組み合わせましょう。\n\n【長く潜る準備】\n残り使用回数にも注目。使い切ると性能が大きく下がります。攻撃・守り・回復に加えて、帰るための札も用意しましょう。','店とデッキ');
 add('Tips：迷宮蒐録',ARCHIVE_TIP_TEXT,'記録');
 return entries;
}
function showSummonaTipsArchive(){
 const detail=document.getElementById('summona-help-detail');if(!detail)return;
 toggleSummonaHelpBrowse(false);
 document.querySelectorAll('#summona-help-menu [id^="summona-help-item-"]').forEach(button=>button.setAttribute('aria-pressed',String(button.id==='summona-help-item-tipsArchive')));
 detail.replaceChildren();
 const title=document.createElement('h3');title.textContent='Tips一覧';detail.append(title);
 const input=document.createElement('input');input.type='search';input.placeholder='例：回復、帰還、カード';input.setAttribute('aria-label','Tipsを検索');input.className='tips-search';detail.append(input);
 const count=document.createElement('p');count.setAttribute('aria-live','polite');count.className='tips-result-count';detail.append(count);
 const list=document.createElement('div');detail.append(list);
 const entries=getReplayableTips();
 const render=()=>{
  list.replaceChildren();
  const query=input.value.trim().normalize('NFKC').toLowerCase();
  const matches=entries.filter(tip=>(tip.title+' '+tip.text+' '+tip.group).normalize('NFKC').toLowerCase().includes(query));
  count.textContent=matches.length?`${matches.length}件・項目をタップして読む`:'見つかりません。別の言葉で試してください。';
  for(const group of [...new Set(matches.map(tip=>tip.group))]){
   const heading=document.createElement('h4');heading.textContent=group;list.append(heading);
   for(const tip of matches.filter(tip=>tip.group===group)){
    const item=document.createElement('details');item.className='tips-entry';
    const summary=document.createElement('summary');summary.textContent=tip.title.replace(/^Tips：/,'');item.append(summary);
    const body=document.createElement('div');renderReadableTip(body,tip.text);item.append(body);list.append(item);
   }
  }
 };
 input.addEventListener('input',render);render();detail.scrollTop=0;
}


function getSummonaSceneGuides(){
 const screen=document.querySelector('#control-area .screen.active');
 if(screen?.id==='screen-word')return customDungeonMode?['mugenIntro','dungeonKinds','difficulty']:['normalIntro','dungeonKinds','difficulty'];
 return SUMMONA_SCENE_GUIDES[screen?.id]||['town','dungeonKinds','battle'];
}
function toggleSummonaHelpBrowse(force){
 const modal=document.getElementById('summona-help-modal');
 const open=typeof force==='boolean'?force:!modal.classList.contains('help-browsing');
 modal.classList.toggle('help-browsing',open);
 const button=document.getElementById('summona-help-browse');
 button.setAttribute('aria-expanded',String(open));
 button.textContent=open?'✓ 本文に戻る':'☰ 話題を選ぶ';
}
function openSummonaHelp(topic=null,forced=false){
	const modal=document.getElementById('summona-help-modal');
	if(!modal)return;
	setFirstResearchTutorialChrome(false);
	modal.dataset.forced=forced?'1':'0';
	modal.style.display='flex';
	showSummonaHelpList();
	showSummonaTopic(topic||getSummonaSceneGuides()[0]);
	toggleSummonaHelpBrowse(false);
}
function closeSummonaHelp(){setFirstResearchTutorialChrome(false);hideModalById('summona-help-modal');}
function isProgressionHelpTopicVisible(key){
	if(key==='research')return hasProgressionUnlock('research');
	return key!=='mugenIntro'||hasProgressionUnlock('mugenDungeon');
}
function showSummonaHelpList(){
	const menu=document.getElementById('summona-help-menu');
	const detail=document.getElementById('summona-help-detail');
	if(!menu||!detail)return;
	menu.innerHTML=SUMMONA_HELP_MENU.map((group,index)=>{
		const topics=group.topics.filter(([,key])=>isProgressionHelpTopicVisible(key));
		if(!topics.length)return '';
		return `<button id="summona-help-category-${index}" onclick="toggleSummonaHelpCategory(${index})" aria-expanded="false" aria-controls="summona-help-items-${index}" style="display:block;width:100%;min-height:40px;padding:6px 5px;margin:3px 0;text-align:left;font-size:11px;line-height:1.35;background:#26343b;border-color:#638ca3;color:#e9d8a6;">${group.title} ▸</button>
		<div id="summona-help-items-${index}" style="display:none;padding:1px 0 5px 5px;">${topics.map(([label,key])=>summonaHelpButton(label,key)).join('')}</div>`;
	}).join('');
	const researchShortcut=hasProgressionUnlock('research')?`<button onclick="showSummonaTopic('research')" style="width:100%;min-height:40px;margin-top:10px;background:#294654;border-color:#7fb7d8;color:#dff3ff;">${ensureExplorationProgress().researchRate>=100?'🔎 持ち帰った資料を解析する':'🔎 調査について話す'}</button>`:'';
	detail.innerHTML=`<div style="color:#bfe8ff;font-size:13px;font-weight:bold;margin-bottom:12px;">やあ、${escapeHtml(getPlayerDisplayName())}。</div><div style="color:#e5edf1;line-height:1.8;">どうかしたのかい？<br><br>話題の一覧を開いて、聞きたい項目を選んでね。</div>${researchShortcut}`;
	menu.scrollTop=0;
	detail.scrollTop=0;
}
function toggleSummonaHelpCategory(index){
	const selected=document.getElementById(`summona-help-category-${index}`);
	if(!selected)return;
	const shouldOpen=selected.getAttribute('aria-expanded')!=='true';
	SUMMONA_HELP_MENU.forEach((group,i)=>{
		const button=document.getElementById(`summona-help-category-${i}`);
		const items=document.getElementById(`summona-help-items-${i}`);
		if(!button||!items)return;
		const open=i===index&&shouldOpen;
		button.setAttribute('aria-expanded',String(open));
		button.textContent=`${group.title} ${open?'▾':'▸'}`;
		button.style.background=open?'#375365':'#26343b';
		items.style.display=open?'block':'none';
	});
	if(shouldOpen){
		const detail=document.getElementById('summona-help-detail');
		if(detail){
			detail.innerHTML=`<div style="color:#bfe8ff;font-size:13px;font-weight:bold;margin-bottom:10px;">${SUMMONA_HELP_MENU[index].title}</div><div style="line-height:1.8;">話題の一覧から、聞きたい項目を選んでね。</div>`;
			detail.scrollTop=0;
		}
		document.querySelectorAll('#summona-help-menu [id^="summona-help-item-"]').forEach(button=>{
			button.setAttribute('aria-pressed','false');
			button.style.background='#23323a';
			button.style.borderColor='#506c79';
		});
	}
}
function showSummonaTopic(key){
 if(key==='research'&&!hasProgressionUnlock('research')){showSummonaHelpList();return;}
 const title=document.getElementById('summona-help-title');if(title)title.textContent=key==='research'?'🔎 ワード調査':'🔔 サモナに聞く';
 toggleSummonaHelpBrowse(false);
 if(key==='tipsArchive'){showSummonaTipsArchive();return;}
	let data=SUMMONA_HELP[key];
	if(key==='dungeonKinds'){
		data=hasProgressionUnlock('mugenDungeon')
			?{...data,text:'<b>通常迷宮</b>は四つのワードを組み合わせ、戦闘経験を積む場所。<b>夢幻迷宮</b>は好きな言葉を入口にして、まだ分からない迷宮そのものを調べる場所だよ。<br><br>どちらも命の扱いはゲーム設定の選択に従う。無理をせず、生きて記録を持ち帰ろう。'}
			:{...data,text:'<b>通常迷宮</b>は四つのワードを組み合わせ、戦闘経験を積む場所だよ。痕跡を調べながら、自分たちで帰る時を決めよう。<br><br>命の扱いはゲーム設定の選択に従う。まずは生きて町へ戻ることが大事だ。'};
	}
	const detail=document.getElementById('summona-help-detail');
	if(!data||!detail)return;
	const categoryIndex=SUMMONA_HELP_MENU.findIndex(group=>group.topics.some(([,topic])=>topic===key));
	if(categoryIndex>=0&&document.getElementById(`summona-help-category-${categoryIndex}`)?.getAttribute('aria-expanded')!=='true')toggleSummonaHelpCategory(categoryIndex);
	document.querySelectorAll('#summona-help-menu [id^="summona-help-item-"]').forEach(button=>{
		const active=button.id===`summona-help-item-${key}`;
		button.setAttribute('aria-pressed',String(active));
		button.style.background=active?'#355971':'#23323a';
		button.style.borderColor=active?'#a5d5f0':'#506c79';
	});
	if(key==='research'){showSummonaResearchList();return;}
	detail.innerHTML=`<div style="color:#bfe8ff;font-size:13px;font-weight:bold;margin-bottom:10px;">${escapeHtml(resolvePlayerReferenceText(data.title))}</div>
		<div style="color:#e5edf1;line-height:1.8;">${resolvePlayerReferenceHtml(data.text)}</div>
		${key==='deckLimits'?'<button onclick="closeSummonaHelp();openDeckRulesModal()" style="width:100%;min-height:40px;margin-top:14px;background:#332a18;border-color:#8b7437;">編成ルールを開く</button>':''}`;
 const guides=getSummonaSceneGuides().filter(topic=>topic!==key);
 if(guides.length){
  const heading=document.createElement('div');heading.textContent='この場面の案内';heading.style.cssText='color:#ead79a;margin-top:18px;font-weight:bold;';detail.append(heading);
  for(const topic of guides){
   const button=document.createElement('button');button.type='button';button.textContent=SUMMONA_HELP[topic]?.title||topic;
   button.style.cssText='display:block;width:100%;min-height:40px;margin:5px 0;padding:6px;text-align:left;background:#26343b;border-color:#638ca3;';
   button.addEventListener('click',()=>showSummonaTopic(topic));detail.append(button);
  }
 }
 const tips=document.createElement('button');tips.type='button';tips.textContent='📌 Tips一覧を見る';
 tips.style.cssText='display:block;width:100%;min-height:40px;margin:12px 0 0;background:#294654;border-color:#7fb7d8;';
 tips.addEventListener('click',showSummonaTipsArchive);detail.append(tips);
	detail.scrollTop=0;
}
let tutorialTipAfterClose=null;
function showTutorialTip(text,title='サモナ',options={}){
	const modal=document.getElementById('tutorial-tip-modal');
	const titleEl=document.getElementById('tutorial-tip-title');
	const textEl=document.getElementById('tutorial-tip-text');
	const buttonEl=document.getElementById('tutorial-tip-button');
	if(!modal||!textEl)return;
	tutorialTipAfterClose=typeof options.afterClose==='function'?options.afterClose:null;
	if(titleEl)titleEl.textContent=resolvePlayerReferenceText(title);
	textEl.innerHTML=resolvePlayerReferenceHtml(text);
	textEl.scrollTop=0;
	const tipCard=document.getElementById('tutorial-tip-card');if(tipCard)tipCard.scrollTop=0;
	if(buttonEl)buttonEl.textContent=options.buttonLabel||'続ける';
	modal.style.display='flex';
}
function closeTutorialTip(){
	const modal=document.getElementById('tutorial-tip-modal');
	if(modal)modal.style.display='none';
	const afterClose=tutorialTipAfterClose;
	tutorialTipAfterClose=null;
	if(afterClose)setTimeout(afterClose,0);
}
function showTutorialSequence(steps,onComplete=null){
	const queue=(Array.isArray(steps)?steps:[]).map(step=>
		typeof step==='string'?{text:step}:{...step}
	);
	if(!queue.length){
		if(typeof onComplete==='function')onComplete();
		return;
	}
	const total=queue.length;
	const showNext=()=>{
		const step=queue.shift();
		if(!step){
			if(typeof onComplete==='function')onComplete();
			return;
		}
		const isLast=queue.length===0;
		showTutorialTip(step.text||'',`${step.title||'サモナ'}${total>1?'　'+(total-queue.length)+' / '+total:''}`,{
			buttonLabel:step.buttonLabel||(isLast?'わかった':'次へ'),
			afterClose:showNext
		});
	};
	showNext();
}

let scheduledSummonaGuideTimer=null;
function cancelScheduledSummonaGuide(){
	if(scheduledSummonaGuideTimer!==null){
		clearTimeout(scheduledSummonaGuideTimer);
		scheduledSummonaGuideTimer=null;
	}
}
function scheduleSummonaGuide(key,delay=80,expectedStage=null,expectedScreen=null){
	cancelScheduledSummonaGuide();
	scheduledSummonaGuideTimer=setTimeout(()=>{
		scheduledSummonaGuideTimer=null;
		if(expectedStage!==null&&gameState?.onboardingStage!==expectedStage)return;
		if(expectedScreen!==null&&document.querySelector('.screen.active')?.id!==expectedScreen)return;
		showSummonaGuide(key);
	},delay);
}
function showSummonaGuide(key){
	cancelScheduledSummonaGuide();
	const steps=SUMMONA_GUIDE[key];
	if(!steps)return;
	let onComplete=null;
	if(key==='potionUse')onComplete=finishPotionExplanationAndReturnTown;
	else if(key==='dungeonKinds')onComplete=finishFirstDungeonLesson;
	else if(key==='treasureComplete')onComplete=completeTutorialAndReturnTown;
	else if(key==='beforeBoss')onComplete=startBossBattle;
	const normalized=steps.map((step,index)=>{
		const item=typeof step==='string'?{text:step}:{...step};
		if(item.dynamic==='starterEquipment'){
			const player=gameState?.player;
			const ref=JOB_REFERENCE_EQUIPMENT[player?.jobType]||{weapon:null,armor:null};
			const names=[ref.weapon,ref.armor].filter(Boolean);
			item.text=names.length
				?`君が倒れていた場所も見てきた。元の武器も防具も<b>大破していて、とても使える状態じゃない</b>。<br><br>代わりに、この迷宮で拾った<b>［${names.join('］と［')}］</b>を持ってきた。上等な品じゃないけれど、<b>ここから脱出するまで</b>なら十分役に立つはずだ。使って。`
				:`君が倒れていた場所も見てきた。元の装備は<b>大破していて使えない</b>。……でも、君は武闘家だね。拾い物を無理に持たせるより、その身ひとつの方が動きやすそうだ。<br><br>装備は任せられないぶん、<b>脱出までは私が隣で援護する</b>よ。`;
			delete item.dynamic;
		}
		if(item.dynamic==='starterJobGift'){
			const names=getStarterJobGiftNames(gameState?.player?.jobType).slice(0,3);
			const jobName=JOB_TEMPLATES[gameState?.player?.jobType]?.name||gameState?.player?.job||'君';
			const escapeName=getCardMaster('m_escape')?.name||'逃走',featherName=getCardMaster('c_return_feather')?.name||'帰還の羽';
			item.text=`そうだ、<b>これもあげよう。</b> ${jobName}の戦い方を広げられそうな札を3枚選んでおいた。加えて、危険な時に退ける<b>［${escapeName}］</b>も1枚。今の基本札より少し癖があるから、カード鞄に入れておくよ。<br><br><b>［${names.join('］　［')}］</b><br><br>それと<b>［${featherName}］</b>を1枚。戦闘中でなければ迷宮から町へ戻れる。無理をしないためのお守り代わりに持っておくといい。`;
			delete item.dynamic;
		}
		if(typeof item.text==='string')item.text=item.text.replaceAll('《サモナ》のお守り',`《サモナ》の${getCardMaster(REVIVAL_CHARM_MASTER_ID)?.name||'お守り'}`);
		if(index===steps.length-1&&!item.buttonLabel&&onComplete){
			item.buttonLabel=key==='potionUse'?'拠点へ'
				:key==='treasureComplete'?'町へ戻る'
				:'わかった';
		}
		return item;
	});
	showTutorialSequence(normalized,onComplete);
}
function isTutorialFirstBattle(){
	return!!(gameState?.tutorialState?.active&&battleState?.tutorialFirstBattle);
}
function isPlayerSteamer(){
	return isSteamerCharacter(gameState?.player);
}
function buildTutorialFirstHand(){
	const job=gameState?.player?.jobType||'hero';
	let ids;
	if(job==='steamer'){
		ids=['m_quick_slash','m_guard','m_spark','m_focus','m_balanced_guard'];
	}else if(job==='clown'){
		ids=['m_quick_slash','m_spark','m_guard','m_minor_heal','m_focus'];
	}else if(['mage','priest','alchemist'].includes(job)){
		ids=['m_spark','m_magic_shot','m_balanced_magic','m_guard','m_focus'];
	}else{
		ids=['m_quick_slash','m_slash','m_balanced_slash','m_guard','m_focus'];
	}
	return ids.map(id=>createCardInstance(id,{rarity:'N',applyCollection:false})).filter(Boolean);
}
function isTutorialCargoLessonBattle(){
	return!!(gameState?.tutorialState?.active&&battleState?.tutorialCargoLessonBattle);
}
function createTutorialPracticeCargoCard(){
	const gemLesson=isMageCharacter(gameState?.player)||isAlchemistCharacter(gameState?.player)||isSteamerCharacter(gameState?.player);
	if(gemLesson){
		return createGeneratedCard('tutorial_gem',{
			masterId:SHOP_GEM_MASTER_ID,suit:'📦',name:'サモナの試験ジェム',rarity:'N',dropRarity:'N',cost:99,
			category:'reward',type:'material_boost',effect:'shop_gem',materialCard:true,shopGem:true,dungeonGem:true,
			sellPrice:DUNGEON_GEM_BASE_VALUE,gemUnits:DUNGEON_GEM_BASE_VALUE,tutorialPracticeCargo:true,battleOnly:true,noGrowth:true,
			tutorialGiftFromSummona:true
		},{instancePrefix:'tutorial_gem'});
	}
	return createGeneratedCard('tutorial_cargo',{
		masterId:'tutorial_cargo_sample',suit:'📦',name:'サモナの試験素材',rarity:'N',dropRarity:'N',cost:0,
		category:'reward',type:'material_boost',materialCard:true,sellPrice:10,tutorialPracticeCargo:true,battleOnly:true,noGrowth:true,
		tutorialGiftFromSummona:true
	},{instancePrefix:'tutorial_cargo'});
}
function ensureTutorialCargoInBattleDeck(selectedDeck){
	if(!isTutorialCargoLessonBattle())return selectedDeck;
	const cargo=createTutorialPracticeCargoCard();
	if(selectedDeck.includes(cargo))return selectedDeck;
	const next=[...selectedDeck];
	if(next.length<20)next.push(cargo);
	else{
		let replaceIndex=next.findIndex(card=>card?.category!=='reward');
		if(replaceIndex<0)replaceIndex=next.length-1;
		next[replaceIndex]=cargo;
	}
	return next;
}
function forceTutorialCargoIntoOpeningHand(){
	if(!isTutorialCargoLessonBattle())return false;
	if((battleState.hand||[]).some(card=>card?.tutorialPracticeCargo))return true;
	let index=(battleState.drawPile||[]).findIndex(card=>card?.tutorialPracticeCargo);
	if(index<0)index=(battleState.drawPile||[]).findIndex(card=>card?.category==='reward');
	if(index<0)return false;
	const[cargo]=battleState.drawPile.splice(index,1);
	if(!cargo)return false;
	if(battleState.hand.length>=5){
		const returned=battleState.hand.pop();
		if(returned)battleState.drawPile.push(returned);
	}
	battleState.hand.push(cargo);
	battleState.drawPile=shuffle(battleState.drawPile);
	return true;
}
function getTutorialJobSpecialCardInfo(char=gameState?.player){
	if(isSteamerCharacter(char)){
		return{
			key:'steam_engine',
			name:'蒸気機関',
			matches:card=>isSteamFuelCard(card),
			text:'ところで……<b>蒸機師には戦闘専用の［蒸気機関］</b>がある。所持デッキ20枚とは別に<b>1ループ2枚</b>加わり、デッキが一巡するか仕切り直すと2枚に戻る。ブーストする時は<b>⚔️物理攻撃＋［蒸気機関］＋ジェム</b>の3枚をそろえるんだ。第2戦では、その3枚を最初から見せるよ。'
		};
	}
	if(isAlchemistCharacter(char)){
		return{
			key:'alchemist_catalyst',
			name:'触媒',
			matches:card=>isAlchemistCatalystCard(card),
			text:'ところで……<b>錬金術師には戦闘専用の［触媒］</b>がある。所持デッキ20枚とは別に<b>1ループ2枚</b>加わり、デッキが一巡するか仕切り直すと2枚に戻る。素材やジェムを使う時は、<b>🔮魔法攻撃＋［触媒］＋素材</b>を3枚そろえる。第2戦では試験ジェムで試してみよう。'
		};
	}
	if(isMageCharacter(char)){
		return{
			key:'mage_gem',
			name:'ジェム',
			matches:card=>isGemCard(card),
			text:'この<b>ジェム</b>は魔術師にも使い道がある。ほかの札と一緒に混ぜると、<b>レアリティに応じてそのコンボの消費マナが軽くなる</b>。使ったジェムは砕ける。第2戦では試験ジェムを混ぜて、予定欄のマナが変わるのを見てみよう。'
		};
	}
	return null;
}
function forceTutorialJobSpecialIntoOpeningHand(){
	if(!isTutorialCargoLessonBattle())return false;
	const info=getTutorialJobSpecialCardInfo(gameState?.player);
	if(!info)return false;
	battleState.hand||=[];
	battleState.drawPile||=[];
	if(battleState.hand.some(info.matches))return true;
	const index=battleState.drawPile.findIndex(info.matches);
	if(index<0)return false;
	const[special]=battleState.drawPile.splice(index,1);
	if(!special)return false;
	if(battleState.hand.length>=5){
		let replaceIndex=-1;
		for(let i=battleState.hand.length-1;i>=0;i--){
			const card=battleState.hand[i];
			if(card?.category==='reward')continue;
			const currentInfo=getTutorialJobSpecialCardInfo(gameState?.player);
			if(currentInfo?.matches(card))continue;
			replaceIndex=i;
			break;
		}
		if(replaceIndex<0)replaceIndex=battleState.hand.length-1;
		const[returned]=battleState.hand.splice(replaceIndex,1,special);
		if(returned)battleState.drawPile.push(returned);
	}else{
		battleState.hand.push(special);
	}
	battleState.drawPile=shuffle(battleState.drawPile);
	return true;
}
function getTutorialOpeningAttackRule(char=gameState?.player){
	const isAttack=card=>!!card&&comboHasAttack([card])&&!isBattleCardForbiddenFor(char,card);
	if(isAlchemistCharacter(char)){
		return{
			matches:card=>isAttack(card)&&isPrimaryMagicalAttackCard(card)&&getExecutedManaCost([card])===0&&Math.max(0,Number(card.manaGen)||0)===0,
			fallbackId:'m_balanced_magic'
		};
	}
	if(isSteamerCharacter(char)){
		return{
			matches:card=>isAttack(card)&&card.suit==='⚔️',
			fallbackId:'m_quick_slash'
		};
	}
	if(isMageCharacter(char)){
		return{
			matches:card=>isAttack(card)&&isPrimaryMagicalAttackCard(card)&&getExecutedManaCost([card])>0,
			fallbackId:'m_fire_wave'
		};
	}
	const magical=['mage','priest','alchemist'].includes(char?.jobType);
	return{
		matches:isAttack,
		fallbackId:magical?'m_spark':'m_quick_slash'
	};
}
function forceTutorialAttackIntoOpeningHand(){
	if(!isTutorialCargoLessonBattle())return false;
	battleState.hand||=[];
	battleState.drawPile||=[];
	const rule=getTutorialOpeningAttackRule(gameState?.player);
	if(battleState.hand.some(rule.matches))return true;
	let attack=null;
	const index=battleState.drawPile.findIndex(rule.matches);
	if(index>=0)[attack]=battleState.drawPile.splice(index,1);
	if(!attack&&rule.fallbackId){
		attack=createCardInstance(rule.fallbackId,{rarity:'N',applyCollection:false});
		if(attack){
			attack.tutorialTemporary=true;
			attack.tutorialOpeningAttack=true;
		}
	}
	if(!attack)return false;
	if(battleState.hand.length>=5){
		const special=getTutorialJobSpecialCardInfo(gameState?.player);
		let replaceIndex=-1;
		for(let i=battleState.hand.length-1;i>=0;i--){
			const card=battleState.hand[i];
			if(card?.category==='reward')continue;
			if(special?.matches(card))continue;
			if(rule.matches(card))continue;
			replaceIndex=i;
			break;
		}
		if(replaceIndex<0)replaceIndex=battleState.hand.length-1;
		const[returned]=battleState.hand.splice(replaceIndex,1,attack);
		if(returned&&!attack.tutorialTemporary)battleState.drawPile.push(returned);
	}else{
		battleState.hand.push(attack);
	}
	battleState.drawPile=shuffle(battleState.drawPile);
	return true;
}
function getTutorialBossResonanceMasterIds(suit){
	if(suit==='🔮')return['m_spark','m_magic_shot','m_spark'];
	if(suit==='⚔️')return['m_quick_slash','m_slash','m_quick_slash'];
	return[];
}
function isTutorialBossBattleActive(){
	const d=gameState?.dungeon;
	return!!(gameState?.tutorialState?.active&&d?.isTutorial&&d?.isBossBattle&&gameState?.inBattle);
}
function forceTutorialBossSteamerHand(){
	if(!isTutorialBossBattleActive()||!isSteamerCharacter(gameState?.player))return false;
	battleState.hand||=[];
	battleState.drawPile||=[];
	battleState.discardPile||=[];
	const pullFrom=(zone,match)=>{
		const index=zone.findIndex(match);
		return index>=0?zone.splice(index,1)[0]:null;
	};
	const oldHand=[...battleState.hand];
	battleState.hand=[];
	let attack=pullFrom(oldHand,card=>card?.suit==='⚔️'&&isPrimaryPhysicalAttackCard(card)&&!isBattleMaterialCard(card));
	if(!attack)attack=pullFrom(battleState.drawPile,card=>card?.suit==='⚔️'&&isPrimaryPhysicalAttackCard(card)&&!isBattleMaterialCard(card));
	if(!attack)attack=createCardInstance('m_balanced_slash',{rarity:'N',applyCollection:false});
	if(attack&&!attack.instanceId)attack.tutorialTemporary=true;
	let engine=pullFrom(oldHand,isSteamFuelCard);
	if(!engine)engine=pullFrom(battleState.drawPile,isSteamFuelCard);
	if(!engine)engine=createSteamFuelCard(90);
	const gem=createGeneratedCard('tutorial_boss_gem',{
		masterId:SHOP_GEM_MASTER_ID,suit:'📦',name:'サモナの試験ジェム',rarity:'N',dropRarity:'N',cost:99,
		category:'reward',type:'material_boost',effect:'shop_gem',materialCard:true,shopGem:true,dungeonGem:true,
		sellPrice:DUNGEON_GEM_BASE_VALUE,gemUnits:DUNGEON_GEM_BASE_VALUE,battleOnly:true,noGrowth:true,
		tutorialTemporary:true,tutorialBossCard:true
	},{instancePrefix:'tutorial_boss_gem'});
	const required=[attack,engine,gem].filter(Boolean);
	if(required.length<3){
		battleState.hand=oldHand;
		return false;
	}
	const keep=oldHand.filter(card=>card!==attack&&card!==engine).slice(0,2);
	const keepSet=new Set(keep);
	oldHand.forEach(card=>{
		if(card===attack||card===engine||keepSet.has(card))return;
		battleState.drawPile.push(card);
	});
	battleState.hand=[...required,...keep].slice(0,5);
	battleState.drawPile=shuffle(battleState.drawPile);
	battleState.selectedIndices=[];
	return true;
}
function forceTutorialBossSuitHand(suit){
	if(!isTutorialBossBattleActive())return false;
	const wanted=getTutorialBossResonanceMasterIds(suit);
	if(!wanted.length)return false;
	battleState.hand||=[];
	battleState.drawPile||=[];
	battleState.discardPile||=[];
	const isTargetSuit=card=>card?.suit===suit&&!isDeckRuleExemptCard(card);
	const existing=battleState.hand.filter(isTargetSuit).length;
	let need=Math.max(0,3-existing);
	if(need<=0){
		battleState.selectedIndices=[];
		return true;
	}
	const additions=[];
	for(let i=battleState.drawPile.length-1;i>=0&&additions.length<need;i--){
		if(!isTargetSuit(battleState.drawPile[i]))continue;
		additions.push(...battleState.drawPile.splice(i,1));
	}
	let serial=0;
	while(additions.length<need){
		const id=wanted[serial%wanted.length];
		const card=createCardInstance(id,{rarity:'N',applyCollection:false});
		if(!card)break;
		card.tutorialTemporary=true;
		card.tutorialResonanceSuit=suit;
		additions.push(card);
		serial++;
	}
	if(additions.length<need)return false;
	additions.forEach(card=>{
		let replaceIndex=-1;
		for(let i=battleState.hand.length-1;i>=0;i--){
			if(!isTargetSuit(battleState.hand[i])){replaceIndex=i;break;}
		}
		if(replaceIndex>=0){
			const[returned]=battleState.hand.splice(replaceIndex,1,card);
			if(returned)battleState.drawPile.push(returned);
		}else{
			battleState.hand.unshift(card);
		}
	});
	battleState.drawPile=shuffle(battleState.drawPile);
	battleState.selectedIndices=[];
	return battleState.hand.filter(isTargetSuit).length>=3;
}
function maybeShowTutorialCargoDrawLesson(){
	const ts=gameState?.tutorialState;
	if(!ts?.active||ts.cargoLessonSeen||!isTutorialCargoLessonBattle())return;
	const cargo=(battleState.hand||[]).find(card=>card?.tutorialPracticeCargo)
		||(battleState.hand||[]).find(card=>card?.category==='reward');
	if(!cargo)return;
	ts.cargoLessonSeen=true;
	saveGame();
	const player=gameState.player;
	const cargoRole=isAlchemistCharacter(player)
		?'君は錬金術師だから、この<b>試験ジェム</b>を錬金素材として使える。<b>🔮魔法攻撃＋触媒＋ジェム</b>をそろえてみよう。'
		:isMageCharacter(player)
			?'君は魔術師だから、この<b>試験ジェム</b>をほかの札に混ぜると消費マナを軽くできる。予定欄のマナ表示を見比べてみよう。'
			:isSteamerCharacter(player)
				?'君は蒸機師だから、この<b>試験ジェム</b>をブーストに使える。<b>⚔️物理攻撃＋蒸気機関＋ジェム</b>をそろえてみよう。'
				:'君の職では、この📦荷物は戦闘中には使えない。手札を1枠ふさぐオジャマ札になる。';
	const lessonItemText=isGemCard(cargo)
		?`<b>${Math.max(0,Math.floor(Number(cargo.sellPrice)||DUNGEON_GEM_BASE_VALUE))}G相当の試験ジェム</b>`
		:'<b>10G相当の試験素材</b>';
	const steps=[
		{
			title:'📦 荷物圧迫',
			text:`おや、<b>［${cargo.name||'荷物'}］</b>が手札に混ざったね。これは説明用に私から渡した${lessonItemText}だよ。通常は迷宮で拾った素材や報酬も、持ち歩けるデッキ枚数を使う。戦闘ではその所持札から<b>20枚だけ</b>が選ばれるから、荷物が増えるほど手札へ混ざりやすくなり、使いたかった札が戦闘デッキから外れることもある。<br><br>${cargoRole}`
		}
	];
	const special=getTutorialJobSpecialCardInfo(gameState.player);
	if(special){
		steps.push({
			title:'ところで……',
			text:special.text
		});
	}
	steps.push({
		title:'♻️ 仕切り直し',
		text:'こういう手札が苦しい時は、左下の<b>「仕切り直し」</b>が使える。手札・山札・捨て札をまとめて混ぜ直し、新しい手札を引き直すんだ。<br><br>ただし、<b>主人公はそのターンの行動を放棄する</b>。荷物そのものが消えるわけでもないから、また引くこともある。必要な時に切る手段として覚えておくといい。'
	});
	showTutorialSequence(steps);
}
function maybeShowTutorialBattleIntro(){
	if(!isTutorialFirstBattle()||battleState.tutorialIntroShown)return;
	battleState.tutorialIntroShown=true;
	if(gameState.tutorialState)gameState.tutorialState.battleLessonSeen=true;
	const job=gameState?.player?.jobType||'hero';
	if(job==='clown'){
		showTutorialTip('まずは<b>1枚</b>選んでみよう。道化師は少し変わっていて、あとから<b>違う印のカード</b>もつなげられるよ。');
	}else if(job==='steamer'){
		showTutorialTip('まずは<b>⚔️の攻撃札を1枚</b>選んでみよう。蒸機師は通常の札を少ない枚数で扱う職業だよ。');
	}else if(['mage','priest','alchemist'].includes(job)){
		showTutorialTip('まずは<b>🔮の攻撃札を1枚</b>選んでみよう。光っている同じ印の札なら、このあと続けてつなげられる。');
	}else{
		showTutorialTip('まずは<b>⚔️の攻撃札を1枚</b>選んでみよう。光っている同じ印の札なら、このあと続けてつなげられる。');
	}
}
function maybeShowTutorialCardSelectionTip(){
	if(!isTutorialFirstBattle())return;
	const count=battleState.selectedIndices.length;
	const isJester=isJesterCharacter(gameState.player);
	if(count===1&&!battleState.tutorialFirstCardTipShown){
		battleState.tutorialFirstCardTipShown=true;
		if(isPlayerSteamer()){
			showTutorialTip('そう、その調子。<b>蒸機師は通常札を一度に1枚</b>だけ使う職業だ。このまま「実行」を押してみよう。特殊なブーストは、もう少し先で実際に試そう。');
		}else if(isJester){
			showTutorialTip('いいね。道化師の札遊びはここからだ。次は今のカードと<b>違うスート</b>の、光っているカードを1枚選んでみよう。');
		}else{
			showTutorialTip('そう、その調子。まだ<b>光っているカード</b>があるなら、もう1枚選んでみよう。');
		}
		return;
	}
	if(count>=2&&!battleState.tutorialComboTipShown){
		battleState.tutorialComboTipShown=true;
		if(gameState.tutorialState)gameState.tutorialState.comboLessonSeen=true;
		if(isJester){
			showTutorialTip('その調子。道化師は<b>コスト0の札なら違うスート同士でもつなげられる</b>。異なる3種類がそろうと、それぞれの印が強く反応する。もう一つ、まだ使っていないスートを選んでみよう。');
		}else{
			showTutorialTip('いいね。同時に選べるのは、基本的に<b>同じスート</b>だよ。🌟はほかのスートにつなげられる。準備できたら、もう1枚つなげられるか試してみよう。');
		}
		return;
	}
	if(count>=3&&battleState.tutorialComboTipShown){
		const selectedCards=battleState.selectedIndices.map(i=>battleState.hand[i]).filter(Boolean);
		if(isJester){
			if(getFoolArcanaBonuses(gameState.player,selectedCards).size>=3&&!gameState.tutorialState?.foolArcanaLessonSeen){
				gameState.tutorialState.foolArcanaLessonSeen=true;
				saveGame();
				showTutorialTip('異なる<b>3種類のスート</b>がそろったね。使った札の印が互いに強く反応している。道化師は「同じ札をそろえる」より、<b>違う札をどう組み合わせるか</b>を楽しむ職業なんだ。','🃏 3つの印');
				return;
			}
			if(!gameState.tutorialState?.foolArcanaNudgeSeen){
				gameState.tutorialState.foolArcanaNudgeSeen=true;
				saveGame();
				showTutorialTip('3枚つながったけれど、道化師らしい反応にはなっていないね。<b>異なる3種類のスート</b>をそろえてみよう。いったん同じスートの札を外して、別の印へ入れ替えてみて。','🃏 道化師のコンボ');
			}
			return;
		}
		if(!gameState.tutorialState?.suitResonanceLessonSeen&&getTripleSuitBonuses(selectedCards).size>0){
			gameState.tutorialState.suitResonanceLessonSeen=true;
			saveGame();
			showTutorialTip('同じスートが<b>3枚そろった</b>ね。⚔️なら物理、🔮なら魔法、🛡️なら守り、✨なら回復、🌟なら行動順に、その印らしい効果が強くなる。予定欄の色が変わったら成立の合図だよ。','🔗 3枚の印');
		}
	}
}
