function getDeckSuitCountText(deck){
 const counts=new Map();
 for(const card of deck||[]){
  if(!card||isDeckRuleExemptCard(card)||isRevivalCharm(card))continue;
  const suit=card.category==='legacy'?'🏅':card.suit;
  if(suit)counts.set(suit,(counts.get(suit)||0)+1);
 }
 return [...counts].sort(([a],[b])=>(SUIT_ORDER[a]||99)-(SUIT_ORDER[b]||99))
  .map(([suit,count])=>`${suit}${count}`).join('　');
}
