function transferSelectedStorageCards(){
	const charIdx=parseInt(document.getElementById('storage-char-select')?.value)||0;
	const targetChar=gameState.party[charIdx]||gameState.player;
	if(targetChar?.friendDeckLocked){setStorageEditMessage('この冒険者のデッキは変更できません');return;}
	const deckList=getCharacterDeck(targetChar);
	const actualBag=gameState.cardStorage||(gameState.cardStorage=[]);
	const bagView=actualBag;
	const outgoing=deckList.filter(card=>storageDeckSelection.has(getStorageCardKey(card)));
	const incomingSource=bagView.filter(card=>storageBagSelection.has(getStorageCardKey(card)));
	const incoming=incomingSource;
	if(!outgoing.length&&!incoming.length)return;
	if(gameState.onboardingStage==='potionStorage'){
		if(outgoing.length||incoming.length!==1||incoming[0]?.tutorialOnboardingPotion!==true){
			showSummonaGuide('potionStorage');
			clearStorageSelections();renderStorageUI();
			return;
		}
	}

  // 鞄→デッキ検証は、同時に外す選択札を除いた仮デッキで行う。
  const outgoingKeys=new Set(outgoing.map(getStorageCardKey));
	const incomingKeys=new Set(incomingSource.map(getStorageCardKey));
	const tempDeck=deckList.filter(card=>!outgoingKeys.has(getStorageCardKey(card)));
	for(const card of incoming){
		const check=validateDeckAddition(targetChar,card,tempDeck);
		if(!check.ok){
			setStorageEditMessage(check.reason);
			return;
		}
		tempDeck.push(card);
	}
	const max=getDeckMaximum(targetChar);
	if(tempDeck.length>max){
		setStorageEditMessage(`デッキ上限${max}枚を超えるため移動できない`);
		return;
	}
	const finalBagCount=actualBag.length-incoming.length+outgoing.length;
	if(finalBagCount>CARD_STORAGE_MAX){
		setStorageEditMessage('カード鞄の空きが足りない');
		return;
	}
	const completesPotionLesson=gameState.onboardingStage==='potionStorage'
		&&incoming.some(card=>card.masterId==='c_potion'&&card.tutorialOnboardingPotion===true);
	const legacyMoved=outgoing.some(card=>card.category==='legacy')||incoming.some(card=>card.category==='legacy');

  const nextDeck=deckList.filter(card=>!outgoingKeys.has(getStorageCardKey(card)));
	const nextBag=actualBag.filter(card=>!incomingKeys.has(getStorageCardKey(card)));
	nextDeck.push(...incoming);
	nextBag.push(...outgoing);
	if(targetChar.isPlayer){
		gameState.deck.length=0;
		gameState.deck.push(...nextDeck);
		targetChar.deck=gameState.deck;
	}else{
		targetChar.deck=nextDeck;
	}
	normalizeCharacterCardUses(targetChar);
	nextBag.forEach(card=>setCardUseOwner(card));
	gameState.cardStorage=nextBag;
	if(legacyMoved)recalculateStats(targetChar);
	const message=outgoing.length&&incoming.length
			?`デッキ${outgoing.length}枚と鞄${incoming.length}枚を入れ替えた`
			:outgoing.length
				?`${outgoing.length}枚をカード鞄へ移動`
				:`${incoming.length}枚をデッキへ移動`;
	clearStorageSelections(message);
	renderStorageUI();
	saveGame();
	if(completesPotionLesson)finishStorageTutorial();
}
function findMarkedTutorialPotionInPartyDecks(){
	const playerDeck=gameState.deck||[];
	const inPlayer=playerDeck.find(card=>card?.tutorialOnboardingPotion===true);
	if(inPlayer)return inPlayer;
	for(const char of(gameState.party||[])){
		if(!char||char.isPlayer)continue;
		const found=(char.deck||[]).find(card=>card?.tutorialOnboardingPotion===true);
		if(found)return found;
	}
	return null;
}
