function isCardEnergyUpgradable(card){
	return Number.isFinite(getCardUseLimit(card));
}
function upgradeCard(cardIndex){
	const card=gameState.cardStorage[cardIndex];
	if(!card||!isCardEnergyUpgradable(card))return;
	const rarity=cardEffectiveRarity(card),lvl=getCardUpgradeLevel(card);
	if(rarity==='UR'&&lvl>=CARD_UPGRADE_MAX_LEVEL)return;
	const reqEnergy=getCardUpgradeEnergyCost(card);
	const suit=card.suit==="✨"?"✨":card.suit;
	if((gameState.energies[suit]||0)<reqEnergy){
		log(`⚠️ エナジーが不足しています (必要: ${suit}${reqEnergy})`);
		return;
	}
	gameState.energies[suit]-=reqEnergy;
	card.energyUpgraded=true;
	const oldLimit=getCardUseLimit(card),oldUses=getCardUses(card);
	const promoted=lvl>=CARD_UPGRADE_MAX_LEVEL;
	const newRarity=promoted?CARD_RARITY_ORDER[getCardRarityStep(rarity)+1]:rarity;
	const nextLevel=promoted?1:lvl+1;
	scaleCardOverallPerformance(card,getCardUpgradePerformanceMult(newRarity,nextLevel)/getCardUpgradePerformanceMult(rarity,lvl));
	if(promoted)changeCardUpgradeRarity(card,newRarity);
	card.level=nextLevel;
	if(Number.isFinite(oldLimit))card.usesRemaining=Math.min(getCardUseLimit(card),oldUses+Math.max(0,getCardUseLimit(card)-oldLimit));
	const usesText=Number.isFinite(oldLimit)?` 使用上限 ${getCardUseLimit(card)}回。`:'';
	log(promoted?`🌟 【${card.name}】 が ${rarity} → ${newRarity} に昇格した！${usesText}`:`🌟 【${card.name}】 を Lv.${card.level} に強化した！${usesText}`);
	updateShopUI();
	saveGame();
}


function refreshLegacyDescriptionExpiry(card){
	if(!card||card.category!=='legacy'||!card.description)return;
	// 残日数は expiresAt から動的表示する。説明文側に古い残日数を保持しない。
	card.description=String(card.description).replace(/\s*残り\d+日。?\s*$/,'').trim();
}
function extendLegacyCard(cardIndex){
	const card=gameState.cardStorage?.[cardIndex];
	if(!card||card.category!=='legacy')return;
	if(!card.expiresAt||card.expiresAt<=Date.now()){
		if(typeof legacyExpireCards==='function')legacyExpireCards(true);
		updateShopUI();
		saveGame();
		return;
	}
	if((gameState.diamonds||0)<LEGACY_EXTEND_DIAMOND_COST){
		log(`⚠️ 💎が不足しています（必要: 💎${LEGACY_EXTEND_DIAMOND_COST}）`);
		return;
	}
	gameState.diamonds-=LEGACY_EXTEND_DIAMOND_COST;
	card.expiresAt+=LEGACY_EXTEND_MS;
	refreshLegacyDescriptionExpiry(card);
	if(typeof updateDiamondDisplays==='function')updateDiamondDisplays();
	log(`🏆 【${card.name}】の残響を💎${LEGACY_EXTEND_DIAMOND_COST}で1日延長した。${legacyExpiryText(card.expiresAt)}。`);
	updateShopUI();
	saveGame();
}
