let currentShopTab='buy';
function getRarityColor(rarity){
	return RARITY_CONFIG[rarity]?.color||"#cccccc";
}

function sortBySuit(cards){
	return[...cards].sort((a,b)=>{
		const orderA=SUIT_ORDER[a.suit]||99;
		const orderB=SUIT_ORDER[b.suit]||99;
		return orderA-orderB;
	});
}


function getLocalWeekInfo(now=Date.now()){
	const d=new Date(now);
	const start=new Date(d.getFullYear(),d.getMonth(),d.getDate());
	const day=(start.getDay()+6)%7;
	start.setDate(start.getDate()-day);
	const next=new Date(start);
	next.setDate(next.getDate()+7);
	const y=start.getFullYear();
	const m=String(start.getMonth()+1).padStart(2,'0');
	const dayText=String(start.getDate()).padStart(2,'0');
	return{key:`${y}-${m}-${dayText}`,startMs:start.getTime(),nextMs:next.getTime()};
}
function getDiamondWeeklyRestockText(now=Date.now()){
	const info=getLocalWeekInfo(now);
	const remain=Math.max(0,info.nextMs-now);
	const days=Math.floor(remain / 86400000);
	const hours=Math.floor((remain%86400000)/ 3600000);
	if(days>0)return `週替わり更新まで ${days}日${hours}時間`;
	const mins=Math.max(1,Math.ceil((remain%3600000)/ 60000));
	return `週替わり更新まで ${hours}時間${mins}分`;
}
function getDiamondWeeklyUrPool(){
	return getCardMastersForChannel('diamondWeekly');
}
function getDiamondPackPool(){
	return getCardMastersForChannel('diamondPack');
}
function getCurrentDiamondWeeklySelection(now=Date.now()){
	const info=getLocalWeekInfo(now);
	const pool=[...getDiamondWeeklyUrPool()];
	const rng=createRNG(stringToSeed(`DIAMOND_WEEKLY_UR_${info.key}`));
	for(let i=pool.length-1;i>0;i--){
		const j=Math.floor(rng()*(i+1));
		[pool[i],pool[j]]=[pool[j],pool[i]];
	}
	const cards=pool.slice(0,DIAMOND_WEEKLY_UR_COUNT).map((master,index)=>({
		masterId:master.masterId,
		name:master.name,
		suit:master.suit,
		rarity:'UR',
		slotId:`diamond_weekly_${info.key}_${index}`,
		fixed:false,
		diamondWeekly:true
	}));
	return{weekKey:info.key,cards};
}
function ensureDiamondShopState(weekKey){
	if(!gameState.diamondShopState||gameState.diamondShopState.weekKey!==weekKey){
		gameState.diamondShopState={weekKey,purchased:{}};
	}
	gameState.diamondShopState.purchased||={};
	return gameState.diamondShopState;
}
function isDiamondWeeklySoldOut(slotId,weekKey){
	const state=ensureDiamondShopState(weekKey);
	return!!state.purchased?.[slotId];
}
function consumeDiamondWeeklyStock(slotId,weekKey){
	const state=ensureDiamondShopState(weekKey);
	state.purchased[slotId]=true;
}
function rollDiamondPackRarity(){
	let r=Math.random()*RARITY_TOTAL_WEIGHT;
	for(const[rarity,cfg]of RARITY_ENTRIES){
		if(r<cfg.weight)return rarity;
		r-=cfg.weight;
	}
	return 'N';
}
function getShopCardPrice(card,rarityOverride=null,fixed=false){
	if(fixed&&Number.isFinite(card?.price))return Math.max(0,Math.floor(card.price));
	const rarity=rarityOverride||card?.rarity||'N';
	return SHOP_RARITY_BASE_PRICE[rarity]||SHOP_RARITY_BASE_PRICE.N;
}
function formatCardPercentValue(value){
	const n=(Number(value)||0)*100;
	const rounded=Math.round(n*10)/ 10;
	return `${Number.isInteger(rounded)?rounded.toFixed(0):rounded.toFixed(1)}%`;
}
function getCardExplorerEffectText(card,options={}){
	if(!card)return '—';
	if(isDepartureBlankCard(card))return '単独使用 / コンボ不可 / マナ0 / 物理20% / ジョブ特殊効果対象外 / 帰還時消滅';
	if(card.masterId==='m_escape')return '単独使用 / 回数あり:確定逃走 / 回数0:30%逃走 / 強敵・守護者戦は確定（探索は継続）';
	if(card.category==='legacy')return typeof legacyEffectText==='function'?legacyEffectText(card):(card.effect||'常時効果');
	if(card.passive&&card.effect==='revive_full')return '死亡時に自動復活・HP全回復';
	if(card.passive&&card.effect==='nullify_interference')return '異常・妨害を無効化 / 無効化時に破損することがある';
	if(isAlchemistCatalystCard(card))return '錬金術師専用 / 🔮魔法攻撃札＋素材と3枚コンボ';
	if(card.category==='reward'){
		return `換金 ${getCardGoldSellPrice(card)}G`;
	}
	const parts=[],pct=formatCardPercentValue;
	if(card.category==='consumable'||card.type==='use_item'){
		if(card.effect==='heal_hp')parts.push(`負傷治療+${card.val||0}（探索専用）`);
		else if(card.effect==='gain_mana')parts.push('全カード使用回数+10%（探索専用）');
		else if(card.effect==='return_town')parts.push('町へ帰還');
		else parts.push('使用時消費');
		return parts.join(' / ');
	}
	if(card.type==='modifier'){
		if(card.targetMode==='highest_hp')parts.push('高HP狙い');
		else if(card.targetMode==='lowest_hp')parts.push('低HP狙い');
		else if(card.targetMode==='all')parts.push('全体化');
	}else if(card.type==='interference'){
		if(card.effect==='insert_blank')parts.push('山札へ無効札を混入');
		else if(card.effect==='random_discard')parts.push('手札を無作為に破棄');
		else parts.push('妨害');
	}else if(card.type==='dead_card')parts.push('効果なし');
	else if(card.type==='status'){
		const names={poison:'毒',stun:'気絶',dazzle:'眩惑'};
		parts.push(names[card.statusType]||card.statusType||'状態異常');
	}
	const sidePhy=Number(card.sidePhyScale)||0,sideMag=Number(card.sideMagScale)||0,sideHeal=Number(card.sideHealScale)||0;
	let shield=0;
	if(card.type==='def')shield+=Number(card.val)||0;
	shield+=Number(card.sideGuard)||0;
	if(card.type==='atk'||card.type==='wild_atk')parts.push(`物理${pct(Math.max(0.10,1+(Number(card.ratio)||0)))}`);
	else if(sidePhy>0)parts.push(`物理+${pct(sidePhy)}`);
	if(card.type==='matk')parts.push(`魔法${pct(Math.max(0.10,1+(Number(card.ratio)||0)))}`);
	else if(sideMag>0)parts.push(`魔法+${pct(sideMag)}`);
	if(card.type==='heal'||card.type==='wild_heal')parts.push(`回復${pct(Math.max(0.10,1+(Number(card.ratio)||0)))}`);
	else if(sideHeal>0)parts.push(`回復+${pct(sideHeal)}`);
	if((card.type==='atk'||card.type==='wild_atk')&&sidePhy>0)parts.push(`副物理+${pct(sidePhy)}`);
	if(card.type==='matk'&&sideMag>0)parts.push(`副魔法+${pct(sideMag)}`);
	if((card.type==='heal'||card.type==='wild_heal')&&sideHeal>0)parts.push(`副回復+${pct(sideHeal)}`);
	if(shield>0)parts.push(`シールド+${Number.isInteger(shield)?shield:Number(shield.toFixed(2))}`);
	if(options.includeMana!==false){
		const gain=Math.max(0,Number(card.manaGen)||0),cost=(Number(card.cost)>0&&Number(card.cost)<99)?Number(card.cost):0;
		if(cost>0)parts.push(`消費${cost}`);
		if(gain>0)parts.push(`マナ+${gain}`);
	}
	if(!parts.length&&Number.isFinite(card.val))parts.push(`${card.val>=0?'+':''}${card.val}`);
	if(options.includeUses!==false){
		const uses=cardUseText(card);
		if(uses)parts.push(uses);
	}
	return parts.length?parts.join(' / '):'—';
}
function rollShopRarity(rng){
	const entries=SHOP_RANDOM_RARITIES.map(key=>[key,RARITY_CONFIG[key]?.weight||1]);
	let total=entries.reduce((sum,[,w])=>sum+w,0);
	let r=rng()*total;
	for(const[key,w]of entries){if(r<w)return key;r-=w;}
	return 'N';
}
function getShopRegularPoolForSuit(suit){
	return getCardMastersForChannel('shopRegular',c=>c.suit===suit);
}
function getCurrentShopSelection(now=Date.now()){
	const rotationKey=Math.floor(now / SHOP_ROTATION_MS);
	const regular=[];
	Object.keys(SUIT_ORDER).forEach(suit=>{
		const pool=getShopRegularPoolForSuit(suit);
		if(!pool.length)return;
		const rng=createRNG(stringToSeed(`SHOP_V3_${rotationKey}_${suit}`));
		const usedRaritiesByMaster=new Map();
		for(let slot=0;slot<3;slot++){
			const master=pool[Math.floor(rng()*pool.length)]||pool[0];
			let rarity=rollShopRarity(rng);
			const used=usedRaritiesByMaster.get(master.masterId)||new Set();
			if(used.has(rarity)&&used.size<SHOP_RANDOM_RARITIES.length){
				const available=SHOP_RANDOM_RARITIES.filter(r=>!used.has(r));
				rarity=available[Math.floor(rng()*available.length)]||rarity;
			}
			used.add(rarity);usedRaritiesByMaster.set(master.masterId,used);
			regular.push({
				masterId:master.masterId,name:master.name,suit:master.suit,rarity,
				slotId:`${rotationKey}_${suit}_${slot}`,fixed:false
			});
		}
	});
	const fixed=getCardMastersForChannel('shopFixed')
		.filter(c=>c.masterId!==SHOP_GEM_MASTER_ID)
		.map(c=>({masterId:c.masterId,name:c.name,suit:c.suit,rarity:'N',slotId:`fixed_${c.masterId}`,fixed:true}));
	return{rotationKey,regular,fixed};
}
function ensureShopStockState(rotationKey){
	if(!gameState.shopStockState||gameState.shopStockState.rotationKey!==rotationKey){
		gameState.shopStockState={rotationKey,purchased:{}};
	}
	gameState.shopStockState.purchased||={};
	return gameState.shopStockState;
}
function getShopRemainingStock(item,rotationKey){
	if(item?.fixed)return Infinity;
	const state=ensureShopStockState(rotationKey);
	const max=SHOP_STOCK_BY_RARITY[item?.rarity]??1;
	return Math.max(0,max-(Number(state.purchased?.[item.slotId])||0));
}
function consumeShopStock(item,rotationKey){
	if(item?.fixed)return;
	const state=ensureShopStockState(rotationKey);
	state.purchased[item.slotId]=(Number(state.purchased[item.slotId])||0)+1;
}
function getShopRestockText(now=Date.now()){
	const remain=SHOP_ROTATION_MS-(now%SHOP_ROTATION_MS);
	const hours=Math.floor(remain / 3600000);
	const mins=Math.max(1,Math.ceil((remain%3600000)/ 60000));
	return `品揃え更新まで ${hours}時間${mins}分`;
}
function updateShopResourceHeader(){
	if(!gameState.energies)gameState.energies=createEmptySuitCounters();
	if(!gameState.cardStorage)gameState.cardStorage=[];
	document.getElementById('shop-gold-display').innerText=`${gameState.player.gold}G`;
	const el=document.getElementById('energy-display');if(!el)return;const e=gameState.energies;
	el.innerHTML=`<span>⚔️:${e['⚔️']||0}</span><span>🛡️:${e['🛡️']||0}</span><span>🔮:${e['🔮']||0}</span><span>✨:${e['✨']||0}</span><span>🌟:${e['🌟']||0}</span>`;
}
function setupShopMarquees(){
	document.querySelectorAll('#screen-shop .shop-card-name-wrap, #screen-shop .shop-card-effect-wrap, #screen-shop .shop-purchase-name-wrap, #screen-shop .shop-purchase-effect-wrap').forEach(viewport=>{
		const text=viewport.querySelector('.shop-card-name-text, .shop-card-effect-text, .shop-purchase-name-text, .shop-purchase-effect-text');
		if(!text)return;
		viewport.classList.remove('is-overflowing');
		viewport.style.removeProperty('--storage-scroll-distance');
		viewport.style.removeProperty('--storage-marquee-duration');
		const distance=Math.max(0,text.scrollWidth-viewport.clientWidth);
		if(distance<=1)return;
		viewport.style.setProperty('--storage-scroll-distance',`${Math.ceil(distance)}px`);
		viewport.style.setProperty('--storage-marquee-duration',`${Math.max(5,Math.min(14,4+distance / 18)).toFixed(1)}s`);
		viewport.classList.add('is-overflowing');
	});
}
let shopPurchaseLongPressTimer=null;
let shopPurchaseLongPressState=null;
function beginShopPurchaseLongPress(event,slotId,masterId,rarity='N',fixed=false){
	if(event.target?.closest?.('button,input'))return;
	if(event.pointerType==='mouse'&&event.button!==0)return;
	cancelShopPurchaseLongPress();
	shopPurchaseLongPressState={pointerId:event.pointerId,x:event.clientX,y:event.clientY,slotId,masterId,rarity,fixed};
	shopPurchaseLongPressTimer=setTimeout(()=>{
		const state=shopPurchaseLongPressState;
		shopPurchaseLongPressTimer=null;
		if(!state)return;
		openShopPurchaseDetailModal(state.slotId,state.masterId,state.rarity,state.fixed);
		if(navigator.vibrate)navigator.vibrate(18);
	},550);
}
function moveShopPurchaseLongPress(event){
	const state=shopPurchaseLongPressState;
	if(!state||state.pointerId!==event.pointerId)return;
	if(Math.hypot(event.clientX-state.x,event.clientY-state.y)>10)cancelShopPurchaseLongPress();
}
function cancelShopPurchaseLongPress(){
	if(shopPurchaseLongPressTimer)clearTimeout(shopPurchaseLongPressTimer);
	shopPurchaseLongPressTimer=null;
	shopPurchaseLongPressState=null;
}
function openShopPurchaseDetailModal(slotId,masterId,rarity='N',fixed=false){
	const master=getCardMaster(masterId);
	if(!master)return;
	const preview=makeCardPerformancePreview(master,rarity,true)||JSON.parse(JSON.stringify(master));
	preview.rarity=rarity;preview.dropRarity=rarity;
	const now=Date.now();
	const selection=getCurrentShopSelection(now);
	const item=[...selection.fixed,...selection.regular].find(x=>x.slotId===slotId&&x.masterId===masterId&&x.rarity===rarity&&!!x.fixed===!!fixed);
	const price=gameState.onboardingStage==='shopPotion'&&masterId==='c_potion'?0:getShopCardPrice(master,rarity,fixed);
	const remaining=item?getShopRemainingStock(item,selection.rotationKey):0;
	const stockText=fixed?'常備品':`在庫 ${remaining}/${SHOP_STOCK_BY_RARITY[rarity]||1}`;
	const modal=document.getElementById('storage-card-detail-modal');
	const title=document.getElementById('storage-card-detail-title');
	const meta=document.getElementById('storage-card-detail-meta');
	const effect=document.getElementById('storage-card-detail-effect');
	if(!modal||!title||!meta||!effect)return;
	title.textContent=`${master.suit||''} ${master.name||'カード'}`.trim();
	title.style.color=getRarityColor(rarity);
	const metaParts=[`${price}G`,stockText];
	const mana=getStorageCardManaText(preview);
	if(mana)metaParts.push(mana);
	meta.textContent=metaParts.join('　');
	effect.textContent=getStorageCardFullText(preview);
	modal.style.display='flex';
}
