const pendingCardDisposals=new Set();
function shouldConfirmCardDisposal(card){
 // Older promoted cards did not record the upgrade, so protect high-rarity cards as well.
 return !!card&&(card.energyUpgraded===true||getCardUpgradeLevel(card)>1||cardEffectiveRarity(card)!=='N');
}
async function sellCardFromStorage(index){
 const card=gameState.cardStorage?.[index];
 if(!card||card.category==='legacy'||pendingCardDisposals.has(card))return;
 pendingCardDisposals.add(card);
 try{
  if(shouldConfirmCardDisposal(card)&&!await showGameConfirm(`【${card.name}】（${cardEffectiveRarity(card)} / Lv.${getCardUpgradeLevel(card)}）を${isCardGoldExchangeable(card)?'換金':'還元'}しますか？\nカードは失われます。強化に使ったエナジーは戻りません。`,{title:'カードの処分確認',confirmText:isCardGoldExchangeable(card)?'換金する':'還元する'}))return;
  const currentIndex=gameState.cardStorage?.indexOf(card)??-1;
  if(currentIndex<0||card.category==='legacy')return;
  gameState.cardStorage.splice(currentIndex,1);
  if(isCardGoldExchangeable(card)){
   const amount=addPlayerGold(getCardGoldSellPrice(card));log(`💰 【${card.name}】を換金し、${amount}G を獲得した。`);
  }else{
   const suit=getCardReturnSuit(card),amount=getCardReturnEnergy(card);
   gameState.energies[suit]=(gameState.energies[suit]||0)+amount;log(`✨ 【${card.name}】を還元し、${suit}${amount} を獲得した。`);
  }
  updateShopUI();saveGame();
 }finally{pendingCardDisposals.delete(card);}
}
async function sellAllRewardCardsFromStorage(...args){
 if(pendingEconomyActions.has('sellAllRewardCardsFromStorage'))return;
 pendingEconomyActions.add('sellAllRewardCardsFromStorage');
 try{return await sellAllRewardCardsFromStorageTransaction(...args);}
 finally{pendingEconomyActions.delete('sellAllRewardCardsFromStorage');}
}
async function sellAllRewardCardsFromStorageTransaction(){
	if(!Array.isArray(gameState.cardStorage))return;
	const rewards=gameState.cardStorage.filter(card=>card?.category==='reward');
	if(!rewards.length){
		log('💰 まとめて換金できる報酬カードはない。');
		updateShopUI();
		return;
	}
	const total=rewards.reduce((sum,card)=>sum+getCardGoldSellPrice(card),0);
	if(!await showGameConfirm(`報酬カード ${rewards.length}枚をまとめて ${total}G に換金しますか？${rewards.some(shouldConfirmCardDisposal)?'\n高レア・強化済みのカードが含まれます。カードは失われ、強化エナジーは戻りません。':''}`,{title:'まとめて換金',confirmText:'換金する'}))return;
	let sold=0,actualTotal=0;
	for(let i=gameState.cardStorage.length-1;i>=0;i--){
		const card=gameState.cardStorage[i];
		if(card?.category!=='reward'||!rewards.includes(card))continue;
		actualTotal+=getCardGoldSellPrice(card);
		gameState.cardStorage.splice(i,1);
		sold++;
	}
	if(!sold)return;
	const earned=addPlayerGold(actualTotal);
	log(`💰 報酬カード ${sold}枚を換金し、${earned}G を獲得した。`);
	updateShopUI();
	saveGame();
}
