function cycleGuildFormation(index){
	if(isGuidedTutorialFlowActive()&&gameState?.onboardingStage!=='formationTutorial'){blockGuidedTutorialAction();return;}
	if(gameState.inBattle||gameState.dungeon)return;
	updatePartyPositions();
	const target=gameState.party[index];
	if(!target||target.hp<=0)return;
	const front=gameState.party.filter(c=>c.hp>0&&c.position==='front');
	const back=gameState.party.filter(c=>c.hp>0&&c.position==='back');
	const reserve=gameState.party.filter(c=>c.hp>0&&c.position==='reserve');
	const dead=gameState.party.filter(c=>c.hp<=0);
	if(target.position==='front'){
		front.splice(front.indexOf(target),1);
		if(!front.length){
			if(!back.length)return;
			front.push(back.shift());
		}
		back.push(target);
		while(back.length>front.length&&front.length<5)front.push(back.shift());
		gameState.formationFrontCount=front.length;
	}else if(target.position==='back'){
		if(target.isPlayer){showGameNotice('リーダーは待機にできません。交代したい場合は「名簿」からリーダーを任命してください。',{title:'隊列'});return;}
		back.splice(back.indexOf(target),1);
		reserve.unshift(target);
		gameState.formationActiveCount=Math.max(1,front.length+back.length);
	}else if(target.position==='reserve'){
		reserve.splice(reserve.indexOf(target),1);
		if(front.length>=5){
			const displaced=[...front].reverse().find(c=>!c.isPlayer);
			front.splice(front.indexOf(displaced),1);
			reserve.unshift(displaced);
		}else if(front.length+back.length>=6){
			const displaced=[...back].reverse().find(c=>!c.isPlayer);
			if(!displaced){showGameNotice('リーダーを待機にできません。',{title:'隊列'});return;}
			back.splice(back.indexOf(displaced),1);
			reserve.unshift(displaced);
		}
		front.push(target);
		gameState.formationFrontCount=front.length;
		gameState.formationActiveCount=front.length+back.length;
	}
	gameState.party=[...front,...back,...reserve,...dead];
	updatePartyUI();
	updateGuildUI();
	saveGame();
}
function toggleDungeonCombatRow(index){
	if(!gameState.dungeon||gameState.inBattle||isGuidedTutorialFlowActive())return;
	updatePartyPositions();
	const selectedChar=gameState.party[selectedDungeonDeckCharIdx];
	const target=gameState.party[index];
	if(!target||target.hp<=0||target.position==='reserve')return;
	const front=gameState.party.filter(c=>c.hp>0&&c.position==='front');
	const back=gameState.party.filter(c=>c.hp>0&&c.position==='back');
	const reserve=gameState.party.filter(c=>c.hp>0&&c.position==='reserve');
	const dead=gameState.party.filter(c=>c.hp<=0);
	if(target.position==='front'){
		front.splice(front.indexOf(target),1);
		if(!front.length){
			if(!back.length)return;
			front.push(back.shift());
		}
		back.push(target);
		while(back.length>front.length&&front.length<5)front.push(back.shift());
	}else{
		back.splice(back.indexOf(target),1);
		if(front.length>=5)back.unshift(front.pop());
		front.push(target);
	}
	gameState.formationFrontCount=front.length;
	gameState.party=[...front,...back,...reserve,...dead];
	selectedDungeonDeckCharIdx=Math.max(0,gameState.party.indexOf(selectedChar));
	updatePartyUI();
	renderDungeonStatusModal();
	saveGame();
}
function ensureCharacterRosterId(char){
	if(!char)return '';
	if(!char.rosterId||char.rosterId==='hero')char.rosterId=`npc_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
	return char.rosterId;
}


function changePartyLeader(index){
	if(isGuidedTutorialFlowActive()){blockGuidedTutorialAction();return;}
	if(gameState.dungeon||gameState.inBattle)return;
	const nextLeader=gameState.party?.[index];
	const oldLeader=gameState.player||(gameState.party||[]).find(c=>c?.isPlayer);
	if(!nextLeader||!oldLeader||nextLeader===oldLeader||nextLeader.isPlayer||nextLeader.missionCompanion||nextLeader.hp<=0||nextLeader.jobType==='supply'||nextLeader.position==='reserve')return;
	const oldDeck=Array.isArray(gameState.deck)?gameState.deck:(Array.isArray(oldLeader.deck)?oldLeader.deck:[]);
	const nextDeck=Array.isArray(nextLeader.deck)?nextLeader.deck:buildDeckFromMasterIds(JOB_DECKS[nextLeader.jobType]||JOB_DECKS.knight);
	const partyGold=clampGameInt(oldLeader.gold||0,0,GAME_LIMITS.GOLD);
	ensureCharacterRosterId(oldLeader);
	if(!nextLeader.rosterId&&nextLeader.id&&nextLeader.id!=='hero')nextLeader.rosterId=nextLeader.id;
	oldLeader.deck=oldDeck;
	oldLeader.isPlayer=false;
	oldLeader.id=oldLeader.rosterId;
	oldLeader.gold=0;
	nextLeader.isPlayer=true;
	nextLeader.id='hero';
	nextLeader.gold=partyGold;
	gameState.player=nextLeader;
	refreshPlayerNamedUi();
	gameState.deck=nextDeck;
	nextLeader.deck=gameState.deck;
	gameState.party.forEach(char=>{if(char!==nextLeader)char.isPlayer=false;});
	normalizeInheritedFriend(nextLeader);
	gameState.party.forEach(normalizeCharacterCardUses);
	recalculateStats(nextLeader);
	updatePartyPositions();
	log(`👑 リーダーを【${nextLeader.name}】へ変更した。`);
	updatePartyUI();
	updateGuildUI();
	saveGame();
}
function movePartyOrder(index,direction){
	if(isGuidedTutorialFlowActive()&&gameState?.onboardingStage!=='formationTutorial'){blockGuidedTutorialAction();return;}
	if(gameState.inBattle)return;
	const targetIndex=index+direction;
	if(targetIndex<0||targetIndex>=gameState.party.length)return;
	const activeLimit=gameState.formationActiveCount||6;
	if((index<activeLimit)!==(targetIndex<activeLimit)&&gameState.party[index<activeLimit?index:targetIndex]?.isPlayer){
		showGameNotice('リーダーを待機にできません。',{title:'隊列'});return;
	}
	const selectedChar=gameState.party[selectedDungeonDeckCharIdx];
	const temp=gameState.party[index];
	gameState.party[index]=gameState.party[targetIndex];
	gameState.party[targetIndex]=temp;
	selectedDungeonDeckCharIdx=Math.max(0,gameState.party.indexOf(selectedChar));
	updatePartyUI();
	if(document.getElementById('screen-guild')?.classList.contains('active'))updateGuildUI();
	if(document.getElementById('dungeon-deck-modal')?.style.display==='flex')renderDungeonDeckList();
	saveGame();
}


let guildHireActiveTab='recruit';
function getRecruitmentLocalDateKey(now=new Date()){
	const y=now.getFullYear(),m=String(now.getMonth()+1).padStart(2,'0'),d=String(now.getDate()).padStart(2,'0');
	return `${y}-${m}-${d}`;
}
function ensureRecruitmentState(){
	const fallback={initialized:false,jobKey:'any',purpose:'balanced',waitingForDungeon:false,runSeen:false,candidates:[],batchSerial:0,dailyHireDate:'',dailyHireCount:0};
	if(!gameState.recruitmentState||typeof gameState.recruitmentState!=='object')gameState.recruitmentState={...fallback};
	const state=gameState.recruitmentState;
	state.initialized=!!state.initialized;
	state.jobKey=(state.jobKey==='any'||JOB_TEMPLATES[state.jobKey])?state.jobKey:'any';
	state.purpose=RECRUITMENT_PURPOSES[state.purpose]?state.purpose:'balanced';
	state.waitingForDungeon=!!state.waitingForDungeon;
	state.runSeen=!!state.runSeen;
	state.candidates=Array.isArray(state.candidates)?state.candidates.filter(Boolean):[];
	state.batchSerial=Math.max(0,Math.floor(Number(state.batchSerial)||0));
	const today=getRecruitmentLocalDateKey();
	if(state.dailyHireDate!==today){state.dailyHireDate=today;state.dailyHireCount=0;}
	state.dailyHireCount=Math.max(0,Math.min(RECRUITMENT_DAILY_HIRE_LIMIT,Math.floor(Number(state.dailyHireCount)||0)));
	return state;
}
function getRecruitmentDailyRemaining(state=ensureRecruitmentState()){
	return Math.max(0,RECRUITMENT_DAILY_HIRE_LIMIT-state.dailyHireCount);
}
function getRecruitmentContractCost(level,bonusTier){
	const lv=Math.max(1,Math.min(MAX_CHARACTER_LEVEL,Math.round(Number(level)||1)));
	const tier=Math.max(1,Math.min(3,Math.round(Number(bonusTier)||1)));
	const base=500+(lv-1)*50;
	const mult=tier===3?1.5:tier===2?1.25:1;
	return Math.ceil((base*mult)/50)*50;
}
function getRecruitmentDeckMasterIds(jobKey,purpose){
	const base=[...(JOB_DECKS[jobKey]||JOB_DECKS.hero||[])];
	if(jobKey==='supply'||purpose==='balanced')return base.slice(0,20);
	if(jobKey==='clown')return base.slice(0,20);
	// 勧誘目的で札を選び直しても主10・副7・🌟3の枠は保つ。
	const choose=(ids,length)=>{
		const unique=[...new Set(ids)].filter(id=>getCardMaster(id));
		const counts=new Map(),out=[];
		for(let slot=0;slot<length;slot++){
			const pool=unique.filter(id=>(counts.get(id)||0)<STANDARD_NAME_MAX);
			if(!pool.length)break;
			const weighted=pool.flatMap(id=>{
				const card=getCardMaster(id);
				const matching=purpose==='offense'?['atk','matk'].includes(card.type)
					:purpose==='defense'?card.type==='def'
					:purpose==='heal'?['heal','wild_heal'].includes(card.type)
					:purpose==='explore'?Number(card.manaGen)>0:false;
				return Array(matching?4:1).fill(id);
			});
			const id=weighted[Math.floor(Math.random()*weighted.length)];
			out.push(id);counts.set(id,(counts.get(id)||0)+1);
		}
		if(out.length!==length)throw new Error('勧誘デッキの枚数が不正');
		return out;
	};
	return [...choose(base.slice(0,10),10),...choose(base.slice(10,17),7),...base.slice(17,20)];
}
function pickRecruitmentName(usedNames){
	const blocked=new Set([...(gameState.party||[]).map(c=>c?.name),...(usedNames||[])]);
	const available=RANDOM_NAMES.filter(name=>!blocked.has(name));
	if(available.length)return available[Math.floor(Math.random()*available.length)];
	return `冒険者${Math.floor(Math.random()*90+10)}`.slice(0,PERSON_NAME_MAX_LENGTH);
}
function buildRecruitmentStatRates(purpose,tier){
	const t=Math.max(1,Math.min(3,Math.round(Number(tier)||1)));
	// 全能力100～120%。総ボーナス量を固定し、どこかが伸びるほど他へ回る分が減る。
	const budget=t===3?72:t===2?54:36;
	const weights=RECRUITMENT_PURPOSE_STAT_WEIGHTS[purpose]||RECRUITMENT_PURPOSE_STAT_WEIGHTS.balanced;
	const bonus=Object.fromEntries(RECRUITMENT_STAT_KEYS.map(k=>[k,0]));
	for(let point=0;point<budget;point++){
		const pool=RECRUITMENT_STAT_KEYS.filter(k=>bonus[k]<20);
		if(!pool.length)break;
		let total=0;
		const weighted=pool.map(k=>{
			// 既に高い能力ほど追加されにくくしつつ、募集目的だけ明確に偏らせる。
			const w=Math.max(.05,(Number(weights[k])||1)*(0.72+Math.random()*.56)/(1+bonus[k]*.13));
			total+=w;return[k,w];
		});
		let roll=Math.random()*total,chosen=weighted[weighted.length-1][0];
		for(const [k,w] of weighted){roll-=w;if(roll<=0){chosen=k;break;}}
		bonus[chosen]++;
	}
	// 個性が埋もれた場合は、総量を変えずに得意・不得意の差を少しだけ作る。
	for(let guard=0;guard<12;guard++){
		const vals=RECRUITMENT_STAT_KEYS.map(k=>bonus[k]);
		if(Math.max(...vals)-Math.min(...vals)>=5)break;
		const hi=purpose==='balanced'
			?RECRUITMENT_STAT_KEYS.reduce((a,b)=>bonus[b]>bonus[a]?b:a,RECRUITMENT_STAT_KEYS[0])
			:RECRUITMENT_STAT_KEYS.reduce((a,b)=>(Number(weights[b])||1)>(Number(weights[a])||1)?b:a,RECRUITMENT_STAT_KEYS[0]);
		const lows=RECRUITMENT_STAT_KEYS.filter(k=>k!==hi&&bonus[k]>0).sort((a,b)=>bonus[a]-bonus[b]);
		if(!lows.length||bonus[hi]>=20)break;
		const low=lows[0];bonus[low]--;bonus[hi]++;
	}
	return Object.fromEntries(RECRUITMENT_STAT_KEYS.map(k=>[k,100+Math.max(0,Math.min(20,bonus[k]))]));
}
function applyRecruitmentLevelBaseline(char,level){
	const lv=Math.max(1,Math.min(MAX_CHARACTER_LEVEL,Math.round(Number(level)||1)));
	const growth=getJobCumulativeGrowth(char?.jobType||'hero',lv);
	char.baseMaxHp=clampGameInt((Number(char.baseMaxHp)||1)+growth.hp,1,GAME_LIMITS.HP);
	const keyMap={atk:'baseAtk',def:'baseDef',matk:'baseMatk',mdef:'baseMdef',spd:'baseSpd'};
	JOB_GROWTH_STAT_KEYS.forEach(key=>{const stat=keyMap[key];char[stat]=clampGameInt((Number(char[stat])||1)+growth[key],1,GAME_LIMITS.STAT);});
	char.level=lv;char.exp=0;char.trainableGrowth=createEmptyTrainableGrowth();
	return char;
}
function applyRecruitmentStatRates(char,rates){
	RECRUITMENT_STAT_KEYS.forEach(key=>{
		const meta=RECRUITMENT_STAT_META[key],rate=Math.max(100,Math.min(120,Math.round(Number(rates?.[key])||100)));
		const max=key==='hp'?GAME_LIMITS.HP:GAME_LIMITS.STAT;
		char[meta.base]=clampGameInt(Math.round((Number(char[meta.base])||1)*rate/100),1,max);
	});
	char.recruitmentStatRates={...rates};
}
function getRecruitmentProfile(candidate){
	const rates=candidate?.recruitmentStatRates||{};
	const ranked=RECRUITMENT_STAT_KEYS.map((key,order)=>({key,rate:Number(rates[key])||100,order})).sort((a,b)=>b.rate-a.rate||a.order-b.order);
	const strongest=ranked[0]||{key:'atk'},weakest=ranked[ranked.length-1]||{key:'def'};
	return{
		strong:`${RECRUITMENT_STAT_META[strongest.key]?.strong||'戦うこと'}が得意`,
		weak:`${RECRUITMENT_STAT_META[weakest.key]?.weak||'苦手なこと'}は苦手`
	};
}
function createRecruitmentCandidate(jobKey,purpose,level,bonusTier,usedNames=[]){
	const keys=Object.keys(JOB_TEMPLATES);
	const key=jobKey==='any'?keys[Math.floor(Math.random()*keys.length)]:jobKey;
	const char=createCharacterObj(key,pickRecruitmentName(usedNames),false);
	const lv=Math.max(1,Math.min(MAX_CHARACTER_LEVEL,Math.round(Number(level)||1)));
	const tier=Math.max(1,Math.min(3,Math.round(Number(bonusTier)||1)));
	applyRecruitmentLevelBaseline(char,lv);
	const rates=buildRecruitmentStatRates(purpose,tier);
	applyRecruitmentStatRates(char,rates);
	applyReferenceTrainableGrowth(char,lv);
	char.deck=buildDeckFromMasterIds(getRecruitmentDeckMasterIds(key,purpose));
	char.recruitmentPurpose=purpose;
	char.recruitmentBonusTier=tier;
	char.recruitmentBaseLevel=lv;
	char.contractCost=getRecruitmentContractCost(lv,tier);
	char.recruitmentCandidate=true;
	equipInitialNpcEquipment(char,'guild_recruit');
	recalculateStats(char,true);
	return char;
}
function buildRecruitmentCandidates(){
	const state=ensureRecruitmentState();
	const level=Math.max(1,Math.min(MAX_CHARACTER_LEVEL,Math.round(getPartyAverageLevel())));
	const tiers=[1,1,2,2,3,3].sort(()=>Math.random()-.5);
	const used=[];
	state.candidates=tiers.map(tier=>{
		const c=createRecruitmentCandidate(state.jobKey,state.purpose,level,tier,used);
		used.push(c.name);
		return c;
	});
	state.batchSerial++;
	state.waitingForDungeon=false;
	state.runSeen=false;
	return state.candidates;
}
function registerRecruitmentDungeonEntry(){
	const state=ensureRecruitmentState();
	if(!state.initialized||!state.waitingForDungeon||state.runSeen)return false;
	state.runSeen=true;
	return true;
}
function resolveRecruitmentCandidatesIfReady(){
	const state=ensureRecruitmentState();
	if(state.initialized&&state.waitingForDungeon&&state.runSeen&&!state.candidates.length){
		buildRecruitmentCandidates();
		return true;
	}
	return false;
}
function openGuildHireModal(){
	if(isGuidedTutorialFlowActive()){blockGuidedTutorialAction();return;}
	if(gameState.dungeon||gameState.inBattle)return;
	resolveRecruitmentCandidatesIfReady();
	guildHireActiveTab='recruit';
	const modal=document.getElementById('guild-hire-modal');
	if(modal)modal.style.display='flex';
	renderGuildHireModal();
	showFeatureTipOnce('recruitment','応募者の職業・特徴・契約金を比べて仲間を選べます。条件を変えて再募集した場合、新しい応募者は次の探索から帰還したあとに届きます。',{title:'Tips：仲間募集'});
}
function closeGuildHireModal(){hideModalById('friend-share-deck-modal');hideModalById('guild-hire-modal');}
async function setGuildHireTab(tab){guildHireActiveTab=tab==='friend'?'friend':'recruit';renderGuildHireModal();if(guildHireActiveTab==='friend')await showFeatureTipOnce('friend','フレンドコードを交換すると、ほかのプレイヤーの探索者を仲間として受け入れられます。自分のコードを共有することもできます。\n\n通常のフレンドコードの受け入れには💎10を消費します。\n\nギルドで共有用デッキを20枚ちょうどに設定してください。全キャラクターのデッキとカード鞄から、通常5スートの札を選べます。通常は3スートまで（道化師は5スート）、同スート12枚・同名4枚まで。選んだ札は移動・消費されません。',{title:'Tips：フレンドコード'});}
