	if(friendTab){friendTab.style.background=guildHireActiveTab==='friend'?'#294654':'#2b2b2b';friendTab.style.borderColor=guildHireActiveTab==='friend'?'#7fb7d8':'#555';}
	if(guildHireActiveTab==='friend')renderFriendHirePanel();else renderRecruitmentPanel(state);
