async function fireNPCTransaction(index){
	if(isGuidedTutorialFlowActive()){blockGuidedTutorialAction();return;}
	const target=gameState.party[index];
	if(!target||target.isPlayer)return;
	if(!await showGameConfirm(`【${target.name}】 をパーティから外しますか？\n装備中の品と本人用の予備も一緒に離脱します。残したい通常装備は先に倉庫へ戻してください。`,{title:'パーティ離脱',confirmText:'外す'}))return;
	if(gameState.party[index]!==target||target.isPlayer||gameState.dungeon||gameState.inBattle)return;
	gameState.party.splice(index,1);
	log(`👋 【${target.name}】 がパーティを離脱しました。`);
	updatePartyUI();
	updateGuildUI();
	saveGame();
}
