    <button onclick="changePartyLeaderFromRoster(${index})" ${canLead?'':'disabled'} style="min-width:62px;min-height:34px;background:#3b3420;border-color:#a88b4a;color:#f0d99b;">${char.isPlayer?'任命中':'任命'}</button>
