async function renamePartyMember(index){
 if(isGuidedTutorialFlowActive()){blockGuidedTutorialAction();return;}
 if(gameState.dungeon||gameState.inBattle)return;
 const current=gameState.party?.[index];
 if(!current||current.friendNameLocked)return;
 const newName=await showGamePrompt(`【${current.name}】 の新しい名前を入力してください（${PERSON_NAME_MAX_LENGTH}文字まで）:`,current.name,{title:'名前変更',maxLength:PERSON_NAME_MAX_LENGTH});
 if(!newName||!newName.trim())return;
 if(gameState.dungeon||gameState.inBattle||gameState.party?.[index]!==current||current.friendNameLocked)return;
 if(!validatePlainNameInput(newName,PERSON_NAME_MAX_LENGTH,'人名'))return;
 current.name=clipPersonName(newName);
 for(const item of [...Object.values(current.equip||{}),...Object.values(current.personalEquipmentReserve||{})])if(item?.personalEquipment)bindPersonalEquipment(current,item);
 log(`✍️ 名前を 【${escapeHtml(current.name)}】 に変更しました。`);
 updatePartyUI();updateGuildUI();saveGame();renderRosterModal();
}

const TRAINING_DIAMOND_COST=3;
const TRAINING_EDIT_LIMIT=10;
const TRAINING_STAT_META=Object.freeze({
 atk:{label:'攻撃',base:'baseAtk'},def:{label:'防御',base:'baseDef'},matk:{label:'魔力',base:'baseMatk'},mdef:{label:'精神',base:'baseMdef'},spd:{label:'速度',base:'baseSpd'}
});
let trainingDraft=null;
function openTrainingModal(){
 if(isGuidedTutorialFlowActive()){blockGuidedTutorialAction();return;}
 if(gameState.dungeon||gameState.inBattle)return;
 (gameState.party||[]).forEach(normalizeTrainableGrowth);
 const modal=document.getElementById('training-modal');if(!modal)return;
 const select=document.getElementById('training-character-select');
 if(select){
  select.innerHTML=(gameState.party||[]).map((char,index)=>`<option value="${index}">${escapeHtml(char.name)} / ${escapeHtml(char.job||'冒険者')} / Lv.${Number(char.level)||1}</option>`).join('');
  let initial=Math.max(0,Math.min((gameState.party||[]).length-1,Number(select.value)||0));
  if(!gameState.party?.[initial])initial=0;
  select.value=String(initial);selectTrainingCharacter(initial);
 }
 const diamond=document.getElementById('training-diamond-display');if(diamond)diamond.textContent=`💎${Math.max(0,gameState.diamonds||0)}`;
 modal.style.display='flex';
}
function closeTrainingModal(){trainingDraft=null;hideModalById('training-modal');}
function selectTrainingCharacter(index){
 const idx=Math.max(0,Math.floor(Number(index)||0)),char=gameState.party?.[idx];if(!char)return;
 const original={...normalizeTrainableGrowth(char)};
 trainingDraft={index:idx,original,draft:{...original},buffer:0,editsUsed:0};
 renderTrainingEditor();
}
function getTrainingProjectedBase(char,key,draft=trainingDraft){
 const meta=TRAINING_STAT_META[key];if(!char||!meta||!draft)return 1;
 return (Number(char[meta.base])||1)+((Number(draft.draft[key])||0)-(Number(draft.original[key])||0));
}
function trainingRemovePoint(key){
 const d=trainingDraft;if(!d||!TRAINING_STAT_META[key]||d.editsUsed>=TRAINING_EDIT_LIMIT)return;
 if((d.draft[key]||0)<=0)return;
 d.draft[key]--;d.buffer++;d.editsUsed++;renderTrainingEditor();
}
function trainingAddPoint(key){
 const d=trainingDraft,char=gameState.party?.[d?.index];if(!d||!char||!TRAINING_STAT_META[key]||d.buffer<=0)return;
 if(getTrainingProjectedBase(char,key,d)>=GAME_LIMITS.STAT)return;
 d.draft[key]++;d.buffer--;renderTrainingEditor();
}
function resetTrainingDraft(){
 const d=trainingDraft;if(!d)return;d.draft={...d.original};d.buffer=0;d.editsUsed=0;renderTrainingEditor();
}
function renderTrainingEditor(){
 const d=trainingDraft,char=gameState.party?.[d?.index];if(!d||!char)return;
 const summary=document.getElementById('training-character-summary');
 const total=JOB_GROWTH_STAT_KEYS.reduce((sum,key)=>sum+(d.original[key]||0),0);
 if(summary)summary.innerHTML=`<b style="color:#e8d9a6;">${escapeHtml(char.name)}</b>　${escapeHtml(char.job||'冒険者')} Lv.${Number(char.level)||1}<br><span style="color:#91aab5;">鍛練可能な札成長：${total}点</span>`;
 const list=document.getElementById('training-stat-list');
 if(list)list.innerHTML=JOB_GROWTH_STAT_KEYS.map(key=>{
  const meta=TRAINING_STAT_META[key],value=d.draft[key]||0,delta=value-(d.original[key]||0),projected=getTrainingProjectedBase(char,key,d);
  const deltaText=delta===0?'':` <span style="color:${delta>0?'#8de8a0':'#ff9d92'};">(${delta>0?'+':''}${delta})</span>`;
  return `<div style="display:grid;grid-template-columns:64px minmax(0,1fr) 36px 36px;gap:5px;align-items:center;background:#171d20;border:1px solid #354b55;border-radius:4px;padding:6px;">
   <b style="color:#d8e7ed;">${meta.label}</b><span style="font-size:11px;color:#b8c8cf;">成長 +${value}${deltaText}　基礎 ${projected}</span>
   <button onclick="trainingRemovePoint('${key}')" ${(value<=0||d.editsUsed>=TRAINING_EDIT_LIMIT)?'disabled':''} style="min-height:32px;">−</button>
   <button onclick="trainingAddPoint('${key}')" ${(d.buffer<=0||projected>=GAME_LIMITS.STAT)?'disabled':''} style="min-height:32px;">＋</button>
  </div>`;
 }).join('');
 const budget=document.getElementById('training-budget');
 if(budget)budget.innerHTML=`編集 ${d.editsUsed}/${TRAINING_EDIT_LIMIT}　・　振替待ち ${d.buffer}点<br><span style="color:#8f9da3;">「−」で成長点を取り出し、「＋」で別能力へ割り当てる。1点を動かすごとに編集1回。</span>`;
 const confirm=document.getElementById('training-confirm-btn');
 const changed=JOB_GROWTH_STAT_KEYS.some(key=>(d.draft[key]||0)!==(d.original[key]||0));
 if(confirm){
  confirm.disabled=!changed||d.buffer!==0||d.editsUsed<=0||(gameState.diamonds||0)<TRAINING_DIAMOND_COST;
  confirm.textContent=`💎${TRAINING_DIAMOND_COST}で鍛練（最大${TRAINING_EDIT_LIMIT}点）`;
 }
 const diamond=document.getElementById('training-diamond-display');if(diamond)diamond.textContent=`💎${Math.max(0,gameState.diamonds||0)}`;
}
async function commitTrainingDraft(...args){
 if(pendingEconomyActions.has('commitTrainingDraft'))return;
 pendingEconomyActions.add('commitTrainingDraft');
 try{return await commitTrainingDraftTransaction(...args);}
 finally{pendingEconomyActions.delete('commitTrainingDraft');}
}
async function commitTrainingDraftTransaction(){
 const d=trainingDraft,char=gameState.party?.[d?.index];if(!d||!char)return;
 if(d.buffer!==0){showGameNotice('取り出した成長点をすべて割り当ててください。',{title:'鍛練'});return;}
 const changed=JOB_GROWTH_STAT_KEYS.filter(key=>(d.draft[key]||0)!==(d.original[key]||0));
 if(!changed.length||d.editsUsed<=0||d.editsUsed>TRAINING_EDIT_LIMIT)return;
 if((gameState.diamonds||0)<TRAINING_DIAMOND_COST){showGameNotice(`ダイヤが足りません。必要：💎${TRAINING_DIAMOND_COST}`,{title:'鍛練'});return;}
 const detail=changed.map(key=>`${TRAINING_STAT_META[key].label} ${d.original[key]}→${d.draft[key]}`).join(' / ');
 if(!await showGameConfirm(`【${char.name}】の成長を${d.editsUsed}点分鍛え直しますか？\n${detail}\n\n費用：💎${TRAINING_DIAMOND_COST}`,{title:'鍛練',confirmText:'鍛練する'}))return;
 if(gameState.dungeon||gameState.inBattle||gameState.party?.[d.index]!==char||trainingDraft!==d)return;
 if(JOB_GROWTH_STAT_KEYS.some(key=>(char.trainableGrowth?.[key]||0)!==(d.original[key]||0)))return;
 if((gameState.diamonds||0)<TRAINING_DIAMOND_COST)return;
 JOB_GROWTH_STAT_KEYS.forEach(key=>{
  const meta=TRAINING_STAT_META[key],delta=(d.draft[key]||0)-(d.original[key]||0);
  char[meta.base]=clampGameInt((Number(char[meta.base])||1)+delta,1,GAME_LIMITS.STAT);
 });
 char.trainableGrowth={...d.draft};
 gameState.diamonds-=TRAINING_DIAMOND_COST;
 recalculateStats(char);updateDiamondDisplays();updatePartyUI();updateGuildUI();saveGame();
 clearLog();log(`⚒️ 【${escapeHtml(char.name)}】が鍛練を行い、成長${d.editsUsed}点を振り替えた（💎${TRAINING_DIAMOND_COST}）。`);
 const select=document.getElementById('training-character-select');if(select)select.value=String(d.index);
 selectTrainingCharacter(d.index);
}

async function openDungeonSelect(){
    if(!gameState?.dungeon&&!await maybeShowDungeonSelectGuide())return;
	if(needsStarterGuildVisit()){explainStarterGuildVisit();return;}
	if(gameState.onboardingStage==='formationTutorial'){
		showScreen('screen-guild');
		showTutorialTip('まずギルドで隊列を決めよう。仲間の<b>配置ボタン</b>で前衛・後衛・待機を切り替えられるよ。','サモナ',{buttonLabel:'隊列を見る'});
		return;
	}
	if(gameState.onboardingStage==='partyName'){openStarterPartyNameModal();return;}
	if(gameState.onboardingStage==='shopPotion'){
		clearLog();
		openShopScreen();
		scheduleSummonaGuide('dungeonBeforeShop',80,'shopPotion','screen-shop');
		return;
	}
	if(gameState.onboardingStage==='shopPotionBought'){
		clearLog();
		showSummonaGuide('potionUse');
		return;
	}
	if(gameState.onboardingStage==='potionStorage'){
		clearLog();
			openStorageScreen();
		scheduleSummonaGuide('dungeonBeforeStorage',80,'potionStorage','screen-storage');
		return;
	}
	if(gameState.onboardingStage==='dungeonLessonPending'&&!gameState.firstDungeonLessonSeen){
		if(!validatePartyDecksForDungeonEntry())return;
		gameState.onboardingStage='dungeonLesson';updateGuidedTutorialLocks();
		saveGame();
		showSummonaGuide('dungeonKinds');
		return;
	}
	if(gameState.onboardingStage==='dungeonLesson'&&!gameState.firstDungeonLessonSeen){
		if(!validatePartyDecksForDungeonEntry())return;
		showSummonaGuide('dungeonKinds');
		return;
	}
	if(gameState.tutorialState&&gameState.tutorialState.completed===false){
		clearLog();
		showSummonaGuide('tutorialNotFinished');
		if(!gameState.tutorialState.active)setTimeout(replayTutorial,120);
		return;
	}
	if(gameState.onboardingGuidePreference==='context'&&!gameState.firstDungeonLessonSeen){
		if(!validatePartyDecksForDungeonEntry())return;
		gameState.onboardingStage='dungeonLesson';updateGuidedTutorialLocks();saveGame();
		showSummonaGuide('dungeonKinds');
		return;
	}
	if(gameState.guildIntroPending&&gameState.onboardingGuidePreference!=='context'){
		clearLog();
		showSummonaGuide('guildMeet');
		return;
	}
	if(!validatePartyDecksForDungeonEntry())return;
	showScreen('screen-word');
	syncProgressionUnlockUI();
	const milestonePrefill=getPendingMilestoneDungeonPrefill();
	if(milestonePrefill){
		setDungeonEntryMode('mugen');
		const input=document.getElementById('custom-dungeon-input');
		if(input)input.value=milestonePrefill.def.dungeonWord;
		milestonePrefill.rec.prefillPending=false;
		if(milestonePrefill.def.id==='research_intro')ensureResearchProgram().prefillPending=false;
		saveGame();
	}else{
		setDungeonEntryMode(customDungeonMode?'mugen':'normal');
	}
	renderDungeonDifficultyUI();
}
