 gameState.firstDungeonLessonSeen=true;
 gameState.firstAdventureGuidesSeen??={quest:false,normal:false,mugen:false};
 gameState.firstAdventureGuidesSeen.normal=true;
 if(hasProgressionUnlock('mugenDungeon'))gameState.firstAdventureGuidesSeen.mugen=true;
