function setStarterPartyFormation(members){
  const fronts=[],backs=[];
  for(const member of members){
    const backJob=['mage','priest','alchemist','supply'].includes(member.jobType);
    if(backJob||member.jobType==='scout'&&isBowEquipped(member))backs.push(member);
    else fronts.push(member);
  }
  gameState.party=[...fronts,...backs];
  gameState.formationFrontCount=Math.max(1,Math.min(5,fronts.length));
  gameState.formationActiveCount=Math.min(6,members.length);
}
