	halo.addColorStop(1,'rgba(20,22,23,0)');
	ctx.fillStyle=halo;
	ctx.fillRect(left-ww*.18,top-hh*.42,ww*1.36,hh*1.84);

	ctx.beginPath();
	ctx.rect(left,top,ww,hh);
	ctx.clip();

	const fog=ctx.createRadialGradient(cx,cy,0,cx,cy,Math.max(ww*.58,hh*1.35));
	fog.addColorStop(0,'rgba(112,124,128,.24)');
	fog.addColorStop(.48,'rgba(67,74,77,.27)');
	fog.addColorStop(1,'rgba(19,22,23,.52)');
	ctx.fillStyle=fog;
	ctx.fillRect(left,top,ww,hh);

	ctx.lineWidth=.65;
	ctx.strokeStyle='rgba(190,199,194,.10)';
	for(let i=0;i<6;i++){
		const t=(i+1)/7;
		const y=top+hh*t;
		const inset=ww*(i%2?.08:.15);
		ctx.beginPath();
		ctx.moveTo(left+inset,y);
		ctx.quadraticCurveTo(cx,y+hh*(i%2?.025:-.018),right-inset,y);
		ctx.stroke();
	}

	// 固定配置の微細な霞点。ランダムを使わないので再描画時にもちらつかない。
	ctx.fillStyle='rgba(205,212,208,.075)';
	const dots=[
		[.18,.24],[.37,.17],[.61,.29],[.82,.20],
		[.26,.48],[.53,.43],[.74,.54],
		[.15,.72],[.42,.67],[.65,.78],[.86,.69]
	];
