function openCurrentQuestInfo(){
	const d=gameState.dungeon;if(!d||gameState.inBattle)return;
	const modal=document.getElementById('current-quest-modal'),title=document.getElementById('current-quest-title'),body=document.getElementById('current-quest-body'),brief=document.getElementById('current-quest-brief');
	if(!modal||!body||!brief)return;
	body.style.whiteSpace='pre-wrap';
	if(d.questInstance){
		if(title)title.textContent='現在の依頼';
		const q=findQuestById(d.questId),progress=d.summonaMissionId?getSummonaMissionFloorProgress(d):null;
		const investigations=progress?.rule?Math.max(0,progress.required-progress.count):0;
		const objective=d.questObjectivePlaced&&d.questObjectiveFloor===d.currentDepth&&!isQuestRetreatPhase(d)?1:0;
		const remaining=investigations+objective;
		body.textContent=`${q?.title||d.questTitle||'依頼'}\nB${d.currentDepth}F の残りのTarget：${remaining}件${isQuestRetreatPhase(d)?'（帰還中）':''}\n目的：${q?getQuestClearGoal(q):d.questObjectiveName||'調査して帰還する'}`;
		brief.style.display=q?'':'none';brief.onclick=()=>{modal.style.display='none';if(q)renderQuestInfoModal(q,'review',d);};
	}else if(d.dungeonKind==='normal'){
		if(title)title.textContent='迷宮情報';
		const words=getDungeonNormalWords(d);
		body.style.whiteSpace='normal';
		body.innerHTML=getNormalDungeonForecastHtml(words)||`<div>${escapeHtml(d.name||'通常迷宮')}</div><div>調査記録を照合できない。</div>`;
		brief.style.display='none';
	}else if(d.dungeonKind==='mugen'){
		if(title)title.textContent='迷宮情報';
		const cards=Array.isArray(d.mugenChosenCards)?d.mugenChosenCards:[];
		const definitions=[...MUGEN_FLOOR_RISK_CARDS,...MUGEN_FLOOR_AID_CARDS];
		const effects=cards.map(choice=>{
			const definition=definitions.find(card=>card.id===choice?.id);
			if(!definition)return '';
			const floor=Math.max(1,Math.floor(Number(choice.floor)||1));
			return `<div style="padding:6px 7px;margin-top:5px;background:#1d231c;border-left:3px solid ${definition.kind==='risk'?'#bb766b':'#79af83'};"><b>${definition.kind==='risk'?'⚠️':'✨'} ${escapeHtml(definition.name)}</b> <span style="color:#aaa;">B${floor}Fで選択</span><br>${escapeHtml(definition.desc)}</div>`;
		}).filter(Boolean).join('');
		const minorMutations=getMugenActiveMinorMutations(d);
		const minorGroups=new Map();
		minorMutations.forEach(m=>{
			const row=minorGroups.get(m.id)||{mutation:m,count:0,floors:[]};
			row.count++;row.floors.push(m.sourceFloor);minorGroups.set(m.id,row);
		});
		const minorEffects=[...minorGroups.values()].map(({mutation:m,count,floors})=>{
			const icon=m.kind==='risk'?'⚠️':m.kind==='aid'?'✨':'◆';
			const border=m.kind==='risk'?'#8d625b':m.kind==='aid'?'#5f8267':'#6d7180';
			const stack=count>1?` ×${count}`:'';
			const firstFloor=Math.min(...floors);
			return `<div style="padding:5px 7px;margin-top:4px;background:#181b1d;border-left:3px solid ${border};"><b>🔹 ${icon} ${escapeHtml(m.name)}${stack}</b> <span style="color:#888;">B${firstFloor}F～</span><br>${escapeHtml(m.desc)}</div>`;
		}).join('');
		body.style.whiteSpace='normal';
		body.innerHTML=`<div><b>${escapeHtml(d.customInput||d.name||'夢幻迷宮')}</b>　B${Math.max(1,Math.floor(Number(d.currentDepth)||1))}F</div><div style="margin-top:6px;color:#ead79a;">現在の階層効果</div>${effects||'<div style="color:#aaa;">まだ階層効果は選択されていない。</div>'}${effects?`<div style="margin-top:8px;color:#c5d9bd;">${getMugenRewardTrendText(d)}</div>`:''}<div style="margin-top:10px;color:#b9cee0;">小変異（累積）</div>${minorEffects||'<div style="color:#888;">小変異は発生していない。</div>'}`;
		brief.style.display='none';
	}else{
		if(title)title.textContent='探索中の迷宮';
		body.textContent=`侵入ワード：${(d.wordNames||[]).join('・')||d.customInput||d.customDungeonKey||d.name||'—'}\n目的：各階層を調査し、記録と戦利品を持って帰還する。`;
		brief.style.display='none';
	}
	modal.style.display='flex';
}
