function getFieldHealingCards(char){
	if(!char||char.hp<=0)return[];
	return getCharacterDeck(char).filter(card=>card&&['heal','wild_heal'].includes(card.type)
		&&!hasCompositePrimaryAndSideEffect(card)&&getCardUses(card)>0).map(card=>({
		card,power:Math.max(1,Math.floor((char.mdef||1)*Math.max(0.1,1+(Number(card.ratio)||0)))),
		remaining:getCardUses(card)
	}));
}
// 目標HPまで、まず使用枚数を最小化し、同数なら過剰回復が少ない組合せを選ぶ。
function planFieldHealing(targetMissing,sources){
	const goal=Math.max(0,Math.floor(targetMissing));
	if(!goal||!sources.length)return[];
	const groups=[];
	for(let index=0;index<sources.length;index++){
		const source=sources[index];
		let count=Math.min(Number.isFinite(source.remaining)?source.remaining:Math.ceil(goal/source.power),Math.ceil(goal/source.power));
		for(let size=1;count>0;size*=2){
			const take=Math.min(size,count);
			groups.push({index,quantity:take,power:source.power*take});
			count-=take;
		}
	}
	const unreachable=32767,counts=new Int16Array(goal+1),amounts=new Int32Array(goal+1),history=[];
	counts.fill(unreachable);counts[0]=0;
	for(const group of groups){
		const previous=new Int32Array(goal+1);previous.fill(-1);
		for(let at=goal-1;at>=0;at--){
			if(counts[at]===unreachable)continue;
			const next=Math.min(goal,at+group.power),uses=counts[at]+group.quantity,amount=amounts[at]+group.power;
			if(uses<counts[next]||(uses===counts[next]&&amount<amounts[next])){
				counts[next]=uses;amounts[next]=amount;previous[next]=at;
			}
		}
		history.push(previous);
	}
	let at=goal;
	if(counts[at]===unreachable){
		for(at=goal-1;at>0&&counts[at]===unreachable;at--){}
	}
	const selected=[];
	for(let i=groups.length-1;i>=0;i--){
		const before=history[i][at];
		if(before<0)continue;
		selected.push(groups[i]);at=before;
	}
	return selected;
}
function buildFieldHealingPlan(targets,sources,smallFirst=false){
	const remaining=sources.map(source=>source.remaining),actions=[];
	let full=0,healed=0,uses=0,waste=0;
	const ordered=[...targets].sort((a,b)=>{
		const diff=(getHealthyHpLimit(b)-b.hp)-(getHealthyHpLimit(a)-a.hp);
		return smallFirst?-diff:diff;
	});
	for(const target of ordered){
		let missing=getHealthyHpLimit(target)-target.hp;
		const available=sources.map((source,index)=>({...source,remaining:remaining[index],index})).filter(source=>source.remaining>0);
		const chosen=planFieldHealing(missing,available).sort((a,b)=>a.power-b.power);
		for(const group of chosen){
			const source=available[group.index];
			for(let n=0;n<group.quantity&&missing>0;n++){
				const actual=Math.min(missing,source.power);
				actions.push({target,source:sources[source.index]});
				missing-=actual;healed+=actual;uses++;waste+=source.power-actual;
				if(Number.isFinite(remaining[source.index]))remaining[source.index]--;
			}
		}
		if(missing<=0)full++;
	}
	return{actions,full,healed,uses,waste};
}
function useDungeonStatusHealing(charIdx){
	if(!gameState?.dungeon||gameState.inBattle)return;
	const char=gameState.party?.[charIdx],sources=getFieldHealingCards(char);
	if(!sources.length)return;
	const targets=(gameState.party||[]).filter(member=>member?.hp>0&&member.hp<getHealthyHpLimit(member));
	if(!targets.length){showGameNotice('通常HPは全員満タンです。負傷による上限は回復札では戻せません。',{title:'回復を使う'});return;}
	const plans=[buildFieldHealingPlan(targets,sources),buildFieldHealingPlan(targets,sources,true)];
	plans.sort((a,b)=>b.full-a.full||b.healed-a.healed||a.uses-b.uses||a.waste-b.waste);
	const used=new Map();let totalHealed=0;
	for(const {target,source} of plans[0].actions){
		const healed=healNormalHp(target,source.power);
		if(healed<=0)continue;
		spendCardUse(source.card);
		used.set(source.card,(used.get(source.card)||0)+1);
		totalHealed+=healed;
	}
	if(!used.size){showGameNotice('回復できるHPがありません。',{title:'回復を使う'});return;}
	const totals=new Map();
	for(const [card,count] of used){
		const key=card.name,entry=totals.get(key)||{count:0,remaining:0};
		entry.count+=count;
		totals.set(key,entry);
	}
	for(const card of getCharacterDeck(char)){
		const entry=totals.get(card?.name);
		if(entry&&['heal','wild_heal'].includes(card.type)&&!hasCompositePrimaryAndSideEffect(card))entry.remaining+=getCardUses(card);
	}
	const summary=[...totals].map(([name,entry])=>`・${name}を${entry.count}回使用しました。（残り：${Number.isFinite(entry.remaining)?entry.remaining:'∞'}回）`);
	const remaining=gameState.party.filter(member=>member?.hp>0&&member.hp<getHealthyHpLimit(member)).length;
	log(`✨ 【${escapeHtml(char.name)}】の回復札で隊のHPを合計 ${totalHealed} 回復した。`);
	updatePartyUI();renderDungeonStatusModal();saveGame();
	showGameNotice(`【${char.name}】が隊のHPを合計 ${totalHealed} 回復しました。\n使用した札：\n${summary.join('\n')}${remaining?`\n残り${remaining}人は札の回数が足りず、全回復できませんでした。`:''}`,{title:'回復の結果'});
}
