function setNpcBattleTactic(index,tactic){
	const char=gameState.party?.[index];
	if(!char||char.isPlayer||!['cooperate','finish','rear','spread'].includes(tactic))return;
	char.battleTactic=tactic;
	saveGame();
}
function closeDungeonStatusModal(){hideModalById('dungeon-status-modal');
}
function useDungeonStatusSupply(type){
	if(!gameState.dungeon||gameState.inBattle)return;
	const source=getDungeonStatusSupplies()[type]?.[0];
	if(!source)return;
	useConsumableInField(source.charIdx,source.index);
	if(document.getElementById('dungeon-status-modal')?.style.display==='flex')renderDungeonStatusModal();
}
let dungeonDeckLongPressTimer=null;
let dungeonDeckLongPressState=null;
function beginDungeonDeckCardLongPress(event,charIdx,cardIdx){
	if(event.target.closest('button,select'))return;
	if(event.pointerType==='mouse'&&event.button!==0)return;
	cancelDungeonDeckCardLongPress();
	dungeonDeckLongPressState={charIdx,cardIdx,pointerId:event.pointerId,x:event.clientX,y:event.clientY};
	dungeonDeckLongPressTimer=setTimeout(()=>{
		const state=dungeonDeckLongPressState;
		dungeonDeckLongPressTimer=null;
		if(!state)return;
		openDungeonDeckCardDetailModal(state.charIdx,state.cardIdx);
		if(navigator.vibrate)navigator.vibrate(18);
	},550);
}
function moveDungeonDeckCardLongPress(event){
	const state=dungeonDeckLongPressState;
	if(!state||state.pointerId!==event.pointerId)return;
	if(Math.hypot(event.clientX-state.x,event.clientY-state.y)>10)cancelDungeonDeckCardLongPress();
}
function cancelDungeonDeckCardLongPress(){
	if(dungeonDeckLongPressTimer)clearTimeout(dungeonDeckLongPressTimer);
	dungeonDeckLongPressTimer=null;
	dungeonDeckLongPressState=null;
}
function openDungeonDeckCardDetailModal(charIdx,cardIdx){
	const char=gameState.party?.[charIdx];
	if(!char)return;
	const deck=getCharacterDeck(char);
	const card=deck?.[cardIdx];
	if(!card)return;
	const modal=document.getElementById('storage-card-detail-modal');
	const title=document.getElementById('storage-card-detail-title');
	const meta=document.getElementById('storage-card-detail-meta');
	const effect=document.getElementById('storage-card-detail-effect');
	if(!modal||!title||!meta||!effect)return;
	const rarity=cardEffectiveRarity(card);
	title.textContent=`${card.suit||''} ${card.name||'カード'}`.trim();
	title.style.color=getRarityColor(rarity);
	const metaParts=[];
	const mana=getStorageCardManaText(card);
	if(mana)metaParts.push(mana);
	if((card.level||1)>1)metaParts.push(`Lv.${card.level}`);
	if(isBattleMaterialCard(card)){
		metaParts.push(`素材価値 ${Math.max(0,Math.floor(Number(card.sellPrice)||0))}G`);
		if(card.bundledMaterial&&Number(card.sourceMaterialCount)>1)metaParts.push(`素材${Math.floor(card.sourceMaterialCount)}個分`);
	}
	if(card.category==='legacy'&&card.expiresAt)metaParts.push(legacyExpiryText(card.expiresAt));
	meta.textContent=metaParts.join('　')||'効果全文';
	effect.textContent=getStorageCardFullText(card);
	modal.style.display='flex';
}
function setupDungeonDeckMarquees(){
	document.querySelectorAll('#dungeon-deck-list .storage-card-name-viewport, #dungeon-deck-list .storage-card-effect-viewport').forEach(viewport=>{
		const text=viewport.querySelector('.storage-card-name-text, .storage-card-effect-text');
		if(!text)return;
		viewport.classList.remove('is-overflowing');
		viewport.style.removeProperty('--storage-scroll-distance');
		viewport.style.removeProperty('--storage-marquee-duration');
		const distance=Math.max(0,text.scrollWidth-viewport.clientWidth);
		if(distance<=1)return;
		viewport.style.setProperty('--storage-scroll-distance',`${Math.ceil(distance)}px`);
		viewport.style.setProperty('--storage-marquee-duration',`${Math.max(5,Math.min(12,4+distance/18)).toFixed(1)}s`);
		viewport.classList.add('is-overflowing');
	});
}
function renderDungeonDeckList(){
	updatePartyPositions();
	const targetChar=gameState.party[selectedDungeonDeckCharIdx];
	if(!targetChar)return;
	const deckList=getCharacterDeck(targetChar);
	const maxLimit=getDeckMaximum(targetChar);
	document.getElementById('dungeon-deck-count').innerText=`${deckList.length}/${maxLimit}`;
	let selectHtml=`<select id="dungeon-char-select" onchange="selectedDungeonDeckCharIdx=parseInt(this.value); renderDungeonDeckList();" style="padding:3px 5px;font-size:11px;background:#222;color:#fff;border:1px solid #555;border-radius:3px;min-width:0;max-width:100%;">`;
	gameState.party.forEach((c,idx)=>{
		if(c.position==='front'||c.position==='back'){
			selectHtml+=`<option value="${idx}" ${idx==selectedDungeonDeckCharIdx?'selected':''}>${escapeHtml(c.name)} (${escapeHtml(c.job)})</option>`;
		}
	});
	selectHtml+=`</select>`;
	const listEl=document.getElementById('dungeon-deck-list');
	let contentHtml=`<div style="display:flex;align-items:center;gap:5px;margin-bottom:2px;font-size:11px;"><span style="color:#aaa;flex:0 0 auto;">対象</span>${selectHtml}</div><div style="padding:5px 7px;margin-bottom:4px;background:#1b242a;border:1px solid #425363;border-radius:4px;">${getPartyAttackReachHtml(targetChar)}</div>`;
	contentHtml+=deckList.length?deckList.map((card,idx)=>{
		const isConsumable=card.category==='consumable';
		const rarity=cardEffectiveRarity(card);
		const color=getRarityColor(rarity);
		const mana=getStorageCardManaText(card);
		const materialSell=isBattleMaterialCard(card)?Math.max(0,Math.floor(Number(card.sellPrice)||0)):null;
		const uses=cardUseText(card);
		const rightMeta=uses?`<span class="storage-card-extra-meta">${uses}</span>`:materialSell!==null?`<span class="storage-card-extra-meta" style="color:#ffd700;">素材価値 ${materialSell}G</span>`:(mana?`<span class="inventory-card-mana">${mana}</span>`:'<span></span>');
		const compactEffect=materialSell!==null
			?(card.bundledMaterial&&Number(card.sourceMaterialCount)>1?`素材 ${Math.floor(card.sourceMaterialCount)}個分`:'素材')
			:getCardExplorerEffectText(card,{includeMana:false,includeUses:false});
		let actionBtns='';
		if((card.type==='heal'||card.type==='wild_heal')&&targetChar.hp>0)actionBtns+=`<button onclick="useHealingCardInField(${selectedDungeonDeckCharIdx},${idx})" style="background:#286047;">回復</button>`;
		if(isConsumable&&!card.passive)actionBtns+=`<button onclick="useConsumableInField(${selectedDungeonDeckCharIdx},${idx})" style="background:#2a5a2a;">使う</button>`;
		if(canMoveCardInField(card))actionBtns+=`<button onclick="discardCardInFieldFromChar(${selectedDungeonDeckCharIdx},${idx})" style="background:#622;">破棄</button>`;
		return `<div class="inventory-card-row dungeon-card-row"
      onpointerdown="beginDungeonDeckCardLongPress(event,${selectedDungeonDeckCharIdx},${idx})"
      onpointermove="moveDungeonDeckCardLongPress(event)"
      onpointerup="cancelDungeonDeckCardLongPress()"
      onpointercancel="cancelDungeonDeckCardLongPress()"
      onpointerleave="if(event.pointerType==='mouse') cancelDungeonDeckCardLongPress()"
      oncontextmenu="if(!event.target.closest('button,select')) openDungeonDeckCardDetailModal(${selectedDungeonDeckCharIdx},${idx});return false;" style="border-left:3px solid ${color};">
        <div class="inventory-card-head">
          <span>${escapeHtml(card.suit||'—')}</span>
          <span class="storage-card-name-viewport"><b class="storage-card-name-text" style="color:${color};">${escapeHtml(card.name||'カード')}</b></span>
          ${rightMeta}
        </div>
        <div class="storage-card-subline">
          <div class="storage-card-effect-viewport"><span class="inventory-card-effect storage-card-effect-text">${escapeHtml(compactEffect)}</span></div>
          ${(card.level||1)>1?`<span class="storage-card-extra-meta" style="color:#d4af37;">Lv.${card.level}</span>`:''}
        </div>
        ${actionBtns?`<div class="dungeon-card-actions">${actionBtns}</div>`:''}
      </div>`;
	}).join(''):`<div style="font-size:11px;color:#666;text-align:center;margin-top:8px;">カードがありません</div>`;
	listEl.innerHTML=contentHtml;
	requestAnimationFrame(setupDungeonDeckMarquees);
}
function useHealingCardInField(charIdx,index){
 if(gameState.inBattle||!gameState.dungeon)return;
 const char=gameState.party[charIdx],card=char&&getCharacterDeck(char)[index];
 if(!char||char.hp<=0||!card||!['heal','wild_heal'].includes(card.type))return;
 const targets=gameState.party.filter(member=>member.hp>0&&member.hp<getHealthyHpLimit(member)).sort((a,b)=>a.hp-b.hp);
 if(!targets.length){
  const injured=gameState.party.some(member=>member.hp>0&&(member.injury||0)>0);
  showGameNotice(injured?'回復できる通常HPがありません。負傷による上限は回復魔法では戻せません。ポーションで治療してください。':'パーティ全員のHPは満タンです。',{title:'回復魔法'});
  return;
 }
 const beforeUses=getCardUses(card), exhausted=beforeUses===0;
 const power=exhausted?1:Math.max(1,Math.floor((char.mdef||1)*Math.max(0.1,1+(Number(card.ratio)||0))));
 const target=targets[0];
 const healed=healNormalHp(target,power);
 if(healed<=0)return;
 spendCardUse(card);
 log(`✨ 【${escapeHtml(char.name)}】が［${escapeHtml(card.name)}］で【${escapeHtml(target.name)}】のHPを ${healed} 回復した。`);
 updatePartyUI();renderDungeonDeckList();saveGame();
}
function getDungeonReturnConfirmationText(d,usesFeather=false){
	const action=usesFeather?'帰還の羽を1枚使って町へ戻りますか？':'入口の階段から町へ戻りますか？';
	if(d?.externalRescue)return `${action}\nこの救助依頼は失敗となり、再挑戦できません。拾った品と素材は持ち帰れます。`;
	if(d?.questInstance)return `${action}\n依頼は中断されます。${getQuestLootReturnText(!!d.summonaArchiveReplay)}挑戦回数は消費しません。`;
	return `${action}\nこの探索を終了し、持ち帰った品を整理します。`;
}
