function isCurrentDownStairGuarded(d){
	if(!d||d.isTreasureRoom)return false;
	if(d.questInstance)return false;
	const depth=Math.max(1,Number(d.currentDepth)||1);
	const maxDepth=Math.max(depth,Number(d.maxDepth)||depth);
	if(d.customDungeon&&typeof customFloorHasBossMarker==='function'){
		return customFloorHasBossMarker(d,depth)&&!isCustomBossDefeatedOnFloor(d,depth);
	}
	if(depth>=maxDepth){
		return d.hasBoss!==false&&!d.bossDefeated;
	}
	if(!d.isTutorial&&d.dungeonKind!=='fixed'){
		return!isStrongEnemyDefeatedOnFloor(d,depth);
	}
	return false;
}
function handleTutorialStairs(d,direction){
 if(!gameState.tutorialState?.active||!d?.isTutorial)return false;
 const ts=gameState.tutorialState;
 if(direction==='up'){
  if(d.currentDepth===1){showSummonaGuide('cannotExitTutorial');return true;}
  const target=d.currentDepth-1;
  runDungeonFloorTransition({d,targetDepth:target},()=>{
   ts.floor=target;loadTutorialFloor(ts.floor,true);window.MugenSE?.playStairs('up');saveGame();
  });
  return true;
 }
 if(direction!=='down')return false;
 if(d.currentDepth===1&&!ts.firstBattleCompleted){
  showTutorialTip('まだ近くに敵がいるね。地図で位置を確かめて、一度一緒に戦ってみよう。','サモナ');return true;
 }
 if(d.currentDepth===2&&(!ts.gateOpened||!ts.lessonChestOpened||!ts.explorationLessonSeen||!ts.springLessonCompleted)){
  showTutorialTip('この階の確認がまだ残っているね。スイッチで扉を開き、宝箱を開けて、泉で一度休んでから進もう。地図は画面を約0.5秒長押しすると開けるよ。','サモナ');return true;
 }
 if(d.currentDepth<3){
  const target=d.currentDepth+1;
  runDungeonFloorTransition({d,targetDepth:target},()=>{
   ts.floor=target;loadTutorialFloor(ts.floor,false);window.MugenSE?.playStairs('down');clearLog();
   log(`⬇️ ${ts.floor}Fに到達した。`);saveGame();
  },()=>{
   if(!gameState.tutorialState?.active)return;
   if(ts.floor===2)showTutorialExplorationLesson();
   else showSummonaGuide('finalFloor');
  });
  return true;
 }
 if(!ts.cargoLessonSeen){showTutorialTip('この階の敵と戦い、荷物を抱えた時の動きも確かめておこう。','サモナ');return true;}
 if(!d.bossDefeated)showSummonaGuide('beforeBoss');else runDungeonFloorTransition({d,kind:'treasure'},()=>{enterTreasureRoom();window.MugenSE?.playStairs('down');});
 return true;
}
function showTutorialExplorationLesson(){
 if(gameState.tutorialState?.explorationLessonSeen)return;
 showTutorialTip('ここは静かだね。先へ進む前に、周りを調べる練習をしよう。<br><br><b>画面を約0.5秒長押し</b>すると地図を開ける。壁に密着した時は「Wall」と表示されるよ。<br><br>すぐ先の<b>スイッチは、そのマスに進むと作動</b>する。扉が開いたら、通路の<b>宝箱</b>まで進んで「宝箱を開ける」を押そう。自動開封の設定なら、その場で開くよ。<br><br>宝箱の先には<b>泉</b>がある。泉のマスで<b>「休む」</b>を押し、回復も試してから次の階へ進もう。','サモナ',{afterClose:()=>{
  if(gameState.tutorialState){gameState.tutorialState.explorationLessonSeen=true;saveGame();}
 }});
}

function findShootLandingPoint(d,endpoints={}){
	if(!d?.map||!Number.isFinite(d.width)||!Number.isFinite(d.height))return null;
	const stairs=[
		[endpoints.startX??d.floorStartX,endpoints.startY??d.floorStartY],
		[endpoints.farX??d.floorFarX,endpoints.farY??d.floorFarY]
	].filter(([x,y])=>Number.isFinite(x)&&Number.isFinite(y));
	const enemies=[
		...(Array.isArray(d.enemySymbols)?d.enemySymbols:[]),
		...(Array.isArray(d.initialEnemyPoints)?d.initialEnemyPoints:[])
	].filter(e=>Number.isFinite(e?.x)&&Number.isFinite(e?.y));
	const candidates=[];
	for(let y=1;y<d.height-1;y++){
		for(let x=1;x<d.width-1;x++){
			if(d.map[y]?.[x]!==0)continue;
			const stairDist=stairs.length?Math.min(...stairs.map(([sx,sy])=>Math.abs(x-sx)+Math.abs(y-sy))):99;
			const enemyDist=enemies.length?Math.min(...enemies.map(e=>Math.abs(x-e.x)+Math.abs(y-e.y))):99;
			candidates.push({x,y,stairDist,enemyDist});
		}
	}
	if(!candidates.length)return null;
	const tiers=[
		p=>p.stairDist>=3&&p.enemyDist>=2,
		p=>p.stairDist>=2&&p.enemyDist>=2,
		p=>p.stairDist>=1&&p.enemyDist>=1,
		()=>true
	];
	for(const accept of tiers){
		const pool=candidates.filter(accept);
		if(pool.length)return pool[Math.floor(Math.random()*pool.length)];
	}
	return candidates[0];
}
function loadDungeonFloorForStairs(d,partyName,entry){

  


	let restored=restoreStoredFloorState(d);
	if(!restored){
		const questReturn=!!(d.questInstance&&isQuestRetreatPhase(d));
		const terrainSeedOwner=getDungeonTerrainSeedOwner(d,partyName);
		const seed=questReturn
			?`${d.specialSeed}::RETURN::${d.questReturnScenario||'collapse'}::${d.currentDepth}F`
			:`${terrainSeedOwner}_${d.name}_${d.currentDepth}F`;
		const objectSeedToken=questReturn
			?`${d.specialSeed}::RETURN::${d.questReturnScenario||'collapse'}::${d.currentDepth}F::objects`
			:(d.questInstance?`${d.specialSeed}::${d.currentDepth}F::objects`:getFreshFloorObjectSeed());
		const baseGeneratedProfile=(entry==='shoot'||questReturn)?{...d,disableGeneratedGimmicks:true}:d;
		const generatedProfile=applyMugenMinorGenerationProfile(d,d.currentDepth,baseGeneratedProfile);
		const floor=questReturn
			?generateFloorMap(d.width,d.height,seed,generatedProfile,objectSeedToken)
			:(d.specialDungeon?generateSpecialFloor(d,d.currentDepth,objectSeedToken,generatedProfile):generateFloorMap(d.width,d.height,seed,generatedProfile,objectSeedToken));
		if(questReturn&&Array.isArray(floor.grid)){
			for(let y=0;y<floor.grid.length;y++)for(let x=0;x<(floor.grid[y]?.length||0);x++){
				if(floor.grid[y][x]===2||floor.grid[y][x]===6)floor.grid[y][x]=0;
			}
		}
		d.map=floor.grid;d.roomMask=floor.roomMask;d.explored=restoreFloorExploration(d,floor);d.trapsMap=floor.trapsMap;
		applyGeneratedFloorRuntime(d,floor);
		legacyDecorateFloor(d);
		restored={endpoints:{startX:floor.startX,startY:floor.startY,farX:floor.farX,farY:floor.farY}};
	}
	legacyMarkVisited(d);
	const endpoints=restored.endpoints||{};
	if(entry==='shoot'){
		const landing=findShootLandingPoint(d,endpoints);
		d.x=landing?.x??endpoints.startX??d.floorStartX??1;
		d.y=landing?.y??endpoints.startY??d.floorStartY??1;
	}else{
		const targetX=entry==='far'?(endpoints.farX??d.floorFarX):(endpoints.startX??d.floorStartX);
		const targetY=entry==='far'?(endpoints.farY??d.floorFarY):(endpoints.startY??d.floorStartY);
		d.x=Number.isFinite(targetX)?targetX:1;
		d.y=Number.isFinite(targetY)?targetY:1;
	}
	clearPrematureSummonaMissionObjective(d);
	if(d.questInstance&&d.currentDepth===d.maxDepth&&Array.isArray(d.map)){
		for(let y=0;y<d.map.length;y++)for(let x=0;x<(d.map[y]?.length||0);x++)if(d.map[y][x]===2)d.map[y][x]=0;
	}
	revealAround(d.x,d.y);
	storeCurrentFloorExploration(d);
	tryScoutRevealNearbyTraps(d);
	storeCurrentFloorState(d);
	placeQuestObjectiveOnCurrentFloor(d);
	placeSummonaMissionInvestigations(d);
	handleSummonaMissionFloorEntry(d);
	updateDungeonView();
	updateStairActionButton();

if(livingEnabledDungeon(d)){livingGetFloorState(d);livingEndFollowerIfNeeded(d);updateDungeonView();updateStairActionButton();}

  if(d?.livingFollower&&d.livingFollower.type!=='escort'&&Number(d.currentDepth)!==Number(d.livingFollower.joinedDepth))livingEndFollowerIfNeeded(d);
  return;

}
async function handleUpStairs(d,partyName){
	if(d.questInstance&&getQuestPhase(d)===QUEST_PHASES.NORMAL_RETURN){
		if(tryStartQuestRetreatEvent(d))return;
		if(d.currentDepth===1){
			if(tryHandleSummonaMissionExitDialogue(d))return;
			runDungeonFloorTransition({d,kind:'exit'},()=>{window.MugenSE?.playStairs('up');finishQuestInstanceSuccess(d);});
			return;
		}
		const target=d.currentDepth-1;
		runDungeonFloorTransition({d,targetDepth:target},()=>{
			legacyCommitCurrentFloorCoverage(d);storeCurrentFloorExploration(d);storeCurrentFloorState(d);
			d.currentDepth=target;loadDungeonFloorForStairs(d,partyName,'far');window.MugenSE?.playStairs('up');
			clearLog();log(`↩️ 来た道を戻り、${d.currentDepth}Fへ。`);if(gameState.dungeon)saveGame();
		});
		return;
	}
	if(d.questInstance&&isQuestRetreatPhase(d)){
		if(d.currentDepth===1){
			if(!isQuestEscapeReady(d)){startQuestEscapeBossBattle();return;}
			if(tryHandleSummonaMissionExitDialogue(d))return;
			runDungeonFloorTransition({d,kind:'exit'},()=>{window.MugenSE?.playStairs('up');finishQuestInstanceSuccess(d);});
			return;
		}
		const target=d.currentDepth-1;
		runDungeonFloorTransition({d,targetDepth:target},()=>{
			legacyCommitCurrentFloorCoverage(d);storeCurrentFloorExploration(d);storeCurrentFloorState(d);
			d.currentDepth=target;loadDungeonFloorForStairs(d,partyName,'far');window.MugenSE?.playStairs('up');
			d.questReturnStoryStep=(Number(d.questReturnStoryStep)||0)+1;clearLog();
			log(`↩️ ${getQuestReturnStepText(d,d.currentDepth)}`);if(gameState.dungeon)saveGame();
		});
		return;
	}
	if(d.currentDepth===1){
		if(!await showGameConfirm('上り階段を発見した。\n'+getDungeonReturnConfirmationText(d),{title:'帰還の確認',confirmText:'帰還する'}))return;
		if(gameState.dungeon!==d)return;
		runDungeonFloorTransition({d,kind:'exit'},()=>{
			log('🏃 登り階段を上がり、迷宮から帰還した！');window.MugenSE?.playStairs('up');escapeDungeon();
		});
		return;
	}
	const target=d.currentDepth-1;
	runDungeonFloorTransition({d,targetDepth:target},()=>{
		legacyCommitCurrentFloorCoverage(d);storeCurrentFloorExploration(d);storeCurrentFloorState(d);
		d.currentDepth=target;loadDungeonFloorForStairs(d,partyName,'far');window.MugenSE?.playStairs('up');
		log(`階段を上り、${d.currentDepth}F に戻った。`);if(gameState.dungeon)saveGame();
	});
}
function completeDownStairTransition(d,partyName){
	if(!d||d.currentDepth>=d.maxDepth)return;
	const target=d.currentDepth+1;
	runDungeonFloorTransition({d,targetDepth:target},()=>{
		d.currentDepth=target;
		if(d.dungeonKind==='mugen')ensureMugenMinorMutationsForFloor(d,d.currentDepth);
		if(gameState.activeAdventureRecord)gameState.activeAdventureRecord.maxDepth=Math.max(gameState.activeAdventureRecord.maxDepth||1,d.currentDepth);
		loadDungeonFloorForStairs(d,partyName,'start');window.MugenSE?.playStairs('down');
		log(`階段を下り、${d.currentDepth}F に到達した！`);
		if(d.dungeonKind==='mugen')logMugenMinorMutationsForFloor(d,d.currentDepth);
		if(gameState.dungeon)saveGame();
	});
}
function handleDownStairs(d,partyName){
	if(d.questInstance&&getSummonaMissionForQuest(findQuestById(d.questId))&&!canLeaveSummonaMissionFloor(d)){const p=getSummonaMissionFloorProgress(d);openSummonaDialogue(`<b>サモナ</b>まだ見ておきたい場所があるよ。あと <b>${Math.max(0,p.required-p.count)}</b> か所だけ確認しよう。`,'サモナ');return;}
	if(d.currentDepth<d.maxDepth){
		if(d.customDungeon&&customFloorHasBossMarker(d,d.currentDepth)&&!isCustomBossDefeatedOnFloor(d,d.currentDepth)){
			log('⬇️ 下り階段を見つけた……しかし守護者が階段を守っている。');
			return;
		}
		if(!d.isTutorial&&!d.customDungeon&&d.dungeonKind!=='fixed'&&d.dungeonKind!=='quest'&&!isStrongEnemyDefeatedOnFloor(d,d.currentDepth)){
			clearLog();
			log('⬇️ 下り階段を見つけた……しかし強敵が階段を守っている。');
			startStrongEnemyBattle();
			return;
		}
		legacyCommitCurrentFloorCoverage(d);
		storeCurrentFloorExploration(d);
		storeCurrentFloorState(d);
		if(d.dungeonKind==='mugen'){
			if(isMugenFloorChoiceResolved(d,d.currentDepth))completeDownStairTransition(d,partyName);
			else offerMugenFloorChoice(d,partyName);
			return;
		}
		completeDownStairTransition(d,partyName);
		return;
	}
	if(d.currentDepth!==d.maxDepth)return;
	if(d.questInstance){
		log(isQuestObjectiveCompleteState(d)?'✅ 依頼目標は達成済みだ。入口へ戻ろう。':'🎯 この階層に依頼目標がある。周囲を捜索しよう。');
		return;
	}
	if(d.customDungeon){
		if(customFloorHasBossMarker(d,d.currentDepth)&&!isCustomBossDefeatedOnFloor(d,d.currentDepth)){
			log('⬇️ 下り階段を見つけた……しかし守護者が階段を守っている。');
			return;
		}
		runDungeonFloorTransition({d,kind:'treasure'},()=>{enterTreasureRoom();window.MugenSE?.playStairs('down');});
	}else if(!d.bossDefeated){
		log('⬇️ 下り階段を見つけた……しかし守護者が階段を守っている。');
		startBossBattle();
	}else{
		runDungeonFloorTransition({d,kind:'treasure'},()=>{enterTreasureRoom();window.MugenSE?.playStairs('down');});
	}
}
function handleStairs(direction){const d=gameState.dungeon,partyName=d?.seedPartyName||gameState.partyName||'無名隊';if(handleTutorialStairs(d,direction))return;if(direction==='up')handleUpStairs(d,partyName);else if(direction==='down')handleDownStairs(d,partyName);}
function isStrongEnemyDefeatedOnFloor(d,depth=d?.currentDepth){
	return!!d?.strongEnemyDefeatedFloors?.[depth];
}
function markStrongEnemyDefeatedOnFloor(d,depth=d?.currentDepth){
	if(!d)return;
	d.strongEnemyDefeatedFloors||={};
	d.strongEnemyDefeatedFloors[depth]=true;
}
function getRareEnemyCategory(d){
	const cats=(d?.topCategories||[]).filter(cat=>ENEMY_DICTIONARY[cat]);
	if(cats.length>=3)return cats[2];
	if(cats.length>=2)return cats[1];
	return cats[0]||'dragon';
}
function pickDungeonEncounterCategory(d){
	const topCats=(d?.topCategories||['beast','undead','demon']).filter(cat=>ENEMY_DICTIONARY[cat]);
	if(!topCats.length)return 'beast';
	const rand=Math.random();
	if(topCats.length>=3)return rand<0.6?topCats[0]:rand<0.9?topCats[1]:topCats[2];
	if(topCats.length===2)return rand<0.6?topCats[0]:topCats[1];
	return topCats[0];
}

// 強敵の取り巻きは3体固定。各個体に役割札を与え、役割札の効果だけ敵専用で常時全体化する。
const STRONG_ESCORT_ROLE_ORDER=Object.freeze(['healer','disruptor','shielder']);
const STRONG_ESCORT_ROLE_CONFIG=Object.freeze({
	healer:Object.freeze({adjective:'献身的な',preferredSuit:'✨',cards:Object.freeze(['m_quick_heal','m_enduring_mend','m_first_aid','m_prayer'])}),
	disruptor:Object.freeze({adjective:'狡猾な',preferredSuit:'🌟',cards:Object.freeze(['m_wild_chip','m_wild_chip','m_focus','m_poison_vial','m_dazzle_smoke','m_stun_bomb','m_curse'])}),
	shielder:Object.freeze({adjective:'堅牢な',preferredSuit:'🛡️',cards:Object.freeze(['m_quick_guard','m_enduring_guard','m_guard','m_balanced_guard','m_tower_shield'])})
});
function getStrongEscortRole(index=0){return STRONG_ESCORT_ROLE_ORDER[Math.max(0,Math.floor(Number(index)||0))%STRONG_ESCORT_ROLE_ORDER.length];}
function getStrongEscortRoleConfig(role){return STRONG_ESCORT_ROLE_CONFIG[role]||STRONG_ESCORT_ROLE_CONFIG.shielder;}
function createStrongEscortRoleDeck(role,category,d){
	const cfg=getStrongEscortRoleConfig(role);
	const deck=buildEnemyDeckFromCardIds(cfg.cards,category,getEnemyCardGradeForDifficulty(d,'N'),getEnemyDangerCardPerformanceMult(d));
	deck.forEach(card=>{card.enemyOnly=true;card.noGrowth=true;card.strongEscortRoleCard=role;});
	return deck;
}
function isStrongEscortRoleAreaCombo(user,cards){
	const role=user?.strongEscortRole;if(!role||!user?.isStrongEscort)return false;
	const list=(cards||[]).filter(Boolean);
	if(!list.some(card=>card?.strongEscortRoleCard===role))return false;
	if(role==='healer')return comboHasHeal(list);
	if(role==='disruptor')return comboHasDisruption(list);
	if(role==='shielder')return comboHasPrimaryShield(list)||list.some(card=>Number(getCardEffectProfile(card).sideGuard)>0);
	return false;
}

// 強敵本体の統率オーラ。本体が生存している間だけ取り巻き3体を強化する。
const STRONG_LEADER_ESCORT_DAMAGE_TAKEN_MULT=0.75;
const STRONG_LEADER_ESCORT_ATTACK_MULT=1.25;
const STRONG_LEADER_ADJECTIVE='威圧的な';
function getLivingStrongLeader(){
	return(battleState?.enemies||[]).find(enemy=>enemy?.isStrongEnemy&&enemy.hp>0)||null;
}
function hasStrongLeaderAura(unit){
	return!!(unit?.isStrongEscort&&getLivingStrongLeader());
}

function getStrongEscortScalingDungeon(d){
	if(!d||d.isTutorial)return d;
	return{...d,areaLevel:Math.max(1,(Number(d.areaLevel)||1)+STRONG_ESCORT_AREA_LEVEL_BONUS)};
}
function createStrongEscortEnemy(d,index=0,options={}){
	const role=options.role||getStrongEscortRole(index);
	const roleConfig=getStrongEscortRoleConfig(role);
	const category=options.category||pickDungeonEncounterCategory(d);
	const list=ENEMY_DICTIONARY[category]||ENEMY_DICTIONARY.beast;
	const enemyData=options.enemyData||list[Math.floor(Math.random()*list.length)]||list[0];
	const depth=d?.currentDepth||1;
	const escortScaleDungeon=getStrongEscortScalingDungeon(d);
	const scales=getEnemyDifficultyScales(escortScaleDungeon,depth);
	const n=ENEMY_BALANCE.normal;
	const mult=enemyData.statMult||{hp:1,atk:1,def:1,matk:1,mdef:1,spd:1};
	Math.random();
	const baseDef=n.defMin+Math.random()*(n.defMax-n.defMin);
	Math.random();
	const baseMdef=n.mdefMin+Math.random()*(n.mdefMax-n.mdefMin);
	const baseSpd=n.spdMin+Math.random()*(n.spdMax-n.spdMin);
	const enemyDef=Math.max(1,Math.floor(baseDef*mult.def*scales.defense));
	const enemyMdef=Math.max(1,Math.floor(baseMdef*mult.mdef*scales.defense));
	const enemyHp=getEnemyTtkTargetHp('normal',escortScaleDungeon,mult,enemyDef,enemyMdef,true);
	const enemy={
		id:`strong_escort_${Date.now()}_${index}`,
		name:`${roleConfig.adjective}${enemyData.name}`,
		category,
		hp:enemyHp,
		atk:getEnemyTargetOffenseStat('normal',escortScaleDungeon,mult,'physical'),
		def:enemyDef,
		matk:getEnemyTargetOffenseStat('normal',escortScaleDungeon,mult,'magical'),
		mdef:enemyMdef,
		spd:Math.max(1,Math.floor(baseSpd*mult.spd*scales.speed)),
		deck:createStrongEscortRoleDeck(role,category,d),
		isPlayer:false,isStrongEscort:true,strongEscortRole:role,strongEscortAreaEffect:true,formationSlot:index+1,position:'front',exp:1,gold:0
	};
	enemy.maxHp=enemy.hp;
	initBattleEntity(enemy);
	return enemy;
}
function startStrongEnemyBattle(options={}){
	const d=gameState.dungeon;resetBattleEnemyReserveState();
	if(!d)return;
	d.isStrongEnemyBattle=true;
	d.isBossBattle=false;
	d.activeMajorBattleType='strong';
	battleState.enemies=[];
	if(!options.livingThug)beginMugenStrongBattleMeasure(d);
	const isQuestTarget=!!(d.questInstance&&d.questMissionKind==='hunt'&&d.questTargetBattle);
	const thug=options.livingThug;
	const category=thug?'humanoid':isQuestTarget&&ENEMY_DICTIONARY[d.questTargetCategory]?d.questTargetCategory:getRareEnemyCategory(d);
	const list=ENEMY_DICTIONARY[category]||ENEMY_DICTIONARY.dragon;
	const depth=d.currentDepth||1;
	const enemyData=(thug?list.find(e=>e.name==='山賊'):isQuestTarget?list.find(e=>e.name===d.questTargetEnemyName):null)||list[(Math.max(1,depth)-1)%list.length]||list[0];
	const mult=enemyData.statMult||{hp:1,atk:1,def:1,matk:1,mdef:1,spd:1};
	const strongScaleDungeon=getMajorEnemyScalingDungeon(d,'strong');
	const scales=getEnemyDifficultyScales(strongScaleDungeon,depth);
	const n=ENEMY_BALANCE.normal;
	const e=ENEMY_BALANCE.strong;
	const repDef=((n.defMin+n.defMax)/ 2)*scales.defense;
	const repMdef=((n.mdefMin+n.mdefMax)/ 2)*scales.defense;
	const repSpd=((n.spdMin+n.spdMax)/ 2)*scales.speed;
	const strongDef=Math.max(1,Math.floor(repDef*mult.def*e.defMult));
	const strongMdef=Math.max(1,Math.floor(repMdef*mult.mdef*e.mdefMult));
	const hp=getEnemyTtkTargetHp('strong',strongScaleDungeon,mult,strongDef,strongMdef,false,depth);
	const enemy={
		id:`strong_${Date.now()}`,
		name:`${STRONG_LEADER_ADJECTIVE}${enemyData.name}`,
		category,
		hp,maxHp:hp,
		atk:getEnemyTargetOffenseStat('strong',strongScaleDungeon,mult,'physical',depth),
		def:strongDef,
		matk:getEnemyTargetOffenseStat('strong',strongScaleDungeon,mult,'magical',depth),
		mdef:strongMdef,
		spd:Math.max(1,Math.floor(repSpd*mult.spd*e.spdMult)),
		deck:createEnemySpeciesDeck(category,enemyData.cards||['m_quick_slash','m_slash','m_guard'],getEnemyCardGradeForDifficulty(d,'R'),getEnemyDangerCardPerformanceMult(d)),
		isPlayer:false,
		isStrongEnemy:true,
		formationSlot:4,position:'back',attackRangePhysical:3,
		pendingTrumpCard:null,
		exp:3,
		gold:0
	};
	if(getCardMaster('m_all_target')&&!enemy.deck.some(card=>card?.masterId==='m_all_target')){
		const areaCard=createEnemyCardInstance('m_all_target',category,getEnemyCardGradeForDifficulty(d,'R'),getEnemyDangerCardPerformanceMult(d));
		if(areaCard){areaCard.enemyOnly=true;areaCard.noGrowth=true;enemy.deck.push(areaCard);}
	}
	const strongTrumpCount=addTrumpCards(enemy.deck,category,getStrongTrumpCount(d.danger),'strong');
	addEnemyTacticCards(enemy.deck,1);
	enemy.strongTrumpCount=strongTrumpCount;
	initBattleEntity(enemy);
	// 強敵本体は通常シールドのみ。isTreasureGuardianを持たないため、守護者のブレイク硬直・再展開・能力上昇は発生しない。
	enemy.initialGuard=Math.max(0,Math.floor(
		(Math.floor(getSummonaMissionShieldReferenceHp(d,hp,'strong')*e.initialGuardHpRatio)+Math.floor((enemy.def+enemy.mdef)/ 3))
		*getEnemyInitialGuardDifficultyMult(d)
	));
	enemy.guard=enemy.initialGuard;
	battleState.enemies.push(enemy);
	const escortOptions=thug?{category:'humanoid',enemyData}:{};
	battleState.enemies.push(createStrongEscortEnemy(d,0,escortOptions),createStrongEscortEnemy(d,1,escortOptions),createStrongEscortEnemy(d,2,escortOptions));
	// UI・戦闘開始ログ・保存が走る前に、一団全員をゴロツキとして確定する。
	if(thug){
		battleState.enemies.forEach((unit,index)=>{
			if(index===0)unit.name=`${STRONG_LEADER_ADJECTIVE}ゴロツキ`;
			else unit.name=`${getStrongEscortRoleConfig(unit.strongEscortRole).adjective}ゴロツキ`;
			unit.category='humanoid';unit.isLivingThug=true;
		});
		log('⚔️ ゴロツキの集団に絡まれた！');
	}else log(isQuestTarget?`🎯 討伐対象【${enemy.name}】が前衛の魔物3体を従えて現れた！`:`⚔️ 【強敵】${enemy.name} が後衛に控え、前衛の魔物3体とともに次層への道を塞いでいる！`);
	log(`👑 【${enemy.name}】の統率：生存中、取り巻きは被ダメージ25%軽減・攻撃25%上昇。`);
	initBattle();
}
function getBossBaseEnemyData(category){const list=ENEMY_DICTIONARY[category]||ENEMY_DICTIONARY.dragon;return list[0]||{name:'ドラゴン',statMult:{hp:1,atk:1,def:1,matk:1,mdef:1,spd:1},cards:['m_quick_slash','m_slash','m_guard']};}
function normalizeGuardianEnemyData(raw,fallbackCategory='dragon'){
	if(!raw||typeof raw!=='object')return null;
	const category=ENEMY_DICTIONARY[raw.category]?raw.category:fallbackCategory;
	const fallback=getBossBaseEnemyData(category);
	const baseMult={hp:1,atk:1,def:1,matk:1,mdef:1,spd:1};
	return{
		...fallback,
		...raw,
		category,
		name:String(raw.name||fallback.name||'守護者'),
		statMult:{...baseMult,...(fallback.statMult||{}),...(raw.statMult||{})},
		cards:Array.isArray(raw.cards)&&raw.cards.length?[...raw.cards]:[...(fallback.cards||['m_quick_slash','m_slash','m_guard'])],
		stats:raw.stats&&typeof raw.stats==='object'?{...raw.stats}:null,
		customGuardian:true
	};
}
function getCustomDungeonGuardianData(d,depth=d?.currentDepth){
	if(d?.mugenSecretArena){
		const secret=getMugenSecretBossWordDefinition(d.mugenSecretBossWord);
		if(!secret||!d.mugenSecretBossUnlocked)return null;
		return normalizeGuardianEnemyData({
			category:secret.category,name:secret.bossName,statMult:{...(secret.statMult||{})},
			cards:[...(secret.cards||[])],trumpCount:Number(secret.trumpCount)||3,mugenSecretBoss:true
		},secret.category);
	}
	if(!d?.customDungeonKey)return null;
	const def=CUSTOM_DUNGEONS[d.customDungeonKey];
	if(!def)return null;
	const byFloor=def.guardians&&typeof def.guardians==='object'?def.guardians[depth]:null;
	const raw=byFloor||(Number(depth)===Number(d.maxDepth)?def.guardian:null);
	if(!raw)return null;
	const fallbackCategory=(d.topCategories&&d.topCategories[0])||'dragon';
	return normalizeGuardianEnemyData(raw,fallbackCategory);
}
function applyGuardianFixedStatOverrides(stats,base){
	const out={...stats};
	const fixed=base?.stats;
	if(!fixed||typeof fixed!=='object')return out;
	['hp','atk','def','matk','mdef','spd'].forEach(key=>{
		const value=Number(fixed[key]);
		if(Number.isFinite(value))out[key]=Math.max(1,Math.floor(value));
	});
	return out;
}
function calculateTreasureBossStats(d,base,depth){
	const m=base.statMult||{hp:1,atk:1,def:1,matk:1,mdef:1,spd:1};
	if(d.isTutorial){
    const tutorialScale=Math.max(1,depth);
		const def=Math.max(1,Math.floor(4*m.def*tutorialScale));
		const mdef=Math.max(1,Math.floor(4*m.mdef*tutorialScale));
		return{
			hp:getTutorialEnemyTargetHp('guardian',m,def,mdef,false),
			atk:getTutorialEnemyTargetOffenseStat('guardian',m,'physical'),
			def,
			matk:getTutorialEnemyTargetOffenseStat('guardian',m,'magical'),
			mdef,
			spd:Math.max(1,Math.floor(8*m.spd*tutorialScale))
		};
	}
	const guardianScaleDungeon=getMajorEnemyScalingDungeon(d,'guardian');
	const s=getEnemyDifficultyScales(guardianScaleDungeon,depth),n=ENEMY_BALANCE.normal,b=ENEMY_BALANCE.boss;
	const def=Math.max(1,Math.floor(((n.defMin+n.defMax)/2)*s.defense*m.def*b.defMult));
	const mdef=Math.max(1,Math.floor(((n.mdefMin+n.mdefMax)/2)*s.defense*m.mdef*b.mdefMult));
	const hp=getEnemyTtkTargetHp('guardian',guardianScaleDungeon,m,def,mdef,false,depth);
	return{hp,atk:getEnemyTargetOffenseStat('guardian',guardianScaleDungeon,m,'physical',depth),def,matk:getEnemyTargetOffenseStat('guardian',guardianScaleDungeon,m,'magical',depth),mdef,spd:Math.max(1,Math.floor(((n.spdMin+n.spdMax)/2)*s.speed*m.spd*b.spdMult))};
}
function createTreasureBossEntity(d,category,base,stats,depth){
	const cardList=base.cards||['m_quick_slash','m_slash','m_focus'];
	const guardianDeckOptions=base?.customGuardian
		?{preferProvided:true,allowRestrictedCards:!!base.allowRestrictedCards,addAllTarget:base.addAllTarget!==false}
		:{};
	const deck=d.isTutorial
		?buildEnemyDeckFromCardIds(ENEMY_SPECIES_DECKS[category]||cardList,category,'N',1)
		:createGuardianSpeciesDeck(category,cardList,{...guardianDeckOptions,grade:getEnemyCardGradeForDifficulty(d,'SR'),dangerPerformanceMult:getEnemyDangerCardPerformanceMult(d)});
	if(!d.isTutorial)addEnemyTacticCards(deck,1);
	const defaultTrumpCount=d.isTutorial?0:getGuardianTrumpCount(d.danger);
	const requestedTrumpCount=Number(base?.trumpCount);
	const trumpCount=d.isTutorial?0:(Number.isFinite(requestedTrumpCount)?Math.max(0,Math.floor(requestedTrumpCount)):defaultTrumpCount);
	const trumps=trumpCount>0?addTrumpCards(deck,category,trumpCount,'guardian'):0;
	const displayName=base?.customGuardian?base.name:`古の${base.name}`;
	const boss={id:`boss_${Date.now()}`,name:displayName,category,hp:stats.hp,maxHp:stats.hp,atk:stats.atk,def:stats.def,matk:stats.matk,mdef:stats.mdef,spd:stats.spd,deck,isPlayer:false,isBoss:true,isTreasureGuardian:!d.isTutorial,bossTrumpCount:trumps,guardianBreakStunRemaining:0,guardianBreakTriggeredTurn:0,guardianBreakSkipTurn:0,guardianShieldReformTurn:0,guardianShieldReformCount:0,guardianBreakCount:0,guardianActionCounter:0,guardianMarkedTargetId:null,guardianSpecialTelegraphed:false,guardianSpecialTelegraphTurn:0,guardianSpecialReadyTurn:0,guardianSpecialQueuedTurn:0,guardianSpecialIsArea:false,bossRole:'treasureGuardian',exp:d.isTutorial?Math.max(1,Math.floor(3*Math.max(1,(d.areaLevel||1)*depth))):10,gold:0};
	initBattleEntity(boss);
	const baseShield=d.isTutorial
		?getTutorialBossLessonShield(gameState?.player,stats.mdef)
		:Math.floor(getSummonaMissionShieldReferenceHp(d,stats.hp,'guardian',base?.summonaBossMode==='unique')*ENEMY_BALANCE.boss.initialGuardHpRatio)+Math.floor((stats.mdef+stats.def)/2);
	const autoShield=d.isTutorial
		?baseShield
		:Math.max(1,Math.floor(
			baseShield
			*(ENEMY_BALANCE.boss.shieldMult||1.05)
			*getGuardianDangerShieldMult(d)
			*getEnemyInitialGuardDifficultyMult(d)
		));
	const fixedShield=Number(base?.shield);
	const shield=Number.isFinite(fixedShield)?Math.max(0,Math.floor(fixedShield)):autoShield;
	boss.initialGuard=shield;boss.guard=shield;boss.guardianShieldAmount=shield;boss.guardianShieldActiveCap=shield;return boss;
}
function startBossBattle(){
	const d=gameState.dungeon;resetBattleEnemyReserveState();if(!d)return;d.isBossBattle=true;d.isStrongEnemyBattle=false;d.activeMajorBattleType='treasureBoss';battleState.enemies=[];
	const depth=d.currentDepth||d.maxDepth||1;
	const customGuardian=getCustomDungeonGuardianData(d,depth);
	const category=customGuardian?.category||(d.topCategories&&d.topCategories[0])||'dragon';
	const base=customGuardian||getBossBaseEnemyData(category);
	const calculated=calculateTreasureBossStats(d,base,depth);
	const stats=applyGuardianFixedStatOverrides(calculated,base);
	const boss=createTreasureBossEntity(d,category,base,stats,depth);
	if(d.mugenSecretArena){
		boss.name=`【碑文の影】${customGuardian?.name||base.name}`;
		boss.isTreasureGuardian=false;
		boss.bossRole='mugenSecretBoss';
	}
	battleState.enemies.push(boss);
	if(d.mugenSecretArena)log(`📜 赤い石板の奥に【${customGuardian?.name||base.name}】が立っている。`);
	else if(customGuardian)log(`👑 固有守護者【${customGuardian.name}】が立ちはだかった！`);
	initBattle();
	if(d.isTutorial)setTimeout(maybeShowTutorialBossShieldIntro,120);
}
function getOneTimeDungeonRewardKey(d=null){
	const target=d||gameState?.dungeon||null;
	if(!target)return '';
	if(target.isTutorial)return '初めての冒険';
	if(target.dungeonKind==='fixed'||target.customDungeonKey)return target.customDungeonKey||target.name||'';
	return '';
}
// 固有迷宮/チュートリアル報酬は報酬源ごとに一度だけ受取可能。
function ensureOneTimeDungeonRewardClaims(){
	if(!gameState.oneTimeDungeonRewardClaims||typeof gameState.oneTimeDungeonRewardClaims!=='object'||Array.isArray(gameState.oneTimeDungeonRewardClaims)){
		gameState.oneTimeDungeonRewardClaims={};
	}
	Object.keys(gameState.oneTimeDungeonRewardClaims).forEach(key=>{
		const raw=gameState.oneTimeDungeonRewardClaims[key];
		if(!raw||typeof raw!=='object'||Array.isArray(raw)){
			gameState.oneTimeDungeonRewardClaims[key]={allClaimed:!!raw,slots:{}};
			return;
		}
		raw.allClaimed=!!raw.allClaimed;
		if(!raw.slots||typeof raw.slots!=='object'||Array.isArray(raw.slots))raw.slots={};
	});
	return gameState.oneTimeDungeonRewardClaims;
}
function getOneTimeDungeonRewardRecord(key,create=true){
	if(!key)return null;
	const claims=ensureOneTimeDungeonRewardClaims();
	if(!claims[key]&&create)claims[key]={allClaimed:false,slots:{}};
	return claims[key]||null;
}
function isOneTimeDungeonRewardClaimed(d,slotId){
	const key=getOneTimeDungeonRewardKey(d);
	if(!key||!slotId)return false;
	const record=getOneTimeDungeonRewardRecord(key,false);
	return!!(record?.allClaimed||record?.slots?.[slotId]);
}
function markOneTimeDungeonRewardClaimed(d,slotId){
	const key=getOneTimeDungeonRewardKey(d);
	if(!key||!slotId)return false;
	const record=getOneTimeDungeonRewardRecord(key,true);
	if(record.allClaimed||record.slots[slotId])return false;
	record.slots[slotId]=true;
	return true;
}
function getFloorChestRewardSlotId(d,x=d?.x,y=d?.y){
	return `floor:${Math.max(1,Number(d?.currentDepth)||1)}:${Number(x)},${Number(y)}`;
}
function getTreasureChestRewardSlotId(rewardKey){
	return `treasure:${String(rewardKey||'')}`;
}
function getOneTimeDungeonRewardStatusText(key){
	if(!key)return '';
	const record=getOneTimeDungeonRewardRecord(key,false);
	if(record?.allClaimed)return '報酬：受取済み（リプレイ可・再取得なし）';
	const count=Object.keys(record?.slots||{}).length;
	return count>0?`報酬：一部受取済み（${count}件・同じ報酬は再取得不可）`:'報酬：未受取（各報酬は1度のみ）';
}
function getConfiguredTreasureRewards(d){
	if(!d?.customDungeonKey)return null;
	const def=CUSTOM_DUNGEONS[d.customDungeonKey];
	if(!def||!Array.isArray(def.treasureRewards)||def.treasureRewards.length===0)return null;
	return def.treasureRewards.map(reward=>({...reward}));
}
