function toggleSelectCard(index){
	if(battleVisualPlaybackActive||battleState.autoMode||!gameState.inBattle||!gameState.player||gameState.player.hp<=0)return;
	const card=battleState.hand[index];if(!card)return;
	if(isBattleCardForbiddenFor(gameState.player,card)){log('⚠️ このカードは戦闘中には使えません。');return;}
	const player=gameState.player;
	const job=player?.jobType||'';
	const steamer=job==='steamer',jester=job==='clown',monk=job==='monk';
	if(card.category==='reward'&&!canUseBattleMaterial(player,card)){log('⚠️ この報酬カードは戦闘中に使用できません。');return;}
	if(isAlchemistCatalystCard(card)&&!isAlchemistCharacter(player)){log('⚠️ ［触媒］は錬金術師専用です。');return;}
	if(card.category==='legacy'){log('⚠️ レガシーは戦闘札ではなく、装備中に常時作用します。');return;}
	if(card.effect==='return_town'){log('⚠️ 帰還の羽は戦闘中には選択できません。');return;}
	if(card.passive){
		if(card.effect==='nullify_interference')log(`⚠️ ［${card.name}］は手動では使えません。異常・妨害を受けた時に自動で働きます。`);
		else log(`⚠️ ［${card.name}］は手動では使えません。死亡時に自動発動します。`);
		return;
	}
	const mana=player?.mana||0,pos=battleState.selectedIndices.indexOf(index);
	if(pos!==-1){battleState.selectedIndices.splice(pos,1);refreshBattleSelectionLog();updateBattleUI();return;}
	if(getBattleComboManaCost(player,[card])>mana){log(`⚡ マナ不足：${card.name} の実行には ${getBattleComboManaCost(player,[card])} マナ必要です。`);return;}
	const currentlySelected=battleState.selectedIndices.map(idx=>battleState.hand[idx]).filter(Boolean);
	if(isSoloOnlyBattleCard(card)){
		if(currentlySelected.length)log(`🔄 ［${card.name}］は単独使用のため、他の選択を解除しました。`);
		battleState.selectedIndices=[index];refreshBattleSelectionLog();updateBattleUI();maybeShowTutorialCardSelectionTip();return;
	}
	if(currentlySelected.some(isSoloOnlyBattleCard)){
		battleState.selectedIndices=[index];log('🔄 単独使用のカードから選択を切り替えました。');refreshBattleSelectionLog();updateBattleUI();maybeShowTutorialCardSelectionTip();return;
	}
	if(steamer){
		const selected=battleState.selectedIndices.map(idx=>battleState.hand[idx]).filter(Boolean);
		const projected=[...selected,card];
		if(selected.length===0||isValidSteamerPartialSelection(projected)){
			battleState.selectedIndices=selected.length===0?[index]:[...battleState.selectedIndices,index];
		}else{
			battleState.selectedIndices=[index];
			log('🔄 蒸機師のブーストは⚔️物理攻撃＋［蒸気機関］＋ジェムの3枚で組み立てます。');
		}
		refreshBattleSelectionLog();updateBattleUI();maybeShowTutorialCardSelectionTip();
		if(battleState.selectedIndices.length>=3)scheduleCombatAdvancedTip();
		return;
	}
	const replace=(msg)=>{battleState.selectedIndices=[index];if(msg)log(msg);};
	if(!monk&&battleState.selectedIndices.length>=3){replace('🔄 3枚上限のため、選択を入れ替えました。');refreshBattleSelectionLog();updateBattleUI();return;}
	if(!(jester&&card.cost===0)){let suit='🌟';for(const idx of battleState.selectedIndices){const c=battleState.hand[idx];if(!c)continue;if(jester&&c.cost===0)continue;if(c.suit&&!isWildLikeCard(c)){suit=c.suit;break;}}if(suit!=='🌟'&&!isWildLikeCard(card)&&card.suit!==suit){replace(`🔄 ${card.suit} は ${suit} と組み合わせられないため、選択を切り替えました。`);refreshBattleSelectionLog();updateBattleUI();return;}}
	const projectedCards=[...battleState.selectedIndices.map(idx=>battleState.hand[idx]).filter(Boolean),card];
	if(getBattleComboManaCost(player,projectedCards)>mana){replace('🔄 合計マナを超えるため、選択を切り替えました。');refreshBattleSelectionLog();updateBattleUI();return;}
	battleState.selectedIndices.push(index);
	refreshBattleSelectionLog();updateBattleUI();
	maybeShowTutorialCardSelectionTip();
	if(battleState.selectedIndices.length>=3)scheduleCombatAdvancedTip();
}
function getEscapeUnitPower(unit){
	if(!unit||unit.hp<=0||unit.position==='reserve')return 0;
	const maxHp=Math.max(1,Number(unit.maxHp)||Number(unit.hp)||1);
	const hpRatio=Math.max(0,Math.min(1,Number(unit.hp)/ maxHp));
	const effectiveHp=Math.max(1,Number(unit.hp)||0)+Math.max(0,Number(unit.guard)||0)*0.5;
	const stats=Math.max(1,
		(Number(unit.atk)||0)+(Number(unit.matk)||0)
		+(Number(unit.def)||0)+(Number(unit.mdef)||0)
		+(Number(unit.spd)||0)*2
	);
	return Math.sqrt(effectiveHp)*Math.sqrt(stats)*(0.55+hpRatio*0.45);
}
function getBattleEscapeChance(){
	const allies=(gameState.party||[]).filter(unit=>unit&&unit.hp>0&&unit.position!=='reserve');
	const enemies=(battleState.enemies||[]).filter(unit=>unit&&unit.hp>0);
	const allyPower=allies.reduce((sum,unit)=>sum+getEscapeUnitPower(unit),0);
	const enemyPower=enemies.reduce((sum,unit)=>sum+getEscapeUnitPower(unit),0);
	if(allyPower<=0)return 0;
	if(enemyPower<=0)return 1;
	const advantage=allyPower /(allyPower+enemyPower);
	return Math.max(0.20,Math.min(0.90,0.20+advantage*0.70));
}
function isGuaranteedBattleEscape(){
	const d=gameState?.dungeon;
	return!!(d?.isStrongEnemyBattle||d?.isBossBattle
		||(battleState.enemies||[]).some(enemy=>enemy?.isStrongEnemy||enemy?.isBoss||enemy?.isTreasureGuardian));
}
