		generatedFloorCount:1,maxDepth:1,currentDepth:1,width,height,x:startX,y:startY,dir:0,
		topCategories:[secretDef.category],rewardWeights:{weapon:0,armor:0,card:0},areaLevel,danger:2,
		enemyRate:0,chestRate:0,eventRate:0,lootTier:0,noEnemySymbols:true,
		mugenRawDepth:1,mugenOverflowDepth:0,wordResearchPoints:0,mugenWordRewardsResolved:false,
		mugenTrapWeight:0,mugenRewardBias:0,mugenEffects:{enemyOffense:0,enemyDurability:0,enemyDefense:0,enemySpeed:0,stepHealRatio:0,startBarrierRatio:0},
		mugenAdaptation:{rating:'steady',last:null},mugenChosenCards:[],
		specialSeed:`secret::${key}::${partyName}`,map,explored,trapsMap,floorExplored:{1:explored},
