 if(d.isTutorial&&d.currentDepth===2){
  gameState.tutorialState.lessonChestOpened=true;
  showTutorialTip('中身を確保できたね。宝箱は開けて初めて持ち帰れる。<br><br>奥の宝物部屋でも、中央の箱を開けてから<b>青い魔法陣</b>で帰還するんだ。戦いで傷ついた時や札が減った時は、無理をせず帰ることも覚えておこう。','サモナ');
 }

	const oneTimeSlot=getOneTimeDungeonRewardKey(d)?getFloorChestRewardSlotId(d):'';
