	d.pendingMimicReward={minRarity:'SR'};
	battleState.enemies=[];
	const category='construct';
	const base=normalizeGuardianEnemyData({
		name:'貪欲のミミック',category,
		statMult:{hp:1.10,atk:1.10,def:1.00,matk:1.05,mdef:1.00,spd:1.10},
		cards:['m_quick_slash','m_heavy_slash','m_guard','m_dazzle_smoke'],trumpCount:2
	},category);
	const depth=d.currentDepth||1;
	const stats=calculateTreasureBossStats(d,base,depth);
	const mimic=createTreasureBossEntity(d,category,base,stats,depth);
	mimic.name='【ミミック】貪欲の箱';
	mimic.bossRole='mimic';
	mimic.exp=6;
	battleState.enemies.push(mimic);
	clearLog();
	log('🦷 豪華な宝箱が跳ね上がった――ミミックだ！');
