		exp:0,
		cardUsage:createEmptySuitCounters(),
		hp:180,maxHp:180,
		baseAtk:12,baseDef:20,baseMatk:30,baseMdef:30,baseSpd:22,
		atk:12,def:20,matk:30,mdef:30,spd:22,
