function localDayKey(date=new Date()){
	const y=date.getFullYear();
	const m=String(date.getMonth()+1).padStart(2,'0');
	const d=String(date.getDate()).padStart(2,'0');
	return `${y}-${m}-${d}`;
}
function localWeekKey(date=new Date()){
	const x=new Date(date.getFullYear(),date.getMonth(),date.getDate());
	const day=(x.getDay()+6)%7;
	x.setDate(x.getDate()-day);
	return `W-${localDayKey(x)}`;
}
function localMonthKey(date=new Date()){
	const y=date.getFullYear();
	const m=String(date.getMonth()+1).padStart(2,'0');
	return `M-${y}-${m}`;
}
function pickSeeded(rng,arr){return arr[Math.floor(rng()*arr.length)%arr.length];}
function getQuestPartyBaseLevel(){
	const members=(gameState.party||[]).filter(c=>c&&c.hp>0&&c.jobType!=='supply');
	if(!members.length)return Math.max(1,Math.round(Number(gameState.player?.level)||1));
	const levels=members.map(c=>Math.max(1,Number(c.level)||1));
	const avg=levels.reduce((a,b)=>a+b,0)/levels.length;
	const max=Math.max(...levels);
	return Math.max(1,Math.round(avg*0.7+max*0.3));
}


function limitMugenInputLength(input){
	if(!input)return '';
	const clipped=Array.from(String(input.value||'')).slice(0,MUGEN_INPUT_MAX_LENGTH).join('');
	if(input.value!==clipped)input.value=clipped;
	return clipped;
}
function ensureMonthlyMugenInputMemory(){
	const monthKey=localMonthKey();
	let memory=gameState.mugenMonthlyInputMemory;
	if(!memory||memory.monthKey!==monthKey){
		memory={monthKey,entries:[]};
		gameState.mugenMonthlyInputMemory=memory;
	}
	if(!Array.isArray(memory.entries))memory.entries=[];
	const clean=[],seen=new Set();
	for(const raw of memory.entries){
		const entry=typeof raw==='string'?{text:raw,source:'legacy',at:0}:raw;
		const text=Array.from(String(entry?.text||'').trim()).slice(0,MUGEN_INPUT_MAX_LENGTH).join('');
		if(!text||seen.has(text))continue;
		seen.add(text);clean.push({text,source:String(entry?.source||'mugen'),at:Number(entry?.at)||0});
	}
	memory.entries=clean.slice(-MUGEN_MONTHLY_INPUT_LIMIT);
	return memory;
}
function getMonthlyMugenInputWords(){
	return ensureMonthlyMugenInputMemory().entries.map(e=>e.text).filter(Boolean);
}
function rememberMonthlyMugenInput(text,source='mugen'){
	const value=String(text||'').trim();
	if(!value||Array.from(value).length>MUGEN_INPUT_MAX_LENGTH)return false;
	const memory=ensureMonthlyMugenInputMemory();
	const index=memory.entries.findIndex(e=>e?.text===value);
	if(index>=0)memory.entries.splice(index,1);
	memory.entries.push({text:value,source,at:Date.now()});
	if(memory.entries.length>MUGEN_MONTHLY_INPUT_LIMIT)memory.entries.splice(0,memory.entries.length-MUGEN_MONTHLY_INPUT_LIMIT);
	return true;
}

function getPastMugenInputWords(){return getMonthlyMugenInputWords();}
function ensureMonthlyMonolithQuestionWords(q){
	if(!q)return[];const history=getPastMugenInputWords();if(!history.length)return[];
	if(Array.isArray(q.monolithQuestionWords)&&q.monolithQuestionWords.length)return q.monolithQuestionWords;
	const rng=createRNG(stringToSeed(`MONTHLY_MONOLITH_WORDS::${q.id||localMonthKey()}`)),pool=[...history],picks=[];
	while(pool.length&&picks.length<3){const i=Math.floor(rng()*pool.length);picks.push(pool.splice(i,1)[0]);}
	q.monolithQuestionWords=picks;return picks;
}
function getMonthlyMonolithQuestions(q){
	const w=ensureMonthlyMonolithQuestionWords(q);if(!w.length)return[];const a=w[0],b=w[1]||a,c=w[2]||b;
	return [`${a}ってなに？`,a!==b?`${a}と${b}はなにがちがうの？`:`${a}は、どこからきたの？`,`${c}って、あなたにとってなに？`];
}
function chooseMonthlyMonolithRewardWord(q){
	if(q?.monthlyRewardWordId){const e=getAreaWordPickById(q.monthlyRewardWordId);if(e)return e;}
	const candidates=getResearchWordCandidates(Math.max(1,Number(q?.fixedAreaLevel)||1),true);if(!candidates.length)return null;
	const rng=createRNG(stringToSeed(`MONTHLY_MONOLITH_REWARD::${q?.id||localMonthKey()}`)),pick=candidates[Math.floor(rng()*candidates.length)]||candidates[0];
	if(pick?.word?.id)q.monthlyRewardWordId=pick.word.id;return pick;
}
function generateMonthlyQuest(period){
	const generatedPartyLevel=getQuestPartyBaseLevel();
	return ensureQuestDefinition({id:`${period}_monolith_survey`,type:'instance',periodType:'monthly',missionKind:'monolith',requesterName:'ギルド',title:'月間調査任務 ― 深部のモノリス',objectiveName:'深部で確認されたモノリス',targetDepth:6,generatedPartyLevel,fixedAreaLevel:Math.max(1,Math.min(100,Math.round(generatedPartyLevel)+5)),rewardSpec:{type:'diamonds',amount:QUEST_MONTHLY_DIAMOND_REWARD},storyText:QUEST_MONTHLY_STORY,completed:false,claimed:false,accepted:false,failedAttempts:0},false);
}
function getQuestPartyNameSet(){
	return new Set((gameState.party||[]).map(c=>String(c?.name||'').trim()).filter(Boolean));
}
function pickDistinctQuestNpcName(rng,excluded=new Set()){
	const blocked=new Set([...excluded].map(x=>String(x||'').trim()).filter(Boolean));
	const pool=RANDOM_NAMES.filter(name=>!blocked.has(name));
	if(pool.length)return pickSeeded(rng,pool);
	for(let i=1;i<=99;i++){const name=`探索者${i}`;if(!blocked.has(name))return name;}
	return '名もなき探索者';
}
function formatQuestWeeklyText(template,q){
	return String(template||'')
		.replaceAll('{client}',q?.requesterName||'依頼人')
		.replaceAll('{target}',q?.objectiveName||'対象')
		.replaceAll('{enemy}',q?.targetEnemyName||q?.objectiveName||'異常個体');
}
function getWeeklySeriesQuests(seriesId){
	return (gameState.quests?.weekly||[]).filter(q=>q?.seriesId===seriesId).sort((a,b)=>(a.chapterIndex||0)-(b.chapterIndex||0));
}
function isQuestUnlocked(q){
	if(!q)return false;
	if(q.periodType==='weekly'&&!hasProgressionUnlock('weeklyQuest'))return false;
	if(q.periodType==='monthly')return getPastMugenInputWords().length>=QUEST_MONTHLY_MONOLITH_REQUIRED_WORDS;
	if(q.periodType!=='weekly'||!q.seriesId)return true;
	const index=Math.max(0,Math.floor(Number(q.chapterIndex)||0));if(index===0)return true;
	const prev=getWeeklySeriesQuests(q.seriesId).find(x=>(x.chapterIndex||0)===index-1);return!!prev?.claimed;
}


function formatReadableProse(text,sentencesPerParagraph=1){
	const raw=resolvePlayerReferenceText(text??'').trim();
	if(!raw)return '';
	const sentences=(raw.match(/[^。！？!?]+[。！？!?]?/g)||[raw]).map(x=>x.trim()).filter(Boolean);
	const per=Math.max(1,Math.floor(Number(sentencesPerParagraph)||1));
	const groups=[];
	for(let i=0;i<sentences.length;i+=per)groups.push(sentences.slice(i,i+per).join(''));
	return `<div class="readable-prose">${groups.map(p=>`<span class="prose-paragraph">${escapeHtml(p)}</span>`).join('')}</div>`;
}


function getQuestIntroArchetypeText(q){
	const index=Math.max(0,Math.floor(Number(q?.introArchetypeIndex)||0))%QUEST_INTRO_ARCHETYPES.length;
	return formatQuestStory(QUEST_INTRO_ARCHETYPES[index],q);
}
function getQuestCircumstanceText(q){
	const index=Math.max(0,Math.floor(Number(q?.targetCircumstanceIndex)||0))%QUEST_TARGET_CIRCUMSTANCES.length;
	const set=QUEST_TARGET_CIRCUMSTANCES[index]||QUEST_TARGET_CIRCUMSTANCES[0];
	return formatQuestStory(set?.[q?.missionKind]||set?.research||'',q);
}
function getQuestMissionRequestText(q){
	return formatQuestStory(QUEST_MISSION_REQUEST_TEXT[q?.missionKind]||QUEST_MISSION_REQUEST_TEXT.research,q);
}
function getQuestMissionLabel(kind){return({rescue:'救助',retrieve:'回収',hunt:'討伐',research:'調査',monolith:'モノリス調査'})[kind]||'探索';}
function getQuestEnemyCategoryLabel(kind){return QUEST_ENEMY_CATEGORY_LABELS[kind]||kind||'不明';}
function getQuestCardRewardPool(){return getCardMastersForChannel('quest',card=>(card.category||'battle')==='battle'&&!card.passive);}


function getQuestGoldSizeMultiplier(q){
	const floors=Math.max(1,Math.floor(Number(q?.targetDepth)||2));
	return Math.max(0.5,1+(floors-2)*QUEST_GOLD_SIZE_STEP);
}
function getQuestGoldDifficultyMultiplier(source=null){
	const key=typeof source==='string'?normalizeDungeonDifficultyKey(source):normalizeDungeonDifficultyKey(source?.difficultyKey||getSelectedDungeonDifficultyKey());
	return Math.max(0.1,Number(DUNGEON_DIFFICULTIES[key]?.expMult)||1);
}
function getSummonaMissionChapterGold(q){
 if(!q?.summonaMissionId||q.archiveReplay)return 0;
 const def=getSummonaMissionDefinition(q.summonaMissionId);
 const chapter=Number(def?.chapterNo)||getOrderedSummonaMissionDefinitions().findIndex(x=>x.id===q.summonaMissionId)+1;
 return Math.max(1,chapter)*500;
}
function getQuestGoldRewardAmount(q,difficultySource=null){
	const r=q?.rewardSpec||{};
	if(r.type!=='gold')return 0;
 if(q?.summonaMissionId)return getSummonaMissionChapterGold(q);
	if(Number.isFinite(Number(r.finalAmount)))return Math.max(0,Math.floor(Number(r.finalAmount)||0));
	const base=Math.max(0,Math.floor(Number(r.baseAmount)||QUEST_GOLD_BASE));
	// 特別救助はGを難易度・階層で増減させず、確定異変による2倍だけを適用する。
	if(q?.externalRescue)return base;
	const raw=base*getQuestGoldSizeMultiplier(q)*getQuestGoldDifficultyMultiplier(difficultySource);
	return Math.max(0,Math.round(raw/100)*100);
}
function hasQuestRetreatRewardBonus(q){
	return !!q?.retreatRewardBonus;
}
function getQuestRewardMultiplier(q){if(q?.summonaMissionId)return 1;return hasQuestRetreatRewardBonus(q)||q?.externalRescue?2:1;}
function getExternalRescueDiamondReward(qOrKey=null){
	const rawKey=typeof qOrKey==='string'?qOrKey:qOrKey?.fixedDifficultyKey;
	const key=normalizeRescueDifficultyKey(rawKey);
	return({standard:1,hard:2,abyss:3,brink:4})[key]||1;
}
function getQuestDangerDiamondReward(q){return q?.externalRescue?getExternalRescueDiamondReward(q):1;}
function buildQuestRewardSpec(q,isWeekly){
	if(q?.special)return{type:'none'};
	const rng=createRNG(stringToSeed(`QUEST_REWARD::${q?.id||'quest'}`));
	const pool=getQuestCardRewardPool();
	if(isWeekly){
		return{type:'diamonds',amount:Math.max(1,Math.floor(Number(q?.weeklyDiamondReward)||2))};
	}
	if(rng()<0.58)return{type:'gold',baseAmount:QUEST_GOLD_BASE};
	if(!pool.length)return{type:'gold',baseAmount:QUEST_GOLD_BASE};
	const rr=rng();const rarity=rr<0.55?'N':rr<0.88?'R':'SR';
	const master=pickSeeded(rng,pool);
	return{type:'card',masterId:master.masterId,rarity};
}
function getQuestRewardText(q,difficultySource=null){
	const r=q?.rewardSpec||{type:'none'};let base=q?.roguelikeRecovery?`🎴 デッキ ${getRoguelikeLostDeck()?.cards?.length||0}枚`:'報酬なし';
	if(r.type==='gold')base=`💰${getQuestGoldRewardAmount(q,difficultySource)}G`;
	else if(r.type==='diamonds')base=`💎${Math.max(0,Math.floor(Number(r.amount)||0))}`;
	else if(r.type==='card'){
		const master=getCardMaster(r.masterId);
		base=`🎴 ${r.rarity||'N'}［${master?.name||'カード'}］`;
	}
	if(q?.periodType==='monthly'){const pick=q.monthlyRewardWordId?getAreaWordPickById(q.monthlyRewardWordId):null;base+=` ＋ 📖 新ワード${q.completed&&pick?.word?.id?`【${isNormalWordOwned(pick.cat,pick.word.id)?pick.word.name:getWordCipherLabel(pick.word.id)}】`:''}`;}
	return base;
}
function makeQuestWordIds(id){
	const seed=`QUEST_WORDS::${id||'quest'}::${gameState.partyName||'party'}`;
	return ['prefix','terrain','modifier','suffix'].map(cat=>{
		const pool=WORD_DB[cat]||[];const rng=createRNG(stringToSeed(`${seed}::${cat}`));
		return(pool[Math.floor(rng()*pool.length)]||pool[0])?.id;
	}).filter(Boolean);
}
function getQuestWordsByIds(ids){return(ids||[]).map(id=>getAreaWordPickById(id)?.word).filter(Boolean);}
function formatQuestStory(template,q){return String(template||'').replaceAll('{target}',q?.objectiveName||'対象').replaceAll('{client}',q?.requesterName||'依頼人').replaceAll('{enemy}',q?.targetEnemyName||q?.objectiveName||'異常個体');}
function buildQuestStory(q){
	if(q?.summonaMissionId){const def=getSummonaMissionDefinition(q.summonaMissionId);if(def?.storyText)return def.storyText;}
	if(q?.storyQuest==='research_intro')return 'サモナが各地の探索記録を照合する中で、説明のつかない黒いモノリスの報告を見つけた。正体を決めつけず、まず現地で形状と表面の記録を取りたいという。今回はサモナ自身も同行する。';
	if(q?.weeklyStoryTemplate)return formatQuestWeeklyText(q.weeklyStoryTemplate,q);
	return [getQuestIntroArchetypeText(q),getQuestCircumstanceText(q),getQuestMissionRequestText(q)].filter(Boolean).join('');
}
function buildQuestTitle(q){
	if(q?.summonaMissionId){const def=getSummonaMissionDefinition(q.summonaMissionId);if(def?.title)return def.title;}
	if(q?.storyQuest==='research_intro')return 'サモナとの共同調査 ― 名のないモノリス';
	if(q?.seriesTitle&&q?.chapterTitle)return `${q.seriesTitle} ${Math.max(1,(q.chapterIndex||0)+1)}/${q.chapterCount||'?'} ― ${q.chapterTitle}`;
	if(q?.missionKind==='rescue')return `行方不明者の救助 ― ${q.targetName||q.objectiveName}`;
	if(q?.missionKind==='retrieve')return `遺失物回収 ― ${q.objectiveName}`;
	if(q?.missionKind==='hunt')return `指定個体討伐 ― ${q.targetEnemyName||q.objectiveName}`;
	return `現地調査 ― ${q.objectiveName}`;
}
function normalizeQuestPeriodAndLevel(q,isWeekly,seedRng){
	q.periodType=q.special?'special':(q.periodType==='monthly'?'monthly':(isWeekly?'weekly':'daily'));
	if(!Number.isFinite(Number(q.introArchetypeIndex)))q.introArchetypeIndex=Math.floor(seedRng()*QUEST_INTRO_ARCHETYPES.length);
	if(!Number.isFinite(Number(q.targetCircumstanceIndex)))q.targetCircumstanceIndex=Math.floor(seedRng()*QUEST_TARGET_CIRCUMSTANCES.length);
	if(!Number.isFinite(Number(q.generatedPartyLevel)))q.generatedPartyLevel=getQuestPartyBaseLevel();
	if(!Number.isFinite(Number(q.fixedAreaLevel))){
		const weeklyBase=q.periodType==='weekly'?3:q.periodType==='monthly'?5:0;
		const chapterBonus=Math.max(0,Math.floor(Number(q.areaLevelBonus)||0));
		q.fixedAreaLevel=Math.max(1,Math.min(100,Math.round(Number(q.generatedPartyLevel)||1)+weeklyBase+chapterBonus));
	}
}
function normalizeQuestSpecialDefinition(q){
	if(q.periodType==='monthly'){
		q.missionKind='monolith';q.requesterName='ギルド';q.objectiveName='深部で確認されたモノリス';q.targetDepth=6;
		q.title='月間調査任務 ― 深部のモノリス';q.storyText=QUEST_MONTHLY_STORY;q.rewardSpec={type:'diamonds',amount:QUEST_MONTHLY_DIAMOND_REWARD};
		ensureMonthlyMonolithQuestionWords(q);chooseMonthlyMonolithRewardWord(q);
	}else if(q.summonaMissionId){const def=getSummonaMissionDefinition(q.summonaMissionId);if(def){q.requesterName=def.requesterName;q.companionNpcId=def.companionNpcId;q.targetDepth=def.targetDepth;q.title=def.title;q.storyText=def.storyText;q.rewardSpec=q.archiveReplay?{type:'none'}:{type:'gold',baseAmount:getSummonaMissionChapterGold(q)};}}
	else if(q.storyQuest==='research_intro')q.requesterName='サモナ';
}
function normalizeQuestObjective(q,seedRng){
	if(!q.requesterName&&!q.special)q.requesterName=pickDistinctQuestNpcName(seedRng,getQuestPartyNameSet());
	if(q.periodType==='monthly'){
		q.missionKind='monolith';q.objectiveName='深部で確認されたモノリス';q.targetDepth=6;
	}else if(q.summonaMissionId){
		const def=getSummonaMissionDefinition(q.summonaMissionId);q.missionKind=def?.missionKind||'research';q.objectiveName=def?.objectiveName||q.objectiveName;q.targetDepth=def?.targetDepth||q.targetDepth||2;q.special=true;
	}else if(q.storyQuest==='research_intro'){
		q.missionKind='research';q.objectiveName='名のないモノリス';q.targetDepth=2;q.special=true;
	}else if(q.missionKind==='rescue'){
		if(q.externalRescue){q.targetName='遭難した探索者';q.objectiveName='遭難した探索者';}
		else{
			const blocked=getQuestPartyNameSet();if(q.requesterName)blocked.add(q.requesterName);
			q.targetName=q.requesterRescue&&q.requesterName?q.requesterName:(q.targetName||pickDistinctQuestNpcName(seedRng,blocked));
			q.objectiveName=`探索者 ${q.targetName}`;
		}
	}else if(q.missionKind==='retrieve'){
		q.objectiveName=q.questTargetName||pickSeeded(seedRng,QUEST_RETRIEVAL_TARGETS);q.questTargetName=q.objectiveName;
	}else if(q.missionKind==='hunt'){
		q.targetEnemyCategory=ENEMY_DICTIONARY[q.targetEnemyCategory]?q.targetEnemyCategory:pickSeeded(seedRng,ENEMY_CATEGORIES);
		const list=ENEMY_DICTIONARY[q.targetEnemyCategory]||[];const enemy=list.length?pickSeeded(seedRng,list):null;
		q.targetEnemyName=q.targetEnemyName||enemy?.name||'異常個体';q.objectiveName=q.targetEnemyName;
	}else{
		q.missionKind='research';q.objectiveName=q.questTargetName||pickSeeded(seedRng,QUEST_RESEARCH_TARGETS);q.questTargetName=q.objectiveName;
	}
}
function normalizeQuestEnvironment(q){
	if(!Array.isArray(q.wordIds)||q.wordIds.length!==4)q.wordIds=makeQuestWordIds(q.id);
	const words=getQuestWordsByIds(q.wordIds);
	if(!Array.isArray(q.anticipatedEnemyCategories)||!q.anticipatedEnemyCategories.length){
		const cats=combineDungeonWordStats(words).topCategories||[];
		q.anticipatedEnemyCategories=[...(q.missionKind==='hunt'?[q.targetEnemyCategory]:[]),...cats].filter((v,i,a)=>v&&a.indexOf(v)===i).slice(0,3);
	}
	if(q.seriesId){q.title=buildQuestTitle(q);q.storyText=buildQuestStory(q);}
	else{q.title=q.title||buildQuestTitle(q);q.storyText=q.storyText||buildQuestStory(q);}
}
function normalizeQuestProgressAndReward(q,isWeekly){
	q.failedAttempts=Math.max(0,Math.floor(Number(q.failedAttempts)||0));
	if(q.externalRescue&&Number(q.rescueExpiresAt||0)>0&&Date.now()>Number(q.rescueExpiresAt)&&!q.completed)q.exhausted=true;
	if(!q.completed){delete q.retreatRewardBonus;delete q.completedRetreatEventLabel;}
	q.attemptLimit=getQuestAttemptLimit(q);
	if(q.attemptLimit>0&&q.failedAttempts>=q.attemptLimit)q.exhausted=true;
	if(typeof q.accepted!=='boolean')q.accepted=!!(q.completed||q.claimed);
	if(isWeekly&&q.seriesId)q.rewardSpec={type:'diamonds',amount:Math.max(1,Math.floor(Number(q.weeklyDiamondReward)||Number(q.rewardSpec?.amount)||2))};
	else if(!q.rewardSpec)q.rewardSpec=buildQuestRewardSpec(q,isWeekly);
	if(q.rewardSpec?.type==='gold'){
		if(q.completed&&!q.claimed&&Number.isFinite(Number(q.rewardSpec.amount))&&!Number.isFinite(Number(q.rewardSpec.finalAmount)))q.rewardSpec.finalAmount=Math.max(0,Math.floor(Number(q.rewardSpec.amount)||0));
		q.rewardSpec.baseAmount=q.summonaMissionId?getSummonaMissionChapterGold(q):q.externalRescue?EXTERNAL_RESCUE_REWARD_BASE:QUEST_GOLD_BASE;
		if(!q.completed)delete q.rewardSpec.amount;
	}
}
function ensureQuestDefinition(q,isWeekly=null){
	if(!q||q.type!=='instance')return q;
	if(isWeekly===null)isWeekly=q.periodType==='weekly'||String(q.id||'').startsWith('W-');
	const seedRng=createRNG(stringToSeed(`QUEST_META::${q.id||'quest'}`));
	normalizeQuestPeriodAndLevel(q,isWeekly,seedRng);
	normalizeQuestSpecialDefinition(q);
	normalizeQuestObjective(q,seedRng);
	normalizeQuestEnvironment(q);
	normalizeQuestProgressAndReward(q,isWeekly);
	return q;
}
function buildInstanceQuest(period,index,isWeekly,rng,options={}){
	const kinds=isWeekly?['rescue','retrieve','hunt','rescue','research']:['rescue','retrieve','hunt'];
	const missionKind=options.missionKind||kinds[index%kinds.length];
	const generatedPartyLevel=Math.max(1,Math.round(Number(options.generatedPartyLevel)||getQuestPartyBaseLevel()));
	const q={id:options.id||`${period}_instance_${index}`,type:'instance',missionKind,targetDepth:options.targetDepth||(isWeekly?3+Math.floor(rng()*2):2+Math.floor(rng()*2)),completed:false,claimed:false,accepted:false,failedAttempts:0,periodType:isWeekly?'weekly':'daily',generatedPartyLevel,...options};
	return ensureQuestDefinition(q,isWeekly);
}
function generateDailyQuestSet(period,excludedNames=[]){
	const generatedPartyLevel=getQuestPartyBaseLevel();
	const rng=createRNG(stringToSeed(`QUEST_INSTANCE_${period}_${gameState.partyName||'party'}`));
	const blocked=new Set([...getQuestPartyNameSet(),...(excludedNames||[])]);
	const out=[];
	for(let i=0;i<3;i++){
		const requesterName=pickDistinctQuestNpcName(rng,blocked);blocked.add(requesterName);
		const depthRoll=rng();const targetDepth=depthRoll<0.40?2:depthRoll<0.80?3:4;out.push(buildInstanceQuest(period,i,false,rng,{requesterName,generatedPartyLevel,targetDepth}));
	}
	return out;
}
function generateWeeklyQuestSet(period){
	const generatedPartyLevel=getQuestPartyBaseLevel();
	const rng=createRNG(stringToSeed(`QUEST_WEEKLY_SERIES_${period}_${gameState.partyName||'party'}`));
	const blocked=getQuestPartyNameSet();
	const templates=[...QUEST_WEEKLY_SERIES_TEMPLATES];
	for(let i=templates.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[templates[i],templates[j]]=[templates[j],templates[i]];}
	const out=[];
	templates.forEach((series,seriesOrder)=>{
		const requesterName=pickDistinctQuestNpcName(rng,blocked);blocked.add(requesterName);
		const chapterCount=series.chapters.length;
		const rewards=QUEST_WEEKLY_REWARDS[chapterCount]||Array(chapterCount).fill(Math.max(1,Math.floor(30/Math.max(1,chapterCount*4))));
		const seriesId=`${period}_series_${series.key}`;
		series.chapters.forEach((chapter,chapterIndex)=>{
			const q=buildInstanceQuest(period,chapterIndex,true,rng,{
				id:`${seriesId}_chapter_${chapterIndex+1}`,
				missionKind:chapter.missionKind,
				targetDepth:(QUEST_WEEKLY_DEPTH_PATTERNS[series.key]||[])[chapterIndex]||Math.min(4,2+chapterIndex),
				requesterName,generatedPartyLevel,
				requesterRescue:!!chapter.requesterRescue,
				seriesId,seriesOrder,seriesKey:series.key,seriesTitle:series.title,
				chapterIndex,chapterCount,chapterTitle:chapter.title,
				weeklyStoryTemplate:chapter.story,
				areaLevelBonus:chapterIndex*2,
				weeklyDiamondReward:rewards[chapterIndex]||1,
				rewardSpec:{type:'diamonds',amount:rewards[chapterIndex]||1}
			});
			out.push(q);
		});
	});
	return out;
}
// サモナミッション・アーキタイプ。DBエントリ側では archetype を指定し、必要な差分だけ上書きする。

// ここには「個体そのもの」の情報だけを置く。登場階・会話・撃破後演出はミッションDB側で指定する。
// stats は6人編成時=100%の基準値。サモナミッションでは参加人数に応じてHP/耐久だけが縮小される。
// baseCategory は種族技・カード名フレーバーのベース。deck は固有ボス専用の基礎デッキ。

function getSummonaUniqueBossDefinition(id){
	const raw=SUMMONA_UNIQUE_BOSS_DB[id];
	return raw?{...raw,stats:raw.stats?{...raw.stats}:null,deck:Array.isArray(raw.deck)?[...raw.deck]:[]}:null;
}

// 主な差分キー: chapterNo / chapterSubtitle / startLevel / targetDepth / dungeonSize / party / floors / startDialogue / investigationEvents / outboundEvents / objective / returnEvents
// boss.mode='boss1' : 通常ボス型。category だけ指定し、通常守護者の能力計算・名称・種族技を使う。
// boss.mode='unique': 固有ボス型。bossId で SUMMONA_UNIQUE_BOSS_DB を参照する。

function mergeSummonaMissionDef(raw){
	if(!raw)return null;const base=SUMMONA_MISSION_ARCHETYPES[raw.archetype]||{};
	return{...base,...raw,party:{...(base.party||{}),...(raw.party||{})},objective:{...(base.objective||{}),...(raw.objective||{})},rewardSpec:{...(base.rewardSpec||{type:'none'}),...(raw.rewardSpec||{})}};
}
function getSummonaMissionDefinition(id){return mergeSummonaMissionDef(SUMMONA_MISSION_DB[id]);}
function resolveSummonaMissionDungeonSize(def,baseSize){
	const base={width:Math.max(8,Math.floor(Number(baseSize?.width)||8)),height:Math.max(8,Math.floor(Number(baseSize?.height)||8))};
	const cfg=def?.dungeonSize;if(!cfg)return base;
	const scale=Math.max(0.5,Math.min(2,Number(cfg.scale)||1));
	const width=Number.isFinite(Number(cfg.width))?Number(cfg.width):base.width*scale+(Number(cfg.widthAdd)||0);
	const height=Number.isFinite(Number(cfg.height))?Number(cfg.height):base.height*scale+(Number(cfg.heightAdd)||0);
	return{width:Math.max(8,Math.min(21,Math.round(width))),height:Math.max(8,Math.min(21,Math.round(height)))};
}
