	const before=(gameState.party||[]).length;
	(gameState.party||[]).filter(c=>c?.npcDbId===npcId||c?.id===`mission_npc_${npcId}`).forEach(recoverMissionCompanionCards);
	gameState.party=(gameState.party||[]).filter(c=>!(c?.npcDbId===npcId||c?.id===`mission_npc_${npcId}`));
