function showSummonaMissionSecondPhaseScene(d){
	const def=getSummonaMissionForQuest(findQuestById(d?.questId)),st=ensureSummonaMissionState(d),phase=def?.objective?.secondPhase;
	if(!d||gameState.dungeon!==d||!gameState.inBattle||!st?.secondPhaseSceneActive||st.activeBossTag!=='objective:second'||!phase)return false;
	const isActive=()=>gameState.dungeon===d&&gameState.inBattle&&st.secondPhaseSceneActive&&st.activeBossTag==='objective:second';
	const lines=phase.battleLines||[];
	const next=()=>{
		if(!isActive())return;
		const line=lines[st.secondPhaseLineIndex];
		if(!line){st.secondPhaseSceneActive=false;syncMonolithBattleDialogueLayout(false);updateBattleUI();saveGame();return;}
		// 再読込でも表示中の台詞を飛ばさず、表示終了後に次の番号を保存する。
		const advance=()=>{if(!isActive())return;st.secondPhaseLineIndex++;next();};
		if(!showMonolithModal(line.text,1,SUMMONA_SECOND_PHASE_LINE_MS,advance,{battleDialogue:true,speaker:line.speaker}))advance();
		saveGame();
	};
	if(st.secondPhaseLineIndex===0){
		if(!showMonolithModal(phase.redText||'……。',phase.redStrength??1,phase.redDurationMs||1800,next,{battleDialogue:true,speaker:'モノリス'}))next();
	}else next();
	return true;
}
function restoreSummonaFinalBossPartyCardUses(){
	const seen=new Set();
	const restore=card=>{if(!card||seen.has(card))return;seen.add(card);restoreCardUses(card);};
	forEachOwnedCard(restore,false);
	for(const zone of [battleState.hand,battleState.drawPile,battleState.discardPile])for(const card of zone||[])restore(card);
	for(const ally of gameState.party||[])for(const zone of [ally?.hand,ally?.drawPile,ally?.discardPile])for(const card of zone||[])restore(card);
}
function tryStartSummonaMissionSecondPhase(d){
	if(!d?.questInstance||!gameState.inBattle)return false;
	const def=getSummonaMissionForQuest(findQuestById(d.questId)),st=ensureSummonaMissionState(d),phase=def?.objective?.secondPhase;
	if(!phase?.boss||!st||st.activeBossTag!=='objective'||st.objectiveSecondPhaseStarted)return false;
	cancelPlayerAutoSequence(true);
	battleState.autoMode=false;
	if(!startSummonaMissionBossBattle(d,phase.boss,'objective:second',{continueBattle:true})){
		return false;
	}
	st.objectiveSecondPhaseStarted=true;
	st.secondPhaseSceneActive=true;
	st.secondPhaseLineIndex=0;
	(gameState.party||[]).forEach(ally=>{
		if(!ally)return;
		ally.injury=0;ally.injuryFraction=0;ally.hp=Math.max(1,Number(ally.maxHp)||1);
		ally.statuses=createInitialStatuses();
	});
	restoreSummonaFinalBossPartyCardUses();
	gameState.turn=Math.max(1,(Number(gameState.turn)||1)+1);
	fillHandTo5();
	clearLog();log('⚔️ 床の刻印が三人の傷をなぞり、札の力まで戻した。味方全員のHP・負傷・カード使用回数が回復した。新たな輪郭が立ち上がる。');
	updatePartyUI();updateBattleUI();playSummonaFinalHealFlash();saveGame();
	showSummonaMissionSecondPhaseScene(d);
	return true;
}
