let questPeriodExpiryScheduled=false;
function getActiveQuestExpiry(d=gameState?.dungeon){
 if(!d?.questInstance)return null;
 const periods={daily:localDayKey(),weekly:localWeekKey(),monthly:localMonthKey()};
 for(const type of ['daily','weekly','monthly']){
  const q=(gameState.quests?.[type]||[]).find(q=>q.id===d.questId);
  if(!q&&d.questPeriodType!==type)continue;
  const previous=d.questPeriodKey||gameState.quests?.[type+'Key'];
  if(previous&&previous!==periods[type])return{type,title:q?.title||d.questTitle||'依頼'};
 }
 return null;
}
function returnFromExpiredQuest(d=gameState?.dungeon){
 const expired=getActiveQuestExpiry(d);
 if(!expired||gameState.dungeon!==d)return false;
 // 期限切れでは拾得物を確定し、報酬・成功経験値は付与せず帰還する。
 commitQuestTemporaryLoot(d);
 const record=gameState.activeAdventureRecord?finalizeAdventureRecord(d,'quest-expired'):null;
 resetFailedQuestRuntimeForRetry(d);
 gameState.party.forEach(c=>{if(c&&c.hp<=0)c.hp=1;});
 if(gameState.missionCompanionContext?.active)restoreMissionCompanionParty(d);
 gameState.dungeon=null;gameState.inBattle=false;
 while(gameDialogState)resolveGameDialog(false);
 closeAllOverlaysForEmergencyEscape();
 ensureQuestPeriods();
 showScreen('screen-town');updatePartyUI();updateTownNotices();clearLog();
 log(`⌛ 依頼「${escapeHtml(expired.title)}」の期限が切れたため、探索を中断して町へ帰還した。入手した品と素材は持ち帰った。`);
 finishMilestoneTownReturn(record);saveGame();
 return true;
}
function ensureQuestPeriods(){
 // 呼び出し元の同期処理を終えてから帰還し、更新で参照中の依頼を消さない。
 if(getActiveQuestExpiry()){
  if(!questPeriodExpiryScheduled){questPeriodExpiryScheduled=true;const d=gameState.dungeon;queueMicrotask(()=>{questPeriodExpiryScheduled=false;returnFromExpiredQuest(d);});}
  return;
 }

	const dailyKey=localDayKey();const weeklyKey=localWeekKey();const monthlyKey=localMonthKey();
	if(!gameState.quests)gameState.quests={};
	if(!Array.isArray(gameState.quests.special))gameState.quests.special=[];
	ensureSummonaMissionQuests();
	syncRoguelikeRecoveryQuest();
	ensureMonthlyMugenInputMemory();
	const monthlyReady=getPastMugenInputWords().length>=QUEST_MONTHLY_MONOLITH_REQUIRED_WORDS;
	const monthlyNeedsReset=gameState.quests.monthlyKey!==monthlyKey||!Array.isArray(gameState.quests.monthly);
	if(monthlyNeedsReset){gameState.quests.monthlyKey=monthlyKey;gameState.quests.monthly=[];}
	if(monthlyReady&&gameState.quests.monthly.length===0)gameState.quests.monthly=[generateMonthlyQuest(monthlyKey)];
	(gameState.quests.monthly||[]).forEach(q=>ensureQuestDefinition(q,false));
	const weeklyNeedsReset=gameState.quests.weeklyKey!==weeklyKey||!Array.isArray(gameState.quests.weekly);
	if(weeklyNeedsReset){gameState.quests.weeklyKey=weeklyKey;gameState.quests.weekly=generateWeeklyQuestSet(weeklyKey);}
	(gameState.quests.weekly||[]).forEach(q=>ensureQuestDefinition(q,true));
	const weeklyRequesters=[...new Set((gameState.quests.weekly||[]).map(q=>q.requesterName).filter(Boolean))];
	const dailyNeedsReset=gameState.quests.dailyKey!==dailyKey||!Array.isArray(gameState.quests.daily);
	if(dailyNeedsReset){gameState.quests.dailyKey=dailyKey;gameState.quests.daily=generateDailyQuestSet(dailyKey,weeklyRequesters);}
	(gameState.quests.special||[]).forEach(q=>ensureQuestDefinition(q,false));
	(gameState.quests.daily||[]).forEach(q=>ensureQuestDefinition(q,false));
	refreshQuestProgress();
}
