let failedQuestRetryId=null;
function closeQuestRetryModal(){hideModalById('quest-retry-modal');failedQuestRetryId=null;}
function openQuestRetryModal(q){
	const modal=document.getElementById('quest-retry-modal'),body=document.getElementById('quest-retry-body'),retry=document.getElementById('quest-retry-btn');if(!modal||!q)return;
	failedQuestRetryId=q.id;
	if(body)body.innerHTML=`これ以上の探索は危険だ。探索を断念し、帰還した。<br>${getQuestLootReturnText(!!q.archiveReplay)}使用した消耗品・素材は戻らない。<br>${escapeHtml(rescueRetreatFeeText(Number(q.lastRescueFee)||0))}${q.archiveReplay?'<br><span style="color:#9fb7c7;">記録からの再調査なので、成功しても報酬・成功EXP・探索戦利品の持ち帰りはありません。</span>':''}<br><br><b style="color:#ead79a;">残り挑戦回数：${escapeHtml(getQuestAttemptText(q))}</b>${q.exhausted?'<br><span style="color:#ff9f8d;">これ以上の再派遣はできず、この依頼は打ち切られた。</span>':''}`;
	if(retry)retry.style.display=q.exhausted?'none':'';
	modal.style.display='flex';
}
function retryFailedQuestInstance(){
	const id=failedQuestRetryId;const q=id?findQuestById(id):null;
	if(!q||q.exhausted){closeQuestRetryModal();return;}
	closeQuestRetryModal();
	// 非同期の戦闘処理が再挑戦へ混入しないよう無効化する。
	resetFailedQuestRuntimeForRetry(gameState.dungeon?.questInstance?gameState.dungeon:null);
	startQuestInstance(id);
}
