 if(summonaGold){addPlayerGold(summonaGold);q.claimed=true;}
 if(q?.summonaMissionId)recordSummonaMissionClear(q.summonaMissionId,{replay:archiveReplay});
	if(!archiveReplay&&q?.periodType==='daily')unlockProgression('weeklyQuest');
	if(!archiveReplay&&(q?.storyQuest==='research_intro'||q?.summonaMissionId==='research_intro'||ensureResearchProgram().introCleared))unlockProgression('mugenDungeon');
	if(!archiveReplay)registerAdventureClear(d);const finalizedRecord=finalizeAdventureRecord(d,archiveReplay?'quest-replay':'quest-clear');if(q?.companionNpcId)restoreMissionCompanionParty(d);
