let explorationTipsTimer=null;
function scheduleExplorationTips(delay=700){
	if(explorationTipsTimer)clearTimeout(explorationTipsTimer);
	explorationTipsTimer=setTimeout(async()=>{
		explorationTipsTimer=null;
		if(!gameState?.dungeon||gameState.inBattle||isGuidedTutorialFlowActive()||!document.getElementById('screen-dungeon')?.classList.contains('active'))return;
		const visibleModal=Array.from(document.querySelectorAll('[id$="-modal"]')).some(el=>{
			if(el.style.display!=='flex')return false;
			const style=getComputedStyle(el);
			return style.visibility!=='hidden'&&style.pointerEvents!=='none';
		});
		if((typeof dungeonEntryTransitionBusy!=='undefined'&&dungeonEntryTransitionBusy)||gameDialogState||visibleModal){
			scheduleExplorationTips(300);return;
		}
		const seen=ensureFeatureTipsSeen();
		const next=!seen.explorationBasics?['explorationBasics','Tips：探索の基本',EXPLORATION_BASICS_TIP_TEXT]
			:gameState.terrainEffectTipPending&&!seen.terrainEffects?['terrainEffects','Tips：地形効果',TERRAIN_EFFECTS_TIP_TEXT]
			:gameState.treasureRoomTipPending&&!seen.treasureRoom?['treasureRoom','Tips：宝物部屋',TREASURE_ROOM_TIP_TEXT]
			:gameState.materialBundleTipPending&&!seen.materialBundle?['materialBundle','Tips：素材とジェム精製',MATERIAL_BUNDLE_TIP_TEXT]:null;
		if(!next)return;
		if(next[0]==='terrainEffects')gameState.terrainEffectTipPending=false;
		if(next[0]==='treasureRoom')gameState.treasureRoomTipPending=false;
		if(next[0]==='materialBundle')gameState.materialBundleTipPending=false;
		await showFeatureTipOnce(next[0],next[2],{title:next[1]});
		scheduleExplorationTips(100);
	},delay);
}
function resetFeatureTips(){
  if(!gameState?.player)return;
  const seen=ensureFeatureTipsSeen();
  for(const key of FEATURE_TIP_KEYS)seen[key]=false;
  gameState.firstCombatUiTipSeen=false;
  gameState.firstCombatJobTipsSeen={};
  saveGame();
  showGameNotice('Tipsの表示履歴をリセットしました。各画面を開くと、説明が再表示されます。',{title:'Tipsを再表示'});
}
function ensureFeatureTipsSeen(){
	gameState.featureTipsSeen=gameState.featureTipsSeen&&typeof gameState.featureTipsSeen==='object'?gameState.featureTipsSeen:{};
	for(const key of FEATURE_TIP_KEYS)gameState.featureTipsSeen[key]=!!gameState.featureTipsSeen[key];
	return gameState.featureTipsSeen;
}
const pendingFeatureTipKeys=new Set();
async function showFeatureTipOnce(key,message,options={}){
	const seen=ensureFeatureTipsSeen();
	if(seen[key]||pendingFeatureTipKeys.has(key))return false;
	pendingFeatureTipKeys.add(key);
	try{
		await showGameNotice(message,options);
		seen[key]=true;
		saveGame();
		return true;
	}finally{
		pendingFeatureTipKeys.delete(key);
	}
}

