let saveWriteEpoch=0;let saveWriteSequence=Promise.resolve();
let saveWritesPending=0,saveHasFailed=false;
let observedSaveText;let saveConflict=false;
async function commitSaveText(stored,epoch=saveWriteEpoch){
 const commit=()=>{
  if(epoch!==saveWriteEpoch)return false;
  if(observedSaveText===undefined||localStorage.getItem(SAVE_STORAGE_KEY)!==observedSaveText){
   saveConflict=true;throw new Error('SAVE_CHANGED_IN_ANOTHER_WINDOW');
  }
  localStorage.setItem(SAVE_STORAGE_KEY,stored);observedSaveText=stored;return true;
 };
 if(globalThis.navigator?.locks?.request)return navigator.locks.request('mugen-main-save-write',commit);
 // A readwrite transaction serializes the synchronous comparison and write across windows.
 const db=await openSaveEncryptionDb();
 try{return await new Promise((resolve,reject)=>{
  const tx=db.transaction(SAVE_ENCRYPTION_STORE,'readwrite');let result;
  const req=tx.objectStore(SAVE_ENCRYPTION_STORE).get('save-write-guard');
  req.onsuccess=()=>{try{result=commit();}catch(error){reject(error);tx.abort();}};
  tx.oncomplete=()=>resolve(result);
  tx.onerror=()=>reject(tx.error||new Error('SAVE_LOCK_ERROR'));
  tx.onabort=()=>reject(tx.error||new Error('SAVE_LOCK_ABORTED'));
 });}finally{db.close();}
}
window.addEventListener('storage',event=>{
 if(event.key===SAVE_STORAGE_KEY&&observedSaveText!==undefined&&event.newValue!==observedSaveText){
  saveConflict=true;
  if(gameState?.player)setSaveFailure(true);
 }
});
const pendingEconomyActions=new Set();
window.addEventListener('beforeunload',event=>{
 if(saveWritesPending>0||saveHasFailed){event.preventDefault();event.returnValue='';}
});
function bytesToBase64(bytes){
	let binary='';const arr=bytes instanceof Uint8Array?bytes:new Uint8Array(bytes);
	for(let i=0;i<arr.length;i+=0x8000)binary+=String.fromCharCode(...arr.subarray(i,i+0x8000));
	return btoa(binary);
}
function base64ToBytes(value){
	const binary=atob(String(value||''));const out=new Uint8Array(binary.length);
	for(let i=0;i<binary.length;i++)out[i]=binary.charCodeAt(i);
	return out;
}
function openSaveEncryptionDb(){
	return new Promise((resolve,reject)=>{
		const request=indexedDB.open(SAVE_ENCRYPTION_DB,1);
		request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains(SAVE_ENCRYPTION_STORE))db.createObjectStore(SAVE_ENCRYPTION_STORE);};
		request.onsuccess=()=>resolve(request.result);
		request.onerror=()=>reject(request.error||new Error('CRYPTO_DB_OPEN_ERROR'));
	});
}
async function getLocalSaveEncryptionKey(){
 const db=await openSaveEncryptionDb();
 try{
  const existing=await new Promise((resolve,reject)=>{
   const tx=db.transaction(SAVE_ENCRYPTION_STORE,'readonly');
   const req=tx.objectStore(SAVE_ENCRYPTION_STORE).get(SAVE_ENCRYPTION_KEY_ID);
   let key;req.onsuccess=()=>{key=req.result;};
   tx.oncomplete=()=>resolve(key);
   tx.onerror=()=>reject(tx.error||new Error('CRYPTO_KEY_READ_ERROR'));
   tx.onabort=()=>reject(tx.error||new Error('CRYPTO_KEY_READ_ABORTED'));
  });
  if(existing)return existing;
  const candidate=await crypto.subtle.generateKey({name:'AES-GCM',length:256},false,['encrypt','decrypt']);
  return await new Promise((resolve,reject)=>{
   const tx=db.transaction(SAVE_ENCRYPTION_STORE,'readwrite');
   let key;
   const req=tx.objectStore(SAVE_ENCRYPTION_STORE).get(SAVE_ENCRYPTION_KEY_ID);
   req.onsuccess=()=>{key=req.result||candidate;if(!req.result)tx.objectStore(SAVE_ENCRYPTION_STORE).put(key,SAVE_ENCRYPTION_KEY_ID);};
   tx.oncomplete=()=>resolve(key);
   tx.onerror=()=>reject(tx.error||new Error('CRYPTO_KEY_WRITE_ERROR'));
   tx.onabort=()=>reject(tx.error||new Error('CRYPTO_KEY_WRITE_ABORTED'));
  });
 }finally{db.close();}
}
async function encryptLocalSaveText(plainText){
	if(!crypto?.subtle)throw new Error('WEB_CRYPTO_UNAVAILABLE');
	const key=await getLocalSaveEncryptionKey();
	const iv=crypto.getRandomValues(new Uint8Array(12));
	const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(plainText));
	return 'ENC1:'+JSON.stringify({v:1,alg:'AES-GCM',iv:bytesToBase64(iv),data:bytesToBase64(new Uint8Array(cipher))});
}
async function decryptLocalSaveText(storedText){
	if(!String(storedText||'').startsWith('ENC1:'))return String(storedText||'');
	if(!crypto?.subtle)throw new Error('WEB_CRYPTO_UNAVAILABLE');
	const envelope=JSON.parse(String(storedText).slice(5));
	if(envelope?.v!==1||envelope?.alg!=='AES-GCM'||!envelope.iv||!envelope.data)throw new Error('SAVE_ENCRYPTION_FORMAT_ERROR');
	const key=await getLocalSaveEncryptionKey();
	const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:base64ToBytes(envelope.iv)},key,base64ToBytes(envelope.data));
	return new TextDecoder().decode(plain);
}
function getBackupCooldownState(){
	try{const value=JSON.parse(localStorage.getItem(SAVE_BACKUP_COOLDOWN_KEY)||'null');return value&&typeof value==='object'?value:{exportAt:0,importAt:0};}
	catch(_){return{exportAt:0,importAt:0};}
}
function saveBackupCooldownState(state){
	try{localStorage.setItem(SAVE_BACKUP_COOLDOWN_KEY,JSON.stringify({exportAt:Number(state?.exportAt)||0,importAt:Number(state?.importAt)||0}));}catch(_){}
}
function getBackupCooldownRemaining(kind){
	const state=getBackupCooldownState();const at=kind==='import'?Number(state.importAt)||0:Number(state.exportAt)||0;
	return Math.max(0,SAVE_BACKUP_COOLDOWN_MS-(Date.now()-at));
}
function formatBackupCooldown(ms){
	if(ms<=0)return'利用可能';
	const totalMinutes=Math.ceil(ms/60000),days=Math.floor(totalMinutes/1440),hours=Math.floor((totalMinutes%1440)/60),minutes=totalMinutes%60;
	if(days>0)return`あと${days}日${hours}時間`;
	if(hours>0)return`あと${hours}時間${minutes}分`;
	return`あと${minutes}分`;
}
function renderSaveBackupCooldownUI(){
	const exportRemain=getBackupCooldownRemaining('export'),importRemain=getBackupCooldownRemaining('import');
	const status=document.getElementById('save-backup-cooldown');
	if(status)status.innerHTML=`保存：<b>${escapeHtml(formatBackupCooldown(exportRemain))}</b>　／　読み込み：<b>${escapeHtml(formatBackupCooldown(importRemain))}</b>`;
	const exportBtn=document.getElementById('save-backup-export-btn'),importBtn=document.getElementById('save-backup-import-btn');
	if(exportBtn){exportBtn.disabled=exportRemain>0;exportBtn.title=exportRemain>0?`次回まで${formatBackupCooldown(exportRemain)}`:'';}
	if(importBtn){importBtn.disabled=importRemain>0;importBtn.title=importRemain>0?`次回まで${formatBackupCooldown(importRemain)}`:'';}
}
async function deriveBackupEncryptionKey(passphrase,salt,iterations=200000){
	const material=await crypto.subtle.importKey('raw',new TextEncoder().encode(passphrase),'PBKDF2',false,['deriveKey']);
	return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);
}
function getBackupPublicPlayerSnapshot(payload){
	const party=Array.isArray(payload?.party)?payload.party:[];
	const hero=party.find(c=>c?.isPlayer)||party.find(c=>c?.id==='hero')||gameState?.player||{};
	return{
		name:String(hero?.name||'冒険者'),
		gold:Math.max(0,Math.floor(Number(hero?.gold)||0))
	};
}
async function sha256Base64(text){
	const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(String(text)));
	return bytesToBase64(new Uint8Array(hash));
}
async function createBackupExplorerSeal(payload,createdAt){
	return sha256Base64(`${BACKUP_INNER_SEAL_PHRASE}\n${createdAt}\n${JSON.stringify(payload)}`);
}
async function createEncryptedBackupEnvelope(payload,passphrase){
	if(!crypto?.subtle)throw new Error('WEB_CRYPTO_UNAVAILABLE');
	// Freeze the exported state before the first asynchronous crypto operation.
	payload=JSON.parse(JSON.stringify(payload));
	const salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),iterations=200000;
	const key=await deriveBackupEncryptionKey(passphrase,salt,iterations);
	const createdAt=new Date().toISOString();
	const explorerSeal=await createBackupExplorerSeal(payload,createdAt);
	const body=JSON.stringify({
		type:'mugen-no-meikyu-main-save',
		version:3,
		createdAt,
		payload,
		anotherLabyrinth:{
			welcome:BACKUP_SURFACE_WELCOME,
			message:BACKUP_INNER_MESSAGE,
			request:'コード改編で作ったセーブデータや解析で知った答えは、自分だけで楽しんでほしい。未来の探索者たちの楽しみを奪わないであげてくれ。',
			explorerSeal
		}
	});
	const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(body));
	const player=getBackupPublicPlayerSnapshot(payload);
	return JSON.stringify({
		format:'MUGEN_MAIN_SAVE',
		version:3,
		createdAt,
		welcome:BACKUP_SURFACE_WELCOME,
		message:BACKUP_SURFACE_REQUEST,
		note:'これは単なる警告ではなく、ソースコードという第三の迷宮へ辿り着いた探索者への手紙です。',
		player,
		saveData:{
			playerName:player.name,
			gold:player.gold,
			scenarioProgress:{
				protected:true,
				protection:'passphrase',
				alg:'AES-GCM',
				kdf:'PBKDF2-SHA256',
				iterations,
				salt:bytesToBase64(salt),
				iv:bytesToBase64(iv),
				data:bytesToBase64(new Uint8Array(cipher))
			}
		}
	});
}
async function decryptBackupEnvelope(text,passphrase){
	if(!crypto?.subtle)throw new Error('WEB_CRYPTO_UNAVAILABLE');
	const env=JSON.parse(text);
	if(env?.format!=='MUGEN_MAIN_SAVE'||Number(env?.version)!==3)throw new Error('BACKUP_FORMAT_ERROR');
	const protectedProgress=env?.saveData?.scenarioProgress;
	if(!protectedProgress||protectedProgress?.alg!=='AES-GCM'||protectedProgress?.kdf!=='PBKDF2-SHA256')throw new Error('BACKUP_FORMAT_ERROR');
	const key=await deriveBackupEncryptionKey(passphrase,base64ToBytes(protectedProgress.salt),Math.max(100000,Math.floor(Number(protectedProgress.iterations)||200000)));
	const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:base64ToBytes(protectedProgress.iv)},key,base64ToBytes(protectedProgress.data));
	const body=JSON.parse(new TextDecoder().decode(plain));
	const data=body?.payload;
	if(body?.type!=='mugen-no-meikyu-main-save'||Number(body?.version)!==3||!data||typeof data!=='object'||!Array.isArray(data.party)||!Array.isArray(data.deck))throw new Error('BACKUP_PAYLOAD_ERROR');

	if(body?.anotherLabyrinth?.explorerSeal){
		const expectedSeal=await createBackupExplorerSeal(data,String(body.createdAt||''));
		if(expectedSeal!==body.anotherLabyrinth.explorerSeal)throw new Error('BACKUP_EXPLORER_SEAL_MISMATCH');
	}
	return data;
}
async function exportEncryptedSaveBackup(options={}){
 const emergency=options.emergency===true&&saveHasFailed;
	if(!emergency&&getBackupCooldownRemaining('export')>0){renderSaveBackupCooldownUI();return;}
	if(!gameState?.player){await showGameNotice('保存できる冒険の記録がありません。',{title:'セーブデータの保存'});return;}
	const passphrase=await showGamePrompt('バックアップを保護するパスフレーズを入力してください。\n忘れると、このバックアップを読み込めなくなります。','',{title:'セーブデータの保存',confirmText:'暗号化して保存',maxLength:64});
	if(passphrase===null||passphrase===false)return;
	const secret=String(passphrase||'');
	if(secret.length<6){await showGameNotice('パスフレーズは6文字以上にしてください。',{title:'セーブデータの保存'});return;}
	try{
		legacyExpireCards(false);enforceGameLimits();
		const payload=buildSaveDataPayload();
		const encrypted=await createEncryptedBackupEnvelope(payload,secret);
		const blob=new Blob([encrypted],{type:'application/json'});
		const url=URL.createObjectURL(blob),a=document.createElement('a');
		const stamp=new Date().toISOString().replace(/[:.]/g,'-');
		a.href=url;a.download=`mugen-main-save-${stamp}.mugen-save`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);
		if(!emergency){const state=getBackupCooldownState();state.exportAt=Date.now();saveBackupCooldownState(state);renderSaveBackupCooldownUI();}
		await showGameNotice(emergency?'退避用バックアップを保存しました。':'セーブデータを保存しました。\n次に保存できるのは7日後です。',{title:'セーブデータの保存'});
	}catch(error){console.error('バックアップ保存エラー:',error);await showGameNotice(globalThis.crypto?.subtle?'バックアップを保存できませんでした。':'この接続環境では暗号化を利用できません。HTTPSまたはローカルファイルで開いてから保存してください。',{title:'セーブデータの保存'});}
}
function selectEncryptedSaveBackup(){
	if(getBackupCooldownRemaining('import')>0){renderSaveBackupCooldownUI();return;}
	const input=document.getElementById('save-backup-file-input');if(input){input.value='';input.click();}
}
async function importEncryptedSaveBackupFromInput(input){
	const file=input?.files?.[0];if(!file)return;
	if(getBackupCooldownRemaining('import')>0){renderSaveBackupCooldownUI();input.value='';return;}
	const passphrase=await showGamePrompt('このバックアップを作成した時のパスフレーズを入力してください。','',{title:'セーブデータの読み込み',confirmText:'復号して確認',maxLength:64});
	if(passphrase===null||passphrase===false){input.value='';return;}
	try{
		const data=await decryptBackupEnvelope(await file.text(),String(passphrase||''));
		const heroName=data.party?.find(c=>c?.isPlayer)?.name||data.party?.find(c=>c?.id==='hero')?.name||'探索者';
		const ok=await showGameConfirm(`バックアップの冒険記録を読み込みます。\n\n探索者：${heroName}\n現在のセーブデータは上書きされます。\n読み込み後、次にバックアップを読み込めるのは7日後です。`,{title:'セーブデータの読み込み',confirmText:'読み込む'});
		if(!ok){input.value='';return;}
		saveWriteEpoch++;
		await saveWriteSequence.catch(()=>{});
		if(!await commitSaveText(await encryptLocalSaveText(JSON.stringify(data))))throw new Error('SAVE_IMPORT_CANCELLED');
		const state=getBackupCooldownState();state.importAt=Date.now();saveBackupCooldownState(state);
		input.value='';
		location.reload();
	}catch(error){
		console.error('バックアップ読込エラー:',error);input.value='';
		if(error?.message==='BACKUP_EXPLORER_SEAL_MISMATCH'){
			await showGameNotice(BACKUP_TAMPER_NOTICE,{title:'もう一つの夢幻ノ迷宮'});
		}else{
			await showGameNotice('バックアップを読み込めませんでした。\nファイルまたはパスフレーズを確認してください。',{title:'セーブデータの読み込み'});
		}
	}
}
